window.CARDS=window.CARDS||{};CARDS["story-v-y3v3-index"]=[{"i":"sc-shiina-hiyori-y3v3-p12-1","v":"y3v3","y":3,"o":35,"k":"inner","w":"ayanokouji-kiyotaka ryuuen-kakeru shiina-hiyori","q":"shiina hiyori prologue  the unspoken confession seaside monologue before the exam  hiyori looks out at the ocean  alone   i like you in the end  i wasn t able to say those words out loud   i am sorry  ryuuen kun   please forgive me for being so pathetic  speaks in apologetic  self effacing terms toward both ryuen and ayanokoji  keeps her feelings to herself   admits she never said  i like you  because they are now enemies  resolves to defeat ayanokoji so class d can reach class a  sees the exam as  a path to survival and a path to death at the same time  vows to inflict defeat on him while her feelings remain unchanged  apologises to him for not being able to help the class  continues to gaze at the ocean until the whistle sounds  her feelings will never change  the page locator also hits the table of contents entry  prologue  shiina hiyori s monologue    not a content page  no scene entry required","h":"<article class=\"card\" id=\"sc-shiina-hiyori-y3v3-p12-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shiina-hiyori.html#sc-shiina-hiyori-y3v3-p12-1\">Prologue: the unspoken confession<\/a><\/span><span class=\"meta\">Y3V3 · p.12–13<\/span><span class=\"by\">notes on <a href=\"../../../people/shiina-hiyori.html\">Shiina Hiyori<\/a><\/span><\/h3><p class=\"setup\">Seaside monologue before the exam: Hiyori looks out at the ocean, alone.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/p><ul class=\"lines\"><li class=\"q inner\"><b class=\"sp\">Shiina Hiyori<\/b> “‘I like you’—in the end, I wasn’t able to say those words out loud.”<span class=\"pg\">p.12<\/span><\/li><li class=\"q inner\"><b class=\"sp\">Shiina Hiyori<\/b> “I am sorry, Ryuuen-kun.”<span class=\"pg\">p.12<\/span><\/li><li class=\"q inner\"><b class=\"sp\">Shiina Hiyori<\/b> “Please forgive me for being so pathetic.”<span class=\"pg\">p.12<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Voice<\/span> Speaks in apologetic, self-effacing terms toward both Ryūen and Ayanokōji.<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Keeps her feelings to herself — admits she never said “I like you” because they are now enemies.<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Position<\/span> Resolves to defeat Ayanokōji so Class D can reach Class A; sees the exam as “a path to survival and a path to death at the same time.”<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Vows to inflict defeat on him while her feelings remain unchanged.<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Apologises to him for not being able to help the class.<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Continues to gaze at the ocean until the whistle sounds; her feelings will never change.<span class=\"pg\">p.13<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The page locator also hits the Table of Contents entry “Prologue: Shiina Hiyori’s Monologue” — not a content page, no scene entry required.<span class=\"pg\">p.9<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shiina-hiyori-y3v3-p171-1\">→ After: The beach conversation with Ryūen<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p14-1","v":"y3v3","y":3,"o":35,"k":"narration spoken","w":"hashimoto-masayoshi ayanokouji-kiyotaka","q":"ayanokoji kiyotaka arrival  the ship  hashimoto s complaints and the landing order cruise ship crossing to the same uninhabited island at just past 8 a m  ayanokoji and hashimoto wait in the ship s cafe to disembark  the third years are on their third straight uninhabited island exam  and the stage is the exact same island as last year   the schedule moved up about a month from prior years   looks like we re finally arriving   ah  i m sleepy  i should ve gone to bed a little earlier yesterday   well then  i wonder what kind of troublesome  no  pain in the ass exam is waiting for us this year  new gym clothes were distributed to all third years on boarding   jersey tops and bottoms plus shirts  nearly identical to the usual ones but with slightly thicker fabric   but isn t this unbearable for students preparing for entrance exams  being pulled away from their desks at this time of year  have the third years up until now never complained about this   who knows  but i did see shimazaki bringing a set of study materials onto the ship   so he s stuck studying even on the ship  huh   they wouldn t cut into our precious summer vacation  would they  if that s how they  make up for it  then spare me  an onboard announcement orders third years to leave all personal belongings  including phones  in their rooms and change into the designated gym clothes   the fact that the first and second years haven t been called yet  does that mean  by any chance  that they won t be landing on the uninhabited island right away   maybe  but speculating now won t tell us anything   true","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p14-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p14-1\">Arrival: the ship, Hashimoto&#x27;s complaints and the landing order<\/a><\/span><span class=\"meta\">Y3V3 · p.14–16<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Cruise ship crossing to the same uninhabited island at just past 8 a.m.; Ayanokōji and Hashimoto wait in the ship&#x27;s café to disembark.<\/p><p class=\"with\">with <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Looks like we&#x27;re finally arriving.&quot;<span class=\"pg\">p.14<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Ah~, I&#x27;m sleepy. I should&#x27;ve gone to bed a little earlier yesterday.&quot;<span class=\"pg\">p.15<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Well then... I wonder what kind of troublesome, no, pain-in-the-ass exam is waiting for us this year.&quot;<span class=\"pg\">p.15<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> The third-years are on their third straight uninhabited-island exam, and the stage is the exact same island as last year — the schedule moved up about a month from prior years.<span class=\"pg\">p.14<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> New gym clothes were distributed to all third-years on boarding — jersey tops and bottoms plus shirts, nearly identical to the usual ones but with slightly thicker fabric.<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;But isn&#x27;t this unbearable for students preparing for entrance exams? Being pulled away from their desks at this time of year. Have the third-years up until now never complained about this?&quot;<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Who knows. But I did see Shimazaki bringing a set of study materials onto the ship.&quot;<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;So he&#x27;s stuck studying even on the ship, huh?&quot;<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;They wouldn&#x27;t cut into our precious summer vacation, would they? If that&#x27;s how they &#x27;make up for it&#x27;, then spare me.&quot;<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> An onboard announcement orders third-years to leave all personal belongings, including phones, in their rooms and change into the designated gym clothes.<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;The fact that the first and second-years haven&#x27;t been called yet... does that mean, by any chance, that they won&#x27;t be landing on the uninhabited island right away?&quot;<span class=\"pg\">p.16<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Maybe. But speculating now won&#x27;t tell us anything.&quot;<span class=\"pg\">p.16<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;True...&quot;<span class=\"pg\">p.16<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p17-1\">→ After: Disembarkation: the grid, Nakanishi&#x27;s absence and the rules begin<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y3v3-p14-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka hashimoto-masayoshi","q":"hashimoto masayoshi sleepy on the crossing  grumbling about the exam rides the ship s cafe with ayanokoji  stretching and yawning as the island comes into view   looks like we re finally arriving   ah  i m sleepy  i should ve gone to bed a little earlier yesterday   well then  i wonder what kind of troublesome  no  pain in the ass exam is waiting for us this year   there s probably a reason they went out of their way to distribute new gym clothes to us  too   but isn t this unbearable for students preparing for entrance exams  being pulled away from their desks at this time of year  have the third years up until now never complained about this   so he s stuck studying even on the ship  huh   they wouldn t cut into our precious summer vacation  would they  if that s how they  make up for it  then spare me   the fact that the first and second years haven t been called yet  does that mean  by any chance  that they won t be landing on the uninhabited island right away   true  sleepy  grumpy and comic   complains about the timing and entrance exams while missing the point of the new gym clothes  has no intention of taking the exams himself  chats idly with him on the ship","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y3v3-p14-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hashimoto-masayoshi.html#sc-hashimoto-masayoshi-y3v3-p14-1\">Sleepy on the crossing: grumbling about the exam<\/a><\/span><span class=\"meta\">Y3V3 · p.14–16<\/span><span class=\"by\">notes on <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/span><\/h3><p class=\"setup\">Rides the ship&#x27;s café with Ayanokōji, stretching and yawning as the island comes into view.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Looks like we&#x27;re finally arriving.&quot;<span class=\"pg\">p.14<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Ah~, I&#x27;m sleepy. I should&#x27;ve gone to bed a little earlier yesterday.&quot;<span class=\"pg\">p.15<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Well then... I wonder what kind of troublesome, no, pain-in-the-ass exam is waiting for us this year.&quot;<span class=\"pg\">p.15<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;There&#x27;s probably a reason they went out of their way to distribute new gym clothes to us, too.&quot;<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;But isn&#x27;t this unbearable for students preparing for entrance exams? Being pulled away from their desks at this time of year. Have the third-years up until now never complained about this?&quot;<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;So he&#x27;s stuck studying even on the ship, huh?&quot;<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;They wouldn&#x27;t cut into our precious summer vacation, would they? If that&#x27;s how they &#x27;make up for it&#x27;, then spare me.&quot;<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;The fact that the first and second-years haven&#x27;t been called yet... does that mean, by any chance, that they won&#x27;t be landing on the uninhabited island right away?&quot;<span class=\"pg\">p.16<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;True...&quot;<span class=\"pg\">p.16<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Sleepy, grumpy and comic — complains about the timing and entrance exams while missing the point of the new gym clothes; has no intention of taking the exams himself.<span class=\"pg\">p.14–16<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Chats idly with him on the ship.<span class=\"pg\">p.14–16<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p21-1\">→ After: Reading the room and the expulsion rule<\/button><\/div><\/article>"},{"i":"sc-shimazaki-ikkei-y3v3-p14-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"sugio-hiroshi shimazaki-ikkei","q":"shimazaki ikkei ch 1   depth read  opposing the mountain plan  i m against it  other classes might be thinking something similar  besides  even if we force ourselves to cross the mountain  there s no guarantee that events will necessarily occur in the northeast  is there  cautious and analytical   rejects sugio s plan as risky and uncertain  opposes his mountain crossing proposal","h":"<article class=\"card\" id=\"sc-shimazaki-ikkei-y3v3-p14-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shimazaki-ikkei.html#sc-shimazaki-ikkei-y3v3-p14-1\">Ch.1 — depth read: opposing the mountain plan<\/a><\/span><span class=\"meta\">Y3V3 · p.14–45<\/span><span class=\"by\">notes on <a href=\"../../../people/shimazaki-ikkei.html\">Shimazaki Ikkei<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/sugio-hiroshi.html\">Sugio Hiroshi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shimazaki Ikkei<\/b> &quot;I&#x27;m against it. Other classes might be thinking something similar. Besides, even if we force ourselves to cross the mountain, there&#x27;s no guarantee that events will necessarily occur in the northeast, is there?&quot;<span class=\"pg\">p.31<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Cautious and analytical — rejects Sugio&#x27;s plan as risky and uncertain.<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sugio Hiroshi<\/b> Opposes his mountain-crossing proposal.<span class=\"pg\">p.31<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shimazaki-ikkei-y3v3-p31-1\">→ After: Opposing the mountain plan<\/button><\/div><\/article>"},{"i":"sc-shiraishi-asuka-y3v3-p14-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka shiraishi-asuka","q":"shiraishi asuka ch 1   depth read  the food problem  looking at the rules  if we can keep running away  we won t lose for the time being  paintballs won t be consumed unless we fight  but the food problem is unavoidable  points out the meager food forces event participation and combat   a sharp strategic observation  shares her analysis of the food supply constraint","h":"<article class=\"card\" id=\"sc-shiraishi-asuka-y3v3-p14-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shiraishi-asuka.html#sc-shiraishi-asuka-y3v3-p14-1\">Ch.1 — depth read: the food problem<\/a><\/span><span class=\"meta\">Y3V3 · p.14–45<\/span><span class=\"by\">notes on <a href=\"../../../people/shiraishi-asuka.html\">Shiraishi Asuka<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shiraishi Asuka<\/b> &quot;Looking at the rules, if we can keep running away, we won&#x27;t lose for the time being. Paintballs won&#x27;t be consumed unless we fight, but the food problem is unavoidable.&quot;<span class=\"pg\">p.31<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Points out the meager food forces event participation and combat — a sharp strategic observation.<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Shares her analysis of the food/supply constraint.<span class=\"pg\">p.31<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shiraishi-asuka-y3v3-p31-1\">→ After: The food problem makes running away impossible<\/button><\/div><\/article>"},{"i":"sc-sugio-hiroshi-y3v3-p14-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"shimazaki-ikkei sugio-hiroshi","q":"sugio hiroshi ch 1   depth read  the mountain crossing proposal  i definitely think aiming for nearby events is dangerous  if we re going to shoulder the risk of fighting poorly and getting out  why don t we just avoid class a from the start and cross the mountain   not moving  huh  i don t intend to deny that  but if we do that  it means we re resolving ourselves to a shootout right from the start  doesn t it  proposes crossing the mountain to monopolize northeast events  argues against a passive strategy  his proposal is opposed by him","h":"<article class=\"card\" id=\"sc-sugio-hiroshi-y3v3-p14-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sugio-hiroshi.html#sc-sugio-hiroshi-y3v3-p14-1\">Ch.1 — depth read: the mountain-crossing proposal<\/a><\/span><span class=\"meta\">Y3V3 · p.14–45<\/span><span class=\"by\">notes on <a href=\"../../../people/sugio-hiroshi.html\">Sugio Hiroshi<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/shimazaki-ikkei.html\">Shimazaki Ikkei<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sugio Hiroshi<\/b> &quot;I definitely think aiming for nearby events is dangerous. If we&#x27;re going to shoulder the risk of fighting poorly and getting out, why don&#x27;t we just avoid Class A from the start and cross the mountain?&quot;<span class=\"pg\">p.31<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sugio Hiroshi<\/b> &quot;Not moving, huh? I don&#x27;t intend to deny that, but if we do that, it means we&#x27;re resolving ourselves to a shootout right from the start, doesn&#x27;t it?&quot;<span class=\"pg\">p.32<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Proposes crossing the mountain to monopolize northeast events; argues against a passive strategy.<span class=\"pg\">p.31–32<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shimazaki Ikkei<\/b> His proposal is opposed by him.<span class=\"pg\">p.31<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sugio-hiroshi-y3v3-p31-1\">→ After: The mountain-crossing proposal<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p17-1","v":"y3v3","y":3,"o":35,"k":"inner narration spoken","w":"ayanokouji-kiyotaka","q":"ayanokoji kiyotaka disembarkation  the grid  nakanishi s absence and the rules begin disembarks onto the beach  the island is more developed than last year and cardboard boxes are stacked up  a school official directs the third years to line up by class at their homeroom teachers  no first  or second years are landing yet   i remember quite a bit  talk about nostalgia  mashima sensei announces that nakanishi of class d is absent due to a fever  so his class begins with one less person  nakanishi s absence was touched on lightly with no heavy penalty  since it is ichinose s class and he is not a standout  the damage is likely minimal   the downside is real but small  the island grid has been subdivided  last year a j   1 10  this year a o   1 15  exam duration is a maximum of three nights and four days  ending early on a decisive result  daily hours 9 00 a m 6 00 p m   4 00 p m  on the final day  five mandatory roles  commander  1  gps tablet  tactics  cannot be eliminated  confined to hq f14  vip  3  plus guards  analysts  2 and scout  1  the exam is won by eliminating other classes  vips and guards with paint guns","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p17-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p17-1\">Disembarkation: the grid, Nakanishi&#x27;s absence and the rules begin<\/a><\/span><span class=\"meta\">Y3V3 · p.17–20<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Disembarks onto the beach; the island is more developed than last year and cardboard boxes are stacked up.<\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> A school official directs the third-years to line up by class at their homeroom teachers; no first- or second-years are landing yet.<span class=\"pg\">p.17<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;I remember quite a bit. Talk about nostalgia.&quot;<span class=\"pg\">p.17<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> Mashima-sensei announces that Nakanishi of Class D is absent due to a fever, so his class begins with one less person.<span class=\"pg\">p.17<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Inner voice<\/span> Nakanishi&#x27;s absence was touched on lightly with no heavy penalty; since it is Ichinose&#x27;s class and he is not a standout, the damage is likely minimal — the downside is real but small.<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> The island grid has been subdivided: last year A–J × 1–10, this year A–O × 1–15.<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> Exam duration is a maximum of three nights and four days, ending early on a decisive result; daily hours 9:00 a.m.–6:00 p.m. (4:00 p.m. on the final day).<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> Five mandatory roles: Commander ×1 (GPS tablet, tactics, cannot be eliminated, confined to HQ F14), VIP ×3, plus Guards, Analysts ×2 and Scout ×1; the exam is won by eliminating other classes&#x27; VIPs and guards with paint guns.<span class=\"pg\">p.18<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p14-1\">← Before: Arrival: the ship, Hashimoto&#x27;s complaints and the landing order<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p21-1\">→ After: Tactics, watches, events and the expulsion penalty<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p21-1","v":"y3v3","y":3,"o":35,"k":"inner narration spoken","w":"hashimoto-masayoshi ayanokouji-kiyotaka","q":"ayanokoji kiyotaka tactics  watches  events and the expulsion penalty on the beach  mashima sensei explains that handling assigned roles and the commander s limited use tactics will be critical   anyone here ever played a survival game  or know anything about it  no one in class c admits to knowing survival games  while class a s onizuka and ijuuin chat excitedly  suggesting prior experience  commander tactics  global gps shutdown  30 min   1  individual gps shutdown  30 min   3  identity check  reveals name and role at a location   5  the using commander can still see positions every five minutes  the global gps shutdown in particular could be a trump card for surprise attacks or escaping pursuers  but poor timing would waste it  wristwatches are distributed and must be worn 24 hours a day  removal risks disqualification  the watch shows vitals  area and direction  and issues an  out  when a paintball bursts on the sensor clothes   an expulsion from the class whose three vip s get taken out first  huh  well  i figured they d pull something like that   is this what you expected   well  pretty much  the expulsion can be minimized   a class can nominate a student with protection points   but fear of it could produce a draw  and since a draw is decided by luck  no class can keep running  combat is forced","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p21-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p21-1\">Tactics, watches, events and the expulsion penalty<\/a><\/span><span class=\"meta\">Y3V3 · p.21–24<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">On the beach, Mashima-sensei explains that handling assigned roles and the commander&#x27;s limited-use tactics will be critical.<\/p><p class=\"with\">with <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Anyone here ever played a survival game? Or know anything about it?&quot;<span class=\"pg\">p.21<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;An expulsion from the class whose three VIP&#x27;s get taken out first, huh? Well, I figured they&#x27;d pull something like that.&quot;<span class=\"pg\">p.22<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Is this what you expected?&quot;<span class=\"pg\">p.22<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> No one in Class C admits to knowing survival games, while Class A&#x27;s Onizuka and Ijuuin chat excitedly, suggesting prior experience.<span class=\"pg\">p.21<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> Commander tactics: Global GPS Shutdown (30 min, ×1), Individual GPS Shutdown (30 min, ×3), Identity Check (reveals name and role at a location, ×5); the using commander can still see positions every five minutes.<span class=\"pg\">p.21<\/span><\/li><li><span class=\"mlabel\">Inner voice<\/span> The global GPS shutdown in particular could be a trump card for surprise attacks or escaping pursuers, but poor timing would waste it.<span class=\"pg\">p.22<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> Wristwatches are distributed and must be worn 24 hours a day; removal risks disqualification. The watch shows vitals, area and direction, and issues an &quot;Out&quot; when a paintball bursts on the sensor clothes.<span class=\"pg\">p.22<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Well, pretty much—&quot;<span class=\"pg\">p.22<\/span><\/li><li><span class=\"mlabel\">Inner voice<\/span> The expulsion can be minimized — a class can nominate a student with Protection Points — but fear of it could produce a draw, and since a draw is decided by luck, no class can keep running; combat is forced.<span class=\"pg\">p.24<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p17-1\">← Before: Disembarkation: the grid, Nakanishi&#x27;s absence and the rules begin<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p25-1\">→ After: Weapons: the prototype paintball guns<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y3v3-p21-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka hashimoto-masayoshi","q":"hashimoto masayoshi reading the room and the expulsion rule on the beach during the rule explanation  checks whether anyone knows survival games   anyone here ever played a survival game  or know anything about it   an expulsion from the class whose three vip s get taken out first  huh  well  i figured they d pull something like that   is this what you expected   well  pretty much  quick to read the exam s harsh logic   he had anticipated the expulsion rule   and candid that no one in class c knows survival games","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y3v3-p21-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hashimoto-masayoshi.html#sc-hashimoto-masayoshi-y3v3-p21-1\">Reading the room and the expulsion rule<\/a><\/span><span class=\"meta\">Y3V3 · p.21–22<\/span><span class=\"by\">notes on <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/span><\/h3><p class=\"setup\">On the beach during the rule explanation, checks whether anyone knows survival games.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Anyone here ever played a survival game? Or know anything about it?&quot;<span class=\"pg\">p.21<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;An expulsion from the class whose three VIP&#x27;s get taken out first, huh? Well, I figured they&#x27;d pull something like that.&quot;<span class=\"pg\">p.22<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Is this what you expected?&quot;<span class=\"pg\">p.22<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Well, pretty much—&quot;<span class=\"pg\">p.22<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Quick to read the exam&#x27;s harsh logic — he had anticipated the expulsion rule — and candid that no one in Class C knows survival games.<span class=\"pg\">p.21–22<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p14-1\">← Before: Sleepy on the crossing: grumbling about the exam<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p29-1\">→ After: Wanting the other classes to crush each other<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p25-1","v":"y3v3","y":3,"o":35,"k":"inner narration","w":"ayanokouji-kiyotaka","q":"ayanokoji kiyotaka weapons  the prototype paintball guns mashima sensei unveils the guards  weapons   assault rifles  shotguns  submachine guns and handguns   and kishinami of kanto shooter co  explains the prototype system  the gym clothes incorporate proprietary temperature sensitive  color reacting and impact sensor technology  a strong hit to the abdomen or back links to the watch and declares an out  while a tiny edge hit may not activate  self reporting a malfunction induced out avoids penalty  but continuing while knowing one is out is a serious violation that can cost the whole class the exam  the lunchtime announcement and rules suggest the school is still going easy on them   an escape route far more lenient than expected","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p25-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p25-1\">Weapons: the prototype paintball guns<\/a><\/span><span class=\"meta\">Y3V3 · p.25–28<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Mashima-sensei unveils the guards&#x27; weapons — assault rifles, shotguns, submachine guns and handguns — and Kishinami of Kanto Shooter Co. explains the prototype system.<\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> The gym clothes incorporate proprietary temperature-sensitive, color-reacting and impact-sensor technology; a strong hit to the abdomen or back links to the watch and declares an out, while a tiny edge hit may not activate.<span class=\"pg\">p.25<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> Self-reporting a malfunction-induced out avoids penalty, but continuing while knowing one is out is a serious violation that can cost the whole class the exam.<span class=\"pg\">p.26<\/span><\/li><li class=\"q inner\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> The lunchtime announcement and rules suggest the school is still going easy on them — an escape route far more lenient than expected.<span class=\"pg\">p.25<\/span><\/li><\/ul><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p21-1\">← Before: Tactics, watches, events and the expulsion penalty<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p29-1\">→ After: The starting-position lottery and meager supplies<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p29-1","v":"y3v3","y":3,"o":35,"k":"inner narration spoken","w":"hashimoto-masayoshi ayanokouji-kiyotaka","q":"ayanokoji kiyotaka the starting position lottery and meager supplies mashima sensei has one representative per class draw lots for the four starting areas   c12  e12  g12  i12   about a 15 minute walk apart  the western c12  not sandwiched  and eastern i12  easy to escape  look advantageous  but the result is the same whoever draws  so he has sanada draw   there were a lot of messy explanations  but basically  it means we just have to win a class vs class survival game  right   pretty much   for now  we keep our distance from the other classes and wait things out  yeah  let s just have them crush each other  that would be the most graceful outcome  but the rules are built so that anyone would want to reap the benefits of the chaos  class c starts at e12  ryuen s b at c12  horikita s a at g12  ichinose s d at i12  sanada apologizes for not drawing a corner area  ayanokoji tells him not to worry  initial supplies are identical for every class and must be chosen now   leftovers are collected once the exam starts  the food is only two nutritional supplement blocks and mineral water per person  barely one lunch  securing food from event supplies becomes essential  which forces event participation and raises the risk of contact with other classes   clearly designed to induce combat","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p29-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p29-1\">The starting-position lottery and meager supplies<\/a><\/span><span class=\"meta\">Y3V3 · p.29–30<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Mashima-sensei has one representative per class draw lots for the four starting areas — C12, E12, G12, I12 — about a 15-minute walk apart.<\/p><p class=\"with\">with <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;There were a lot of messy explanations, but basically, it means we just have to win a class vs class survival game, right?&quot;<span class=\"pg\">p.29<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Pretty much.&quot;<span class=\"pg\">p.29<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;For now, we keep our distance from the other classes and wait things out, yeah? Let&#x27;s just have them crush each other.&quot;<span class=\"pg\">p.29<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Inner voice<\/span> The western C12 (not sandwiched) and eastern I12 (easy to escape) look advantageous, but the result is the same whoever draws, so he has Sanada draw.<span class=\"pg\">p.29<\/span><\/li><li><span class=\"mlabel\">Inner voice<\/span> That would be the most graceful outcome, but the rules are built so that anyone would want to reap the benefits of the chaos.<span class=\"pg\">p.29<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> Class C starts at E12; Ryūen&#x27;s B at C12, Horikita&#x27;s A at G12, Ichinose&#x27;s D at I12. Sanada apologizes for not drawing a corner area; Ayanokōji tells him not to worry.<span class=\"pg\">p.30<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> Initial supplies are identical for every class and must be chosen now — leftovers are collected once the exam starts. The food is only two nutritional supplement blocks and mineral water per person, barely one lunch.<span class=\"pg\">p.30<\/span><\/li><li><span class=\"mlabel\">Inner voice<\/span> Securing food from event supplies becomes essential, which forces event participation and raises the risk of contact with other classes — clearly designed to induce combat.<span class=\"pg\">p.30<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p25-1\">← Before: Weapons: the prototype paintball guns<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p31-1\">→ After: The food debate: Shiraishi, Sugio and Shimazaki<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y3v3-p29-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka hashimoto-masayoshi","q":"hashimoto masayoshi wanting the other classes to crush each other after the starting position lottery  sums up the exam for ayanokoji   there were a lot of messy explanations  but basically  it means we just have to win a class vs class survival game  right   pretty much   for now  we keep our distance from the other classes and wait things out  yeah  let s just have them crush each other  favors a passive strategy of letting the other classes fight   the  most graceful outcome  though ayanokoji doubts it will work","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y3v3-p29-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hashimoto-masayoshi.html#sc-hashimoto-masayoshi-y3v3-p29-1\">Wanting the other classes to crush each other<\/a><\/span><span class=\"meta\">Y3V3 · p.29–30<\/span><span class=\"by\">notes on <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/span><\/h3><p class=\"setup\">After the starting-position lottery, sums up the exam for Ayanokōji.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;There were a lot of messy explanations, but basically, it means we just have to win a class vs class survival game, right?&quot;<span class=\"pg\">p.29<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Pretty much.&quot;<span class=\"pg\">p.29<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;For now, we keep our distance from the other classes and wait things out, yeah? Let&#x27;s just have them crush each other.&quot;<span class=\"pg\">p.29<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Favors a passive strategy of letting the other classes fight — the &quot;most graceful outcome,&quot; though Ayanokōji doubts it will work.<span class=\"pg\">p.29<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p21-1\">← Before: Reading the room and the expulsion rule<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p32-1\">→ After: Mediating the argument; tents and guns<\/button><\/div><\/article>"},{"i":"sc-sanada-kousei-y3v3-p29-1","v":"y3v3","y":3,"o":35,"k":"","w":"sanada-kousei","q":"sanada kosei drawing the starting position lot standing nearby  he is asked by ayanokoji to draw the starting position lot  the draw gives class c the e12 position  apologizes for failing to secure a corner area  ayanokoji tells him not to worry  since nothing could be done about it","h":"<article class=\"card\" id=\"sc-sanada-kousei-y3v3-p29-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sanada-kousei.html#sc-sanada-kousei-y3v3-p29-1\">Drawing the starting-position lot<\/a><\/span><span class=\"meta\">Y3V3 · p.29<\/span><span class=\"by\">notes on <a href=\"../../../people/sanada-kousei.html\">Sanada Kōsei<\/a><\/span><\/h3><p class=\"setup\">Standing nearby, he is asked by Ayanokōji to draw the starting-position lot; the draw gives Class C the E12 position.<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Apologizes for failing to secure a corner area; Ayanokōji tells him not to worry, since nothing could be done about it.<span class=\"pg\">p.30<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sanada-kousei-y3v3-p35-1\">→ After: The role assignment discussion<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p31-1","v":"y3v3","y":3,"o":35,"k":"inner spoken","w":"shiraishi-asuka sugio-hiroshi shimazaki-ikkei hashimoto-masayoshi ayanokouji-kiyotaka","q":"ayanokoji kiyotaka the food debate  shiraishi  sugio and shimazaki the class debates strategy over the meager food supply before the first event   looking at the rules  if we can keep running away  we won t lose for the time being  paintballs won t be consumed unless we fight  but the food problem is unavoidable   i definitely think aiming for nearby events is dangerous  if we re going to shoulder the risk of fighting poorly and getting out  why don t we just avoid class a from the start and cross the mountain  that way  it ll be easier for us to monopolize the events in the northeast area  other classes wouldn t bother traveling that far to fight us  right   i m against it  other classes might be thinking something similar  besides  even if we force ourselves to cross the mountain  there s no guarantee that events will necessarily occur in the northeast  is there   in that case  i think it s better not to go too far from the starting point until the first event begins  deriving the correct opening move is impossible at this stage  the shortest safe route north runs through the narrow riverside g8  where class a might arrive first   not moving  huh  i don t intend to deny that  but if we do that  it means we re resolving ourselves to a shootout right from the start  doesn t it  if  by some chance  three vips get taken out because of   okay  okay  i get what you want to say  sugio  but for now  let s look at the other supplies before we argue about that  our leader will squeeze out a good idea for us in the meantime  neither sugio nor shimazaki had the resolve to push their opinion and shoulder the responsibility  so they left the judgment to the leader","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p31-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p31-1\">The food debate: Shiraishi, Sugio and Shimazaki<\/a><\/span><span class=\"meta\">Y3V3 · p.31–32<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">The class debates strategy over the meager food supply before the first event.<\/p><p class=\"with\">with <a href=\"../../../people/shiraishi-asuka.html\">Shiraishi Asuka<\/a> · <a href=\"../../../people/sugio-hiroshi.html\">Sugio Hiroshi<\/a> · <a href=\"../../../people/shimazaki-ikkei.html\">Shimazaki Ikkei<\/a> · <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shiraishi Asuka<\/b> &quot;Looking at the rules, if we can keep running away, we won&#x27;t lose for the time being. Paintballs won&#x27;t be consumed unless we fight, but the food problem is unavoidable.&quot;<span class=\"pg\">p.31<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sugio Hiroshi<\/b> &quot;I definitely think aiming for nearby events is dangerous. If we&#x27;re going to shoulder the risk of fighting poorly and getting out, why don&#x27;t we just avoid Class A from the start and cross the mountain? That way, it&#x27;ll be easier…<span class=\"pg\">p.31<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shimazaki Ikkei<\/b> &quot;I&#x27;m against it. Other classes might be thinking something similar. Besides, even if we force ourselves to cross the mountain, there&#x27;s no guarantee that events will necessarily occur in the northeast, is there?&quot;<span class=\"pg\">p.31<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I definitely think aiming for nearby events is dangerous. If we&#x27;re going to shoulder the risk of fighting poorly and getting out, why don&#x27;t we just avoid Class A from the start and cross the mountain? That way, it&#x27;ll be easier for us to monopolize the events in the northeast area. Other classes wouldn&#x27;t bother traveling that far to fight us, right?&quot;<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;In that case, I think it&#x27;s better not to go too far from the starting point until the first event begins.&quot;<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Inner voice<\/span> Deriving the correct opening move is impossible at this stage; the shortest safe route north runs through the narrow riverside G8, where Class A might arrive first.<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Not moving, huh? I don&#x27;t intend to deny that, but if we do that, it means we&#x27;re resolving ourselves to a shootout right from the start, doesn&#x27;t it? If, by some chance, three VIPs get taken out because of—&quot;<span class=\"pg\">p.32<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Okay, okay. I get what you want to say, Sugio, but for now, let&#x27;s look at the other supplies before we argue about that. Our leader will squeeze out a good idea for us in the meantime.&quot;<span class=\"pg\">p.32<\/span><\/li><li><span class=\"mlabel\">Inner voice<\/span> Neither Sugio nor Shimazaki had the resolve to push their opinion and shoulder the responsibility, so they left the judgment to the leader.<span class=\"pg\">p.32<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p29-1\">← Before: The starting-position lottery and meager supplies<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p33-1\">→ After: Tents and weapons: supplying the class<\/button><\/div><\/article>"},{"i":"sc-shimazaki-ikkei-y3v3-p31-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"sugio-hiroshi shimazaki-ikkei","q":"shimazaki ikkei opposing the mountain plan voices immediate opposition to sugio s mountain crossing proposal   i m against it  other classes might be thinking something similar  besides  even if we force ourselves to cross the mountain  there s no guarantee that events will necessarily occur in the northeast  is there  cautious and analytical   rejects the plan as risky and built on an assumption about even event distribution  opposes his proposal","h":"<article class=\"card\" id=\"sc-shimazaki-ikkei-y3v3-p31-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shimazaki-ikkei.html#sc-shimazaki-ikkei-y3v3-p31-1\">Opposing the mountain plan<\/a><\/span><span class=\"meta\">Y3V3 · p.31<\/span><span class=\"by\">notes on <a href=\"../../../people/shimazaki-ikkei.html\">Shimazaki Ikkei<\/a><\/span><\/h3><p class=\"setup\">Voices immediate opposition to Sugio&#x27;s mountain-crossing proposal.<\/p><p class=\"with\">with <a href=\"../../../people/sugio-hiroshi.html\">Sugio Hiroshi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shimazaki Ikkei<\/b> &quot;I&#x27;m against it. Other classes might be thinking something similar. Besides, even if we force ourselves to cross the mountain, there&#x27;s no guarantee that events will necessarily occur in the northeast, is there?&quot;<span class=\"pg\">p.31<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Cautious and analytical — rejects the plan as risky and built on an assumption about even event distribution.<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sugio Hiroshi<\/b> Opposes his proposal.<span class=\"pg\">p.31<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shimazaki-ikkei-y3v3-p14-1\">← Before: Ch.1 — depth read: opposing the mountain plan<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-shimazaki-ikkei-y3v3-p43-1\">→ After: Volunteering as commander<\/button><\/div><\/article>"},{"i":"sc-shiraishi-asuka-y3v3-p31-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"shiraishi-asuka","q":"shiraishi asuka the food problem makes running away impossible picks up a box of nutritional supplement blocks during the supply debate   looking at the rules  if we can keep running away  we won t lose for the time being  paintballs won t be consumed unless we fight  but the food problem is unavoidable  sharp strategic read   identifies that the meager food forces event participation and combat  narrowing any passive strategy","h":"<article class=\"card\" id=\"sc-shiraishi-asuka-y3v3-p31-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shiraishi-asuka.html#sc-shiraishi-asuka-y3v3-p31-1\">The food problem makes running away impossible<\/a><\/span><span class=\"meta\">Y3V3 · p.31<\/span><span class=\"by\">notes on <a href=\"../../../people/shiraishi-asuka.html\">Shiraishi Asuka<\/a><\/span><\/h3><p class=\"setup\">Picks up a box of nutritional supplement blocks during the supply debate.<\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shiraishi Asuka<\/b> &quot;Looking at the rules, if we can keep running away, we won&#x27;t lose for the time being. Paintballs won&#x27;t be consumed unless we fight, but the food problem is unavoidable.&quot;<span class=\"pg\">p.31<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Sharp strategic read — identifies that the meager food forces event participation and combat, narrowing any passive strategy.<span class=\"pg\">p.31<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shiraishi-asuka-y3v3-p14-1\">← Before: Ch.1 — depth read: the food problem<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-shiraishi-asuka-y3v3-p46-1\">→ After: Ch.2 — depth read: Shiraishi as VIP and messenger<\/button><\/div><\/article>"},{"i":"sc-sugio-hiroshi-y3v3-p31-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"shimazaki-ikkei sugio-hiroshi","q":"sugio hiroshi the mountain crossing proposal staring at the small food supply  proposes avoiding class a and crossing the mountain   i definitely think aiming for nearby events is dangerous  if we re going to shoulder the risk of fighting poorly and getting out  why don t we just avoid class a from the start and cross the mountain  that way  it ll be easier for us to monopolize the events in the northeast area  other classes wouldn t bother traveling that far to fight us  right   not moving  huh  i don t intend to deny that  but if we do that  it means we re resolving ourselves to a shootout right from the start  doesn t it  if  by some chance  three vips get taken out because of  proposes a bold avoidance strategy and presses the worst case risk of staying put  imagined the class could be wiped out within an hour  but lacks the resolve to push his view against shimazaki s objection  his plan is opposed by him","h":"<article class=\"card\" id=\"sc-sugio-hiroshi-y3v3-p31-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sugio-hiroshi.html#sc-sugio-hiroshi-y3v3-p31-1\">The mountain-crossing proposal<\/a><\/span><span class=\"meta\">Y3V3 · p.31–32<\/span><span class=\"by\">notes on <a href=\"../../../people/sugio-hiroshi.html\">Sugio Hiroshi<\/a><\/span><\/h3><p class=\"setup\">Staring at the small food supply, proposes avoiding Class A and crossing the mountain.<\/p><p class=\"with\">with <a href=\"../../../people/shimazaki-ikkei.html\">Shimazaki Ikkei<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sugio Hiroshi<\/b> &quot;I definitely think aiming for nearby events is dangerous. If we&#x27;re going to shoulder the risk of fighting poorly and getting out, why don&#x27;t we just avoid Class A from the start and cross the mountain? That way, it&#x27;ll be easier…<span class=\"pg\">p.31<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sugio Hiroshi<\/b> &quot;Not moving, huh? I don&#x27;t intend to deny that, but if we do that, it means we&#x27;re resolving ourselves to a shootout right from the start, doesn&#x27;t it? If, by some chance, three VIPs get taken out because of—&quot;<span class=\"pg\">p.32<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I definitely think aiming for nearby events is dangerous. If we&#x27;re going to shoulder the risk of fighting poorly and getting out, why don&#x27;t we just avoid Class A from the start and cross the mountain? That way, it&#x27;ll be easier for us to monopolize the events in the northeast area. Other classes wouldn&#x27;t bother traveling that far to fight us, right?&quot;<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Proposes a bold avoidance strategy and presses the worst-case risk of staying put; imagined the class could be wiped out within an hour, but lacks the resolve to push his view against Shimazaki&#x27;s objection.<span class=\"pg\">p.31–32<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shimazaki Ikkei<\/b> His plan is opposed by him.<span class=\"pg\">p.31<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sugio-hiroshi-y3v3-p14-1\">← Before: Ch.1 — depth read: the mountain-crossing proposal<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y3v3-p32-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"sugio-hiroshi hashimoto-masayoshi","q":"hashimoto masayoshi mediating the argument  tents and guns steps between sugio and shimazaki to pause the strategy argument over supplies   okay  okay  i get what you want to say  sugio  but for now  let s look at the other supplies before we argue about that  our leader will squeeze out a good idea for us in the meantime   tents  huh  we need to think about what to take and how much right away  the question is how much of the thinking we should burden ayanokouji with    they look real up close  this is my first time touching something like this   man  the shotguns look hard to use  though  and they re heavy  the class s self appointed straight man   defuses the heated debate  defers to ayanokoji as leader  and is wide eyed handling real looking weapons for the first time  cuts off his argument with shimazaki","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y3v3-p32-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hashimoto-masayoshi.html#sc-hashimoto-masayoshi-y3v3-p32-1\">Mediating the argument; tents and guns<\/a><\/span><span class=\"meta\">Y3V3 · p.32–34<\/span><span class=\"by\">notes on <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/span><\/h3><p class=\"setup\">Steps between Sugio and Shimazaki to pause the strategy argument over supplies.<\/p><p class=\"with\">with <a href=\"../../../people/sugio-hiroshi.html\">Sugio Hiroshi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Okay, okay. I get what you want to say, Sugio, but for now, let&#x27;s look at the other supplies before we argue about that. Our leader will squeeze out a good idea for us in the meantime.&quot;<span class=\"pg\">p.32<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Tents, huh? We need to think about what to take and how much right away. The question is how much of the thinking we should burden Ayanokouji with —&quot;<span class=\"pg\">p.33<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;They look real up close. This is my first time touching something like this.&quot;<span class=\"pg\">p.33<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Man, the shotguns look hard to use, though. And they&#x27;re heavy.&quot;<span class=\"pg\">p.33<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> The class&#x27;s self-appointed straight man — defuses the heated debate, defers to Ayanokōji as leader, and is wide-eyed handling real-looking weapons for the first time.<span class=\"pg\">p.32–34<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sugio Hiroshi<\/b> Cuts off his argument with Shimazaki.<span class=\"pg\">p.32<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p29-1\">← Before: Wanting the other classes to crush each other<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p36-1\">→ After: Reacting to being named the sacrifice<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p33-1","v":"y3v3","y":3,"o":35,"k":"inner narration spoken","w":"hashimoto-masayoshi morishita-ai ayanokouji-kiyotaka","q":"ayanokoji kiyotaka tents and weapons  supplying the class the class sorts through the remaining boxes   small items  tents and weapons   and ayanokoji sets a supply guideline   tents  huh  we need to think about what to take and how much right away  the question is how much of the thinking we should burden ayanokouji with    i will provide a guideline for what supplies are necessary and how much to carry  if there are objections  voice them then with your reasoning  he sets a framework first and folds in classmates  views later   the optimal way to avoid wasting time  favors two  and multi person tents for shared carrying  since small tents become convenient as the class shrinks  forty main weapons are prepared   twenty assault rifles  ten submachine guns  ten shotguns   plus two handguns  each guard can carry one main weapon   they look real up close  this is my first time touching something like this   man  the shotguns look hard to use  though  and they re heavy  the assault rifle looks the most user friendly and well balanced  submachine guns and shotguns would only fill out the guard ranks   if we start with zero analysts  it looks like we can take two extra guns  what will you do   getting slightly more paintballs is certainly an advantage  but we will need analysts immediately  considering the trouble of carrying and managing the guns at that time  it s hard to say if it s worth it   we ll go with a policy of not increasing our luggage   so you don t intend to take any surplus  at times like this  human psychology makes us want to prepare at least a little insurance  one tends to get greedy   if we need something  we can just obtain it through an event  that s what the rules are for","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p33-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p33-1\">Tents and weapons: supplying the class<\/a><\/span><span class=\"meta\">Y3V3 · p.33–35<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">The class sorts through the remaining boxes — small items, tents and weapons — and Ayanokōji sets a supply guideline.<\/p><p class=\"with\">with <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a> · <a href=\"../../../people/morishita-ai.html\">Morishita Ai<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Tents, huh? We need to think about what to take and how much right away. The question is how much of the thinking we should burden Ayanokouji with —&quot;<span class=\"pg\">p.33<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;I will provide a guideline for what supplies are necessary and how much to carry. If there are objections, voice them then with your reasoning.&quot;<span class=\"pg\">p.33<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;They look real up close. This is my first time touching something like this.&quot;<span class=\"pg\">p.33<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Inner voice<\/span> He sets a framework first and folds in classmates&#x27; views later — the optimal way to avoid wasting time; favors two- and multi-person tents for shared carrying, since small tents become convenient as the class shrinks.<span class=\"pg\">p.33<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> Forty main weapons are prepared — twenty assault rifles, ten submachine guns, ten shotguns — plus two handguns; each Guard can carry one main weapon.<span class=\"pg\">p.33<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Man, the shotguns look hard to use, though. And they&#x27;re heavy.&quot;<span class=\"pg\">p.33<\/span><\/li><li><span class=\"mlabel\">Inner voice<\/span> The assault rifle looks the most user-friendly and well-balanced; submachine guns and shotguns would only fill out the Guard ranks.<span class=\"pg\">p.33<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;If we start with zero analysts, it looks like we can take two extra guns; what will you do?&quot;<span class=\"pg\">p.34<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Getting slightly more paintballs is certainly an advantage, but we will need analysts immediately. Considering the trouble of carrying and managing the guns at that time, it&#x27;s hard to say if it&#x27;s worth it.&quot;<span class=\"pg\">p.34<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;We&#x27;ll go with a policy of not increasing our luggage.&quot;<span class=\"pg\">p.34<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;So you don&#x27;t intend to take any surplus. At times like this, human psychology makes us want to prepare at least a little insurance; one tends to get greedy.&quot;<span class=\"pg\">p.34<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;If we need something, we can just obtain it through an event. That&#x27;s what the rules are for.&quot;<span class=\"pg\">p.34<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p31-1\">← Before: The food debate: Shiraishi, Sugio and Shimazaki<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p36-1\">→ After: Taking responsibility: I will be the one expelled<\/button><\/div><\/article>"},{"i":"sc-morishita-ai-y3v3-p34-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"morishita-ai","q":"morishita ai the surplus weapons question approaches ayanokoji after he checks the weapon count   if we start with zero analysts  it looks like we can take two extra guns  what will you do   so you don t intend to take any surplus  at times like this  human psychology makes us want to prepare at least a little insurance  one tends to get greedy  thinks about the extra gun option and voices the natural  insurance  instinct  then accepts the reasoning against excess luggage","h":"<article class=\"card\" id=\"sc-morishita-ai-y3v3-p34-1\"><h3><span class=\"ttl\"><a href=\"../../../people/morishita-ai.html#sc-morishita-ai-y3v3-p34-1\">The surplus-weapons question<\/a><\/span><span class=\"meta\">Y3V3 · p.34<\/span><span class=\"by\">notes on <a href=\"../../../people/morishita-ai.html\">Morishita Ai<\/a><\/span><\/h3><p class=\"setup\">Approaches Ayanokōji after he checks the weapon count.<\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Morishita Ai<\/b> &quot;If we start with zero analysts, it looks like we can take two extra guns; what will you do?&quot;<span class=\"pg\">p.34<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Morishita Ai<\/b> &quot;So you don&#x27;t intend to take any surplus. At times like this, human psychology makes us want to prepare at least a little insurance; one tends to get greedy.&quot;<span class=\"pg\">p.34<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Thinks about the extra-gun option and voices the natural &quot;insurance&quot; instinct, then accepts the reasoning against excess luggage.<span class=\"pg\">p.34<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-morishita-ai-y3v3-p36-1\">→ After: Naming Hashimoto as the sacrifice<\/button><\/div><\/article>"},{"i":"sc-sanada-kousei-y3v3-p35-1","v":"y3v3","y":3,"o":35,"k":"action","w":"sanada-kousei","q":"sanada kosei the role assignment discussion speaks up in agreement with matoba that no one would honestly volunteer for expulsion  ayanokoji names himself instead  listens as morishita argues the commander should be chosen first  appointed one of class c s two analysts","h":"<article class=\"card\" id=\"sc-sanada-kousei-y3v3-p35-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sanada-kousei.html#sc-sanada-kousei-y3v3-p35-1\">The role assignment discussion<\/a><\/span><span class=\"meta\">Y3V3 · p.35–44<\/span><span class=\"by\">notes on <a href=\"../../../people/sanada-kousei.html\">Sanada Kōsei<\/a><\/span><\/h3><p class=\"setup\">Speaks up in agreement with Matoba that no one would honestly volunteer for expulsion; Ayanokōji names himself instead. Listens as Morishita argues the commander should be chosen first.<\/p><ul class=\"lines\"><li class=\"q action\">Appointed one of Class C&#x27;s two Analysts.<span class=\"pg\">p.44<\/span><\/li><\/ul><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sanada-kousei-y3v3-p29-1\">← Before: Drawing the starting-position lot<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sanada-kousei-y3v3-p53-1\">→ After: Sanada suggests using Identity Check<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p36-1","v":"y3v3","y":3,"o":35,"k":"inner spoken","w":"hashimoto-masayoshi morishita-ai ayanokouji-kiyotaka","q":"ayanokoji kiyotaka taking responsibility  i will be the one expelled the class reacts with horror to the idea of naming an expulsion sacrifice before the exam  ayanokoji lets morishita float hashimoto s name  then intervenes   if hashimoto is willing to volunteer  that s fine  but unfortunately  i have already decided who will be expelled  and i won t change it even if there are objections   if we end up receiving the penalty  i ll take on that role   taking responsibility for defeat precisely because i am the leader  it sounds cool if i say it like that  but the reason is different  for better or worse  i m an outsider  not many days have gone by since i entered this class  if i  who joined to lead the class to victory  instead lead us to defeat  then bearing that responsibility is only logical   either way  you wouldn t be able to trust a leader who lost miserably without being able to do anything  right   as i just said  in the event that an expulsion occurs in the class  i want to confirm it s me  this is to prevent something like retracting it later  announcing and determining it in advance is unrelated to the rules of the exam  right   of course  these aren t words that should be spoken merely to ease the anxiety of my classmates  without a firm public commitment he could resist at the last moment and shift the blame onto someone else   announcing it in advance removes that escape  the declaration is a calculated move to galvanize the class  it buys their trust and unites them behind him  while costing him nothing he intends to pay  calm and strategically ruthless   deliberately lets the class squirm over the sacrifice before naming himself  knowing a leader who owns defeat is one they will follow  lets morishita name him as sacrifice  hashimoto is trapped into relying on ayanokoji s ability since he has no other route to class a  plays along with her proposal that hashimoto be the victim","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p36-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p36-1\">Taking responsibility: I will be the one expelled<\/a><\/span><span class=\"meta\">Y3V3 · p.36–39<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">The class reacts with horror to the idea of naming an expulsion sacrifice before the exam; Ayanokōji lets Morishita float Hashimoto&#x27;s name, then intervenes.<\/p><p class=\"with\">with <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a> · <a href=\"../../../people/morishita-ai.html\">Morishita Ai<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;If Hashimoto is willing to volunteer, that&#x27;s fine, but unfortunately, I have already decided who will be expelled, and I won&#x27;t change it even if there are objections.&quot;<span class=\"pg\">p.37<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;If we end up receiving the penalty, I&#x27;ll take on that role.&quot;<span class=\"pg\">p.37<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Taking responsibility for defeat precisely because I am the leader. It sounds cool if I say it like that, but the reason is different. For better or worse, I&#x27;m an outsider. Not many days have gone by since I entered this class.…<span class=\"pg\">p.37<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Taking responsibility for defeat precisely because I am the leader. It sounds cool if I say it like that, but the reason is different. For better or worse, I&#x27;m an outsider. Not many days have gone by since I entered this class. If I, who joined to lead the class to victory, instead lead us to defeat, then bearing that responsibility is only logical.&quot;<span class=\"pg\">p.37<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Either way, you wouldn&#x27;t be able to trust a leader who lost miserably without being able to do anything, right?&quot;<span class=\"pg\">p.37<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;As I just said, in the event that an expulsion occurs in the class, I want to confirm it&#x27;s me. This is to prevent something like retracting it later. Announcing and determining it in advance is unrelated to the rules of the exam, right?&quot;<span class=\"pg\">p.38<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Of course. These aren&#x27;t words that should be spoken merely to ease the anxiety of my classmates.&quot;<span class=\"pg\">p.38<\/span><\/li><li><span class=\"mlabel\">Inner voice<\/span> Without a firm public commitment he could resist at the last moment and shift the blame onto someone else — announcing it in advance removes that escape.<span class=\"pg\">p.38<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> The declaration is a calculated move to galvanize the class: it buys their trust and unites them behind him, while costing him nothing he intends to pay.<span class=\"pg\">p.37–38<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Calm and strategically ruthless — deliberately lets the class squirm over the sacrifice before naming himself, knowing a leader who owns defeat is one they will follow.<span class=\"pg\">p.36–39<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Lets Morishita name him as sacrifice; Hashimoto is trapped into relying on Ayanokōji&#x27;s ability since he has no other route to Class A.<span class=\"pg\">p.36–38<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Morishita Ai<\/b> Plays along with her proposal that Hashimoto be the victim.<span class=\"pg\">p.36–38<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p33-1\">← Before: Tents and weapons: supplying the class<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p40-1\">→ After: Assigning roles: guard, not commander<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y3v3-p36-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka morishita-ai hashimoto-masayoshi","q":"hashimoto masayoshi reacting to being named the sacrifice reacts as morishita names him first sacrifice  then as ayanokoji declares himself the one who will be expelled   i see  if that s the case  i accept like hell i would  good grief  give me a break  i was an idiot for even thinking about listening seriously for a second   well  if they re safe themselves  i guess they would   then are you saying it s okay to make me the victim   anyway  you just forced my name out there hoping to actually make me the sacrifice  didn t you   you seriously just clicked your tongue at me  i can t let my guard down around you at all   wait a minute  i said this earlier  but just because you re the leader doesn t mean you can decide everything   you re really dying to sacrifice me no matter what  aren t you  comically cornered by morishita s needling and shaken when ayanokoji declares himself the sacrifice  sharp enough to see through their maneuvers but powerless to stop them  is stunned by the self sacrifice declaration  which leaves him no choice but to believe in ayanokoji  spars with her over being the named sacrifice","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y3v3-p36-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hashimoto-masayoshi.html#sc-hashimoto-masayoshi-y3v3-p36-1\">Reacting to being named the sacrifice<\/a><\/span><span class=\"meta\">Y3V3 · p.36–37<\/span><span class=\"by\">notes on <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/span><\/h3><p class=\"setup\">Reacts as Morishita names him first sacrifice, then as Ayanokōji declares himself the one who will be expelled.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/morishita-ai.html\">Morishita Ai<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;I see, if that&#x27;s the case, I accept—like hell I would...! Good grief, give me a break. I was an idiot for even thinking about listening seriously for a second.&quot;<span class=\"pg\">p.36<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Well, if they&#x27;re safe themselves, I guess they would.&quot;<span class=\"pg\">p.36<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Then are you saying it&#x27;s okay to make me the victim?&quot;<span class=\"pg\">p.36<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Anyway, you just forced my name out there hoping to actually make me the sacrifice, didn&#x27;t you?&quot;<span class=\"pg\">p.36<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You seriously just clicked your tongue at me... I can&#x27;t let my guard down around you at all.&quot;<span class=\"pg\">p.37<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Wait a minute. I said this earlier, but just because you&#x27;re the leader doesn&#x27;t mean you can decide everything—&quot;<span class=\"pg\">p.37<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You&#x27;re really dying to sacrifice me no matter what, aren&#x27;t you?&quot;<span class=\"pg\">p.38<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Comically cornered by Morishita&#x27;s needling and shaken when Ayanokōji declares himself the sacrifice; sharp enough to see through their maneuvers but powerless to stop them.<span class=\"pg\">p.36–38<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is stunned by the self-sacrifice declaration, which leaves him no choice but to believe in Ayanokōji.<span class=\"pg\">p.37–38<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Morishita Ai<\/b> Spars with her over being the named sacrifice.<span class=\"pg\">p.36–38<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p32-1\">← Before: Mediating the argument; tents and guns<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p40-1\">→ After: Arguing for Ayanokōji as a guard<\/button><\/div><\/article>"},{"i":"sc-morishita-ai-y3v3-p36-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"hashimoto-masayoshi ayanokouji-kiyotaka morishita-ai","q":"morishita ai naming hashimoto as the sacrifice proposes that hashimoto be the class s sacrifice if they lose   hashimoto masayoshi  it seems ayanokouji kiyotaka s policy is already decided  i understand his decision without even receiving an explanation from him   if we end up receiving the penalty  then hashimoto masayoshi will be the first sacrifice to protect the classmates  this would be the fairest and most balanced conclusion   is that so  i am speaking with absolute  total seriousness  you know  don t you think everyone other than hashimoto masayoshi would happily accept this proposal   see  everyone s saved  no unfortunate victims   that can t be helped  you ll protect your classmates and become a star  a hero  goodbye  hashimoto masayoshi  i will make sure to remember your existence for at least a week   tch  you noticed   however  if that really happens  you should offer yourself for expulsion through self sacrifice  right  hashimoto masayoshi  needling and theatrical   pushes hashimoto as the  fairest  sacrifice with a smirk  enjoys provoking him  but her barbs are at least partly performance  later concedes ayanokoji s own declaration should stand for now  repeatedly names him as the expulsion sacrifice  accepts his self declaration as the sacrifice  for now  out of consideration for the class s mental burden","h":"<article class=\"card\" id=\"sc-morishita-ai-y3v3-p36-1\"><h3><span class=\"ttl\"><a href=\"../../../people/morishita-ai.html#sc-morishita-ai-y3v3-p36-1\">Naming Hashimoto as the sacrifice<\/a><\/span><span class=\"meta\">Y3V3 · p.36–38<\/span><span class=\"by\">notes on <a href=\"../../../people/morishita-ai.html\">Morishita Ai<\/a><\/span><\/h3><p class=\"setup\">Proposes that Hashimoto be the class&#x27;s sacrifice if they lose.<\/p><p class=\"with\">with <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Morishita Ai<\/b> &quot;Hashimoto Masayoshi, it seems Ayanokouji Kiyotaka&#x27;s policy is already decided. I understand his decision without even receiving an explanation from him.&quot;<span class=\"pg\">p.36<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Morishita Ai<\/b> &quot;If we end up receiving the penalty, then Hashimoto Masayoshi will be the first sacrifice to protect the classmates. This would be the fairest and most balanced conclusion.&quot;<span class=\"pg\">p.36<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Morishita Ai<\/b> &quot;Is that so? I am speaking with absolute, total seriousness, you know? Don&#x27;t you think everyone other than Hashimoto Masayoshi would happily accept this proposal?&quot;<span class=\"pg\">p.36<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;See? Everyone&#x27;s saved. No unfortunate victims.&quot;<span class=\"pg\">p.36<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;That can&#x27;t be helped. You&#x27;ll protect your classmates and become a star. A hero. Goodbye, Hashimoto Masayoshi. I will make sure to remember your existence for at least a week.&quot;<span class=\"pg\">p.36<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Tch, you noticed?&quot;<span class=\"pg\">p.37<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;However, if that really happens, you should offer yourself for expulsion through self-sacrifice, right, Hashimoto Masayoshi?&quot;<span class=\"pg\">p.38<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Needling and theatrical — pushes Hashimoto as the &quot;fairest&quot; sacrifice with a smirk, enjoys provoking him, but her barbs are at least partly performance; later concedes Ayanokōji&#x27;s own declaration should stand for now.<span class=\"pg\">p.36–38<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Repeatedly names him as the expulsion sacrifice.<span class=\"pg\">p.36–38<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Accepts his self-declaration as the sacrifice &quot;for now&quot; out of consideration for the class&#x27;s mental burden.<span class=\"pg\">p.37–38<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-morishita-ai-y3v3-p34-1\">← Before: The surplus-weapons question<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-morishita-ai-y3v3-p40-1\">→ After: Pushing for the commander to be chosen first; declining a guard role<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p40-1","v":"y3v3","y":3,"o":35,"k":"action inner spoken","w":"hashimoto-masayoshi shimazaki-ikkei ayanokouji-kiyotaka","q":"ayanokoji kiyotaka assigning roles  guard  not commander mashima sensei leaves the class thirty minutes to assign the five roles or the school picks randomly   isn t the reason obvious  it s because i view ayanokouji as a special combat asset   my hope is to be a guard  two untagged lines follow his  guard  statement in the text   one approving the choice  one adding that it depends on finding a trustworthy commander  the translation leaves both speakers unmarked  so no  says  row is claimed for them  he had already ruled out vip  analyst and scout for himself  the choice was commander or guard  commander s gps overview is attractive  but as a guard he can demonstrate his ability without relying on others   and class c lacks physically gifted students to execute orders  appoints shimazaki as commander  takemoto shiraishi nishikawa as vips  sanada nakajima as analysts  tsukaji as scout  the rest as guards  chooses him as commander by elimination despite doubts about his flexibility  takes full responsibility for the outcome to ease his burden  rebuts the suggestion he be commander  relies on his case for him as guard","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p40-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p40-1\">Assigning roles: guard, not commander<\/a><\/span><span class=\"meta\">Y3V3 · p.40–43<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Mashima-sensei leaves the class thirty minutes to assign the five roles or the school picks randomly.<\/p><p class=\"with\">with <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a> · <a href=\"../../../people/shimazaki-ikkei.html\">Shimazaki Ikkei<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Isn&#x27;t the reason obvious? It&#x27;s because I view Ayanokouji as a special combat asset.&quot;<span class=\"pg\">p.41<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;My hope is to be a guard.&quot;<span class=\"pg\">p.42<\/span><\/li><li class=\"q inner\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> He had already ruled out VIP, analyst and scout for himself; the choice was commander or guard. Commander&#x27;s GPS overview is attractive, but as a guard he can demonstrate his ability without relying on others — and Class C lacks…<span class=\"pg\">p.41–42<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Two untagged lines follow his &quot;guard&quot; statement in the text — one approving the choice, one adding that it depends on finding a trustworthy commander. The translation leaves both speakers unmarked, so no `[says]` row is claimed for them.<span class=\"pg\">p.42<\/span><\/li><li><span class=\"mlabel\">Inner voice<\/span> He had already ruled out VIP, analyst and scout for himself; the choice was commander or guard. Commander&#x27;s GPS overview is attractive, but as a guard he can demonstrate his ability without relying on others — and Class C lacks physically gifted students to execute orders.<span class=\"pg\">p.41–42<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Appoints Shimazaki as commander, Takemoto/Shiraishi/Nishikawa as VIPs, Sanada/Nakajima as analysts, Tsukaji as scout, the rest as guards.<span class=\"pg\">p.43–44<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shimazaki Ikkei<\/b> Chooses him as commander by elimination despite doubts about his flexibility; takes full responsibility for the outcome to ease his burden.<span class=\"pg\">p.43<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Rebuts the suggestion he be commander; relies on his Case for him as guard.<span class=\"pg\">p.40–41<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p36-1\">← Before: Taking responsibility: I will be the one expelled<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p44-1\">→ After: Briefing Shimazaki: report everything to Shiraishi<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y3v3-p40-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka hashimoto-masayoshi","q":"hashimoto masayoshi arguing for ayanokoji as a guard argues against making ayanokoji the commander during role assignment   she sure says the obvious with a self important attitude  that girl    muttered about morishita  isn t the reason obvious  it s because i view ayanokouji as a special combat asset  putting it bluntly  guards are pawns  but they re the only ones given a means of attack  aside from me and kitou  we don t have many students skilled in this kind of combat  that s why it s absolutely better to have ayanokouji fight on the front lines  besides  just because he can t directly communicate with the commander doesn t mean he can t organize the class  right  passionate and strategic   wants ayanokoji on the front line as a  combat asset  showing he grasps the value of concentrating offensive power in guards  argues for him as a guard rather than commander","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y3v3-p40-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hashimoto-masayoshi.html#sc-hashimoto-masayoshi-y3v3-p40-1\">Arguing for Ayanokōji as a guard<\/a><\/span><span class=\"meta\">Y3V3 · p.40–41<\/span><span class=\"by\">notes on <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/span><\/h3><p class=\"setup\">Argues against making Ayanokōji the commander during role assignment.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;She sure says the obvious with a self-important attitude, that girl.&quot; — muttered about Morishita<span class=\"pg\">p.40<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Isn&#x27;t the reason obvious? It&#x27;s because I view Ayanokouji as a special combat asset. Putting it bluntly, guards are pawns, but they&#x27;re the only ones given a means of attack. Aside from me and Kitou, we don&#x27;t have many students…<span class=\"pg\">p.41<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Isn&#x27;t the reason obvious? It&#x27;s because I view Ayanokouji as a special combat asset. Putting it bluntly, guards are pawns, but they&#x27;re the only ones given a means of attack. Aside from me and Kitou, we don&#x27;t have many students skilled in this kind of combat. That&#x27;s why it&#x27;s absolutely better to have Ayanokouji fight on the front lines. Besides, just because he can&#x27;t directly communicate with the commander doesn&#x27;t mean he can&#x27;t organize the class, right?&quot;<span class=\"pg\">p.41<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Passionate and strategic — wants Ayanokōji on the front line as a &quot;combat asset,&quot; showing he grasps the value of concentrating offensive power in guards.<span class=\"pg\">p.40–41<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Argues for him as a guard rather than commander.<span class=\"pg\">p.40–41<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p36-1\">← Before: Reacting to being named the sacrifice<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p46-1\">→ After: Ch.2 — depth read: Hashimoto&#x27;s reactions to the ambush<\/button><\/div><\/article>"},{"i":"sc-kondou-reo-y3v3-p40-1","v":"y3v3","y":3,"o":35,"k":"","w":"kondou-reo","q":"kondo reo named in the role discussion ayanokoji s narration weighs commander material and names ike or hondou  horikita s class  and ishizaki or kondou  ryuen s class  as choices that would sink a class s chances  named  not present  not a scene presence","h":"<article class=\"card\" id=\"sc-kondou-reo-y3v3-p40-1\"><h3><span class=\"ttl\">Named in the role discussion<\/span><span class=\"meta\">Y3V3 · p.40<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#kondou-reo\">Kondō Reo<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> Ayanokōji&#x27;s narration weighs commander material and names Ike or Hondou (Horikita&#x27;s class) and Ishizaki or Kondou (Ryūen&#x27;s class) as choices that would sink a class&#x27;s chances; named, not present. Not a scene presence.<span class=\"pg\">p.40<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-morishita-ai-y3v3-p40-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"morishita-ai","q":"morishita ai pushing for the commander to be chosen first  declining a guard role steps forward as the class begins assigning roles   the commander is an extremely important position  they must survey the entire battlefield  anticipate other classes  movements and above all  determine the timing for using tactics  if so  we should determine it first while we re free to choose from all thirty seven students in our class   reason  because i ll participate as a guard  when i see an uninhabited island  my old blood stirs no matter what  yes  back then  i was known and feared as the warrior woman of the dense forest no  this is an old story  please forget it  it s not worth discussing  articulate about the commander s importance and self dramatizing about her  warrior woman  past   a tall tale ayanokoji writes off as one hundred percent fiction","h":"<article class=\"card\" id=\"sc-morishita-ai-y3v3-p40-1\"><h3><span class=\"ttl\"><a href=\"../../../people/morishita-ai.html#sc-morishita-ai-y3v3-p40-1\">Pushing for the commander to be chosen first; declining a guard role<\/a><\/span><span class=\"meta\">Y3V3 · p.40, 43<\/span><span class=\"by\">notes on <a href=\"../../../people/morishita-ai.html\">Morishita Ai<\/a><\/span><\/h3><p class=\"setup\">Steps forward as the class begins assigning roles.<\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Morishita Ai<\/b> &quot;The commander is an extremely important position. They must survey the entire battlefield, anticipate other classes&#x27; movements and above all, determine the timing for using tactics. If so, we should determine it first while…<span class=\"pg\">p.40<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Morishita Ai<\/b> &quot;Reason? Because I&#x27;ll participate as a guard. When I see an uninhabited island, my old blood stirs no matter what. Yes, back then, I was known and feared as the Warrior Woman of the Dense Forest—no, this is an old story, please…<span class=\"pg\">p.43<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;The commander is an extremely important position. They must survey the entire battlefield, anticipate other classes&#x27; movements and above all, determine the timing for using tactics. If so, we should determine it first while we&#x27;re free to choose from all thirty-seven students in our class.&quot;<span class=\"pg\">p.40<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Reason? Because I&#x27;ll participate as a guard. When I see an uninhabited island, my old blood stirs no matter what. Yes, back then, I was known and feared as the Warrior Woman of the Dense Forest—no, this is an old story, please forget it. It&#x27;s not worth discussing.&quot;<span class=\"pg\">p.43<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Articulate about the commander&#x27;s importance and self-dramatizing about her &quot;Warrior Woman&quot; past — a tall tale Ayanokōji writes off as one hundred percent fiction.<span class=\"pg\">p.40, 43<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-morishita-ai-y3v3-p36-1\">← Before: Naming Hashimoto as the sacrifice<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-morishita-ai-y3v3-p46-1\">→ After: Ch.2 — depth read: Morishita&#x27;s complaints and exhaustion<\/button><\/div><\/article>"},{"i":"sc-tamiya-emi-y3v3-p40-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"tamiya-emi","q":"tamiya emi backing ayanokoji as commander weighs in during the role assignment discussion   i agree with morishita san too  i guess  it will likely be a tough fight without the commander s instructions  wouldn t ayanokouji kun be the natural choice  he is the leader  after all  backs ayanokoji for commander on the grounds that he is the leader   a simple  reasonable view that contrasts with hashimoto s guard argument","h":"<article class=\"card\" id=\"sc-tamiya-emi-y3v3-p40-1\"><h3><span class=\"ttl\"><a href=\"../../../people/tamiya-emi.html#sc-tamiya-emi-y3v3-p40-1\">Backing Ayanokōji as commander<\/a><\/span><span class=\"meta\">Y3V3 · p.40<\/span><span class=\"by\">notes on <a href=\"../../../people/tamiya-emi.html\">Tamiya Emi<\/a><\/span><\/h3><p class=\"setup\">Weighs in during the role-assignment discussion.<\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Tamiya Emi<\/b> &quot;I agree with Morishita-san too, I guess. It will likely be a tough fight without the commander&#x27;s instructions. Wouldn&#x27;t Ayanokouji-kun be the natural choice? He is the leader, after all.&quot;<span class=\"pg\">p.40<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Backs Ayanokōji for commander on the grounds that he is the leader — a simple, reasonable view that contrasts with Hashimoto&#x27;s guard argument.<span class=\"pg\">p.40<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-shimazaki-ikkei-y3v3-p43-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka shiraishi-asuka yoshida-kenta shimazaki-ikkei","q":"shimazaki ikkei volunteering as commander steps forward when ayanokoji is at a loss for a commander   ayanokouji  if you re lost on who to make commander  could you let me handle it   i don t know how well i ll be able to live up to your expectations  but i think i can handle the role without any issues   yeah  i don t really like moving around on a deserted island in the first place  i figured i d be more useful if i could focus on thinking   i ve been entrusted with an important role  that goes without saying   that s  won t receiving miscellaneous information throw the chain of command into chaos   no  no  that actually makes it harder  yoshida will get mad at me   i can t believe you can say something like that with a straight face  but  still  shiraishi is   no  actually  you re right  shiraishi is fine  i ll do it properly  so don t worry   right  got it  let s do that  honors student and orthodox thinker   eager to be useful where he can think rather than roam  visibly nervous about the weight of command  and flustered when ayanokoji routes reports through shiraishi  whom he likes  is appointed commander  humbled when ayanokoji takes full responsibility for the exam s outcome  is told to report all concerns to her  resists then accepts because of his feelings for her  worries yoshida will be angry if he reports through shiraishi","h":"<article class=\"card\" id=\"sc-shimazaki-ikkei-y3v3-p43-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shimazaki-ikkei.html#sc-shimazaki-ikkei-y3v3-p43-1\">Volunteering as commander<\/a><\/span><span class=\"meta\">Y3V3 · p.43–45<\/span><span class=\"by\">notes on <a href=\"../../../people/shimazaki-ikkei.html\">Shimazaki Ikkei<\/a><\/span><\/h3><p class=\"setup\">Steps forward when Ayanokōji is at a loss for a commander.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/shiraishi-asuka.html\">Shiraishi Asuka<\/a> · <a href=\"../../../people/yoshida-kenta.html\">Yoshida Kenta<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shimazaki Ikkei<\/b> &quot;Ayanokouji. If you&#x27;re lost on who to make commander, could you let me handle it?&quot;<span class=\"pg\">p.43<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shimazaki Ikkei<\/b> &quot;I don&#x27;t know how well I&#x27;ll be able to live up to your expectations, but I think I can handle the role without any issues.&quot;<span class=\"pg\">p.43<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shimazaki Ikkei<\/b> &quot;Yeah. I don&#x27;t really like moving around on a deserted island in the first place. I figured I&#x27;d be more useful if I could focus on thinking.&quot;<span class=\"pg\">p.43<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;ve been entrusted with an important role; that goes without saying.&quot;<span class=\"pg\">p.44<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;That&#x27;s... Won&#x27;t receiving miscellaneous information throw the chain of command into chaos?&quot;<span class=\"pg\">p.44<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;No, no... That actually makes it harder... Yoshida will get mad at me.&quot;<span class=\"pg\">p.45<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I can&#x27;t believe you can say something like that with a straight face... But, still, Shiraishi is...&quot;<span class=\"pg\">p.45<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;No, actually... You&#x27;re right, Shiraishi is fine. I&#x27;ll do it properly, so don&#x27;t worry.&quot;<span class=\"pg\">p.45<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;...Right. Got it, let&#x27;s do that.&quot;<span class=\"pg\">p.45<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Honors student and orthodox thinker — eager to be useful where he can think rather than roam, visibly nervous about the weight of command, and flustered when Ayanokōji routes reports through Shiraishi (whom he likes).<span class=\"pg\">p.43–45<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is appointed commander; humbled when Ayanokōji takes full responsibility for the exam&#x27;s outcome.<span class=\"pg\">p.43–45<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiraishi Asuka<\/b> Is told to report all concerns to her; resists then accepts because of his feelings for her.<span class=\"pg\">p.44–45<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yoshida Kenta<\/b> Worries Yoshida will be angry if he reports through Shiraishi.<span class=\"pg\">p.45<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shimazaki-ikkei-y3v3-p31-1\">← Before: Opposing the mountain plan<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p44-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"shimazaki-ikkei shiraishi-asuka yoshida-kenta ayanokouji-kiyotaka","q":"ayanokoji kiyotaka briefing shimazaki  report everything to shiraishi pulls shimazaki aside before parting   they cannot speak directly until the exam ends   no matter how trivial  i want you to report anything you find strange or unusual without hesitation   that s not it  the more you feel the weight of the commander position  the more likely you are to miss what s right under your nose  a commander from another class laughed  or got angry  changes in the gps that feels slightly off but doesn t seem worth mentioning  please report anything that concerns you personally  shimazaki   that s true  which is why it can t just be anyone  let s narrow it down to one person   it doesn t matter who  but let s see  let s go with shiraishi for now  that should make things easier for you as well   there s no need to favor only yoshida  to me  both of you are important friends   in other words  you can tell shiraishi anything and everything  no matter what it is  routes shimazaki s reports through shiraishi deliberately   knowing he likes her  this raises their contact  and she is the vip he reads most clearly  quietly matchmaking while optimizing command  uses the briefing to increase shimazaki s contact with shiraishi under the guise of avoiding  telephone game  confusion  briefs him on reporting  knows of his feelings for shiraishi  names her as the single reporting conduit  trusts her judgment most  cites him as another important friend to defuse shimazaki s objection  safety goggles recommended at all times  sensors are on the gym uniform only  though hits register through a tracksuit","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p44-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p44-1\">Briefing Shimazaki: report everything to Shiraishi<\/a><\/span><span class=\"meta\">Y3V3 · p.44–45<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Pulls Shimazaki aside before parting — they cannot speak directly until the exam ends.<\/p><p class=\"with\">with <a href=\"../../../people/shimazaki-ikkei.html\">Shimazaki Ikkei<\/a> · <a href=\"../../../people/shiraishi-asuka.html\">Shiraishi Asuka<\/a> · <a href=\"../../../people/yoshida-kenta.html\">Yoshida Kenta<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;No matter how trivial, I want you to report anything you find strange or unusual without hesitation.&quot;<span class=\"pg\">p.44<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;That&#x27;s not it. The more you feel the weight of the commander position, the more likely you are to miss what&#x27;s right under your nose. A commander from another class laughed, or got angry. Changes in the GPS that feels slightly…<span class=\"pg\">p.44<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;That&#x27;s true, which is why it can&#x27;t just be anyone. Let&#x27;s narrow it down to one person.&quot;<span class=\"pg\">p.44<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;That&#x27;s not it. The more you feel the weight of the commander position, the more likely you are to miss what&#x27;s right under your nose. A commander from another class laughed, or got angry. Changes in the GPS that feels slightly off but doesn&#x27;t seem worth mentioning. Please report anything that concerns you personally, Shimazaki.&quot;<span class=\"pg\">p.44<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;It doesn&#x27;t matter who, but let&#x27;s see. Let&#x27;s go with Shiraishi for now. That should make things easier for you as well.&quot;<span class=\"pg\">p.44<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;There&#x27;s no need to favor only Yoshida. To me, both of you are important friends.&quot;<span class=\"pg\">p.45<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;In other words, you can tell Shiraishi anything and everything, no matter what it is.&quot;<span class=\"pg\">p.45<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> Routes Shimazaki&#x27;s reports through Shiraishi deliberately — knowing he likes her, this raises their contact, and she is the VIP he reads most clearly.<span class=\"pg\">p.44–45<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Quietly matchmaking while optimizing command: uses the briefing to increase Shimazaki&#x27;s contact with Shiraishi under the guise of avoiding &quot;telephone game&quot; confusion.<span class=\"pg\">p.44–45<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shimazaki Ikkei<\/b> Briefs him on reporting; knows of his feelings for Shiraishi.<span class=\"pg\">p.44–45<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiraishi Asuka<\/b> Names her as the single reporting conduit; trusts her judgment most.<span class=\"pg\">p.44–45<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yoshida Kenta<\/b> Cites him as another important friend to defuse Shimazaki&#x27;s objection.<span class=\"pg\">p.45<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Safety goggles recommended at all times; sensors are on the gym uniform only, though hits register through a tracksuit.<span class=\"pg\">p.45<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p40-1\">← Before: Assigning roles: guard, not commander<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p46-1\">→ After: Ch.2 — depth read: the ambush and the alliance reveal<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p46-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"kitou-hayato hashimoto-masayoshi shiina-hiyori ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 2   depth read  the ambush and the alliance reveal  even if we were to pick up the pace  the enemy would find out within five minutes  if they knew we d quickened our movement  class a would do the same   yeah  if i determine the supplies are necessary  i ll go for them without hesitation   i believe this class s ultimate goal  the rank we should be aiming for  is second place   the reason is simple and clear  i m thinking we can give first place to ichinose s class   you could say a provisional agreement has been made  the other side is keen on it   everyone  run  now   the answer is quite simple  ryuuen s class deliberately kept its distance after the start to make it seem like they were avoiding engagement  rotates a magazine removed weapon to each vip as misdirection so enemies cannot identify vips by their lack of a gun  deduced ryuen s fake retreat   global gps shutdown ambush from the frozen position updates  is asked by him to confirm he aims to win  relies on his counterattack during the ambush  relays instructions and reports  both react to the ambush  vip in the front row  struggles to keep up during the retreat","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p46-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p46-1\">Ch.2 — depth read: the ambush and the alliance reveal<\/a><\/span><span class=\"meta\">Y3V3 · p.46–85<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/kitou-hayato.html\">Kitō Hayato<\/a> · <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a> · <a href=\"../../../people/shiina-hiyori.html\">Shiina Hiyori<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Even if we were to pick up the pace, the enemy would find out within five minutes. If they knew we&#x27;d quickened our movement, Class A would do the same.&quot;<span class=\"pg\">p.49<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Yeah. If I determine the supplies are necessary, I&#x27;ll go for them without hesitation.&quot;<span class=\"pg\">p.50<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;I believe this class&#x27;s ultimate goal, the rank we should be aiming for, is second place.&quot;<span class=\"pg\">p.64<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;The reason is simple and clear. I&#x27;m thinking we can give first place to Ichinose&#x27;s class.&quot;<span class=\"pg\">p.66<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You could say a provisional agreement has been made. The other side is keen on it.&quot;<span class=\"pg\">p.66<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Everyone, run! Now!&quot;<span class=\"pg\">p.69<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;The answer is quite simple. Ryuuen&#x27;s class deliberately kept its distance after the start to make it seem like they were avoiding engagement.&quot;<span class=\"pg\">p.72<\/span><\/li><li><span class=\"mlabel\">Tactic<\/span> Rotates a magazine-removed weapon to each VIP as misdirection so enemies cannot identify VIPs by their lack of a gun.<span class=\"pg\">p.60–62<\/span><\/li><li><span class=\"mlabel\">Tactic<\/span> Deduced Ryūen&#x27;s fake-retreat + Global GPS Shutdown ambush from the frozen position updates.<span class=\"pg\">p.72<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kitō Hayato<\/b> Is asked by him to confirm he aims to win; relies on his counterattack during the ambush.<span class=\"pg\">p.63–70<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Relays instructions and reports; both react to the ambush.<span class=\"pg\">p.46–73<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiina Hiyori<\/b> VIP in the front row; struggles to keep up during the retreat.<span class=\"pg\">p.52–74<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p44-1\">← Before: Briefing Shimazaki: report everything to Shiraishi<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p46-2\">→ After: The first reports: other classes&#x27; commanders and movements<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p46-2","v":"y3v3","y":3,"o":35,"k":"inner narration spoken","w":"ayanokouji-kiyotaka","q":"ayanokoji kiyotaka the first reports  other classes  commanders and movements leads class c north in scattered formation from e12 toward g8  head of the group  the self sacrifice declaration had a greater effect than expected  the first strategy is to head north and be first across g8  avoiding the pincer between ryuuen west and horikita east  commanders revealed  matsushita  a  kaneda  b  ichinose  d    only ichinose commands her own class  matsushita is a solid  fitting choice for class a s honor student makeup  kaneda is safe and unremarkable   unlikely to shine or blunder  first gps update  class b heading north into c11  class a in g11 also north  class d east toward j12   all avoiding early conflict   even if we were to pick up the pace  the enemy would find out within five minutes  if they knew we d quickened our movement  class a would do the same  that would be nothing more than an act that increases risk   that s the situation  i don t want to do anything that would give another class the chance to profit from our conflict   yeah  if i determine the supplies are necessary  i ll go for them without hesitation  cautious and controlling   refuses to quicken pace because the five minute gps update exposes it  commits to fighting for supplies if needed","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p46-2\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p46-2\">The first reports: other classes&#x27; commanders and movements<\/a><\/span><span class=\"meta\">Y3V3 · p.46–50<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Leads Class C north in scattered formation from E12 toward G8, head of the group.<\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Even if we were to pick up the pace, the enemy would find out within five minutes. If they knew we&#x27;d quickened our movement, Class A would do the same. That would be nothing more than an act that increases risk.&quot;<span class=\"pg\">p.49<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;That&#x27;s the situation. I don&#x27;t want to do anything that would give another class the chance to profit from our conflict.&quot;<span class=\"pg\">p.49<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Yeah. If I determine the supplies are necessary, I&#x27;ll go for them without hesitation.&quot;<span class=\"pg\">p.50<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> The self-sacrifice declaration had a greater effect than expected; the first strategy is to head north and be first across G8, avoiding the pincer between Ryuuen west and Horikita east.<span class=\"pg\">p.46<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> Commanders revealed: Matsushita (A), Kaneda (B), Ichinose (D) — only Ichinose commands her own class.<span class=\"pg\">p.47<\/span><\/li><li><span class=\"mlabel\">Inner voice<\/span> Matsushita is a solid, fitting choice for Class A&#x27;s honor-student makeup; Kaneda is safe and unremarkable — unlikely to shine or blunder.<span class=\"pg\">p.47<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> First GPS update: Class B heading north into C11, Class A in G11 also north, Class D east toward J12 — all avoiding early conflict.<span class=\"pg\">p.48<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Cautious and controlling — refuses to quicken pace because the five-minute GPS update exposes it; commits to fighting for supplies if needed.<span class=\"pg\">p.46–50<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p46-1\">← Before: Ch.2 — depth read: the ambush and the alliance reveal<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p51-1\">→ After: Halting for weapons practice; the Kōenji question<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y3v3-p46-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka ryuuen-kakeru hashimoto-masayoshi","q":"hashimoto masayoshi ch 2   depth read  hashimoto s reactions to the ambush  let s hear it   if ryuuen and his crew are heading for b10  that means they ll come out by the sea   ayanokouji kiyotaka said as much  but when push comes to shove  hashimoto masayoshi is our only choice   a surprise attack  huh  that bastard ryuuen  he took on a pretty big risk  didn t he  manages communications and the map  jokes about being the expulsion sacrifice  and reacts with a mix of frustration and admiration to ryuen s gambit  relays his instructions  notes his lack of fighting spirit  admires the risky surprise attack","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y3v3-p46-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hashimoto-masayoshi.html#sc-hashimoto-masayoshi-y3v3-p46-1\">Ch.2 — depth read: Hashimoto&#x27;s reactions to the ambush<\/a><\/span><span class=\"meta\">Y3V3 · p.46–85<\/span><span class=\"by\">notes on <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Let&#x27;s hear it.&quot;<span class=\"pg\">p.47<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;If Ryuuen and his crew are heading for B10, that means they&#x27;ll come out by the sea.&quot;<span class=\"pg\">p.50<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Ayanokouji Kiyotaka said as much, but when push comes to shove, Hashimoto Masayoshi is our only choice.&quot;<span class=\"pg\">p.58<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;A surprise attack, huh... That bastard Ryuuen, he took on a pretty big risk, didn&#x27;t he?&quot;<span class=\"pg\">p.73<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Manages communications and the map, jokes about being the expulsion sacrifice, and reacts with a mix of frustration and admiration to Ryūen&#x27;s gambit.<span class=\"pg\">p.46–73<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Relays his instructions; notes his lack of fighting spirit.<span class=\"pg\">p.46–73<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Admires the risky surprise attack.<span class=\"pg\">p.73<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p40-1\">← Before: Arguing for Ayanokōji as a guard<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p47-1\">→ After: Reading the reports and the map<\/button><\/div><\/article>"},{"i":"sc-kitou-hayato-y3v3-p46-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka kitou-hayato","q":"kito hayato ch 2   depth read  kitou s counterattack  let me confirm something  just to be sure  you re aiming to take first place in this exam  am i right to think that   a survival game  this feels like nothing more than playtime  but if we re aiming to win  i m going to take this seriously   in other words  you re not confident  during the surprise attack  takes cover behind a tree and counterattacks  taking out an enemy and halting the assault   showing skill despite never having fired in a real fight  intense and serious about winning  his intuition senses ayanokoji s lack of fighting spirit  and he acts decisively in the ambush  presses him for a commitment to win  backs up the retreat with his counterattack","h":"<article class=\"card\" id=\"sc-kitou-hayato-y3v3-p46-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kitou-hayato.html#sc-kitou-hayato-y3v3-p46-1\">Ch.2 — depth read: Kitou&#x27;s counterattack<\/a><\/span><span class=\"meta\">Y3V3 · p.46–85<\/span><span class=\"by\">notes on <a href=\"../../../people/kitou-hayato.html\">Kitō Hayato<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kitō Hayato<\/b> &quot;Let me confirm something, just to be sure. You&#x27;re aiming to take first place in this exam... Am I right to think that?&quot;<span class=\"pg\">p.63<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kitō Hayato<\/b> &quot;A survival game... This feels like nothing more than playtime, but if we&#x27;re aiming to win, I&#x27;m going to take this seriously.&quot;<span class=\"pg\">p.63<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kitō Hayato<\/b> &quot;...In other words, you&#x27;re not confident?&quot;<span class=\"pg\">p.63<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Feat<\/span> During the surprise attack, takes cover behind a tree and counterattacks, taking out an enemy and halting the assault — showing skill despite never having fired in a real fight.<span class=\"pg\">p.70<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Intense and serious about winning; his intuition senses Ayanokōji&#x27;s lack of fighting spirit, and he acts decisively in the ambush.<span class=\"pg\">p.63–70<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Presses him for a commitment to win; backs up the retreat with his counterattack.<span class=\"pg\">p.63–70<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kitou-hayato-y3v3-p55-1\">→ After: Placed in the front guard<\/button><\/div><\/article>"},{"i":"sc-morishita-ai-y3v3-p46-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka hashimoto-masayoshi morishita-ai","q":"morishita ai ch 2   depth read  morishita s complaints and exhaustion  i m not pleased with being placed in the middle row  ayanokouji kiyotaka  i m the main strength of this class   to demote me and place a traitor in the front row instead  it seems we ve been saddled with an incompetent leader   this special exam is on a deserted island  so the rewards are pretty huge  y know   hah  hah  i suppose this is because i ran a full marathon in the schoolyard yesterday  isn t it  hah  complains about her placement and calls others names  traitor   tissue paper  but lags furthest behind on the retreat   an  amazoness of the dense forest  who overexerts herself  complain about her middle row placement  calls him a traitor and argues with him","h":"<article class=\"card\" id=\"sc-morishita-ai-y3v3-p46-1\"><h3><span class=\"ttl\"><a href=\"../../../people/morishita-ai.html#sc-morishita-ai-y3v3-p46-1\">Ch.2 — depth read: Morishita&#x27;s complaints and exhaustion<\/a><\/span><span class=\"meta\">Y3V3 · p.46–85<\/span><span class=\"by\">notes on <a href=\"../../../people/morishita-ai.html\">Morishita Ai<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Morishita Ai<\/b> &quot;I&#x27;m not pleased with being placed in the middle row, Ayanokouji Kiyotaka. I&#x27;m the main strength of this class.&quot;<span class=\"pg\">p.56<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Morishita Ai<\/b> &quot;To demote me and place a traitor in the front row instead... It seems we&#x27;ve been saddled with an incompetent leader.&quot;<span class=\"pg\">p.56<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Morishita Ai<\/b> &quot;This special exam is on a deserted island, so the rewards are pretty huge, y&#x27;know.&quot;<span class=\"pg\">p.58<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Hah... hah... I suppose this is because I ran a full marathon in the schoolyard yesterday, isn&#x27;t it... hah.&quot;<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Complains about her placement and calls others names (traitor, &quot;tissue paper&quot;), but lags furthest behind on the retreat — an &quot;Amazoness of the Dense Forest&quot; who overexerts herself.<span class=\"pg\">p.56–74<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Complain about her middle-row placement.<span class=\"pg\">p.56<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Calls him a traitor and argues with him.<span class=\"pg\">p.56–58<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-morishita-ai-y3v3-p40-1\">← Before: Pushing for the commander to be chosen first; declining a guard role<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-morishita-ai-y3v3-p51-1\">→ After: Demanding weapons practice<\/button><\/div><\/article>"},{"i":"sc-nishikawa-ryouko-y3v3-p46-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"nishikawa-ryouko","q":"nishikawa ryoko the first radio relay receives the commander s first report as one of the three vips   a call from shimazaki kun  he found out who the other classes  commanders are   it s matsushita san for class a  kaneda kun for class b and ichinose san for class d  acts as radio relay between shimazaki and the class  juggling simultaneous requests from hashimoto and ayanokoji","h":"<article class=\"card\" id=\"sc-nishikawa-ryouko-y3v3-p46-1\"><h3><span class=\"ttl\"><a href=\"../../../people/nishikawa-ryouko.html#sc-nishikawa-ryouko-y3v3-p46-1\">The first radio relay<\/a><\/span><span class=\"meta\">Y3V3 · p.46–50<\/span><span class=\"by\">notes on <a href=\"../../../people/nishikawa-ryouko.html\">Nishikawa Ryōko<\/a><\/span><\/h3><p class=\"setup\">Receives the commander&#x27;s first report as one of the three VIPs.<\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Nishikawa Ryōko<\/b> &quot;A call from Shimazaki-kun. He found out who the other classes&#x27; commanders are.&quot;<span class=\"pg\">p.46<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nishikawa Ryōko<\/b> &quot;It&#x27;s Matsushita-san for Class A, Kaneda-kun for Class B and Ichinose-san for Class D.&quot;<span class=\"pg\">p.47<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Acts as radio relay between Shimazaki and the class, juggling simultaneous requests from Hashimoto and Ayanokōji.<span class=\"pg\">p.46–50<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nishikawa-ryouko-y3v3-p54-1\">→ After: Discovering the line is busy<\/button><\/div><\/article>"},{"i":"sc-shiraishi-asuka-y3v3-p46-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka shimazaki-ikkei shiraishi-asuka","q":"shiraishi asuka ch 2   depth read  shiraishi as vip and messenger  h9  on his own does that mean it s koenji   i was able to confirm that the gps at h9 is koenji kun s  his role is apparently a guard  acts as a vip and radio messenger to the commander  confirms koenji split off  struggles to keep up during the retreat and can t communicate due to exhaustion  relays reports and is placed in the front row as a vip  receives intel from him as commander  via radio","h":"<article class=\"card\" id=\"sc-shiraishi-asuka-y3v3-p46-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shiraishi-asuka.html#sc-shiraishi-asuka-y3v3-p46-1\">Ch.2 — depth read: Shiraishi as VIP and messenger<\/a><\/span><span class=\"meta\">Y3V3 · p.46–85<\/span><span class=\"by\">notes on <a href=\"../../../people/shiraishi-asuka.html\">Shiraishi Asuka<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/shimazaki-ikkei.html\">Shimazaki Ikkei<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shiraishi Asuka<\/b> &quot;H9? On his own?...Does that mean it&#x27;s Koenji?&quot;<span class=\"pg\">p.52<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiraishi Asuka<\/b> &quot;I was able to confirm that the GPS at H9 is Koenji-kun&#x27;s. His role is apparently a guard.&quot;<span class=\"pg\">p.55<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Acts as a VIP and radio messenger to the commander; confirms Koenji split off; struggles to keep up during the retreat and can&#x27;t communicate due to exhaustion.<span class=\"pg\">p.46–74<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Relays reports and is placed in the front row as a VIP.<span class=\"pg\">p.52–74<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shimazaki Ikkei<\/b> Receives intel from him as commander (via radio).<span class=\"pg\">p.46–74<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shiraishi-asuka-y3v3-p31-1\">← Before: The food problem makes running away impossible<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-shiraishi-asuka-y3v3-p52-1\">→ After: Confirming Kōenji; forming the formation<\/button><\/div><\/article>"},{"i":"sc-yoshida-kenta-y3v3-p46-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka yoshida-kenta","q":"yoshida kenta ch 2   depth read  yoshida s panic and questions  what the hell   so they used their one time only big move right from the get go   thinking about it normally  there was no way to defend against that surprise attack  was there  it s a flaw in the rules  urges learning to handle weapons before fighting  panics and grumbles at the surprise attack  calling it a rules flaw  argues for stopping to let class a pass and learn the guns","h":"<article class=\"card\" id=\"sc-yoshida-kenta-y3v3-p46-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yoshida-kenta.html#sc-yoshida-kenta-y3v3-p46-1\">Ch.2 — depth read: Yoshida&#x27;s panic and questions<\/a><\/span><span class=\"meta\">Y3V3 · p.46–85<\/span><span class=\"by\">notes on <a href=\"../../../people/yoshida-kenta.html\">Yoshida Kenta<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Yoshida Kenta<\/b> &quot;What the hell!&quot;<span class=\"pg\">p.72<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Yoshida Kenta<\/b> &quot;So they used their one-time-only big move right from the get-go...&quot;<span class=\"pg\">p.73<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Yoshida Kenta<\/b> &quot;Thinking about it normally, there was no way to defend against that surprise attack, was there...? It&#x27;s a flaw in the rules.&quot;<span class=\"pg\">p.74<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Urges learning to handle weapons before fighting; panics and grumbles at the surprise attack, calling it a rules flaw.<span class=\"pg\">p.51–74<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Argues for stopping to let Class A pass and learn the guns.<span class=\"pg\">p.51<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yoshida-kenta-y3v3-p51-1\">→ After: Urging a halt before the fight<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y3v3-p47-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"hashimoto-masayoshi","q":"hashimoto masayoshi reading the reports and the map steps closer to nishikawa to hear the commander s first report   let s hear it   if ryuuen and his crew are heading for b10  that means they ll come out by the sea   if by some chance they ambush us  we might not be able to get through   i think getting into a fight right now would be bad news  we should stop for a bit and let class a go on ahead  manages the map and radio traffic  reads the other classes  routes  and urges avoiding an early fight until the guns are mastered","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y3v3-p47-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hashimoto-masayoshi.html#sc-hashimoto-masayoshi-y3v3-p47-1\">Reading the reports and the map<\/a><\/span><span class=\"meta\">Y3V3 · p.47–51<\/span><span class=\"by\">notes on <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/span><\/h3><p class=\"setup\">Steps closer to Nishikawa to hear the commander&#x27;s first report.<\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Let&#x27;s hear it.&quot;<span class=\"pg\">p.47<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;If Ryuuen and his crew are heading for B10, that means they&#x27;ll come out by the sea.&quot;<span class=\"pg\">p.50<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;If by some chance they ambush us, we might not be able to get through...&quot;<span class=\"pg\">p.50<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I think getting into a fight right now would be bad news. We should stop for a bit and let Class A go on ahead.&quot;<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Manages the map and radio traffic, reads the other classes&#x27; routes, and urges avoiding an early fight until the guns are mastered.<span class=\"pg\">p.47–51<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p46-1\">← Before: Ch.2 — depth read: Hashimoto&#x27;s reactions to the ambush<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p52-1\">→ After: Doubts about the captain&#x27;s policy; Kōenji<\/button><\/div><\/article>"},{"i":"sc-takemoto-shigeru-y3v3-p48-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"takemoto-shigeru","q":"takemoto shigeru relaying the gps reports takes over the radio relay for the first gps update   he says we can relax for now  it looks like all of class b s gps signals are heading straight north  into area c11  and  uh  class a is apparently in g11  also to the north   but at least we ve confirmed that neither class a nor class b wants to fight from the get go  that alone isn t so bad   he says class d started walking toward j12  so  to the east  they plan on keeping their distance completely  a vip who relays the commander s reports and reads them accurately   notes all classes are avoiding early conflict","h":"<article class=\"card\" id=\"sc-takemoto-shigeru-y3v3-p48-1\"><h3><span class=\"ttl\"><a href=\"../../../people/takemoto-shigeru.html#sc-takemoto-shigeru-y3v3-p48-1\">Relaying the GPS reports<\/a><\/span><span class=\"meta\">Y3V3 · p.48–50<\/span><span class=\"by\">notes on <a href=\"../../../people/takemoto-shigeru.html\">Takemoto Shigeru<\/a><\/span><\/h3><p class=\"setup\">Takes over the radio relay for the first GPS update.<\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Takemoto Shigeru<\/b> &quot;He says we can relax for now. It looks like all of Class B&#x27;s GPS signals are heading straight north, into area C11. And, uh, Class A is apparently in G11, also to the north.&quot;<span class=\"pg\">p.48<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Takemoto Shigeru<\/b> &quot;But at least we&#x27;ve confirmed that neither Class A nor Class B wants to fight from the get-go. That alone isn&#x27;t so bad.&quot;<span class=\"pg\">p.48<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Takemoto Shigeru<\/b> &quot;He says Class D started walking toward J12, so, to the east. They plan on keeping their distance completely.&quot;<span class=\"pg\">p.48<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> A VIP who relays the commander&#x27;s reports and reads them accurately — notes all classes are avoiding early conflict.<span class=\"pg\">p.48–50<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-takemoto-shigeru-y3v3-p72-1\">→ After: During the retreat<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p51-1","v":"y3v3","y":3,"o":35,"k":"inner spoken","w":"ayanokouji-kiyotaka","q":"ayanokoji kiyotaka halting for weapons practice  the koenji question class stops to learn weapon handling as yoshida and morishita urge caution about fighting before they know the guns   it s not like i decided this because yoshida told me to  i was also thinking we should wait and see for a bit   ten minutes have passed and we ve gotten a small glimpse of each class s intentions  our primary objective was to pass through g8 first  but allow me to revise that  first  we ll learn how to properly handle our weapons here and once we re ready to fight  we ll check the gps positions again   i can t say for sure  but if anything  the usual koenji has no motivation  in almost every exam  he does as he pleases  last year s island was an exception to koenji s apathy because of his  complete freedom until graduation  bet with horikita  which she lost   he is now a free agent  but he could still be bought with points   have the commander identify the gps of the student who started acting alone   i don t mind  it s worth a try  let s use one as a test  has nishikawa test whether a second vip can contact the commander while she is speaking   confirms the line is one to one and busy when occupied   tell them i want to know the movements of the three classes every five minutes until the event starts   let s decide on our positions and formation for when the whole class moves together from now on   i considered that at one point  but i figured it s important to place someone who can react instantly in the rear precisely because she can  besides  shiraishi isn t good at raising her voice and it won t carry far  but nishikawa  on the other hand  has a loud voice  disperses the three vips across front middle rear rows and places fast responders to the rear so enemies can t wipe the class out at once  probing and efficient   uses the lull to gather intel  commander loopholes  radio line limits  koenji s identity  and locks down formation and communications","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p51-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p51-1\">Halting for weapons practice; the Kōenji question<\/a><\/span><span class=\"meta\">Y3V3 · p.51–56<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Class stops to learn weapon handling as Yoshida and Morishita urge caution about fighting before they know the guns.<\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;It&#x27;s not like I decided this because Yoshida told me to. I was also thinking we should wait and see for a bit.&quot;<span class=\"pg\">p.52<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Ten minutes have passed and we&#x27;ve gotten a small glimpse of each class&#x27;s intentions. Our primary objective was to pass through G8 first, but allow me to revise that. First, we&#x27;ll learn how to properly handle our weapons here and…<span class=\"pg\">p.52<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;I can&#x27;t say for sure, but if anything, the usual Koenji has no motivation. In almost every exam, he does as he pleases.&quot;<span class=\"pg\">p.53<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Ten minutes have passed and we&#x27;ve gotten a small glimpse of each class&#x27;s intentions. Our primary objective was to pass through G8 first, but allow me to revise that. First, we&#x27;ll learn how to properly handle our weapons here and once we&#x27;re ready to fight, we&#x27;ll check the GPS positions again.&quot;<span class=\"pg\">p.52<\/span><\/li><li><span class=\"mlabel\">Inner voice<\/span> Last year&#x27;s island was an exception to Kōenji&#x27;s apathy because of his &quot;complete freedom until graduation&quot; bet with Horikita, which she lost — he is now a free agent, but he could still be bought with points.<span class=\"pg\">p.53<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Have the commander identify the GPS of the student who started acting alone.&quot;<span class=\"pg\">p.54<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I don&#x27;t mind. It&#x27;s worth a try. Let&#x27;s use one as a test.&quot;<span class=\"pg\">p.54<\/span><\/li><li><span class=\"mlabel\">Inner voice<\/span> Has Nishikawa test whether a second VIP can contact the commander while she is speaking — confirms the line is one-to-one and busy when occupied.<span class=\"pg\">p.54<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Tell them I want to know the movements of the three classes every five minutes until the event starts.&quot;<span class=\"pg\">p.55<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Let&#x27;s decide on our positions and formation for when the whole class moves together from now on.&quot;<span class=\"pg\">p.55<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I considered that at one point, but I figured it&#x27;s important to place someone who can react instantly in the rear precisely because she can. Besides, Shiraishi isn&#x27;t good at raising her voice and it won&#x27;t carry far. But Nishikawa, on the other hand, has a loud voice.&quot;<span class=\"pg\">p.56<\/span><\/li><li><span class=\"mlabel\">Tactic<\/span> Disperses the three VIPs across front/middle/rear rows and places fast responders to the rear so enemies can&#x27;t wipe the class out at once.<span class=\"pg\">p.55–56<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Probing and efficient — uses the lull to gather intel (commander loopholes, radio line limits, Kōenji&#x27;s identity) and locks down formation and communications.<span class=\"pg\">p.51–56<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p46-2\">← Before: The first reports: other classes&#x27; commanders and movements<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p58-1\">→ After: The weapon lecture and the misdirection plan<\/button><\/div><\/article>"},{"i":"sc-morishita-ai-y3v3-p51-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"morishita-ai","q":"morishita ai demanding weapons practice  so why don t we get on with a lecture on how to handle weapons and stuff   i m in agreement with that opinion   that couldn t possibly be the case  it s merely that this morning  i had an excess of energy and repeatedly dashed through the ship at full speed for about an hour  perhaps that s why i ve accumulated some slight fatigue  pushes for weapons training while pretending her exhaustion comes from a burst of energy the previous morning   the self styled amazoness of the dense forest imposing a burden on herself","h":"<article class=\"card\" id=\"sc-morishita-ai-y3v3-p51-1\"><h3><span class=\"ttl\"><a href=\"../../../people/morishita-ai.html#sc-morishita-ai-y3v3-p51-1\">Demanding weapons practice<\/a><\/span><span class=\"meta\">Y3V3 · p.51<\/span><span class=\"by\">notes on <a href=\"../../../people/morishita-ai.html\">Morishita Ai<\/a><\/span><\/h3><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Morishita Ai<\/b> &quot;So why don&#x27;t we get on with a lecture on how to handle weapons and stuff?&quot;<span class=\"pg\">p.51<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Morishita Ai<\/b> &quot;I&#x27;m in agreement with that opinion.&quot;<span class=\"pg\">p.51<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Morishita Ai<\/b> &quot;That couldn&#x27;t possibly be the case. It&#x27;s merely that this morning, I had an excess of energy and repeatedly dashed through the ship at full speed for about an hour. Perhaps that&#x27;s why I&#x27;ve accumulated some slight fatigue.&quot;<span class=\"pg\">p.51<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Pushes for weapons training while pretending her exhaustion comes from a burst of energy the previous morning — the self-styled Amazoness of the Dense Forest imposing a burden on herself.<span class=\"pg\">p.51<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-morishita-ai-y3v3-p46-1\">← Before: Ch.2 — depth read: Morishita&#x27;s complaints and exhaustion<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-morishita-ai-y3v3-p56-1\">→ After: Complaining about her formation placement<\/button><\/div><\/article>"},{"i":"sc-yoshida-kenta-y3v3-p51-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"yoshida-kenta","q":"yoshida kenta urging a halt before the fight approaches ayanokoji as the class nears g8   if you decide to fight  i ll follow you  but  isn t there something we should be doing first  we don t even really know how to use these guns yet  voices the class s shared concern   he will follow ayanokoji into a fight but wants weapons practice first","h":"<article class=\"card\" id=\"sc-yoshida-kenta-y3v3-p51-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yoshida-kenta.html#sc-yoshida-kenta-y3v3-p51-1\">Urging a halt before the fight<\/a><\/span><span class=\"meta\">Y3V3 · p.51<\/span><span class=\"by\">notes on <a href=\"../../../people/yoshida-kenta.html\">Yoshida Kenta<\/a><\/span><\/h3><p class=\"setup\">Approaches Ayanokōji as the class nears G8.<\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Yoshida Kenta<\/b> &quot;If you decide to fight, I&#x27;ll follow you. But, isn&#x27;t there something we should be doing first? We don&#x27;t even really know how to use these guns yet.&quot;<span class=\"pg\">p.51<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Voices the class&#x27;s shared concern — he will follow Ayanokōji into a fight but wants weapons practice first.<span class=\"pg\">p.51<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yoshida-kenta-y3v3-p46-1\">← Before: Ch.2 — depth read: Yoshida&#x27;s panic and questions<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yoshida-kenta-y3v3-p72-1\">→ After: Panic after the ambush<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y3v3-p52-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka hashimoto-masayoshi","q":"hashimoto masayoshi doubts about the captain s policy  koenji is surprised how easily ayanokoji agrees to let class a pass   are you for real  you agreed to that pretty easily   what  is that right  then i guess this is your decision  ayanokouji   i9  damn  he s fast   nah  we shouldn t use it yet  this could be a strategy to get us to waste one of our tactics   so it s that guy  huh  let s just pray he goofs around for a bit and then calls it quits  loyal but uneasy   wants a clear fighting policy  misreads the koenji split off as a reason to save tactics  and is proven wrong when identity check confirms it  is reassured when the wait and see decision is framed as ayanokoji s own","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y3v3-p52-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hashimoto-masayoshi.html#sc-hashimoto-masayoshi-y3v3-p52-1\">Doubts about the captain&#x27;s policy; Kōenji<\/a><\/span><span class=\"meta\">Y3V3 · p.52–55<\/span><span class=\"by\">notes on <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/span><\/h3><p class=\"setup\">Is surprised how easily Ayanokōji agrees to let Class A pass.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Are you for real? You agreed to that pretty easily.&quot;<span class=\"pg\">p.52<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;What, is that right? Then I guess this is your decision, Ayanokouji.&quot;<span class=\"pg\">p.52<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;I9? Damn, he&#x27;s fast.&quot;<span class=\"pg\">p.53<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Nah, we shouldn&#x27;t use it yet. This could be a strategy to get us to waste one of our tactics.&quot;<span class=\"pg\">p.54<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;So it&#x27;s that guy, huh. Let&#x27;s just pray he goofs around for a bit and then calls it quits.&quot;<span class=\"pg\">p.55<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Loyal but uneasy — wants a clear fighting policy, misreads the Kōenji split-off as a reason to save tactics, and is proven wrong when Identity Check confirms it.<span class=\"pg\">p.52–55<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is reassured when the wait-and-see decision is framed as Ayanokōji&#x27;s own.<span class=\"pg\">p.52<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p47-1\">← Before: Reading the reports and the map<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p63-1\">→ After: The alliance bombshell and its defense<\/button><\/div><\/article>"},{"i":"sc-shiraishi-asuka-y3v3-p52-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"shiraishi-asuka","q":"shiraishi asuka confirming koenji  forming the formation  h9  on his own does that mean it s koenji   i was able to confirm that the gps at h9 is koenji kun s  his role is apparently a guard   understood  for now  let s move on to the next matter  identifies the isolated gps as koenji and confirms the identity check result  then approaches ayanokoji as the next report comes in","h":"<article class=\"card\" id=\"sc-shiraishi-asuka-y3v3-p52-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shiraishi-asuka.html#sc-shiraishi-asuka-y3v3-p52-1\">Confirming Kōenji; forming the formation<\/a><\/span><span class=\"meta\">Y3V3 · p.52–55<\/span><span class=\"by\">notes on <a href=\"../../../people/shiraishi-asuka.html\">Shiraishi Asuka<\/a><\/span><\/h3><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shiraishi Asuka<\/b> &quot;H9? On his own?...Does that mean it&#x27;s Koenji?&quot;<span class=\"pg\">p.52<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiraishi Asuka<\/b> &quot;I was able to confirm that the GPS at H9 is Koenji-kun&#x27;s. His role is apparently a guard.&quot;<span class=\"pg\">p.55<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiraishi Asuka<\/b> &quot;Understood. For now, let&#x27;s move on to the next matter.&quot;<span class=\"pg\">p.55<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Identifies the isolated GPS as Kōenji and confirms the Identity Check result, then approaches Ayanokōji as the next report comes in.<span class=\"pg\">p.52–55<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shiraishi-asuka-y3v3-p46-1\">← Before: Ch.2 — depth read: Shiraishi as VIP and messenger<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-shiraishi-asuka-y3v3-p59-1\">→ After: Relaying the commander&#x27;s loophole findings<\/button><\/div><\/article>"},{"i":"sc-sanada-kousei-y3v3-p53-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"sanada-kousei","q":"sanada kosei sanada suggests using identity check  wouldn t it be a good idea to have the commander use a tactic  proposes spending a tactic to identify the student splitting off toward h9  ayanokoji declines for now","h":"<article class=\"card\" id=\"sc-sanada-kousei-y3v3-p53-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sanada-kousei.html#sc-sanada-kousei-y3v3-p53-1\">Sanada suggests using Identity Check<\/a><\/span><span class=\"meta\">Y3V3 · p.53<\/span><span class=\"by\">notes on <a href=\"../../../people/sanada-kousei.html\">Sanada Kōsei<\/a><\/span><\/h3><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sanada Kōsei<\/b> &quot;Wouldn&#x27;t it be a good idea to have the commander use a tactic?&quot;<span class=\"pg\">p.53<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Proposes spending a tactic to identify the student splitting off toward H9; Ayanokōji declines for now.<span class=\"pg\">p.53<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sanada-kousei-y3v3-p35-1\">← Before: The role assignment discussion<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sanada-kousei-y3v3-p103-1\">→ After: Sanada reads the final drop locations<\/button><\/div><\/article>"},{"i":"sc-nishikawa-ryouko-y3v3-p54-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka shiraishi-asuka nishikawa-ryouko","q":"nishikawa ryoko discovering the line is busy is asked to contact shimazaki while he is already speaking to shiraishi   huh  now  isn t he still talking to asuka   mm  okay   it s not connecting   oh  so that s it  that s what you wanted to find out   so there really is something to report  okay  what should i tell them  quick to realize ayanokoji was probing the radio s one to one limitation  not actually trying to reach the commander  runs his test of the commander radio line  notes shimazaki is already speaking to her  asuka","h":"<article class=\"card\" id=\"sc-nishikawa-ryouko-y3v3-p54-1\"><h3><span class=\"ttl\"><a href=\"../../../people/nishikawa-ryouko.html#sc-nishikawa-ryouko-y3v3-p54-1\">Discovering the line is busy<\/a><\/span><span class=\"meta\">Y3V3 · p.54–55<\/span><span class=\"by\">notes on <a href=\"../../../people/nishikawa-ryouko.html\">Nishikawa Ryōko<\/a><\/span><\/h3><p class=\"setup\">Is asked to contact Shimazaki while he is already speaking to Shiraishi.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/shiraishi-asuka.html\">Shiraishi Asuka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Nishikawa Ryōko<\/b> &quot;Huh? Now? Isn&#x27;t he still talking to Asuka?&quot;<span class=\"pg\">p.54<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nishikawa Ryōko<\/b> &quot;Mm, okay.&quot;<span class=\"pg\">p.54<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nishikawa Ryōko<\/b> &quot;It&#x27;s not connecting.&quot;<span class=\"pg\">p.54<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Oh, so that&#x27;s it... That&#x27;s what you wanted to find out.&quot;<span class=\"pg\">p.54<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;So there really is something to report. Okay, what should I tell them?&quot;<span class=\"pg\">p.55<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Quick to realize Ayanokōji was probing the radio&#x27;s one-to-one limitation, not actually trying to reach the commander.<span class=\"pg\">p.54–55<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Runs his test of the commander radio line.<span class=\"pg\">p.54–55<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiraishi Asuka<\/b> Notes Shimazaki is already speaking to her (&quot;Asuka&quot;).<span class=\"pg\">p.54<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nishikawa-ryouko-y3v3-p46-1\">← Before: The first radio relay<\/button><\/div><\/article>"},{"i":"sc-kitou-hayato-y3v3-p55-1","v":"y3v3","y":3,"o":35,"k":"","w":"kitou-hayato","q":"kito hayato placed in the front guard assigned to the front row as a main guard protecting the rear  recognized by ayanokoji as one of the few students skilled in combat  placed in the front guard row","h":"<article class=\"card\" id=\"sc-kitou-hayato-y3v3-p55-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kitou-hayato.html#sc-kitou-hayato-y3v3-p55-1\">Placed in the front guard<\/a><\/span><span class=\"meta\">Y3V3 · p.55–56<\/span><span class=\"by\">notes on <a href=\"../../../people/kitou-hayato.html\">Kitō Hayato<\/a><\/span><\/h3><p class=\"setup\">Assigned to the front row as a main guard protecting the rear.<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Recognized by Ayanokōji as one of the few students skilled in combat, placed in the front guard row.<span class=\"pg\">p.55<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kitou-hayato-y3v3-p46-1\">← Before: Ch.2 — depth read: Kitou&#x27;s counterattack<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kitou-hayato-y3v3-p63-1\">→ After: Demanding a commitment to win<\/button><\/div><\/article>"},{"i":"sc-morishita-ai-y3v3-p56-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"hashimoto-masayoshi yamamura-miki morishita-ai","q":"morishita ai complaining about her formation placement approaches ayanokoji  weapon in hand  angry at being placed in the middle row   i m not pleased with being placed in the middle row  ayanokouji kiyotaka  i m the main strength of this class   to demote me and place a traitor in the front row instead  it seems we ve been saddled with an incompetent leader  let us go  yamamura miki   oh  so in addition to a traitor  you ve appointed tissue paper to the front row  you are beyond saving   the exam s only just begun  there s no need to rush  loudly complains about her placement  insults hashimoto and yamamura  yet sits down for a  complete break  and tells the impatient hashimoto there is no rush   more bluster than action  calls him a traitor for being in the front row  drags her along  calling her  tissue paper","h":"<article class=\"card\" id=\"sc-morishita-ai-y3v3-p56-1\"><h3><span class=\"ttl\"><a href=\"../../../people/morishita-ai.html#sc-morishita-ai-y3v3-p56-1\">Complaining about her formation placement<\/a><\/span><span class=\"meta\">Y3V3 · p.56–58<\/span><span class=\"by\">notes on <a href=\"../../../people/morishita-ai.html\">Morishita Ai<\/a><\/span><\/h3><p class=\"setup\">Approaches Ayanokōji, weapon in hand, angry at being placed in the middle row.<\/p><p class=\"with\">with <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a> · <a href=\"../../../people/yamamura-miki.html\">Yamamura Miki<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Morishita Ai<\/b> &quot;I&#x27;m not pleased with being placed in the middle row, Ayanokouji Kiyotaka. I&#x27;m the main strength of this class.&quot;<span class=\"pg\">p.56<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Morishita Ai<\/b> &quot;To demote me and place a traitor in the front row instead... It seems we&#x27;ve been saddled with an incompetent leader. Let us go, Yamamura Miki.&quot;<span class=\"pg\">p.56<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Morishita Ai<\/b> &quot;Oh? So in addition to a traitor, you&#x27;ve appointed tissue paper to the front row. You are beyond saving.&quot;<span class=\"pg\">p.56<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;The exam&#x27;s only just begun. There&#x27;s no need to rush.&quot;<span class=\"pg\">p.58<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Loudly complains about her placement, insults Hashimoto and Yamamura, yet sits down for a &quot;complete break&quot; and tells the impatient Hashimoto there is no rush — more bluster than action.<span class=\"pg\">p.56–58<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Calls him a traitor for being in the front row.<span class=\"pg\">p.56<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamamura Miki<\/b> Drags her along, calling her &quot;tissue paper.&quot;<span class=\"pg\">p.56<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-morishita-ai-y3v3-p51-1\">← Before: Demanding weapons practice<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-morishita-ai-y3v3-p66-1\">→ After: Doubting the alliance and Hashimoto<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p58-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"toba-shigeru kitou-hayato ayanokouji-kiyotaka","q":"ayanokoji kiyotaka the weapon lecture and the misdirection plan has shimazaki check what commanders can and cannot do   direct contact and messages are banned  screenshots are blacked out  but gps markers can be annotated   i had him look into it because i thought there might be things he could do outside of his official authority as commander  but it seems they re being monitored more strictly than i anticipated   that s why i m going to take the time now to properly lecture you all on how to use these weapons   then  after the lecture  i want one of the guards who isn t confident in their fighting ability to temporarily give their weapon to one of the three vips  one after another   one method for identifying another class s vip is to see if they can use a weapon  if we get into an unexpected fight  it s entirely conceivable that they ll prioritize targeting any student without one   the firing chamber basically  there might be cases where a round remains inside even after you remove the magazine   regarding this type of firearm  ijuuin from horikita s class is very knowledgeable and he taught me a few things in the past  his firearms knowledge actually comes from the white room  the ijuuin story is a cover toba cannot verify  rotates a magazine removed  chamber checked weapon among the vips as misdirection so enemies cannot identify them by their lack of a gun  teaches him to check the chamber  notes he is athletic and a capable fighter  is pressed by him for a commitment to win","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p58-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p58-1\">The weapon lecture and the misdirection plan<\/a><\/span><span class=\"meta\">Y3V3 · p.58–63<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Has Shimazaki check what commanders can and cannot do — direct contact and messages are banned, screenshots are blacked out, but GPS markers can be annotated.<\/p><p class=\"with\">with <a href=\"../../../people/index.html#toba-shigeru\">Toba Shigeru<\/a> · <a href=\"../../../people/kitou-hayato.html\">Kitō Hayato<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;I had him look into it because I thought there might be things he could do outside of his official authority as commander, but it seems they&#x27;re being monitored more strictly than I anticipated.&quot;<span class=\"pg\">p.59<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;That&#x27;s why I&#x27;m going to take the time now to properly lecture you all on how to use these weapons.&quot;<span class=\"pg\">p.60<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Then, after the lecture, I want one of the guards who isn&#x27;t confident in their fighting ability to temporarily give their weapon to one of the three VIPs, one after another.&quot;<span class=\"pg\">p.60<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;One method for identifying another class&#x27;s VIP is to see if they can use a weapon. If we get into an unexpected fight, it&#x27;s entirely conceivable that they&#x27;ll prioritize targeting any student without one.&quot;<span class=\"pg\">p.60<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;The firing chamber—basically, there might be cases where a round remains inside even after you remove the magazine.&quot;<span class=\"pg\">p.62<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Regarding this type of firearm, Ijuuin from Horikita&#x27;s class is very knowledgeable and he taught me a few things in the past.&quot;<span class=\"pg\">p.62<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> His firearms knowledge actually comes from the White Room; the Ijuuin story is a cover Toba cannot verify.<span class=\"pg\">p.62<\/span><\/li><li><span class=\"mlabel\">Tactic<\/span> Rotates a magazine-removed, chamber-checked weapon among the VIPs as misdirection so enemies cannot identify them by their lack of a gun.<span class=\"pg\">p.60–62<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Toba Shigeru<\/b> Teaches him to check the chamber; notes he is athletic and a capable fighter.<span class=\"pg\">p.60–62<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kitō Hayato<\/b> Is pressed by him for a commitment to win.<span class=\"pg\">p.63<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p51-1\">← Before: Halting for weapons practice; the Kōenji question<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p64-1\">→ After: Announcing the alliance; postponing the vote<\/button><\/div><\/article>"},{"i":"sc-shiraishi-asuka-y3v3-p59-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"shimazaki-ikkei shiraishi-asuka","q":"shiraishi asuka relaying the commander s loophole findings relays a report from shimazaki about the commander s restrictions   apparently  the commanders were informed that during the special exam  direct contact  private conversations and any message like exchanges are prohibited  and the tablet s screenshot function is disabled  even if you try to use it  it will only save a completely black screen as the picture that s what he said   also  it seems the gps on the tablet s map has individual tags  and he found out it s possible to take notes on the gps of students from other classes  so  he said he made sure to put koenji kun s name on the gps marker at i9  where he s isolated  passes on detailed commander intel   the monitoring restrictions and the gps annotation trick that lets them track koenji by name  relays his findings about commander loopholes","h":"<article class=\"card\" id=\"sc-shiraishi-asuka-y3v3-p59-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shiraishi-asuka.html#sc-shiraishi-asuka-y3v3-p59-1\">Relaying the commander&#x27;s loophole findings<\/a><\/span><span class=\"meta\">Y3V3 · p.59<\/span><span class=\"by\">notes on <a href=\"../../../people/shiraishi-asuka.html\">Shiraishi Asuka<\/a><\/span><\/h3><p class=\"setup\">Relays a report from Shimazaki about the commander&#x27;s restrictions.<\/p><p class=\"with\">with <a href=\"../../../people/shimazaki-ikkei.html\">Shimazaki Ikkei<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shiraishi Asuka<\/b> &quot;Apparently, the commanders were informed that during the special exam, direct contact, private conversations and any message-like exchanges are prohibited. And the tablet&#x27;s screenshot function is disabled; even if you try to use…<span class=\"pg\">p.59<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiraishi Asuka<\/b> &quot;Also, it seems the GPS on the tablet&#x27;s map has individual tags, and he found out it&#x27;s possible to take notes on the GPS of students from other classes. So, he said he made sure to put Koenji-kun&#x27;s name on the GPS marker at I9…<span class=\"pg\">p.59<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Apparently, the commanders were informed that during the special exam, direct contact, private conversations and any message-like exchanges are prohibited. And the tablet&#x27;s screenshot function is disabled; even if you try to use it, it will only save a completely black screen as the picture—that&#x27;s what he said.&quot;<span class=\"pg\">p.59<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Also, it seems the GPS on the tablet&#x27;s map has individual tags, and he found out it&#x27;s possible to take notes on the GPS of students from other classes. So, he said he made sure to put Koenji-kun&#x27;s name on the GPS marker at I9, where he&#x27;s isolated.&quot;<span class=\"pg\">p.59<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Passes on detailed commander intel — the monitoring restrictions and the GPS annotation trick that lets them track Kōenji by name.<span class=\"pg\">p.59<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shimazaki Ikkei<\/b> Relays his findings about commander loopholes.<span class=\"pg\">p.59<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shiraishi-asuka-y3v3-p52-1\">← Before: Confirming Kōenji; forming the formation<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-shiraishi-asuka-y3v3-p117-1\">→ After: Depth review: Class C&#x27;s recon commander<\/button><\/div><\/article>"},{"i":"sc-toba-shigeru-y3v3-p60-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka toba-shigeru","q":"toba shigeru learning the weapon check  sizing up ayanokoji realizes why ayanokoji wants guards to hand weapons to vips   what do you mean by that  the vips are forbidden from using weapons  right  no  is that exactly why   you re awfully knowledgeable about this stuff  you look like you belong holding a weapon  too   is that so  in that case  they ll probably adopt a similar strategy  of course   anyway  i understand the aim  i should also practice when i have some free time  right  quick to grasp the misdirection plan and observant of ayanokoji s firearms skill  athletic and a capable fighter  he steps forward proactively to practice  learns the magazine chamber check from him and accepts the cover story that ijuuin taught him about guns","h":"<article class=\"card\" id=\"sc-toba-shigeru-y3v3-p60-1\"><h3><span class=\"ttl\">Learning the weapon check; sizing up Ayanokōji<\/span><span class=\"meta\">Y3V3 · p.60–62<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#toba-shigeru\">Toba Shigeru<\/a><\/span><\/h3><p class=\"setup\">Realizes why Ayanokōji wants guards to hand weapons to VIPs.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Toba Shigeru<\/b> &quot;What do you mean by that? The VIPs are forbidden from using weapons, right? No... is that exactly why...?&quot;<span class=\"pg\">p.60<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Toba Shigeru<\/b> &quot;...You&#x27;re awfully knowledgeable about this stuff. You look like you belong holding a weapon, too.&quot;<span class=\"pg\">p.62<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Toba Shigeru<\/b> &quot;Is that so... In that case, they&#x27;ll probably adopt a similar strategy, of course.&quot;<span class=\"pg\">p.62<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Anyway, I understand the aim. I should also practice when I have some free time, right?&quot;<span class=\"pg\">p.62<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Quick to grasp the misdirection plan and observant of Ayanokōji&#x27;s firearms skill; athletic and a capable fighter, he steps forward proactively to practice.<span class=\"pg\">p.60–62<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Learns the magazine/chamber check from him and accepts the cover story that Ijuuin taught him about guns.<span class=\"pg\">p.60–62<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-hashimoto-masayoshi-y3v3-p63-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka hashimoto-masayoshi","q":"hashimoto masayoshi the alliance bombshell and its defense cuts in when kitou presses ayanokoji for a commitment to win   ayanokouji is betting his own expulsion on this  you know  of course he s going to play for real   hey  ayanokouji   you should probably stop talking about that here  no matter how you look at it  now s not the time   if class d is on our side  we can focus just on class a and class b  huh   i think it s a good idea  it d be no laughing matter if we gave it our all and ended up in last  or third place at best   how about we discipline them  the only class member already in on the alliance   tries to stop ayanokoji announcing it at the wrong moment  then argues its merits and offers to discipline the critics  whispers urgently that the timing is wrong  ayanokoji ignores him","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y3v3-p63-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hashimoto-masayoshi.html#sc-hashimoto-masayoshi-y3v3-p63-1\">The alliance bombshell and its defense<\/a><\/span><span class=\"meta\">Y3V3 · p.63–68<\/span><span class=\"by\">notes on <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/span><\/h3><p class=\"setup\">Cuts in when Kitou presses Ayanokōji for a commitment to win.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Ayanokouji is betting his own expulsion on this, you know? Of course he&#x27;s going to play for real.&quot;<span class=\"pg\">p.63<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Hey, Ayanokouji...&quot;<span class=\"pg\">p.65<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;You should probably stop talking about that here. No matter how you look at it, now&#x27;s not the time...&quot;<span class=\"pg\">p.65<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;If Class D is on our side, we can focus just on Class A and Class B... huh.&quot;<span class=\"pg\">p.66<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I think it&#x27;s a good idea. It&#x27;d be no laughing matter if we gave it our all and ended up in last, or third place at best.&quot;<span class=\"pg\">p.66<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;How about we discipline them?&quot;<span class=\"pg\">p.67<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> The only class member already in on the alliance — tries to stop Ayanokōji announcing it at the wrong moment, then argues its merits and offers to discipline the critics.<span class=\"pg\">p.63–68<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Whispers urgently that the timing is wrong; Ayanokōji ignores him.<span class=\"pg\">p.65<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p52-1\">← Before: Doubts about the captain&#x27;s policy; Kōenji<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p69-1\">→ After: The ambush: shouting to the class<\/button><\/div><\/article>"},{"i":"sc-kitou-hayato-y3v3-p63-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka kitou-hayato","q":"kito hayato demanding a commitment to win  let me confirm something  just to be sure  you re aiming to take first place in this exam  am i right to think that   a survival game  this feels like nothing more than playtime  but if we re aiming to win  i m going to take this seriously   in other words  you re not confident  intense and serious   suspicious of ayanokoji s lack of fighting spirit and presses him for a commitment to win  his eyes sharpening at the evasive answer  confronts him about aiming for first place  unsettled when he says he cannot meet that expectation","h":"<article class=\"card\" id=\"sc-kitou-hayato-y3v3-p63-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kitou-hayato.html#sc-kitou-hayato-y3v3-p63-1\">Demanding a commitment to win<\/a><\/span><span class=\"meta\">Y3V3 · p.63–64<\/span><span class=\"by\">notes on <a href=\"../../../people/kitou-hayato.html\">Kitō Hayato<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kitō Hayato<\/b> &quot;...Let me confirm something, just to be sure. You&#x27;re aiming to take first place in this exam... Am I right to think that?&quot;<span class=\"pg\">p.63<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kitō Hayato<\/b> &quot;A survival game... This feels like nothing more than playtime, but if we&#x27;re aiming to win, I&#x27;m going to take this seriously.&quot;<span class=\"pg\">p.63<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kitō Hayato<\/b> &quot;...In other words, you&#x27;re not confident?&quot;<span class=\"pg\">p.63<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Intense and serious — suspicious of Ayanokōji&#x27;s lack of fighting spirit and presses him for a commitment to win, his eyes sharpening at the evasive answer.<span class=\"pg\">p.63–64<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Confronts him about aiming for first place; unsettled when he says he cannot meet that expectation.<span class=\"pg\">p.63–64<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kitou-hayato-y3v3-p55-1\">← Before: Placed in the front guard<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kitou-hayato-y3v3-p70-1\">→ After: Counterattacking during the ambush<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p64-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"hashimoto-masayoshi matoba-shinji ayanokouji-kiyotaka","q":"ayanokoji kiyotaka announcing the alliance  postponing the vote addresses the whole class after kitou s question and reveals the true aim   i believe this class s ultimate goal  the rank we should be aiming for  is second place   the reason is simple and clear  i m thinking we can give first place to ichinose s class   i transferred to raise this class to class a  but given that the hurdle is actually very high  we must use a strategy to win efficiently   that strategy  i believe  lies in an alliance with ichinose s class   in this survival exam  we re supposed to be fighting three other classes  that means we re facing nearly 120 enemies  but an alliance can change that premise   you can refuse or rather  reject the idea but it s not something we can pick up and drop as we please   look  we re not going to form an alliance just from this one discussion  there s no way  that said  i m not going to reject the idea out of hand  either   my bad for bringing this up so suddenly  like matoba and the others said  let s talk about the alliance again after this special exam is over  for now  just forget we had this conversation  introduces the c d alliance deliberately when the class is desperate  then withdraws the immediate vote   a big step toward making them accept it later  the backlash is expected and welcomed  a single change in perspective can overturn it  and postponing is not the same as abandoning  he tries to interrupt and whisper that now is the wrong time  ayanokoji ignores him and says it anyway  faces his criticism of the  selfish proposition  and lets him think he has won the postponement","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p64-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p64-1\">Announcing the alliance; postponing the vote<\/a><\/span><span class=\"meta\">Y3V3 · p.64–68<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Addresses the whole class after Kitou&#x27;s question and reveals the true aim.<\/p><p class=\"with\">with <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a> · <a href=\"../../../people/matoba-shinji.html\">Matoba Shinji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;I believe this class&#x27;s ultimate goal, the rank we should be aiming for, is second place.&quot;<span class=\"pg\">p.64<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;The reason is simple and clear. I&#x27;m thinking we can give first place to Ichinose&#x27;s class.&quot;<span class=\"pg\">p.64<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;I transferred to raise this class to Class A. But given that the hurdle is actually very high, we must use a strategy to win efficiently.&quot;<span class=\"pg\">p.65<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;That strategy, I believe, lies in an alliance with Ichinose&#x27;s class.&quot;<span class=\"pg\">p.65<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;In this survival exam, we&#x27;re supposed to be fighting three other classes. That means we&#x27;re facing nearly 120 enemies, but an alliance can change that premise.&quot;<span class=\"pg\">p.66<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You can refuse—or rather, reject the idea—but it&#x27;s not something we can pick up and drop as we please.&quot;<span class=\"pg\">p.67<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Look, we&#x27;re not going to form an alliance just from this one discussion. There&#x27;s no way. That said, I&#x27;m not going to reject the idea out of hand, either.&quot;<span class=\"pg\">p.68<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;My bad for bringing this up so suddenly. Like Matoba and the others said, let&#x27;s talk about the alliance again after this special exam is over. For now, just forget we had this conversation.&quot;<span class=\"pg\">p.68<\/span><\/li><li><span class=\"mlabel\">Tactic<\/span> Introduces the C–D alliance deliberately when the class is desperate, then withdraws the immediate vote — a big step toward making them accept it later.<span class=\"pg\">p.65–68<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> The backlash is expected and welcomed; a single change in perspective can overturn it, and postponing is not the same as abandoning.<span class=\"pg\">p.68<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> He tries to interrupt and whisper that now is the wrong time; Ayanokōji ignores him and says it anyway.<span class=\"pg\">p.65<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Matoba Shinji<\/b> Faces his criticism of the &quot;selfish proposition&quot; and lets him think he has won the postponement.<span class=\"pg\">p.67–68<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p58-1\">← Before: The weapon lecture and the misdirection plan<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p68-1\">→ After: The surprise attack and the retreat<\/button><\/div><\/article>"},{"i":"sc-shimizu-naoki-y3v3-p64-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"shimizu-naoki","q":"shimizu naoki first to object to aiming for second  second place  i mean  i wouldn t say it s a bad goal  but what s the deal with aiming for that right from the start  the first to voice dissatisfaction at aiming for second   an orthodox honors student who cannot hide his objection to the passive target","h":"<article class=\"card\" id=\"sc-shimizu-naoki-y3v3-p64-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shimizu-naoki.html#sc-shimizu-naoki-y3v3-p64-1\">First to object to aiming for second<\/a><\/span><span class=\"meta\">Y3V3 · p.64<\/span><span class=\"by\">notes on <a href=\"../../../people/shimizu-naoki.html\">Shimizu Naoki<\/a><\/span><\/h3><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shimizu Naoki<\/b> &quot;Second place? I mean, I wouldn&#x27;t say it&#x27;s a bad goal, but what&#x27;s the deal with aiming for that right from the start?&quot;<span class=\"pg\">p.64<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> The first to voice dissatisfaction at aiming for second — an orthodox honors student who cannot hide his objection to the passive target.<span class=\"pg\">p.64<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-matoba-shinji-y3v3-p66-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka matoba-shinji","q":"matoba shinji criticizing the alliance as class c groveling  that s a pretty selfish proposition   i agree  so basically  we re the ones who have to suck up and bring them a gift  right  dumbfounded and resentful   reads the alliance as class c groveling to class d and objects to giving up the top position  nods emphatically when ayanokoji agrees to postpone the vote  his anger subsides when the alliance decision is deferred until after the exam","h":"<article class=\"card\" id=\"sc-matoba-shinji-y3v3-p66-1\"><h3><span class=\"ttl\"><a href=\"../../../people/matoba-shinji.html#sc-matoba-shinji-y3v3-p66-1\">Criticizing the alliance as Class C groveling<\/a><\/span><span class=\"meta\">Y3V3 · p.66–68<\/span><span class=\"by\">notes on <a href=\"../../../people/matoba-shinji.html\">Matoba Shinji<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Matoba Shinji<\/b> &quot;That&#x27;s a pretty selfish proposition.&quot;<span class=\"pg\">p.67<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Matoba Shinji<\/b> &quot;I agree. So basically, we&#x27;re the ones who have to suck up and bring them a gift, right?&quot;<span class=\"pg\">p.67<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Dumbfounded and resentful — reads the alliance as Class C groveling to Class D and objects to giving up the top position; nods emphatically when Ayanokōji agrees to postpone the vote.<span class=\"pg\">p.66–68<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> His anger subsides when the alliance decision is deferred until after the exam.<span class=\"pg\">p.68<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-matoba-shinji-y3v3-p102-1\">→ After: Pushing to break out, then group up<\/button><\/div><\/article>"},{"i":"sc-morishita-ai-y3v3-p66-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"hashimoto-masayoshi morishita-ai","q":"morishita ai doubting the alliance and hashimoto  just when this pain in the ass exam starts  you drop a bombshell like this on us  and the fact that hashimoto s so into the idea is shady as hell   how about we discipline them  suspicious that hashimoto backed the alliance from the start  and delighted when others share her doubt   the  see  of someone vindicated  suspects he was briefed in advance and wants him disciplined","h":"<article class=\"card\" id=\"sc-morishita-ai-y3v3-p66-1\"><h3><span class=\"ttl\"><a href=\"../../../people/morishita-ai.html#sc-morishita-ai-y3v3-p66-1\">Doubting the alliance and Hashimoto<\/a><\/span><span class=\"meta\">Y3V3 · p.66–67<\/span><span class=\"by\">notes on <a href=\"../../../people/morishita-ai.html\">Morishita Ai<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Morishita Ai<\/b> &quot;Just when this pain-in-the-ass exam starts, you drop a bombshell like this on us. And the fact that Hashimoto&#x27;s so into the idea is shady as hell.&quot;<span class=\"pg\">p.66<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Morishita Ai<\/b> &quot;How about we discipline them?&quot;<span class=\"pg\">p.67<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Suspicious that Hashimoto backed the alliance from the start, and delighted when others share her doubt — the &quot;See?&quot; of someone vindicated.<span class=\"pg\">p.66–67<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Suspects he was briefed in advance and wants him disciplined.<span class=\"pg\">p.66–67<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-morishita-ai-y3v3-p56-1\">← Before: Complaining about her formation placement<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-morishita-ai-y3v3-p101-1\">→ After: Morishita calls Class B &quot;stalkers&quot;<\/button><\/div><\/article>"},{"i":"sc-motodoi-chikako-y3v3-p67-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"motodoi-chikako","q":"motodoi chikako objecting to the alliance  let me say something  too  this talk about an alliance  do we have to decide right now  no matter how you look at it  this isn t the right time   i ll admit  this special exam isn t exactly in our favor  but to throw away first place and aim for second just to get a better advantage  i can t accept that  articulate and principled   accepts class c s disadvantage but refuses to throw away its own chance to win for an alliance","h":"<article class=\"card\" id=\"sc-motodoi-chikako-y3v3-p67-1\"><h3><span class=\"ttl\"><a href=\"../../../people/motodoi-chikako.html#sc-motodoi-chikako-y3v3-p67-1\">Objecting to the alliance<\/a><\/span><span class=\"meta\">Y3V3 · p.67<\/span><span class=\"by\">notes on <a href=\"../../../people/motodoi-chikako.html\">Motodoi Chikako<\/a><\/span><\/h3><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Motodoi Chikako<\/b> &quot;Let me say something, too. This talk about an alliance... do we have to decide right now? No matter how you look at it, this isn&#x27;t the right time.&quot;<span class=\"pg\">p.67<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Motodoi Chikako<\/b> &quot;I&#x27;ll admit, this special exam isn&#x27;t exactly in our favor. But to throw away first place and aim for second just to get a better advantage... I can&#x27;t accept that.&quot;<span class=\"pg\">p.67<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Articulate and principled — accepts Class C&#x27;s disadvantage but refuses to throw away its own chance to win for an alliance.<span class=\"pg\">p.67<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p68-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"kitou-hayato ayanokouji-kiyotaka","q":"ayanokoji kiyotaka the surprise attack and the retreat senses the rustle of trees before anyone else as the class stands at ease after the alliance debate   everyone  run  now   we ll leave this place to kitou and the others and retreat   the answer is quite simple  ryuuen s class deliberately kept its distance after the start to make it seem like they were avoiding engagement   judging by the speed of their decision  they must have been planning to use it from the moment they understood the rules of the special exam   no  this is about our limit  if we force ourselves to keep going  we ll only increase the risk of our allies dropping out  deduced ryuen s fake retreat   global gps shutdown ambush from the frozen position updates  stops the retreat when laggards start falling behind  calm under sudden violence   issues one word of warning  abandons the rear to kitou  and manages the retreat pace to prevent further dropouts  leaves him and several boys to hold off the ambush while the front line withdraws","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p68-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p68-1\">The surprise attack and the retreat<\/a><\/span><span class=\"meta\">Y3V3 · p.68–73<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Senses the rustle of trees before anyone else as the class stands at ease after the alliance debate.<\/p><p class=\"with\">with <a href=\"../../../people/kitou-hayato.html\">Kitō Hayato<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;—Everyone, run! Now!&quot;<span class=\"pg\">p.69<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;We&#x27;ll leave this place to Kitou and the others and retreat.&quot;<span class=\"pg\">p.70<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;The answer is quite simple. Ryuuen&#x27;s class deliberately kept its distance after the start to make it seem like they were avoiding engagement.&quot;<span class=\"pg\">p.72<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Judging by the speed of their decision, they must have been planning to use it from the moment they understood the rules of the special exam.&quot;<span class=\"pg\">p.73<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;No, this is about our limit. If we force ourselves to keep going, we&#x27;ll only increase the risk of our allies dropping out.&quot;<span class=\"pg\">p.73<\/span><\/li><li><span class=\"mlabel\">Tactic<\/span> Deduced Ryūen&#x27;s fake-retreat + Global GPS Shutdown ambush from the frozen position updates; stops the retreat when laggards start falling behind.<span class=\"pg\">p.72–73<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Calm under sudden violence — issues one word of warning, abandons the rear to Kitou, and manages the retreat pace to prevent further dropouts.<span class=\"pg\">p.69–73<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kitō Hayato<\/b> Leaves him and several boys to hold off the ambush while the front line withdraws.<span class=\"pg\">p.70<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p64-1\">← Before: Announcing the alliance; postponing the vote<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p86-1\">→ After: Ch.3 — depth read: pressure, provisioning and camp<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y3v3-p69-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"hashimoto-masayoshi","q":"hashimoto masayoshi the ambush  shouting to the class is caught in the surprise attack from the rear   your packs  don t forget your packs  just run   we don t even know how many of them there are  for now  run  just run   a surprise attack  huh  if they d just waited and watched  another class might ve crushed each other for them  heh  that bastard ryuuen  he took on a pretty big risk  didn t he  keeps his head in the panic   shouts practical orders about packs and running  then mixes frustration with open admiration for ryuen s gamble","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y3v3-p69-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hashimoto-masayoshi.html#sc-hashimoto-masayoshi-y3v3-p69-1\">The ambush: shouting to the class<\/a><\/span><span class=\"meta\">Y3V3 · p.69–73<\/span><span class=\"by\">notes on <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/span><\/h3><p class=\"setup\">Is caught in the surprise attack from the rear.<\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Your packs, don&#x27;t forget your packs! Just run!&quot;<span class=\"pg\">p.70<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;We don&#x27;t even know how many of them there are. For now, run! Just run!&quot;<span class=\"pg\">p.70<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;A surprise attack, huh... If they&#x27;d just waited and watched, another class might&#x27;ve crushed each other for them. Heh... That bastard Ryuuen, he took on a pretty big risk, didn&#x27;t he?&quot;<span class=\"pg\">p.73<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Keeps his head in the panic — shouts practical orders about packs and running, then mixes frustration with open admiration for Ryūen&#x27;s gamble.<span class=\"pg\">p.69–73<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p63-1\">← Before: The alliance bombshell and its defense<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p86-1\">→ After: Ch.3 — depth read: Hashimoto rallies the gloomy class<\/button><\/div><\/article>"},{"i":"sc-kitou-hayato-y3v3-p70-1","v":"y3v3","y":3,"o":35,"k":"","w":"ayanokouji-kiyotaka kitou-hayato","q":"kito hayato counterattacking during the ambush takes cover behind a tree the instant the ambush begins  counterattacks from cover with skill and courage  hard to believe  from someone who had never fired in a real fight  taking out an enemy and halting the assault   giving the front line time to retreat  instinctive and composed under fire   reads the predicament before any verbal order and acts  is left to hold off the ambush while the front line withdraws","h":"<article class=\"card\" id=\"sc-kitou-hayato-y3v3-p70-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kitou-hayato.html#sc-kitou-hayato-y3v3-p70-1\">Counterattacking during the ambush<\/a><\/span><span class=\"meta\">Y3V3 · p.70<\/span><span class=\"by\">notes on <a href=\"../../../people/kitou-hayato.html\">Kitō Hayato<\/a><\/span><\/h3><p class=\"setup\">Takes cover behind a tree the instant the ambush begins.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Feat<\/span> Counterattacks from cover with skill and courage &quot;hard to believe&quot; from someone who had never fired in a real fight, taking out an enemy and halting the assault — giving the front line time to retreat.<span class=\"pg\">p.70<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Instinctive and composed under fire — reads the predicament before any verbal order and acts.<span class=\"pg\">p.70<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is left to hold off the ambush while the front line withdraws.<span class=\"pg\">p.70<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kitou-hayato-y3v3-p63-1\">← Before: Demanding a commitment to win<\/button><\/div><\/article>"},{"i":"sc-takemoto-shigeru-y3v3-p72-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"takemoto-shigeru","q":"takemoto shigeru during the retreat jogs while relaying messages after the ambush  asked to report because shiraishi cannot keep up   hah  no  hah  wh what the hell  hah  i i ll tell him   he says there was no sign of any other classes approaching our vicinity on the tablet  and that class b s position still hasn t changed  exhausted and winded but keeps the radio link alive when shiraishi is too breathless to communicate","h":"<article class=\"card\" id=\"sc-takemoto-shigeru-y3v3-p72-1\"><h3><span class=\"ttl\"><a href=\"../../../people/takemoto-shigeru.html#sc-takemoto-shigeru-y3v3-p72-1\">During the retreat<\/a><\/span><span class=\"meta\">Y3V3 · p.72<\/span><span class=\"by\">notes on <a href=\"../../../people/takemoto-shigeru.html\">Takemoto Shigeru<\/a><\/span><\/h3><p class=\"setup\">Jogs while relaying messages after the ambush, asked to report because Shiraishi cannot keep up.<\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Takemoto Shigeru<\/b> &quot;Hah? No, hah, wh-what the hell, hah... I-I&#x27;ll tell him!&quot;<span class=\"pg\">p.72<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Takemoto Shigeru<\/b> &quot;He says there was no sign of any other classes approaching our vicinity on the tablet. And that Class B&#x27;s position still hasn&#x27;t changed!&quot;<span class=\"pg\">p.72<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Exhausted and winded but keeps the radio link alive when Shiraishi is too breathless to communicate.<span class=\"pg\">p.72<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-takemoto-shigeru-y3v3-p48-1\">← Before: Relaying the GPS reports<\/button><\/div><\/article>"},{"i":"sc-yoshida-kenta-y3v3-p72-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"yoshida-kenta","q":"yoshida kenta panic after the ambush  what the hell   so they used their one time only big move right from the get go  angry and frustrated at being ambushed so early  vents at the scale of the casualties","h":"<article class=\"card\" id=\"sc-yoshida-kenta-y3v3-p72-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yoshida-kenta.html#sc-yoshida-kenta-y3v3-p72-1\">Panic after the ambush<\/a><\/span><span class=\"meta\">Y3V3 · p.72–73<\/span><span class=\"by\">notes on <a href=\"../../../people/yoshida-kenta.html\">Yoshida Kenta<\/a><\/span><\/h3><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Yoshida Kenta<\/b> &quot;What the hell!&quot;<span class=\"pg\">p.72<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Yoshida Kenta<\/b> &quot;So they used their one-time-only big move right from the get-go...&quot;<span class=\"pg\">p.73<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Angry and frustrated at being ambushed so early; vents at the scale of the casualties.<span class=\"pg\">p.72–73<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yoshida-kenta-y3v3-p51-1\">← Before: Urging a halt before the fight<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p86-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"yamamura-miki hashimoto-masayoshi matoba-shinji ryuuen-kakeru ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 3   depth read  pressure  provisioning and camp  if you  yamamura  can just stay in for even one second longer without getting out  that alone is useful   head north and class a s there to greet you  head east and it s class d  there s no escaping a scenario where we get pincered by class b coming up from behind   if i were ryuuen no  if i were any other class  i d be grateful to see class c moving in one big clump   this is my decision as the one temporarily in charge of class c   i ll go to i10 alone   basically  if we don t attack  we won t be attacked  operate under that assumption   i can t say something baseless   i suppose it s because i don t dislike the deserted island exam itself  goes alone to i10 and secures food supplies while the d12 group draws class b away  divides provisions equally and explains small portion eating  rejects grouping up   it would let other classes ignore them and gather supplies freely   and splits the team to cover both food drops  reassures her that simply surviving is a contribution  discusses strategy and the gloomy mood  listens to his story in the tent  rebuts his group up and escape plans  reasons about how ryuen would exploit class c s mistakes","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p86-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p86-1\">Ch.3 — depth read: pressure, provisioning and camp<\/a><\/span><span class=\"meta\">Y3V3 · p.86–118<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/yamamura-miki.html\">Yamamura Miki<\/a> · <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a> · <a href=\"../../../people/matoba-shinji.html\">Matoba Shinji<\/a> · <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;If you, Yamamura, can just stay in for even one second longer without getting out, that alone is useful.&quot;<span class=\"pg\">p.94<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Head north and Class A&#x27;s there to greet you; head east and it&#x27;s Class D. There&#x27;s no escaping a scenario where we get pincered by Class B coming up from behind.&quot;<span class=\"pg\">p.102<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;If I were Ryuuen—no, if I were any other class, I&#x27;d be grateful to see Class C moving in one big clump.&quot;<span class=\"pg\">p.105<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;This is my decision as the one temporarily in charge of Class C.&quot;<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;ll go to I10 alone.&quot;<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Basically, if we don&#x27;t attack, we won&#x27;t be attacked. Operate under that assumption.&quot;<span class=\"pg\">p.106<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I can&#x27;t say something baseless.&quot;<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I suppose it&#x27;s because I don&#x27;t dislike the deserted island exam itself.&quot;<span class=\"pg\">p.111<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Goes alone to I10 and secures food supplies while the D12 group draws Class B away; divides provisions equally and explains small-portion eating.<span class=\"pg\">p.105–108<\/span><\/li><li><span class=\"mlabel\">Tactic<\/span> Rejects grouping up — it would let other classes ignore them and gather supplies freely — and splits the team to cover both food drops.<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamamura Miki<\/b> Reassures her that simply surviving is a contribution.<span class=\"pg\">p.94<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Discusses strategy and the gloomy mood; listens to his story in the tent.<span class=\"pg\">p.101–118<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Matoba Shinji<\/b> Rebuts his group-up and escape plans.<span class=\"pg\">p.102–105<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Reasons about how Ryūen would exploit Class C&#x27;s mistakes.<span class=\"pg\">p.105<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p68-1\">← Before: The surprise attack and the retreat<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p91-1\">→ After: Event one: splitting for supplies<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y3v3-p86-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka hashimoto-masayoshi","q":"hashimoto masayoshi ch 3   depth read  hashimoto rallies the gloomy class  ayanokouji kiyotaka  you could just charge in by yourself and annihilate the enemy unit  you know   man  everyone s lookin  so gloomy  well  can t be helped  given our results so far   isn t there somethin  you can say as our leader   anyway  i guess when things are this gloomy is when it s my time to shine  huh  keeps the class s morale up after the disastrous start  cheerful  a natural straight man  and tells a funny middle school bike story in the tent  admires his securing the i10 supplies alone and prods him to encourage the class","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y3v3-p86-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hashimoto-masayoshi.html#sc-hashimoto-masayoshi-y3v3-p86-1\">Ch.3 — depth read: Hashimoto rallies the gloomy class<\/a><\/span><span class=\"meta\">Y3V3 · p.86–118<\/span><span class=\"by\">notes on <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Ayanokouji Kiyotaka. You could just charge in by yourself and annihilate the enemy unit, you know?&quot;<span class=\"pg\">p.101<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Man, everyone&#x27;s lookin&#x27; so gloomy. Well, can&#x27;t be helped, given our results so far.&quot;<span class=\"pg\">p.110<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Isn&#x27;t there somethin&#x27; you can say as our leader?&quot;<span class=\"pg\">p.111<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Anyway, I guess when things are this gloomy is when it&#x27;s my time to shine, huh?&quot;<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Keeps the class&#x27;s morale up after the disastrous start; cheerful, a natural straight man, and tells a funny middle-school bike story in the tent.<span class=\"pg\">p.101–113<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Admires his securing the I10 supplies alone and prods him to encourage the class.<span class=\"pg\">p.108–113<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p69-1\">← Before: The ambush: shouting to the class<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p101-1\">→ After: Hashimoto on the food situation<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y3v3-p86-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka hirata-yousuke sudou-ken kouenji-rokusuke horikita-suzune","q":"horikita suzune ch 3   depth read  horikita s disbelief and invisible pressure  my honest impression is   really  is it possible   ayanokouji kun is how should i put it  he s not the type of person to be careless in this kind of fight   i probably  just don t want to frankly acknowledge it  acknowledge ryuuen kun  who managed to get the better of him   but let s gratefully accept the result  the situation is now slightly in our favor   even without koenji kun  our situation isn t bad   still  i wonder why i can t feel relieved in the slightest  even though class c is in a jam  refuses to accept that ayanokoji could be defeated so easily   a dangerous  faith  that he has no weaknesses   yet moves north to gain distance  is unsettled by the  invisible pressure  he still exerts even half destroyed  discusses the exam with him  comforts her and vows to crush any class in a straight fight  expects him to retire at any moment  notes the large sum spent on his cooperation previously","h":"<article class=\"card\" id=\"sc-horikita-suzune-y3v3-p86-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y3v3-p86-1\">Ch.3 — depth read: Horikita&#x27;s disbelief and invisible pressure<\/a><\/span><span class=\"meta\">Y3V3 · p.86–118<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a> · <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> &quot;My honest impression is, &#x27;Really? Is it possible?&#x27;&quot;<span class=\"pg\">p.96<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> &quot;Ayanokouji-kun is—how should I put it... He&#x27;s not the type of person to be careless in this kind of fight.&quot;<span class=\"pg\">p.96<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> &quot;I probably... just don&#x27;t want to frankly acknowledge it. Acknowledge Ryuuen-kun, who managed to get the better of him.&quot;<span class=\"pg\">p.97<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;But let&#x27;s gratefully accept the result. The situation is now slightly in our favor.&quot;<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Even without Koenji-kun, our situation isn&#x27;t bad.&quot;<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Still, I wonder why I can&#x27;t feel relieved in the slightest, even though Class C is in a jam.&quot;<span class=\"pg\">p.99<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Refuses to accept that Ayanokōji could be defeated so easily — a dangerous &quot;faith&quot; that he has no weaknesses — yet moves north to gain distance.<span class=\"pg\">p.96–98<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is unsettled by the &quot;invisible pressure&quot; he still exerts even half-destroyed.<span class=\"pg\">p.96–98<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Discusses the exam with him.<span class=\"pg\">p.96–99<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Comforts her and vows to crush any class in a straight fight.<span class=\"pg\">p.99<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> Expects him to retire at any moment; notes the large sum spent on his cooperation previously.<span class=\"pg\">p.97–98<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y3v3-p95-1\">→ After: Class A reacts: disbelief and &quot;invisible pressure&quot;<\/button><\/div><\/article>"},{"i":"sc-ryuuen-kakeru-y3v3-p86-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka katsuragi-kouhei ishizaki-daichi ryuuen-kakeru","q":"ryuen kakeru ch 3   depth read  ryuen s caution after the ambush looks down at the shattered class c students after the surprise attack   yeah  if things go well  that s eighteen people  not bad   it s probably better if kondou doesn t catch up   no send ten people   no  this is as far as we go   he held out longer than i expected   the problem is we failed to take down the one guy we needed to  sends a ten person search party  with vip yamashita  so identify person can t cheaply reveal the vip  calls off the pursuit because ayanokoji survived  decisive and ruthlessly rational   struck first to deny ayanokoji time to think  and values the psychological proof that ayanokoji has openings more than the casualties  launched the ambush to defeat him before he could plan  regrets failing to take him out  receives casualty reports and gives orders  holds him back from pursuing class c","h":"<article class=\"card\" id=\"sc-ryuuen-kakeru-y3v3-p86-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ryuuen-kakeru.html#sc-ryuuen-kakeru-y3v3-p86-1\">Ch.3 — depth read: Ryūen&#x27;s caution after the ambush<\/a><\/span><span class=\"meta\">Y3V3 · p.86–118<\/span><span class=\"by\">notes on <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/span><\/h3><p class=\"setup\">Looks down at the shattered Class C students after the surprise attack.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;Yeah. If things go well, that&#x27;s eighteen people. Not bad.&quot;<span class=\"pg\">p.87<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;It&#x27;s probably better if Kondou doesn&#x27;t catch up.&quot;<span class=\"pg\">p.87<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;No—send ten people.&quot;<span class=\"pg\">p.87<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;No, this is as far as we go.&quot;<span class=\"pg\">p.88<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;He held out longer than I expected.&quot;<span class=\"pg\">p.89<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;The problem is we failed to take down the one guy we needed to.&quot;<span class=\"pg\">p.89<\/span><\/li><li><span class=\"mlabel\">Tactic<\/span> Sends a ten-person search party (with VIP Yamashita) so Identify Person can&#x27;t cheaply reveal the VIP; calls off the pursuit because Ayanokōji survived.<span class=\"pg\">p.87<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Decisive and ruthlessly rational — struck first to deny Ayanokōji time to think, and values the psychological proof that Ayanokōji has openings more than the casualties.<span class=\"pg\">p.86–90<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Launched the ambush to defeat him before he could plan; regrets failing to take him out.<span class=\"pg\">p.86–90<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Receives casualty reports and gives orders.<span class=\"pg\">p.87–90<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> Holds him back from pursuing Class C.<span class=\"pg\">p.88<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y3v3-p86-2\">→ After: After the ambush: calling off the pursuit<\/button><\/div><\/article>"},{"i":"sc-ryuuen-kakeru-y3v3-p86-2","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka katsuragi-kouhei ishizaki-daichi ryuuen-kakeru","q":"ryuen kakeru after the ambush  calling off the pursuit looks down at the shattered class c students  the surprise attack has taken 15 of theirs including kitou and vip nishikawa   yeah  if things go well  that s eighteen people  not bad   it s probably better if kondou doesn t catch up   no send ten people   i almost forgot myself  but moving in a small group will just give them a hint   no  this is as far as we go   he held out longer than i expected   this ain t about our losses  the problem is we failed to take down the one guy we needed to   but as long as the most troublesome bastard is still standing  i wouldn t be surprised if he managed to turn the tables on us even when we ve got twice the strength   now that one of their vips is down  ayanokouji has no choice but to go on the offensive  like it or not  so there s no need for us to jump the gun  the ambush was conceived at once on reading the rules and drawing the adjacent start   strike ayanokoji before he has time to think  the best counter to his superhuman intellect  raises the search party from the minimum to ten so identify person cannot cheaply reveal vip yamashita   one in ten odds  ruthlessly rational   values the psychological proof that ayanokoji is not infallible more than the casualties  and refuses to press an advantage that could become a trap  launched the ambush to defeat him before he could plan  calls off pursuit because he survived  receives casualty reports and debate  ultimately agrees to send the ten person party  rebuffs his eager demand to chase class c","h":"<article class=\"card\" id=\"sc-ryuuen-kakeru-y3v3-p86-2\"><h3><span class=\"ttl\"><a href=\"../../../people/ryuuen-kakeru.html#sc-ryuuen-kakeru-y3v3-p86-2\">After the ambush: calling off the pursuit<\/a><\/span><span class=\"meta\">Y3V3 · p.86–90<\/span><span class=\"by\">notes on <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/span><\/h3><p class=\"setup\">Looks down at the shattered Class C students; the surprise attack has taken 15 of theirs including Kitou and VIP Nishikawa.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;Yeah. If things go well, that&#x27;s eighteen people. Not bad.&quot;<span class=\"pg\">p.87<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;It&#x27;s probably better if Kondou doesn&#x27;t catch up.&quot;<span class=\"pg\">p.87<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;No—send ten people.&quot;<span class=\"pg\">p.87<\/span><\/li><\/ul><details class=\"more\"><summary>12 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I almost forgot myself, but moving in a small group will just give them a hint.&quot;<span class=\"pg\">p.88<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;—No, this is as far as we go.&quot;<span class=\"pg\">p.88<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;He held out longer than I expected.&quot;<span class=\"pg\">p.89<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;This ain&#x27;t about our losses. The problem is we failed to take down the one guy we needed to.&quot;<span class=\"pg\">p.89<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;But as long as the most troublesome bastard is still standing, I wouldn&#x27;t be surprised if he managed to turn the tables on us even when we&#x27;ve got twice the strength.&quot;<span class=\"pg\">p.89<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Now that one of their VIPs is down, Ayanokouji has no choice but to go on the offensive, like it or not. So there&#x27;s no need for us to jump the gun.&quot;<span class=\"pg\">p.90<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> The ambush was conceived at once on reading the rules and drawing the adjacent start — strike Ayanokōji before he has time to think, the best counter to his superhuman intellect.<span class=\"pg\">p.86<\/span><\/li><li><span class=\"mlabel\">Tactic<\/span> Raises the search party from the minimum to ten so Identify Person cannot cheaply reveal VIP Yamashita — one in ten odds.<span class=\"pg\">p.87–88<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Ruthlessly rational — values the psychological proof that Ayanokōji is not infallible more than the casualties, and refuses to press an advantage that could become a trap.<span class=\"pg\">p.86–90<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Launched the ambush to defeat him before he could plan; calls off pursuit because he survived.<span class=\"pg\">p.86–90<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Receives casualty reports and debate, ultimately agrees to send the ten-person party.<span class=\"pg\">p.87–90<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> Rebuffs his eager demand to chase Class C.<span class=\"pg\">p.88–89<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y3v3-p86-1\">← Before: Ch.3 — depth read: Ryūen&#x27;s caution after the ambush<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y3v3-p89-1\">→ After: Depth review: the defeated rival<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y3v3-p86-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka yamamura-miki","q":"yamamura miki ch 3   depth read  yamamura s fear and reassurance  it s just  it s scary  isn t it  if i get separated  i won t have any idea where my allies are or where the enemy is  right  anxious about being separated and feeling useless after class c lost nishikawa  a vip  nods with resolve after ayanokoji s reassurance  is reassured by him that simply surviving is a contribution","h":"<article class=\"card\" id=\"sc-yamamura-miki-y3v3-p86-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yamamura-miki.html#sc-yamamura-miki-y3v3-p86-1\">Ch.3 — depth read: Yamamura&#x27;s fear and reassurance<\/a><\/span><span class=\"meta\">Y3V3 · p.86–118<\/span><span class=\"by\">notes on <a href=\"../../../people/yamamura-miki.html\">Yamamura Miki<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Yamamura Miki<\/b> &quot;It&#x27;s just... it&#x27;s scary, isn&#x27;t it? If I get separated, I won&#x27;t have any idea where my allies are or where the enemy is, right?&quot;<span class=\"pg\">p.94<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Anxious about being separated and feeling useless after Class C lost Nishikawa (a VIP); nods with resolve after Ayanokōji&#x27;s reassurance.<span class=\"pg\">p.94<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is reassured by him that simply surviving is a contribution.<span class=\"pg\">p.94<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y3v3-p94-1\">→ After: Yamamura&#x27;s fear of being separated<\/button><\/div><\/article>"},{"i":"sc-katsuragi-kouhei-y3v3-p87-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ryuuen-kakeru katsuragi-kouhei","q":"katsuragi kohei katsuragi reports and debates the pursuit approaches ryuen with the casualty report from the surprise attack   i ve finished confirming with kaneda through the vip  we have three casualties and they have fifteen   among those fifteen were our target  kitou and the designated vip  nishikawa   then  may i send yamashita to retrieve komiya   ten people  the risk of engagement seems low  but is this for insurance   that may be true  but  are you sure  this will interfere with our plans for later   i can t say the thought that you re being overly cautious with ayanokouji hasn t crossed my mind  but if we re speaking from a position of maximum vigilance  then perhaps pulling back here is the best move  methodical and principled   confirms casualties  proposes retrieving the stray vip  and rationally accepts ryuen s call to stop  recognizing the ambush itself was a victory  relays reports and debates strategy  ultimately agrees with his decision to withdraw","h":"<article class=\"card\" id=\"sc-katsuragi-kouhei-y3v3-p87-1\"><h3><span class=\"ttl\"><a href=\"../../../people/katsuragi-kouhei.html#sc-katsuragi-kouhei-y3v3-p87-1\">Katsuragi reports and debates the pursuit<\/a><\/span><span class=\"meta\">Y3V3 · p.87–90<\/span><span class=\"by\">notes on <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a><\/span><\/h3><p class=\"setup\">Approaches Ryūen with the casualty report from the surprise attack.<\/p><p class=\"with\">with <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Katsuragi Kōhei<\/b> &quot;I&#x27;ve finished confirming with Kaneda through the VIP. We have three casualties and they have fifteen.&quot;<span class=\"pg\">p.87<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Katsuragi Kōhei<\/b> &quot;Among those fifteen were our target, Kitou and the designated VIP, Nishikawa.&quot;<span class=\"pg\">p.87<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Katsuragi Kōhei<\/b> &quot;Then, may I send Yamashita to retrieve Komiya?&quot;<span class=\"pg\">p.87<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Ten people? The risk of engagement seems low, but is this for insurance?&quot;<span class=\"pg\">p.87<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;That may be true, but... are you sure? This will interfere with our plans for later.&quot;<span class=\"pg\">p.88<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I can&#x27;t say the thought that you&#x27;re being overly cautious with Ayanokouji hasn&#x27;t crossed my mind... but if we&#x27;re speaking from a position of maximum vigilance, then perhaps pulling back here is the best move.&quot;<span class=\"pg\">p.90<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Methodical and principled — confirms casualties, proposes retrieving the stray VIP, and rationally accepts Ryūen&#x27;s call to stop, recognizing the ambush itself was a victory.<span class=\"pg\">p.87–90<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Relays reports and debates strategy; ultimately agrees with his decision to withdraw.<span class=\"pg\">p.87–90<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-katsuragi-kouhei-y3v3-p210-1\">→ After: The final confrontation with Class A<\/button><\/div><\/article>"},{"i":"sc-ryuuen-kakeru-y3v3-p89-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka ibuki-mio katsuragi-kouhei ryuuen-kakeru","q":"ryuen kakeru depth review  the defeated rival orders his class b to withdraw from the surprise attack on class c after kito holds out longer than expected   sounds like you were pretty successful   i just wanna know  is this really you surrendering   you  threw it   i ve seen your process of using any environment to win  calls off the ambush on class c when the reserve he expected to exploit does not materialise  katsuragi and ishizaki question the caution  obsessed with victory   chooses the 2 v 1 against ayanokoji over the safer shot at a vip because  settling things by running away on a rare occasion like this  is not fun  is beaten by a thrown paintball after burning his ammunition chasing ayanokoji onto the beach  concedes defeat and declares he will show no mercy in the truest sense from now on  fights him on the beach after ayanokoji fed class b the vip names  loses and vows revenge  fights alongside her  she is eliminated first and protests bitterly  discusses the withdrawal decision with him","h":"<article class=\"card\" id=\"sc-ryuuen-kakeru-y3v3-p89-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ryuuen-kakeru.html#sc-ryuuen-kakeru-y3v3-p89-1\">Depth review: the defeated rival<\/a><\/span><span class=\"meta\">Y3V3 · p.89–250<\/span><span class=\"by\">notes on <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/span><\/h3><p class=\"setup\">Orders his Class B to withdraw from the surprise attack on Class C after Kitō holds out longer than expected.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a> · <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;Sounds like you were pretty successful.&quot;<span class=\"pg\">p.237<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;I just wanna know, is this really you surrendering?&quot;<span class=\"pg\">p.241<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;You... threw it...!?&quot;<span class=\"pg\">p.248<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;ve seen your process of using any environment to win.&quot;<span class=\"pg\">p.250<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Calls off the ambush on Class C when the reserve he expected to exploit does not materialise; Katsuragi and Ishizaki question the caution.<span class=\"pg\">p.89<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Obsessed with victory — chooses the 2-v-1 against Ayanokōji over the safer shot at a VIP because &quot;settling things by running away on a rare occasion like this&quot; is not fun.<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Limit<\/span> Is beaten by a thrown paintball after burning his ammunition chasing Ayanokōji onto the beach.<span class=\"pg\">p.248<\/span><\/li><li><span class=\"mlabel\">Position<\/span> Concedes defeat and declares he will show no mercy in the truest sense from now on.<span class=\"pg\">p.250<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Fights him on the beach after Ayanokōji fed Class B the VIP names; loses and vows revenge.<span class=\"pg\">p.236–250<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ibuki Mio<\/b> Fights alongside her; she is eliminated first and protests bitterly.<span class=\"pg\">p.236–240<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Discusses the withdrawal decision with him.<span class=\"pg\">p.89<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y3v3-p86-2\">← Before: After the ambush: calling off the pursuit<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y3v3-p90-1\">→ After: The real prize: proof of an opening<\/button><\/div><\/article>"},{"i":"sc-ryuuen-kakeru-y3v3-p90-1","v":"y3v3","y":3,"o":35,"k":"","w":"katsuragi-kouhei ryuuen-kakeru","q":"ryuen kakeru the real prize  proof of an opening what he gained was not just half of class c but the certainty that even ayanokoji has exploitable openings   a  great relief  katsuragi notes that being cautious with ayanokoji is itself a victory  ryuen answers  exactly","h":"<article class=\"card\" id=\"sc-ryuuen-kakeru-y3v3-p90-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ryuuen-kakeru.html#sc-ryuuen-kakeru-y3v3-p90-1\">The real prize: proof of an opening<\/a><\/span><span class=\"meta\">Y3V3 · p.90<\/span><span class=\"by\">notes on <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> What he gained was not just half of Class C but the certainty that even Ayanokōji has exploitable openings — a &quot;great relief.&quot;<span class=\"pg\">p.90<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Katsuragi notes that being cautious with Ayanokōji is itself a victory; Ryūen answers &quot;Exactly.&quot;<span class=\"pg\">p.90<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y3v3-p89-1\">← Before: Depth review: the defeated rival<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y3v3-p119-1\">→ After: Ch.4 — depth read: Ryūen deliberates the next attack<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p91-1","v":"y3v3","y":3,"o":35,"k":"action spoken","w":"ayanokouji-kiyotaka","q":"ayanokoji kiyotaka event one  splitting for supplies the first event begins  he directs the class from the f12 base as sanada reads the ten locations   the main unit will move to g13 and we ll form a separate detachment with four people to escort our vip  takemoto   just getting there wouldn t be a problem  but no matter how safe d14 is  i want to avoid a situation where we can t find the event location  or the supplies are too much to carry back all at once   yeah  the base is an easy landmark  so f13 is fine  sends the main unit to g13 and a four person escort with takemoto to d14  keeps watch from f12 g12 for class b","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p91-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p91-1\">Event one: splitting for supplies<\/a><\/span><span class=\"meta\">Y3V3 · p.91–94<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">The first event begins; he directs the class from the F12 base as Sanada reads the ten locations.<\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;The main unit will move to G13 and we&#x27;ll form a separate detachment with four people to escort our VIP, Takemoto.&quot;<span class=\"pg\">p.93<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Just getting there wouldn&#x27;t be a problem, but no matter how safe D14 is, I want to avoid a situation where we can&#x27;t find the event location, or the supplies are too much to carry back all at once.&quot;<span class=\"pg\">p.93<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Yeah. The base is an easy landmark, so F13 is fine.&quot;<span class=\"pg\">p.93<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">What happens<\/span> Sends the main unit to G13 and a four-person escort with Takemoto to D14; keeps watch from F12/G12 for Class B.<span class=\"pg\">p.91–94<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p86-1\">← Before: Ch.3 — depth read: pressure, provisioning and camp<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p94-1\">→ After: Reassuring Yamamura<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p94-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"yamamura-miki ayanokouji-kiyotaka","q":"ayanokoji kiyotaka reassuring yamamura notices yamamura s anxious look as the class prepares to depart   what is it  if you have a problem  i ll hear you out   that s not true  our class was half decimated due to my poor judgment  but at least we still have half of us left  as long as half of us are still here  it means there s still a chance to win   if you  yamamura  can just stay in for even one second longer without getting out  that alone is useful   even if you can t shoot  as long as you don t get shot  that alone is a huge plus for the class  you should remember that the value is the same  reframes survival itself as contribution   calmly turns yamamura s fear into a concrete  achievable role  reassures her that simply staying in the exam is useful","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p94-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p94-1\">Reassuring Yamamura<\/a><\/span><span class=\"meta\">Y3V3 · p.94<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Notices Yamamura&#x27;s anxious look as the class prepares to depart.<\/p><p class=\"with\">with <a href=\"../../../people/yamamura-miki.html\">Yamamura Miki<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;What is it? If you have a problem, I&#x27;ll hear you out.&quot;<span class=\"pg\">p.94<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;That&#x27;s not true. Our class was half-decimated due to my poor judgment, but at least we still have half of us left. As long as half of us are still here, it means there&#x27;s still a chance to win.&quot;<span class=\"pg\">p.94<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;If you, Yamamura, can just stay in for even one second longer without getting out, that alone is useful.&quot;<span class=\"pg\">p.94<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Even if you can&#x27;t shoot, as long as you don&#x27;t get shot, that alone is a huge plus for the class. You should remember that the value is the same.&quot;<span class=\"pg\">p.94<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Reframes survival itself as contribution — calmly turns Yamamura&#x27;s fear into a concrete, achievable role.<span class=\"pg\">p.94<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamamura Miki<\/b> Reassures her that simply staying in the exam is useful.<span class=\"pg\">p.94<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p91-1\">← Before: Event one: splitting for supplies<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p100-1\">→ After: The stalemate with Class B&#x27;s &quot;stalkers&quot;<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y3v3-p94-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka yamamura-miki","q":"yamamura miki yamamura s fear of being separated looks anxious as the class prepares to split into supply teams   it s just  it s scary  isn t it  if i get separated  i won t have any idea where my allies are or where the enemy is  right   and there s nothing i can do to be of use   is that  really all it takes  anxious about being separated and feeling useless after class c lost vip nishikawa  gives a small  definite nod after ayanokoji s reassurance  is reassured by him that simply surviving is a contribution","h":"<article class=\"card\" id=\"sc-yamamura-miki-y3v3-p94-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yamamura-miki.html#sc-yamamura-miki-y3v3-p94-1\">Yamamura&#x27;s fear of being separated<\/a><\/span><span class=\"meta\">Y3V3 · p.94<\/span><span class=\"by\">notes on <a href=\"../../../people/yamamura-miki.html\">Yamamura Miki<\/a><\/span><\/h3><p class=\"setup\">Looks anxious as the class prepares to split into supply teams.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Yamamura Miki<\/b> &quot;It&#x27;s just... it&#x27;s scary, isn&#x27;t it? If I get separated, I won&#x27;t have any idea where my allies are or where the enemy is, right?&quot;<span class=\"pg\">p.94<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Yamamura Miki<\/b> &quot;And there&#x27;s nothing I can do to be of use...&quot;<span class=\"pg\">p.94<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Yamamura Miki<\/b> &quot;Is that... really all it takes?&quot;<span class=\"pg\">p.94<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Anxious about being separated and feeling useless after Class C lost VIP Nishikawa; gives a small, definite nod after Ayanokōji&#x27;s reassurance.<span class=\"pg\">p.94<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is reassured by him that simply surviving is a contribution.<span class=\"pg\">p.94<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y3v3-p86-1\">← Before: Ch.3 — depth read: Yamamura&#x27;s fear and reassurance<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y3v3-p233-1\">→ After: Epilogue — depth read: the unseen final guard<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y3v3-p95-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka hirata-yousuke sudou-ken kouenji-rokusuke horikita-suzune","q":"horikita suzune class a reacts  disbelief and  invisible pressure  leads class a north toward g7 after the first event  refusing involvement at h9   me too  to use a tactic for an all out attack right at the start  even if you thought of it  it would take considerable courage to execute   my honest impression is   really  is it possible   ayanokouji kun is how should i put it  he s not the type of person to be careless in this kind of fight   i probably  just don t want to frankly acknowledge it  acknowledge ryuuen kun  who managed to get the better of him   but let s gratefully accept the result  the situation is now slightly in our favor   even without koenji kun  our situation isn t bad   still  i wonder why i can t feel relieved in the slightest  even though class c is in a jam   even though their numbers have been halved  i still can t help but feel this invisible pressure  refuses to accept that ayanokoji could be defeated easily   a dangerous  faith  bordering on worship   yet moves north to gain distance from him  is unsettled by the  invisible pressure  he still exerts even half destroyed  moves away to avoid any surprise attack  discusses the exam and ayanokoji s apparent defeat with him  consults with him  accepts his offer to crush any class in a straight fight  expects him to retire at any moment  notes the large point expenditure to secure his cooperation before  horikita and koenji hold protection points  relevant to the expulsion penalty","h":"<article class=\"card\" id=\"sc-horikita-suzune-y3v3-p95-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y3v3-p95-1\">Class A reacts: disbelief and &quot;invisible pressure&quot;<\/a><\/span><span class=\"meta\">Y3V3 · p.95–98<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">Leads Class A north toward G7 after the first event, refusing involvement at H9.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a> · <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> &quot;Me too. To use a tactic for an all-out attack right at the start... even if you thought of it, it would take considerable courage to execute.&quot;<span class=\"pg\">p.96<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> &quot;My honest impression is, &#x27;Really? Is it possible?&#x27;&quot;<span class=\"pg\">p.96<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> &quot;Ayanokouji-kun is—how should I put it... He&#x27;s not the type of person to be careless in this kind of fight.&quot;<span class=\"pg\">p.96<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I probably... just don&#x27;t want to frankly acknowledge it. Acknowledge Ryuuen-kun, who managed to get the better of him.&quot;<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;But let&#x27;s gratefully accept the result. The situation is now slightly in our favor.&quot;<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Even without Koenji-kun, our situation isn&#x27;t bad.&quot;<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Still, I wonder why I can&#x27;t feel relieved in the slightest, even though Class C is in a jam.&quot;<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Even though their numbers have been halved, I still can&#x27;t help but feel this invisible pressure.&quot;<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Refuses to accept that Ayanokōji could be defeated easily — a dangerous &quot;faith&quot; bordering on worship — yet moves north to gain distance from him.<span class=\"pg\">p.96–98<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is unsettled by the &quot;invisible pressure&quot; he still exerts even half-destroyed; moves away to avoid any surprise attack.<span class=\"pg\">p.96–98<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Discusses the exam and Ayanokōji&#x27;s apparent defeat with him.<span class=\"pg\">p.96–98<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Consults with him; accepts his offer to crush any class in a straight fight.<span class=\"pg\">p.95–99<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> Expects him to retire at any moment; notes the large point expenditure to secure his cooperation before.<span class=\"pg\">p.97–98<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Horikita and Kōenji hold Protection Points, relevant to the expulsion penalty.<span class=\"pg\">p.97<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y3v3-p86-1\">← Before: Ch.3 — depth read: Horikita&#x27;s disbelief and invisible pressure<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y3v3-p185-1\">→ After: Class A reaches G8; the unease<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y3v3-p95-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"horikita-suzune ike-kanji sudou-ken","q":"sudo ken sudo s read and his vow crosses his arms and approaches horikita after ike s group mocks class c s defeat   suzune  about that fight between class b and class c just now  honestly  i was surprised   yeah  but still  for ayanokouji to get taken down so easily   well  let s just focus on what we can do  if it comes to a straight up fight  we ll crush  em  whether it s class b  class d  or even ayanokouji  right  bashful around horikita  a shy hand on her shoulder  but bluntly confident in his physical stamina   ready to protect the class with all his might  reassures her with a vow to crush any opponent  she gives a short reply as they move north  overhears ike laughing at ayanokoji s defeat","h":"<article class=\"card\" id=\"sc-sudou-ken-y3v3-p95-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sudou-ken.html#sc-sudou-ken-y3v3-p95-1\">Sudō&#x27;s read and his vow<\/a><\/span><span class=\"meta\">Y3V3 · p.95–99<\/span><span class=\"by\">notes on <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/span><\/h3><p class=\"setup\">Crosses his arms and approaches Horikita after Ike&#x27;s group mocks Class C&#x27;s defeat.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/ike-kanji.html\">Ike Kanji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> &quot;Suzune. About that fight between Class B and Class C just now. Honestly, I was surprised.&quot;<span class=\"pg\">p.95<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> &quot;Yeah. But still, for Ayanokouji to get taken down so easily...&quot;<span class=\"pg\">p.96<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> &quot;Well, let&#x27;s just focus on what we can do. If it comes to a straight-up fight, we&#x27;ll crush &#x27;em, whether it&#x27;s Class B, Class D... or even Ayanokouji. Right?&quot;<span class=\"pg\">p.99<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Bashful around Horikita (a shy hand on her shoulder) but bluntly confident in his physical stamina — ready to protect the class with all his might.<span class=\"pg\">p.95–99<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Reassures her with a vow to crush any opponent; she gives a short reply as they move north.<span class=\"pg\">p.95–99<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> Overhears Ike laughing at Ayanokōji&#x27;s defeat.<span class=\"pg\">p.95<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y3v3-p197-1\">→ After: Ch.7 — depth read: Sudō protects Satō<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p100-1","v":"y3v3","y":3,"o":35,"k":"narration spoken","w":"ayanokouji-kiyotaka","q":"ayanokoji kiyotaka the stalemate with class b s  stalkers  by 5 p m  the class has secured five supply sets  class b s main camp between g9 and g10 pins them in  five sets  200 rounds  1 5 kg rice  eight cans  nuts  chicken  a few provisions  15 liters of water   a minimal harvest from 39 crates   i can t exactly pull off something like the protagonist of an american action movie  at best  i d get taken down after defeating two or three of them   that d be rough  attacking them from our position is a complete suicide mission   head north and class a s there to greet you  head east and it s class d  there s no escaping a scenario where we get pincered by class b coming up from behind   i m sure they don t want to fight  but we d be crashing an event they re trying to claim in safety  right  clear eyed about the hopeless position   rejects both a heroic charge and a breakout  reading the other classes  incentives precisely","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p100-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p100-1\">The stalemate with Class B&#x27;s &quot;stalkers&quot;<\/a><\/span><span class=\"meta\">Y3V3 · p.100–103<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">By 5 p.m. the class has secured five supply sets; Class B&#x27;s main camp between G9 and G10 pins them in.<\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;I can&#x27;t exactly pull off something like the protagonist of an American action movie. At best, I&#x27;d get taken down after defeating two or three of them.&quot;<span class=\"pg\">p.101<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;That&#x27;d be rough. Attacking them from our position is a complete suicide mission.&quot;<span class=\"pg\">p.102<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Head north and Class A&#x27;s there to greet you; head east and it&#x27;s Class D. There&#x27;s no escaping a scenario where we get pincered by Class B coming up from behind.&quot;<span class=\"pg\">p.102<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> Five sets: 200 rounds, 1.5 kg rice, eight cans, nuts, chicken, a few provisions, 15 liters of water — a minimal harvest from 39 crates.<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;m sure they don&#x27;t want to fight. But we&#x27;d be crashing an event they&#x27;re trying to claim in safety, right?&quot;<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Clear-eyed about the hopeless position — rejects both a heroic charge and a breakout, reading the other classes&#x27; incentives precisely.<span class=\"pg\">p.101–103<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p94-1\">← Before: Reassuring Yamamura<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p104-1\">→ After: Going alone to I10<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y3v3-p101-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"hashimoto-masayoshi","q":"hashimoto masayoshi hashimoto on the food situation  but man  we re barely managing to endure this as it is  classes with forty people must be struggling big time  worries about the dwindling supplies but points out larger classes must be suffering more","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y3v3-p101-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hashimoto-masayoshi.html#sc-hashimoto-masayoshi-y3v3-p101-1\">Hashimoto on the food situation<\/a><\/span><span class=\"meta\">Y3V3 · p.101–102<\/span><span class=\"by\">notes on <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/span><\/h3><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;But man, we&#x27;re barely managing to endure this as it is. Classes with forty people must be struggling big time.&quot;<span class=\"pg\">p.102<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Worries about the dwindling supplies but points out larger classes must be suffering more.<span class=\"pg\">p.101–102<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p86-1\">← Before: Ch.3 — depth read: Hashimoto rallies the gloomy class<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p151-1\">→ After: Ch.5 — depth read: Hashimoto&#x27;s lingering doubt<\/button><\/div><\/article>"},{"i":"sc-morishita-ai-y3v3-p101-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"morishita-ai","q":"morishita ai morishita calls class b  stalkers   being pinned down like this is just so unpleasant  they re practically stalkers at this point  stalkers   just that many  how pathetic  if it were me  the so called  amazoness of the jungle  i could easily dispose of a hundred of them   you re such a stickler for details   jungle  and  dense forest  mean basically the same thing  fumes at class b s suffocating presence and boasts about fighting a hundred enemies   bluster ayanokoji notes is wasted breath","h":"<article class=\"card\" id=\"sc-morishita-ai-y3v3-p101-1\"><h3><span class=\"ttl\"><a href=\"../../../people/morishita-ai.html#sc-morishita-ai-y3v3-p101-1\">Morishita calls Class B &quot;stalkers&quot;<\/a><\/span><span class=\"meta\">Y3V3 · p.101–103<\/span><span class=\"by\">notes on <a href=\"../../../people/morishita-ai.html\">Morishita Ai<\/a><\/span><\/h3><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Morishita Ai<\/b> &quot;Being pinned down like this is just so unpleasant. They&#x27;re practically stalkers at this point. Stalkers.&quot;<span class=\"pg\">p.101<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Morishita Ai<\/b> &quot;Just that many? How pathetic. If it were me, the so-called &#x27;Amazoness of the Jungle,&#x27; I could easily dispose of a hundred of them.&quot;<span class=\"pg\">p.101<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Morishita Ai<\/b> &quot;You&#x27;re such a stickler for details. &#x27;Jungle&#x27; and &#x27;dense forest&#x27; mean basically the same thing.&quot;<span class=\"pg\">p.101<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Fumes at Class B&#x27;s suffocating presence and boasts about fighting a hundred enemies — bluster Ayanokōji notes is wasted breath.<span class=\"pg\">p.101–103<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-morishita-ai-y3v3-p66-1\">← Before: Doubting the alliance and Hashimoto<\/button><\/div><\/article>"},{"i":"sc-matoba-shinji-y3v3-p102-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"matoba-shinji","q":"matoba shinji pushing to break out  then group up  morishita s proposal is something else  but can t we actually break through somehow  like just forcing our way through   and now we get the fewest of the day   how about a strategy where we risk it and escape to the east  class d is at n12 right now  right   so we re prepared to fight  then   going after the supplies means we re not gonna back down easily  right  then shouldn t we concentrate our forces  anxious and insistent on a breakout or consolidation  ayanokoji concludes he never considered the plan from the enemy s perspective","h":"<article class=\"card\" id=\"sc-matoba-shinji-y3v3-p102-1\"><h3><span class=\"ttl\"><a href=\"../../../people/matoba-shinji.html#sc-matoba-shinji-y3v3-p102-1\">Pushing to break out, then group up<\/a><\/span><span class=\"meta\">Y3V3 · p.102–105<\/span><span class=\"by\">notes on <a href=\"../../../people/matoba-shinji.html\">Matoba Shinji<\/a><\/span><\/h3><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Matoba Shinji<\/b> &quot;Morishita&#x27;s proposal is something else, but can&#x27;t we actually break through somehow? Like just forcing our way through?&quot;<span class=\"pg\">p.102<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Matoba Shinji<\/b> &quot;And now we get the fewest of the day?&quot;<span class=\"pg\">p.103<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Matoba Shinji<\/b> &quot;How about a strategy where we risk it and escape to the east? Class D is at N12 right now, right?&quot;<span class=\"pg\">p.103<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;...So we&#x27;re prepared to fight, then.&quot;<span class=\"pg\">p.104<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Going after the supplies means we&#x27;re not gonna back down easily, right? Then shouldn&#x27;t we concentrate our forces?&quot;<span class=\"pg\">p.104<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Anxious and insistent on a breakout or consolidation; Ayanokōji concludes he never considered the plan from the enemy&#x27;s perspective.<span class=\"pg\">p.102–105<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-matoba-shinji-y3v3-p66-1\">← Before: Criticizing the alliance as Class C groveling<\/button><\/div><\/article>"},{"i":"sc-sanada-kousei-y3v3-p103-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"sanada-kousei","q":"sanada kosei sanada reads the final drop locations  moreover  you could hardly say these are favorable areas for us  either   class b has no intention of letting us escape  so we ll definitely be competing there  the analyst reads the nine final locations and judges that class b will contest them  adjusts his glasses as he points them out","h":"<article class=\"card\" id=\"sc-sanada-kousei-y3v3-p103-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sanada-kousei.html#sc-sanada-kousei-y3v3-p103-1\">Sanada reads the final drop locations<\/a><\/span><span class=\"meta\">Y3V3 · p.103<\/span><span class=\"by\">notes on <a href=\"../../../people/sanada-kousei.html\">Sanada Kōsei<\/a><\/span><\/h3><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sanada Kōsei<\/b> &quot;Moreover, you could hardly say these are favorable areas for us, either.&quot;<span class=\"pg\">p.103<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sanada Kōsei<\/b> &quot;Class B has no intention of letting us escape, so we&#x27;ll definitely be competing there.&quot;<span class=\"pg\">p.103<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> The analyst reads the nine final locations and judges that Class B will contest them; adjusts his glasses as he points them out.<span class=\"pg\">p.103<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sanada-kousei-y3v3-p53-1\">← Before: Sanada suggests using Identity Check<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p104-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"matoba-shinji hashimoto-masayoshi ayanokouji-kiyotaka","q":"ayanokoji kiyotaka going alone to i10 the final 5 p m  event offers only d12 and i10  he decides to go after both   we re staying based in the southern area and securing the supplies   if we were only thinking about today  avoiding them would be fine  but tomorrow s event isn t until 11 00 am at the earliest   the other classes are the ones who desperately need supplies right now  if we group up  we d just be helping them out  huh   sorry  but we don t have time to debate this any further  this is my decision as the one temporarily in charge of class c   if i were ryuuen no  if i were any other class  i d be grateful to see class c moving in one big clump   i ll go to i10 alone   even so  i have no intention of changing my decision   after that  we ll regroup in one to one and a half hours  the primary rendezvous is f12  rejects matoba s group up plan because a large  slow moving clump would let other classes ignore them and gather supplies freely  starving class c by morning  splits the team   goes alone to i10 while takemoto hashimoto take d12   and sets f12 primary   h12 secondary rendezvous points  decisive and unyielding under dissent   makes the call alone and makes clear that objections carry the risk of expulsion  overrules his group up and eastward escape proposals  sends him with takemoto to d12  brushes off his alarm at going alone","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p104-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p104-1\">Going alone to I10<\/a><\/span><span class=\"meta\">Y3V3 · p.104–107<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">The final 5 p.m. event offers only D12 and I10; he decides to go after both.<\/p><p class=\"with\">with <a href=\"../../../people/matoba-shinji.html\">Matoba Shinji<\/a> · <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;We&#x27;re staying based in the southern area and securing the supplies.&quot;<span class=\"pg\">p.104<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;If we were only thinking about today, avoiding them would be fine. But tomorrow&#x27;s event isn&#x27;t until 11:00 AM at the earliest.&quot;<span class=\"pg\">p.104<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;The other classes are the ones who desperately need supplies right now. If we group up, we&#x27;d just be helping them out, huh.&quot;<span class=\"pg\">p.105<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Sorry, but we don&#x27;t have time to debate this any further. This is my decision as the one temporarily in charge of Class C.&quot;<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;If I were Ryuuen—no, if I were any other class, I&#x27;d be grateful to see Class C moving in one big clump.&quot;<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;ll go to I10 alone.&quot;<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Even so. I have no intention of changing my decision.&quot;<span class=\"pg\">p.106<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;After that, we&#x27;ll regroup in one to one and a half hours. The primary rendezvous is F12.&quot;<span class=\"pg\">p.106<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> Rejects Matoba&#x27;s group-up plan because a large, slow-moving clump would let other classes ignore them and gather supplies freely, starving Class C by morning.<span class=\"pg\">p.104–105<\/span><\/li><li><span class=\"mlabel\">Tactic<\/span> Splits the team — goes alone to I10 while Takemoto/Hashimoto take D12 — and sets F12 primary / H12 secondary rendezvous points.<span class=\"pg\">p.105–106<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Decisive and unyielding under dissent — makes the call alone and makes clear that objections carry the risk of expulsion.<span class=\"pg\">p.104–106<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Matoba Shinji<\/b> Overrules his group-up and eastward-escape proposals.<span class=\"pg\">p.104–105<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Sends him with Takemoto to D12; brushes off his alarm at going alone.<span class=\"pg\">p.106<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p100-1\">← Before: The stalemate with Class B&#x27;s &quot;stalkers&quot;<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p119-1\">→ After: Ch.4 — depth read: Kōenji and the G11 offensive<\/button><\/div><\/article>"},{"i":"sc-shiraishi-asuka-y3v3-p117-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka shiraishi-asuka","q":"shiraishi asuka depth review  class c s recon commander speaks privately with ayanokoji after the surprise attack  assuring him she trusts him completely   at the very least  i trust you   then i ll make use of that trust without reservation   just as you said  ayanokouji kun  it s turned into quite a chaotic battle  hasn t it  acts as class c s commander over the radio  relaying other classes  positions and directing the gps jammer tactics  shows respect and a willingness to tell a  gentle lie  for someone s own good  or speak plainly when it is not   ayanokoji notes this diverges from his first impression of her  expresses no doubt about ayanokoji s leadership even after the failed prediction  which unsettles him  places unconditional trust in him and serves as his reconnaissance lead","h":"<article class=\"card\" id=\"sc-shiraishi-asuka-y3v3-p117-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shiraishi-asuka.html#sc-shiraishi-asuka-y3v3-p117-1\">Depth review: Class C&#x27;s recon commander<\/a><\/span><span class=\"meta\">Y3V3 · p.117–232<\/span><span class=\"by\">notes on <a href=\"../../../people/shiraishi-asuka.html\">Shiraishi Asuka<\/a><\/span><\/h3><p class=\"setup\">Speaks privately with Ayanokōji after the surprise attack, assuring him she trusts him completely.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shiraishi Asuka<\/b> &quot;At the very least, I trust you.&quot;<span class=\"pg\">p.117<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiraishi Asuka<\/b> &quot;Then I&#x27;ll make use of that trust without reservation.&quot;<span class=\"pg\">p.117<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiraishi Asuka<\/b> &quot;Just as you said, Ayanokouji-kun, it&#x27;s turned into quite a chaotic battle, hasn&#x27;t it?&quot;<span class=\"pg\">p.230<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Post<\/span> Acts as Class C&#x27;s commander over the radio, relaying other classes&#x27; positions and directing the GPS-jammer tactics.<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Shows respect and a willingness to tell a &quot;gentle lie&quot; for someone&#x27;s own good, or speak plainly when it is not — Ayanokōji notes this diverges from his first impression of her.<span class=\"pg\">p.117<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Expresses no doubt about Ayanokōji&#x27;s leadership even after the failed prediction, which unsettles him.<span class=\"pg\">p.117<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Places unconditional trust in him and serves as his reconnaissance lead.<span class=\"pg\">p.117–232<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shiraishi-asuka-y3v3-p59-1\">← Before: Relaying the commander&#x27;s loophole findings<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-shiraishi-asuka-y3v3-p151-1\">→ After: Ch.5 — depth read: Class D&#x27;s trust impresses<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p119-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"kouenji-rokusuke ryuuen-kakeru hashimoto-masayoshi ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 4   depth read  koenji and the g11 offensive  that s our common understanding  but there s just a certain  creepiness to it  it s because i don t understand the reason why he s still here instead of retiring   right now  everyone s focused on moving around the island  gathering supplies and staying healthy  but that s nothing more than a prelude   we re leaving now  we re going to secure the supplies and food at g11   enough idle talk  it s precisely because the enemy is closer that we must get there first   we ll wait here for five minutes   we re not using any tactics  if we save them  the enemy will have to remain constantly on guard  chooses to go on the offensive for g11 and deliberately delays twice by five minutes  saving tactics and exploiting the enemy s need to stay vigilant    i already knew the result  deduces the exam s true endgame is a chaotic firefight in a shrinking area  where stray rounds could eliminate vips  puzzled that he hasn t retired  keeps monitoring him as a wild card  anticipates his moves at g11 and positions the class for the confrontation  relies on him to steady the anxious class","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p119-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p119-1\">Ch.4 — depth read: Kōenji and the G11 offensive<\/a><\/span><span class=\"meta\">Y3V3 · p.119–150<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a> · <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;That&#x27;s our common understanding, but there&#x27;s just a certain... creepiness to it. It&#x27;s because I don&#x27;t understand the reason why he&#x27;s still here instead of retiring.&quot;<span class=\"pg\">p.124<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Right now, everyone&#x27;s focused on moving around the island, gathering supplies and staying healthy, but that&#x27;s nothing more than a prelude.&quot;<span class=\"pg\">p.136<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;We&#x27;re leaving now. We&#x27;re going to secure the supplies and food at G11.&quot;<span class=\"pg\">p.137<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Enough idle talk. It&#x27;s precisely because the enemy is closer that we must get there first.&quot;<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;We&#x27;ll wait here for five minutes.&quot;<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;We&#x27;re not using any tactics. If we save them, the enemy will have to remain constantly on guard.&quot;<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Tactic<\/span> Chooses to go on the offensive for G11 and deliberately delays twice by five minutes, saving tactics and exploiting the enemy&#x27;s need to stay vigilant — &quot;I already knew the result.&quot;<span class=\"pg\">p.137–140<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> Deduces the exam&#x27;s true endgame is a chaotic firefight in a shrinking area, where stray rounds could eliminate VIPs.<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> Puzzled that he hasn&#x27;t retired; keeps monitoring him as a wild card.<span class=\"pg\">p.123–124<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Anticipates his moves at G11 and positions the class for the confrontation.<span class=\"pg\">p.137–140<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Relies on him to steady the anxious class.<span class=\"pg\">p.137–139<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p104-1\">← Before: Going alone to I10<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p123-1\">→ After: Day two: Kōenji still alive; waiting strategy<\/button><\/div><\/article>"},{"i":"sc-kanzaki-ryuuji-y3v3-p119-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ichinose-honami andou kanzaki-ryuuji","q":"kanzaki ryuji ch 4   depth read  kanzaki sees the shrinking map stares at the analyst s tablet as the 11 00 event s outer squares are marked as soon to be restricted   it s too early to draw conclusions  but if the next event has a similar mechanic  the probability will be orders of magnitude higher   there s no way to avoid a fight from here on   for now  we ll move to secure it  o14 has little land  so the supplies themselves should be easy to find   we ll split into three groups at once and head to collect the event rewards  sharp and analytical   immediately grasps that the map is shrinking and combat is now unavoidable  momentarily shaken  then refocused by ichinose s message  receives her message not to worry and not to push for o14  class d s analyst operates the tablet he reads","h":"<article class=\"card\" id=\"sc-kanzaki-ryuuji-y3v3-p119-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kanzaki-ryuuji.html#sc-kanzaki-ryuuji-y3v3-p119-1\">Ch.4 — depth read: Kanzaki sees the shrinking map<\/a><\/span><span class=\"meta\">Y3V3 · p.119–150<\/span><span class=\"by\">notes on <a href=\"../../../people/kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a><\/span><\/h3><p class=\"setup\">Stares at the analyst&#x27;s tablet as the 11:00 event&#x27;s outer squares are marked as soon-to-be restricted.<\/p><p class=\"with\">with <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kanzaki Ryūji<\/b> &quot;It&#x27;s too early to draw conclusions, but if the next event has a similar mechanic, the probability will be orders of magnitude higher.&quot;<span class=\"pg\">p.126<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kanzaki Ryūji<\/b> &quot;There&#x27;s no way to avoid a fight from here on—&quot;<span class=\"pg\">p.126<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kanzaki Ryūji<\/b> &quot;For now, we&#x27;ll move to secure it. O14 has little land, so the supplies themselves should be easy to find.&quot;<span class=\"pg\">p.127<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;We&#x27;ll split into three groups at once and head to collect the event rewards.&quot;<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Sharp and analytical — immediately grasps that the map is shrinking and combat is now unavoidable; momentarily shaken, then refocused by Ichinose&#x27;s message.<span class=\"pg\">p.126–127<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Receives her message not to worry and not to push for O14.<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">andou<\/b> Class D&#x27;s analyst operates the tablet he reads.<span class=\"pg\">p.126<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kanzaki-ryuuji-y3v3-p126-1\">→ After: Kanzaki sees the map shrinking<\/button><\/div><\/article>"},{"i":"sc-kouenji-rokusuke-y3v3-p119-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"morofuji-rika komiya-kyogo kouenji-rokusuke","q":"koenji rokusuke ch 4   depth read  koenji s casual massacre ambushes class b s e9 supply group from the forest with unseen  precise shots   you re the vip  aren t you  if you were to fight back  you would simply be eliminated for nothing   there is nothing to it  is there  i am from class a  you are from class b  we re enemies   i enjoyed the uninhabited island for a day and thinking i had my fill  was on my way back to the ship but i thought i d give this a try for the novelty of it   for me  winning or losing this special exam is a matter of supreme indifference   very well  i shall take my leave now  i trust you will take care not to get in my way again  eliminates six of class b s eight guards in under thirty seconds without being seen  then spares vip morofuji and lets her keep the supplies  detached and theatrical   fights purely for amusement  indifferent to winning  yet his  kindness   sparing morofuji  doubles as a stern warning  spares her and lets her take the supplies  is baited by his shouting  which reveals their position  takes him out first","h":"<article class=\"card\" id=\"sc-kouenji-rokusuke-y3v3-p119-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kouenji-rokusuke.html#sc-kouenji-rokusuke-y3v3-p119-1\">Ch.4 — depth read: Kōenji&#x27;s casual massacre<\/a><\/span><span class=\"meta\">Y3V3 · p.119–150<\/span><span class=\"by\">notes on <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/span><\/h3><p class=\"setup\">Ambushes Class B&#x27;s E9 supply group from the forest with unseen, precise shots.<\/p><p class=\"with\">with <a href=\"../../../people/morofuji-rika.html\">Morofuji Rika<\/a> · <a href=\"../../../people/komiya-kyogo.html\">Komiya Kyogo<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> &quot;You&#x27;re the VIP, aren&#x27;t you? If you were to fight back, you would simply be eliminated for nothing.&quot;<span class=\"pg\">p.133<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> &quot;There is nothing to it, is there? I am from Class A, you are from Class B. We&#x27;re enemies.&quot;<span class=\"pg\">p.133<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> &quot;I enjoyed the uninhabited island for a day and thinking I had my fill, was on my way back to the ship—but I thought I&#x27;d give this a try for the novelty of it.&quot;<span class=\"pg\">p.133<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;For me, winning or losing this special exam is a matter of supreme indifference.&quot;<span class=\"pg\">p.134<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Very well. I shall take my leave now. I trust you will take care not to get in my way again.&quot;<span class=\"pg\">p.134<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Eliminates six of Class B&#x27;s eight guards in under thirty seconds without being seen, then spares VIP Morofuji and lets her keep the supplies.<span class=\"pg\">p.130–134<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Detached and theatrical — fights purely for amusement, indifferent to winning, yet his &quot;kindness&quot; (sparing Morofuji) doubles as a stern warning.<span class=\"pg\">p.133–134<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Morofuji Rika<\/b> Spares her and lets her take the supplies.<span class=\"pg\">p.133–134<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Komiya Kyogo<\/b> Is baited by his shouting, which reveals their position; takes him out first.<span class=\"pg\">p.128–133<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kouenji-rokusuke-y3v3-p128-1\">→ After: The unseen ambush on Class B&#x27;s supply group<\/button><\/div><\/article>"},{"i":"sc-ryuuen-kakeru-y3v3-p119-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"katsuragi-kouhei ayanokouji-kiyotaka ryuuen-kakeru","q":"ryuen kakeru ch 4   depth read  ryuen deliberates the next attack  i ve got him cornered  but how re you gonna move  ayanokouji   there s always the option of crushin  that eyesore class a first  but that d just make the guys at the bottom happy   the main target s always class c   it s the fear of not being able to see your opponent s face  the stronger the enemy  the more one s imagination is stirred up  obsessed with defeating ayanokoji but restrained by katsuragi  recognizes that even after a successful ambush  ayanokoji shows no sign of weakness  debates strategy with him  accepts the advice to stay defensive for now  focuses on him as the main target","h":"<article class=\"card\" id=\"sc-ryuuen-kakeru-y3v3-p119-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ryuuen-kakeru.html#sc-ryuuen-kakeru-y3v3-p119-1\">Ch.4 — depth read: Ryūen deliberates the next attack<\/a><\/span><span class=\"meta\">Y3V3 · p.119–150<\/span><span class=\"by\">notes on <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;I&#x27;ve got him cornered... but how&#x27;re you gonna move, Ayanokouji?&quot;<span class=\"pg\">p.120<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;There&#x27;s always the option of crushin&#x27; that eyesore Class A first... but that&#x27;d just make the guys at the bottom happy.&quot;<span class=\"pg\">p.120<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;The main target&#x27;s always Class C.&quot;<span class=\"pg\">p.120<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;It&#x27;s the fear of not being able to see your opponent&#x27;s face. The stronger the enemy, the more one&#x27;s imagination is stirred up.&quot;<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Obsessed with defeating Ayanokōji but restrained by Katsuragi; recognizes that even after a successful ambush, Ayanokōji shows no sign of weakness.<span class=\"pg\">p.119–122<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Debates strategy with him; accepts the advice to stay defensive for now.<span class=\"pg\">p.120–122<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Focuses on him as the main target.<span class=\"pg\">p.120<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y3v3-p90-1\">← Before: The real prize: proof of an opening<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y3v3-p119-2\">→ After: Morning deliberation: whom to attack next<\/button><\/div><\/article>"},{"i":"sc-ryuuen-kakeru-y3v3-p119-2","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka katsuragi-kouhei ryuuen-kakeru","q":"ryuen kakeru morning deliberation  whom to attack next wakes before 6 a m  and studies the map  deciding whom to fight on day two   i ve got him cornered  but how re you gonna move  ayanokouji   there s always the option of crushin  that eyesore class a first  but that d just make the guys at the bottom happy   well  the main target s always class c   sure  maintainin  our numbers advantage ain t a bad thing  we re the ones holdin  the initiative here  but we already used our main tactic yesterday to get the first strike   it s a strange thing  they should ve been half destroyed by that surprise attack  but lookin  at this map  i can t see ayanokouji showin  any sign of weakness   it s the fear of not being able to see your opponent s face  the stronger the enemy  the more one s imagination is stirred up  judges an all out attack on class c would win  99  if the exam ended immediately  but would leave too few forces to beat a and d   rejects a war of attrition that benefits the bottom classes  obsessed with ayanokoji and belligerent  but rational   recognizes the minuscule opening he found is hard to press and that time hunger will force class c s hand anyway  fixates on him as the main target even half destroyed  cannot see any sign of weakness  debates strategy with him  agrees  maybe so  to consider turning on class a","h":"<article class=\"card\" id=\"sc-ryuuen-kakeru-y3v3-p119-2\"><h3><span class=\"ttl\"><a href=\"../../../people/ryuuen-kakeru.html#sc-ryuuen-kakeru-y3v3-p119-2\">Morning deliberation: whom to attack next<\/a><\/span><span class=\"meta\">Y3V3 · p.119–122<\/span><span class=\"by\">notes on <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/span><\/h3><p class=\"setup\">Wakes before 6 a.m. and studies the map, deciding whom to fight on day two.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;I&#x27;ve got him cornered... but how&#x27;re you gonna move, Ayanokouji?&quot;<span class=\"pg\">p.120<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;There&#x27;s always the option of crushin&#x27; that eyesore Class A first... but that&#x27;d just make the guys at the bottom happy.&quot;<span class=\"pg\">p.120<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;Well, the main target&#x27;s always Class C.&quot;<span class=\"pg\">p.120<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Sure, maintainin&#x27; our numbers advantage ain&#x27;t a bad thing. We&#x27;re the ones holdin&#x27; the initiative here. But we already used our main tactic yesterday to get the first strike.&quot;<span class=\"pg\">p.120<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;It&#x27;s a strange thing. They should&#x27;ve been half-destroyed by that surprise attack, but lookin&#x27; at this map, I can&#x27;t see Ayanokouji showin&#x27; any sign of weakness.&quot;<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;It&#x27;s the fear of not being able to see your opponent&#x27;s face. The stronger the enemy, the more one&#x27;s imagination is stirred up.&quot;<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> Judges an all-out attack on Class C would win ~99% if the exam ended immediately, but would leave too few forces to beat A and D — rejects a war of attrition that benefits the bottom classes.<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Obsessed with Ayanokōji and belligerent, but rational — recognizes the minuscule opening he found is hard to press and that time/hunger will force Class C&#x27;s hand anyway.<span class=\"pg\">p.119–122<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Fixates on him as the main target even half-destroyed; cannot see any sign of weakness.<span class=\"pg\">p.120–121<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Debates strategy with him; agrees (&quot;Maybe so&quot;) to consider turning on Class A.<span class=\"pg\">p.120–122<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y3v3-p119-1\">← Before: Ch.4 — depth read: Ryūen deliberates the next attack<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y3v3-p167-1\">→ After: Ch.6 — depth read: Ryūen through Shiina<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p123-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"hashimoto-masayoshi shiraishi-asuka ayanokouji-kiyotaka","q":"ayanokoji kiyotaka day two  koenji still alive  waiting strategy hears the first report of day two   no one is missing and koenji is still alive alone in d6   that s our common understanding  but there s just a certain  creepiness to it  it s because i don t understand the reason why he s still here instead of retiring   it s more accurate to say that s how i saw him  that s why i expected him to have already retired by this morning   this place is the same as last year  there shouldn t be anything new about it for koenji   unless the other classes make any suspicious moves  our basic strategy is to wait until an event occurs  finds koenji s continued presence  creepy  and unreadable   expected him to retire   and keeps monitoring his gps rather than dismissing him  discusses koenji s survival with him  she suggests leaving koenji alone  he agrees it is the common understanding but remains uneasy","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p123-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p123-1\">Day two: Kōenji still alive; waiting strategy<\/a><\/span><span class=\"meta\">Y3V3 · p.123–125<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Hears the first report of day two — no one is missing and Kōenji is still alive alone in D6.<\/p><p class=\"with\">with <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a> · <a href=\"../../../people/shiraishi-asuka.html\">Shiraishi Asuka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;That&#x27;s our common understanding, but there&#x27;s just a certain... creepiness to it. It&#x27;s because I don&#x27;t understand the reason why he&#x27;s still here instead of retiring.&quot;<span class=\"pg\">p.124<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;It&#x27;s more accurate to say that&#x27;s how I saw him. That&#x27;s why I expected him to have already retired by this morning.&quot;<span class=\"pg\">p.124<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;This place is the same as last year. There shouldn&#x27;t be anything new about it for Koenji.&quot;<span class=\"pg\">p.124<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Unless the other classes make any suspicious moves, our basic strategy is to wait until an event occurs.&quot;<span class=\"pg\">p.125<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Finds Kōenji&#x27;s continued presence &quot;creepy&quot; and unreadable — expected him to retire — and keeps monitoring his GPS rather than dismissing him.<span class=\"pg\">p.123–125<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Discusses Kōenji&#x27;s survival with him.<span class=\"pg\">p.123–124<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiraishi Asuka<\/b> She suggests leaving Kōenji alone; he agrees it is the common understanding but remains uneasy.<span class=\"pg\">p.124<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p119-1\">← Before: Ch.4 — depth read: Kōenji and the G11 offensive<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p135-1\">→ After: Reading the shrinking map; deciding on G11<\/button><\/div><\/article>"},{"i":"sc-kanzaki-ryuuji-y3v3-p126-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ichinose-honami andou-sayo kanzaki-ryuuji","q":"kanzaki ryuji kanzaki sees the map shrinking stares at andou s tablet as the 11 a m  event marks the outer squares as soon to be restricted   it s too early to draw conclusions  but if the next event has a similar mechanic  the probability will be orders of magnitude higher   there s no way to avoid a fight from here on out   if one or two more prohibited areas are created today by shrinking the perimeter  we should probably consider making a major move  sharp and analytical   immediately grasps that the map is shrinking inward each event and combat is unavoidable  worries about the detour and class a s ambush risk in the north  is called back to the present when his name is repeatedly called  ichinose s earlier message told him not to push for o14  class d s analyst operates the tablet he reads","h":"<article class=\"card\" id=\"sc-kanzaki-ryuuji-y3v3-p126-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kanzaki-ryuuji.html#sc-kanzaki-ryuuji-y3v3-p126-1\">Kanzaki sees the map shrinking<\/a><\/span><span class=\"meta\">Y3V3 · p.126<\/span><span class=\"by\">notes on <a href=\"../../../people/kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a><\/span><\/h3><p class=\"setup\">Stares at Andou&#x27;s tablet as the 11 a.m. event marks the outer squares as soon-to-be-restricted.<\/p><p class=\"with\">with <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"../../../people/index.html#andou-sayo\">Andō Sayo<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kanzaki Ryūji<\/b> &quot;It&#x27;s too early to draw conclusions, but if the next event has a similar mechanic, the probability will be orders of magnitude higher.&quot;<span class=\"pg\">p.126<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kanzaki Ryūji<\/b> &quot;There&#x27;s no way to avoid a fight from here on out—&quot;<span class=\"pg\">p.126<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kanzaki Ryūji<\/b> &quot;If one or two more prohibited areas are created today by shrinking the perimeter, we should probably consider making a major move.&quot;<span class=\"pg\">p.127<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Sharp and analytical — immediately grasps that the map is shrinking inward each event and combat is unavoidable; worries about the detour and Class A&#x27;s ambush risk in the north.<span class=\"pg\">p.126–127<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Is called back to the present when his name is repeatedly called; Ichinose&#x27;s earlier message told him not to push for O14.<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Andō Sayo<\/b> Class D&#x27;s analyst operates the tablet he reads.<span class=\"pg\">p.126<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kanzaki-ryuuji-y3v3-p119-1\">← Before: Ch.4 — depth read: Kanzaki sees the shrinking map<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kanzaki-ryuuji-y3v3-p151-1\">→ After: Ch.5 — depth read: Kanzaki&#x27;s armed scrutiny<\/button><\/div><\/article>"},{"i":"sc-komiya-kyogo-y3v3-p128-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"morofuji-rika kouenji-rokusuke komiya-kyogo","q":"komiya kyogo komiya s bravado and downfall leads class b s ten person e9 supply group  accompanied by vip morofuji   you say he s comin  our way  but it s just one guy  right  some scrub like that doesn t even know where we are  so there s no need to sweat it   see  i told ya you re worryin  too much  if we run into him  i ll put a round right through his heart   where are you  koenji   here  it s over here  huh   why are you attacking us  koenji  overconfident and loud   dismisses the lone koenji as a  scrub  fires his shotgun into the forest to bait him  and is the first cut down  his bragging reveals the group s position  leads the guard group escorting her  taunts him  is eliminated by him first","h":"<article class=\"card\" id=\"sc-komiya-kyogo-y3v3-p128-1\"><h3><span class=\"ttl\"><a href=\"../../../people/komiya-kyogo.html#sc-komiya-kyogo-y3v3-p128-1\">Komiya&#x27;s bravado and downfall<\/a><\/span><span class=\"meta\">Y3V3 · p.128–131<\/span><span class=\"by\">notes on <a href=\"../../../people/komiya-kyogo.html\">Komiya Kyogo<\/a><\/span><\/h3><p class=\"setup\">Leads Class B&#x27;s ten-person E9 supply group, accompanied by VIP Morofuji.<\/p><p class=\"with\">with <a href=\"../../../people/morofuji-rika.html\">Morofuji Rika<\/a> · <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Komiya Kyogo<\/b> &quot;You say he&#x27;s comin&#x27; our way, but it&#x27;s just one guy, right? Some scrub like that doesn&#x27;t even know where we are, so there&#x27;s no need to sweat it.&quot;<span class=\"pg\">p.128<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Komiya Kyogo<\/b> &quot;See, I told ya you&#x27;re worryin&#x27; too much. If we run into him, I&#x27;ll put a round right through his heart.&quot;<span class=\"pg\">p.129<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Komiya Kyogo<\/b> &quot;Where are you, Koenji!&quot;<span class=\"pg\">p.129<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Here!? It&#x27;s over here, huh!?&quot;<span class=\"pg\">p.129<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Why are you attacking us, Koenji!&quot;<span class=\"pg\">p.131<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Overconfident and loud — dismisses the lone Kōenji as a &quot;scrub,&quot; fires his shotgun into the forest to bait him, and is the first cut down; his bragging reveals the group&#x27;s position.<span class=\"pg\">p.128–131<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Morofuji Rika<\/b> Leads the guard group escorting her.<span class=\"pg\">p.128<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> Taunts him; is eliminated by him first.<span class=\"pg\">p.129–131<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-kouenji-rokusuke-y3v3-p128-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"morofuji-rika komiya-kyogo kouenji-rokusuke","q":"koenji rokusuke the unseen ambush on class b s supply group appears walking with a confident stride after eliminating class b s guards from unseen positions in the forest   you re the vip  aren t you  if you were to fight back  you would simply be eliminated for nothing   there is nothing to it  is there  i am from class a  you are from class b  we re enemies   my  my  i had no knowledge that i would stumble upon you  however  when one hears voices and gunshots so unsuited for this great wilderness  it is something one would understand whether one likes it or not   i enjoyed the uninhabited island for a day and thinking i had my fill  was on my way back to the ship but i thought i d give this a try for the novelty of it   is that so  in that case  you may take the supplies and return with them to class b   for me  winning or losing this special exam is a matter of supreme indifference   very well  i shall take my leave now  i trust you will take care not to get in my way again  eliminates six of class b s guards in under thirty seconds with unseen  precise shots  then appears and takes out the last two   all eight guards around vip morofuji down without ever being located  detached  theatrical and bored   fought purely for novelty  indifferent to winning  and let morofuji keep the supplies  his  kindness  doubles as a stern warning  he located the group by following komiya s loud provoking shouts and gunfire  which were quite unsuited for the great wilderness  spares her and lets her take the supplies despite her aiming a dropped weapon at him  komiya s bragging and shotgun blasts give away their position  koenji takes him out first","h":"<article class=\"card\" id=\"sc-kouenji-rokusuke-y3v3-p128-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kouenji-rokusuke.html#sc-kouenji-rokusuke-y3v3-p128-1\">The unseen ambush on Class B&#x27;s supply group<\/a><\/span><span class=\"meta\">Y3V3 · p.128–134<\/span><span class=\"by\">notes on <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/span><\/h3><p class=\"setup\">Appears walking with a confident stride after eliminating Class B&#x27;s guards from unseen positions in the forest.<\/p><p class=\"with\">with <a href=\"../../../people/morofuji-rika.html\">Morofuji Rika<\/a> · <a href=\"../../../people/komiya-kyogo.html\">Komiya Kyogo<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> &quot;You&#x27;re the VIP, aren&#x27;t you? If you were to fight back, you would simply be eliminated for nothing.&quot;<span class=\"pg\">p.133<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> &quot;There is nothing to it, is there? I am from Class A, you are from Class B. We&#x27;re enemies.&quot;<span class=\"pg\">p.133<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> &quot;My, my. I had no knowledge that I would stumble upon you. However, when one hears voices and gunshots so unsuited for this great wilderness, it is something one would understand whether one likes it or not.&quot;<span class=\"pg\">p.133<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I enjoyed the uninhabited island for a day and thinking I had my fill, was on my way back to the ship—but I thought I&#x27;d give this a try for the novelty of it.&quot;<span class=\"pg\">p.133<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Is that so? In that case, you may take the supplies and return with them to Class B.&quot;<span class=\"pg\">p.134<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;For me, winning or losing this special exam is a matter of supreme indifference.&quot;<span class=\"pg\">p.134<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Very well. I shall take my leave now. I trust you will take care not to get in my way again.&quot;<span class=\"pg\">p.134<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Eliminates six of Class B&#x27;s guards in under thirty seconds with unseen, precise shots, then appears and takes out the last two — all eight guards around VIP Morofuji down without ever being located.<span class=\"pg\">p.130–133<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Detached, theatrical and bored — fought purely for novelty, indifferent to winning, and let Morofuji keep the supplies; his &quot;kindness&quot; doubles as a stern warning.<span class=\"pg\">p.133–134<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> He located the group by following Komiya&#x27;s loud provoking shouts and gunfire, which were quite unsuited for the great wilderness.<span class=\"pg\">p.133<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Morofuji Rika<\/b> Spares her and lets her take the supplies despite her aiming a dropped weapon at him.<span class=\"pg\">p.133–134<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Komiya Kyogo<\/b> Komiya&#x27;s bragging and shotgun blasts give away their position; Koenji takes him out first.<span class=\"pg\">p.128–133<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kouenji-rokusuke-y3v3-p119-1\">← Before: Ch.4 — depth read: Kōenji&#x27;s casual massacre<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kouenji-rokusuke-y3v3-p131-1\">→ After: Depth review: the unreachable lone wolf<\/button><\/div><\/article>"},{"i":"sc-ibuki-mio-y3v3-p131-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka ryuuen-kakeru morofuji-rika ibuki-mio","q":"ibuki mio depth review  the wild card eliminated ambushes a class b supply group surrounding morofuji  unseen  eliminating eight guards in under thirty seconds   die  ayanokouji   agh  dammit  so this is how it ends  single handedly picks off eight class b guards with precise submachine gun fire from cover  cocky and theatrical   thanks her victims for the fun  calls the encounter  an act of kindness  in koenji s own way  fiercely competitive  loud and profane when she loses  is hit by ayanokoji s final shot to the right thigh after her own spray runs dry  eliminated  complains she never wanted to take part in the exam  fights him alongside ryuen at the end  partners with him in the final 2 v 1  spares her and lets class b keep the supplies","h":"<article class=\"card\" id=\"sc-ibuki-mio-y3v3-p131-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ibuki-mio.html#sc-ibuki-mio-y3v3-p131-1\">Depth review: the wild card eliminated<\/a><\/span><span class=\"meta\">Y3V3 · p.131–240<\/span><span class=\"by\">notes on <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/span><\/h3><p class=\"setup\">Ambushes a Class B supply group surrounding Morofuji, unseen, eliminating eight guards in under thirty seconds.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"../../../people/morofuji-rika.html\">Morofuji Rika<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ibuki Mio<\/b> &quot;Die, Ayanokouji!&quot;<span class=\"pg\">p.238<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ibuki Mio<\/b> &quot;Agh, dammit! So this is how it ends!?&quot;<span class=\"pg\">p.240<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Feat<\/span> Single-handedly picks off eight Class B guards with precise submachine-gun fire from cover.<span class=\"pg\">p.131<\/span><\/li><li><span class=\"mlabel\">Voice<\/span> Cocky and theatrical — thanks her victims for the fun, calls the encounter &quot;an act of kindness, in Koenji&#x27;s own way.&quot;<span class=\"pg\">p.133<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Fiercely competitive, loud and profane when she loses.<span class=\"pg\">p.240<\/span><\/li><li><span class=\"mlabel\">Limit<\/span> Is hit by Ayanokōji&#x27;s final shot to the right thigh after her own spray runs dry.<span class=\"pg\">p.240<\/span><\/li><li><span class=\"mlabel\">Position<\/span> Eliminated; complains she never wanted to take part in the exam.<span class=\"pg\">p.240<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Fights him alongside Ryūen at the end.<span class=\"pg\">p.236–240<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Partners with him in the final 2-v-1.<span class=\"pg\">p.236–240<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Morofuji Rika<\/b> Spares her and lets Class B keep the supplies.<span class=\"pg\">p.131–134<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ibuki-mio-y3v3-p212-1\">→ After: Ibuki&#x27;s grudge against Horikita<\/button><\/div><\/article>"},{"i":"sc-kouenji-rokusuke-y3v3-p131-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"morofuji-rika kouenji-rokusuke","q":"koenji rokusuke depth review  the unreachable lone wolf appears unseen and eliminates eight class b guards around morofuji in under thirty seconds   you re the vip  aren t you   there is nothing to it  is there  i am from class a  you are from class b  we re enemies   for me  winning or losing this special exam is a matter of supreme indifference  single handedly dismantles a class b guard unit with precise  unseen fire  spares vip morofuji and lets her keep the supplies  courtly  theatrical and self assured    my  my  and grand pronouncements about the  great wilderness  acts purely for his own amusement  true to his word that winning or losing is a matter of indifference to him  spares her with a warning dressed as kindness","h":"<article class=\"card\" id=\"sc-kouenji-rokusuke-y3v3-p131-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kouenji-rokusuke.html#sc-kouenji-rokusuke-y3v3-p131-1\">Depth review: the unreachable lone wolf<\/a><\/span><span class=\"meta\">Y3V3 · p.131–134<\/span><span class=\"by\">notes on <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/span><\/h3><p class=\"setup\">Appears unseen and eliminates eight Class B guards around Morofuji in under thirty seconds.<\/p><p class=\"with\">with <a href=\"../../../people/morofuji-rika.html\">Morofuji Rika<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> &quot;You&#x27;re the VIP, aren&#x27;t you?&quot;<span class=\"pg\">p.133<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> &quot;There is nothing to it, is there? I am from Class A, you are from Class B. We&#x27;re enemies.&quot;<span class=\"pg\">p.133<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> &quot;For me, winning or losing this special exam is a matter of supreme indifference.&quot;<span class=\"pg\">p.134<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Feat<\/span> Single-handedly dismantles a Class B guard unit with precise, unseen fire; spares VIP Morofuji and lets her keep the supplies.<span class=\"pg\">p.131<\/span><\/li><li><span class=\"mlabel\">Voice<\/span> Courtly, theatrical and self-assured — &quot;My, my...&quot; and grand pronouncements about the &quot;great wilderness.&quot;<span class=\"pg\">p.133<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Acts purely for his own amusement; true to his word that winning or losing is a matter of indifference to him.<span class=\"pg\">p.134<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Morofuji Rika<\/b> Spares her with a warning dressed as kindness.<span class=\"pg\">p.131–134<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kouenji-rokusuke-y3v3-p128-1\">← Before: The unseen ambush on Class B&#x27;s supply group<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p135-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"matoba-shinji ayanokouji-kiyotaka","q":"ayanokoji kiyotaka reading the shrinking map  deciding on g11 after the perimeter is restricted  weighs how the four classes will move as the map shrinks   right now  everyone s focused on moving around the island  gathering supplies and staying healthy  but that s nothing more than a prelude   it s become more likely that the class that can secure the best position for the final firefight or the one that can seize even the slightest momentum  will be the victor   we re leaving now  we re going to secure the supplies and food at g11   enough idle talk  it s precisely because the enemy is closer that we must get there first  deduces the exam s endgame is a chaotic final firefight in the shrinking area  decides to strike rather than wait   he already knew the result  overrides his objection to the risky offensive","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p135-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p135-1\">Reading the shrinking map; deciding on G11<\/a><\/span><span class=\"meta\">Y3V3 · p.135–137<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">After the perimeter is restricted, weighs how the four classes will move as the map shrinks.<\/p><p class=\"with\">with <a href=\"../../../people/matoba-shinji.html\">Matoba Shinji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Right now, everyone&#x27;s focused on moving around the island, gathering supplies and staying healthy, but that&#x27;s nothing more than a prelude.&quot;<span class=\"pg\">p.136<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;It&#x27;s become more likely that the class that can secure the best position for the final firefight or the one that can seize even the slightest momentum, will be the victor.&quot;<span class=\"pg\">p.136<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;We&#x27;re leaving now. We&#x27;re going to secure the supplies and food at G11.&quot;<span class=\"pg\">p.137<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Enough idle talk. It&#x27;s precisely because the enemy is closer that we must get there first.&quot;<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> Deduces the exam&#x27;s endgame is a chaotic final firefight in the shrinking area; decides to strike rather than wait — he already knew the result.<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Matoba Shinji<\/b> Overrides his objection to the risky offensive.<span class=\"pg\">p.137<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p123-1\">← Before: Day two: Kōenji still alive; waiting strategy<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p139-1\">→ After: The G11 standoff: waiting five minutes twice<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p139-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"matoba-shinji hashimoto-masayoshi ayanokouji-kiyotaka","q":"ayanokoji kiyotaka the g11 standoff  waiting five minutes twice halts the class two or three minutes from the hidden class b positions   we ll wait here for five minutes   they don t have that luxury   we re not using any tactics  if we save them  the enemy will have to remain constantly on guard   we ll wait another five minutes   let s advance  once you find the enemy  you have my permission to attack without hesitation   also  matoba  you ll take command during the battle  delays twice by five minutes   saving tactics and forcing the enemy to stay constantly vigilant   then hands battlefield command to matoba  knowing the outcome already  patient and coldly calculating   times the engagement for the ideal moment and stays behind to protect the vips rather than take command  appoints him battlefield commander to coordinate the front line  manages the weapon alongside him  asks ayanokoji to stay back and protect the vips","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p139-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p139-1\">The G11 standoff: waiting five minutes twice<\/a><\/span><span class=\"meta\">Y3V3 · p.139–143<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Halts the class two or three minutes from the hidden Class B positions.<\/p><p class=\"with\">with <a href=\"../../../people/matoba-shinji.html\">Matoba Shinji<\/a> · <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;We&#x27;ll wait here for five minutes.&quot;<span class=\"pg\">p.139<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;They don&#x27;t have that luxury.&quot;<span class=\"pg\">p.139<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;We&#x27;re not using any tactics. If we save them, the enemy will have to remain constantly on guard.&quot;<span class=\"pg\">p.139<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;We&#x27;ll wait another five minutes.&quot;<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Let&#x27;s advance. Once you find the enemy, you have my permission to attack without hesitation.&quot;<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Also, Matoba, you&#x27;ll take command during the battle.&quot;<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Tactic<\/span> Delays twice by five minutes — saving tactics and forcing the enemy to stay constantly vigilant — then hands battlefield command to Matoba, knowing the outcome already.<span class=\"pg\">p.139–140<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Patient and coldly calculating — times the engagement for the ideal moment and stays behind to protect the VIPs rather than take command.<span class=\"pg\">p.139–140<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Matoba Shinji<\/b> Appoints him battlefield commander to coordinate the front line.<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Manages the weapon alongside him; asks Ayanokōji to stay back and protect the VIPs.<span class=\"pg\">p.138, 140<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p135-1\">← Before: Reading the shrinking map; deciding on G11<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p151-1\">→ After: Ch.5 — depth read: sealing the alliance<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p151-1","v":"y3v3","y":3,"o":35,"k":"action spoken","w":"ichinose-honami hashimoto-masayoshi kanzaki-ryuuji shiraishi-asuka ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 5   depth read  sealing the alliance  if you ve seen the kind of student ichinose is  you should understand that she can be trusted   it s not like taking first place one time will get them to class a   what s wrong  are you worried about the alliance after all   i suppose i ll gratefully accept your sentiment    to hashimoto offering to be his shield  let s join forces  that way  class c and class d can form a group of fifty   you should try to better understand just how incredible it is to be trusted  goes unarmed with hashimoto to negotiate the alliance with kanzaki s class d  securing their acceptance  trusts her to honor the alliance  she had pre briefed class d to accept them  persuades the class  hashimoto offers to shield him and voices private doubts  negotiates with him  defuses his armed welcome  and later urges him to trust in class d and know ichinose  discusses class d s trust with her","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p151-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p151-1\">Ch.5 — depth read: sealing the alliance<\/a><\/span><span class=\"meta\">Y3V3 · p.151–166<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a> · <a href=\"../../../people/kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a> · <a href=\"../../../people/shiraishi-asuka.html\">Shiraishi Asuka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;If you&#x27;ve seen the kind of student Ichinose is, you should understand that she can be trusted.&quot;<span class=\"pg\">p.152<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;It&#x27;s not like taking first place one time will get them to Class A.&quot;<span class=\"pg\">p.152<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;What&#x27;s wrong? Are you worried about the alliance after all?&quot;<span class=\"pg\">p.153<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I suppose I&#x27;ll gratefully accept your sentiment.&quot; — to Hashimoto offering to be his shield<span class=\"pg\">p.154<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Let&#x27;s join forces. That way, Class C and Class D can form a group of fifty.&quot;<span class=\"pg\">p.156<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You should try to better understand just how incredible it is to be trusted.&quot;<span class=\"pg\">p.166<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Goes unarmed with Hashimoto to negotiate the alliance with Kanzaki&#x27;s Class D, securing their acceptance.<span class=\"pg\">p.154–157<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Trusts her to honor the alliance; she had pre-briefed Class D to accept them.<span class=\"pg\">p.152–159<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Persuades the class; Hashimoto offers to shield him and voices private doubts.<span class=\"pg\">p.151–154<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kanzaki Ryūji<\/b> Negotiates with him, defuses his armed welcome, and later urges him to trust in Class D and know Ichinose.<span class=\"pg\">p.156–166<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiraishi Asuka<\/b> Discusses Class D&#x27;s trust with her.<span class=\"pg\">p.160<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p139-1\">← Before: The G11 standoff: waiting five minutes twice<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p151-2\">→ After: Moving to contact Class D; the class accepts<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p151-2","v":"y3v3","y":3,"o":35,"k":"spoken","w":"hashimoto-masayoshi ayanokouji-kiyotaka","q":"ayanokoji kiyotaka moving to contact class d  the class accepts after the retreat  moves east toward class d at m10 as the map shrinks toward the center   if you ve seen the kind of student ichinose is  you should understand that she can be trusted   it s not like taking first place one time will get them to class a  if they were to carelessly throw away our alliance  the backlash would be greater than you can imagine  the collapse of a class that s been built on trust would be inevitable   what s wrong  are you worried about the alliance after all   i don t mind  in fact  actively speaking your mind is a benefit to me  not a detriment  argues ichinose can be trusted because betrayal would destroy the trust based class she built  encourages hashimoto s doubts as useful  persuades the class  fields hashimoto s private doubts","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p151-2\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p151-2\">Moving to contact Class D; the class accepts<\/a><\/span><span class=\"meta\">Y3V3 · p.151–154<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">After the retreat, moves east toward Class D at M10 as the map shrinks toward the center.<\/p><p class=\"with\">with <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;If you&#x27;ve seen the kind of student Ichinose is, you should understand that she can be trusted.&quot;<span class=\"pg\">p.152<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;It&#x27;s not like taking first place one time will get them to Class A. If they were to carelessly throw away our alliance, the backlash would be greater than you can imagine. The collapse of a class that&#x27;s been built on trust would…<span class=\"pg\">p.152<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;What&#x27;s wrong? Are you worried about the alliance after all?&quot;<span class=\"pg\">p.153<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;It&#x27;s not like taking first place one time will get them to Class A. If they were to carelessly throw away our alliance, the backlash would be greater than you can imagine. The collapse of a class that&#x27;s been built on trust would be inevitable.&quot;<span class=\"pg\">p.152<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I don&#x27;t mind. In fact, actively speaking your mind is a benefit to me, not a detriment.&quot;<span class=\"pg\">p.153<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Argues Ichinose can be trusted because betrayal would destroy the trust-based class she built; encourages Hashimoto&#x27;s doubts as useful.<span class=\"pg\">p.151–153<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Persuades the class; fields Hashimoto&#x27;s private doubts.<span class=\"pg\">p.151–154<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p151-1\">← Before: Ch.5 — depth read: sealing the alliance<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p154-1\">→ After: Going unarmed to negotiate<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y3v3-p151-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka hashimoto-masayoshi","q":"hashimoto masayoshi ch 5   depth read  hashimoto s lingering doubt  we re lucky ayanokouji brought up the idea of an alliance   you re sure this is gonna be okay  right   i m going too and don t try to stop me  alright  if they start shootin  without askin  questions  i can be your shield  publicly champions the alliance to steady the class but privately doubts it  offers to shield ayanokoji  showing genuine loyalty  persuades classmates  voices doubts  and offers to protect him in negotiations","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y3v3-p151-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hashimoto-masayoshi.html#sc-hashimoto-masayoshi-y3v3-p151-1\">Ch.5 — depth read: Hashimoto&#x27;s lingering doubt<\/a><\/span><span class=\"meta\">Y3V3 · p.151–166<\/span><span class=\"by\">notes on <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;We&#x27;re lucky Ayanokouji brought up the idea of an alliance.&quot;<span class=\"pg\">p.151<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;You&#x27;re sure this is gonna be okay, right?&quot;<span class=\"pg\">p.153<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;I&#x27;m going too and don&#x27;t try to stop me, alright? If they start shootin&#x27; without askin&#x27; questions, I can be your shield.&quot;<span class=\"pg\">p.154<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Publicly champions the alliance to steady the class but privately doubts it; offers to shield Ayanokōji, showing genuine loyalty.<span class=\"pg\">p.151–154<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Persuades classmates, voices doubts, and offers to protect him in negotiations.<span class=\"pg\">p.151–154<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p101-1\">← Before: Hashimoto on the food situation<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p151-2\">→ After: Selling the alliance, then private doubts<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y3v3-p151-2","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka hashimoto-masayoshi","q":"hashimoto masayoshi selling the alliance  then private doubts  we re lucky ayanokouji brought up the idea of an alliance  if no one had even mentioned the word  alliance  at this point  there s no way one would ve been formed during this special exam   don t you worry about that  ayanokouji ll handle the talks   you re sure this is gonna be okay  right   nah  forget i said that  it s your plan and you re the one who said you d drop out if we lose  publicly champions the alliance to steady the class but cannot shake his own doubts  reveals he never told the class ichinose might have formed it anyway  voices private doubts  accepts ayanokoji s offer to consult him anytime","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y3v3-p151-2\"><h3><span class=\"ttl\"><a href=\"../../../people/hashimoto-masayoshi.html#sc-hashimoto-masayoshi-y3v3-p151-2\">Selling the alliance, then private doubts<\/a><\/span><span class=\"meta\">Y3V3 · p.151–154<\/span><span class=\"by\">notes on <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;We&#x27;re lucky Ayanokouji brought up the idea of an alliance. If no one had even mentioned the word &#x27;alliance&#x27; at this point, there&#x27;s no way one would&#x27;ve been formed during this special exam.&quot;<span class=\"pg\">p.151<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Don&#x27;t you worry about that. Ayanokouji&#x27;ll handle the talks.&quot;<span class=\"pg\">p.151<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;You&#x27;re sure this is gonna be okay, right?&quot;<span class=\"pg\">p.153<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;...Nah, forget I said that. It&#x27;s your plan and you&#x27;re the one who said you&#x27;d drop out if we lose.&quot;<span class=\"pg\">p.153<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Publicly champions the alliance to steady the class but cannot shake his own doubts; reveals he never told the class Ichinose might have formed it anyway.<span class=\"pg\">p.151–153<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Voices private doubts; accepts Ayanokōji&#x27;s offer to consult him anytime.<span class=\"pg\">p.153<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p151-1\">← Before: Ch.5 — depth read: Hashimoto&#x27;s lingering doubt<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p154-1\">→ After: Going as Ayanokōji&#x27;s shield<\/button><\/div><\/article>"},{"i":"sc-ichinose-honami-y3v3-p151-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka kobashi-yume kanzaki-ryuuji ichinose-honami","q":"ichinose honami ch 5   depth read  ichinose s faith from afar watches the g11 battle on her tablet and  seeing class c flee  prepares her class to receive them   ayanokouji kun won t lose  no  i won t let him lose   if we absorb class c  we ll become the largest force   i need you to tell everyone in the class properly beforehand  ayanokouji kun will be making contact with class d  so when he does  make sure we absolutely do not attack first   i understand  ayanokouji kun  i know what you re thinking  calmly confident in ayanokoji despite his apparent blunders  orchestrates class d s reception of class c and pre empts any attack  trusts him completely  attributes his  carelessness  to a deeper plan  and entrusts command to him  vip  relays her instructions to the class  sends instructions via kobashi  kanzaki wonders whether the alliance benefits class d","h":"<article class=\"card\" id=\"sc-ichinose-honami-y3v3-p151-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ichinose-honami.html#sc-ichinose-honami-y3v3-p151-1\">Ch.5 — depth read: Ichinose&#x27;s faith from afar<\/a><\/span><span class=\"meta\">Y3V3 · p.151–166<\/span><span class=\"by\">notes on <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/span><\/h3><p class=\"setup\">Watches the G11 battle on her tablet and, seeing Class C flee, prepares her class to receive them.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/index.html#kobashi-yume\">Kobashi Yume<\/a> · <a href=\"../../../people/kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> &quot;Ayanokouji-kun won&#x27;t lose. No, I won&#x27;t let him lose.&quot;<span class=\"pg\">p.159<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> &quot;If we absorb Class C, we&#x27;ll become the largest force.&quot;<span class=\"pg\">p.159<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> &quot;I need you to tell everyone in the class properly beforehand. Ayanokouji-kun will be making contact with Class D, so when he does, make sure we absolutely do not attack first.&quot;<span class=\"pg\">p.159<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I understand, Ayanokouji-kun. I know what you&#x27;re thinking.&quot;<span class=\"pg\">p.159<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Calmly confident in Ayanokōji despite his apparent blunders; orchestrates Class D&#x27;s reception of Class C and pre-empts any attack.<span class=\"pg\">p.158–159<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Trusts him completely, attributes his &quot;carelessness&quot; to a deeper plan, and entrusts command to him.<span class=\"pg\">p.158–159<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kobashi Yume<\/b> VIP; relays her instructions to the class.<span class=\"pg\">p.158–159<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kanzaki Ryūji<\/b> Sends instructions via Kobashi; Kanzaki wonders whether the alliance benefits Class D.<span class=\"pg\">p.159<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y3v3-p158-1\">→ After: Watching the G11 battle; pre-briefing Class D<\/button><\/div><\/article>"},{"i":"sc-kanzaki-ryuuji-y3v3-p151-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka ichinose-honami ayanokouji-atsuomi kanzaki-ryuuji","q":"kanzaki ryuji ch 5   depth read  kanzaki s armed scrutiny leads ten class d guards in a wall  guns trained on ayanokoji and hashimoto as they approach unarmed   i wonder about that  there s a possibility your allies are hiding nearby   just three people ain t gonna do nothin   if we defeat the two of you here  we can significantly lower our chances of coming in last  this is a golden opportunity   what if we trust you and are betrayed  that would be a crisis for our class   i forgot to tell you something important  regarding the chain of command from here on  ichinose has said to entrust everything to you  ayanokouji   you have the power to turn the tide of battle all by yourself  stern  loyal to ichinose and initially hostile  but principled   lowers his guns once briefed  yet remains troubled by why ayanokoji proposed the alliance  confronts him at gunpoint  then accepts the alliance and questions his motives  fully loyal  reports that she entrusted command to ayanokoji  admires ayanokoji s father  which colors his high opinion of ayanokoji","h":"<article class=\"card\" id=\"sc-kanzaki-ryuuji-y3v3-p151-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kanzaki-ryuuji.html#sc-kanzaki-ryuuji-y3v3-p151-1\">Ch.5 — depth read: Kanzaki&#x27;s armed scrutiny<\/a><\/span><span class=\"meta\">Y3V3 · p.151–166<\/span><span class=\"by\">notes on <a href=\"../../../people/kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a><\/span><\/h3><p class=\"setup\">Leads ten Class D guards in a wall, guns trained on Ayanokōji and Hashimoto as they approach unarmed.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kanzaki Ryūji<\/b> &quot;I wonder about that. There&#x27;s a possibility your allies are hiding nearby.&quot;<span class=\"pg\">p.155<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kanzaki Ryūji<\/b> &quot;Just three people ain&#x27;t gonna do nothin&#x27;.&quot;<span class=\"pg\">p.155<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kanzaki Ryūji<\/b> &quot;If we defeat the two of you here, we can significantly lower our chances of coming in last. This is a golden opportunity.&quot;<span class=\"pg\">p.156<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;What if we trust you and are betrayed? That would be a crisis for our class.&quot;<span class=\"pg\">p.156<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I forgot to tell you something important. Regarding the chain of command from here on, Ichinose has said to entrust everything to you, Ayanokouji.&quot;<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You have the power to turn the tide of battle all by yourself.&quot;<span class=\"pg\">p.164<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Stern, loyal to Ichinose and initially hostile, but principled — lowers his guns once briefed, yet remains troubled by why Ayanokōji proposed the alliance.<span class=\"pg\">p.155–166<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Confronts him at gunpoint, then accepts the alliance and questions his motives.<span class=\"pg\">p.155–166<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Fully loyal; reports that she entrusted command to Ayanokōji.<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Atsuomi<\/b> Admires Ayanokōji&#x27;s father, which colors his high opinion of Ayanokōji.<span class=\"pg\">p.164<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kanzaki-ryuuji-y3v3-p126-1\">← Before: Kanzaki sees the map shrinking<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kanzaki-ryuuji-y3v3-p155-1\">→ After: The armed reception; lowering the guns<\/button><\/div><\/article>"},{"i":"sc-shibata-sou-y3v3-p151-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka shibata-sou","q":"shibata so ch 5   depth read  shibata s interrupted greeting  h hey  ayanokouji  sorry to bother you before you eat  but you got a sec   uh  how should i put it  we re allies now  right  so  i just wanted to say hi  or something  nervous and eager to befriend ayanokoji now that they re allies  cut off by kanzaki before he can ask his question  tries to greet him at the campfire  flees when kanzaki intervenes","h":"<article class=\"card\" id=\"sc-shibata-sou-y3v3-p151-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shibata-sou.html#sc-shibata-sou-y3v3-p151-1\">Ch.5 — depth read: Shibata&#x27;s interrupted greeting<\/a><\/span><span class=\"meta\">Y3V3 · p.151–166<\/span><span class=\"by\">notes on <a href=\"../../../people/shibata-sou.html\">Shibata Sō<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shibata Sō<\/b> &quot;H-Hey, Ayanokouji. Sorry to bother you before you eat, but you got a sec?&quot;<span class=\"pg\">p.162<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shibata Sō<\/b> &quot;Uh... how should I put it? We&#x27;re allies now, right? So, I just wanted to say hi, or something...&quot;<span class=\"pg\">p.162<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Nervous and eager to befriend Ayanokōji now that they&#x27;re allies; cut off by Kanzaki before he can ask his question.<span class=\"pg\">p.162<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Tries to greet him at the campfire; flees when Kanzaki intervenes.<span class=\"pg\">p.162<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shibata-sou-y3v3-p162-1\">→ After: The interrupted greeting<\/button><\/div><\/article>"},{"i":"sc-shiraishi-asuka-y3v3-p151-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka shiraishi-asuka","q":"shiraishi asuka ch 5   depth read  class d s trust impresses  the charm class d possesses is incredible  impressed by how warmly class d treats the wary class c members as equals  lowering their guard  discusses the alliance and class d s strength with him","h":"<article class=\"card\" id=\"sc-shiraishi-asuka-y3v3-p151-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shiraishi-asuka.html#sc-shiraishi-asuka-y3v3-p151-1\">Ch.5 — depth read: Class D&#x27;s trust impresses<\/a><\/span><span class=\"meta\">Y3V3 · p.151–166<\/span><span class=\"by\">notes on <a href=\"../../../people/shiraishi-asuka.html\">Shiraishi Asuka<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shiraishi Asuka<\/b> &quot;The charm Class D possesses is incredible.&quot;<span class=\"pg\">p.160<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Impressed by how warmly Class D treats the wary Class C members as equals, lowering their guard.<span class=\"pg\">p.160<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Discusses the alliance and Class D&#x27;s strength with him.<span class=\"pg\">p.160<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shiraishi-asuka-y3v3-p117-1\">← Before: Depth review: Class C&#x27;s recon commander<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-shiraishi-asuka-y3v3-p160-1\">→ After: Impressed by Class D&#x27;s trust<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p154-1","v":"y3v3","y":3,"o":35,"k":"action spoken","w":"kanzaki-ryuuji hashimoto-masayoshi ayanokouji-kiyotaka","q":"ayanokoji kiyotaka going unarmed to negotiate hands his weapon to matoba and walks unarmed toward class d s standby point with hashimoto   we ll wait here for now  i ll go talk to them by myself first   i suppose i ll gratefully accept your sentiment   it would be the same even if we had our weapons  standing up to them would be futile against their overwhelming numbers   we have no intention of attacking   but in reality  we have no desire to fight class d  first  let us talk   let s join forces  that way  class c and class d can form a group of fifty   right now  we need class d s help  and we believe we can be the strength that class d needs  walks unarmed into kanzaki s gun wall  argues that beating class c doesn t win the exam  and secures class d s acceptance of the alliance  negotiates with him at gunpoint  his calm win or lose logic and ichinose s prior briefing win him over  lets him come as a shield  grateful for his resolve","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p154-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p154-1\">Going unarmed to negotiate<\/a><\/span><span class=\"meta\">Y3V3 · p.154–157<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Hands his weapon to Matoba and walks unarmed toward Class D&#x27;s standby point with Hashimoto.<\/p><p class=\"with\">with <a href=\"../../../people/kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a> · <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;We&#x27;ll wait here for now. I&#x27;ll go talk to them by myself first.&quot;<span class=\"pg\">p.154<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;I suppose I&#x27;ll gratefully accept your sentiment.&quot;<span class=\"pg\">p.154<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;It would be the same even if we had our weapons. Standing up to them would be futile against their overwhelming numbers.&quot;<span class=\"pg\">p.154<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;We have no intention of attacking.&quot;<span class=\"pg\">p.156<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;But in reality, we have no desire to fight Class D. First, let us talk.&quot;<span class=\"pg\">p.156<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Let&#x27;s join forces. That way, Class C and Class D can form a group of fifty.&quot;<span class=\"pg\">p.156<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Right now, we need Class D&#x27;s help. And we believe we can be the strength that Class D needs.&quot;<span class=\"pg\">p.156<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Walks unarmed into Kanzaki&#x27;s gun wall, argues that beating Class C doesn&#x27;t win the exam, and secures Class D&#x27;s acceptance of the alliance.<span class=\"pg\">p.154–157<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kanzaki Ryūji<\/b> Negotiates with him at gunpoint; his calm win-or-lose logic and Ichinose&#x27;s prior briefing win him over.<span class=\"pg\">p.155–157<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Lets him come as a shield, grateful for his resolve.<span class=\"pg\">p.154<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p151-2\">← Before: Moving to contact Class D; the class accepts<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p160-1\">→ After: The merged campsite and the talk with Kanzaki<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y3v3-p154-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"hashimoto-masayoshi","q":"hashimoto masayoshi going as ayanokoji s shield  i m going too and don t try to stop me  alright  if they start shootin  without askin  questions  i can be your shield   so now we ve got no way to fight back  huh   i m grateful we didn t get shot  but  you re being awfully reasonable  aren t ya   well  what do you know  you re sayin  ichinose saw it comin  that we d ask for your help  genuinely loyal   offers to shield ayanokoji unarmed  then is suspicious of class d s reasonableness until ichinose s foresight is revealed","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y3v3-p154-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hashimoto-masayoshi.html#sc-hashimoto-masayoshi-y3v3-p154-1\">Going as Ayanokōji&#x27;s shield<\/a><\/span><span class=\"meta\">Y3V3 · p.154–157<\/span><span class=\"by\">notes on <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/span><\/h3><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;I&#x27;m going too and don&#x27;t try to stop me, alright? If they start shootin&#x27; without askin&#x27; questions, I can be your shield.&quot;<span class=\"pg\">p.154<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;So now we&#x27;ve got no way to fight back, huh.&quot;<span class=\"pg\">p.154<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;I&#x27;m grateful we didn&#x27;t get shot, but... you&#x27;re being awfully reasonable, aren&#x27;t ya?&quot;<span class=\"pg\">p.157<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Well, what do you know— You&#x27;re sayin&#x27; Ichinose saw it comin&#x27; that we&#x27;d ask for your help?&quot;<span class=\"pg\">p.157<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Genuinely loyal — offers to shield Ayanokōji unarmed, then is suspicious of Class D&#x27;s reasonableness until Ichinose&#x27;s foresight is revealed.<span class=\"pg\">p.154–157<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p151-2\">← Before: Selling the alliance, then private doubts<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p167-1\">→ After: Ch.6 — depth read: Hashimoto on the shrinking area<\/button><\/div><\/article>"},{"i":"sc-kanzaki-ryuuji-y3v3-p155-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka ichinose-honami hashimoto-masayoshi kanzaki-ryuuji","q":"kanzaki ryuji the armed reception  lowering the guns leads ten class d guards in a wall  guns trained on ayanokoji and hashimoto as they approach unarmed   halt   i wonder about that  there s a possibility your allies are hiding nearby   if your commander is using tactics  that s not necessarily the case  as you should be well aware   it seems you were caught in a surprise attack by ryuuen and lost the morning battle as well   if we defeat the two of you here  we can significantly lower our chances of coming in last  this is a golden opportunity   an alliance  what if we trust you and are betrayed  that would be a crisis for our class   you can bring your allies  as you wish  let s talk first   ichinose told us that class c might make contact at some point  she also warned us not to make the first move until we were attacked  holds a disciplined armed line and probes their story about gps jamming  then lowers his gun once ayanokoji s reasoning and ichinose s prior briefing align  stern and loyal to ichinose but principled   no hostility once the logic is clear  willing to talk rather than fire  confronts him at gunpoint then accepts the alliance  acts on her instruction not to attack first  debates the gps jamming possibilities with him","h":"<article class=\"card\" id=\"sc-kanzaki-ryuuji-y3v3-p155-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kanzaki-ryuuji.html#sc-kanzaki-ryuuji-y3v3-p155-1\">The armed reception; lowering the guns<\/a><\/span><span class=\"meta\">Y3V3 · p.155–157<\/span><span class=\"by\">notes on <a href=\"../../../people/kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a><\/span><\/h3><p class=\"setup\">Leads ten Class D guards in a wall, guns trained on Ayanokōji and Hashimoto as they approach unarmed.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kanzaki Ryūji<\/b> &quot;—Halt.&quot;<span class=\"pg\">p.155<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kanzaki Ryūji<\/b> &quot;I wonder about that. There&#x27;s a possibility your allies are hiding nearby.&quot;<span class=\"pg\">p.155<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kanzaki Ryūji<\/b> &quot;If your commander is using tactics, that&#x27;s not necessarily the case, as you should be well aware.&quot;<span class=\"pg\">p.155<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;It seems you were caught in a surprise attack by Ryuuen and lost the morning battle as well.&quot;<span class=\"pg\">p.156<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;If we defeat the two of you here, we can significantly lower our chances of coming in last. This is a golden opportunity.&quot;<span class=\"pg\">p.156<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;An alliance... What if we trust you and are betrayed? That would be a crisis for our class.&quot;<span class=\"pg\">p.156<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You can bring your allies. As you wish, let&#x27;s talk first.&quot;<span class=\"pg\">p.156<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Ichinose told us that Class C might make contact at some point. She also warned us not to make the first move until we were attacked.&quot;<span class=\"pg\">p.157<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Holds a disciplined armed line and probes their story about GPS jamming, then lowers his gun once Ayanokōji&#x27;s reasoning and Ichinose&#x27;s prior briefing align.<span class=\"pg\">p.155–157<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Stern and loyal to Ichinose but principled — no hostility once the logic is clear, willing to talk rather than fire.<span class=\"pg\">p.155–157<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Confronts him at gunpoint then accepts the alliance.<span class=\"pg\">p.155–157<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Acts on her instruction not to attack first.<span class=\"pg\">p.157<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Debates the GPS-jamming possibilities with him.<span class=\"pg\">p.155<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kanzaki-ryuuji-y3v3-p151-1\">← Before: Ch.5 — depth read: Kanzaki&#x27;s armed scrutiny<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kanzaki-ryuuji-y3v3-p162-1\">→ After: Serving duty; questioning Ayanokōji&#x27;s motives<\/button><\/div><\/article>"},{"i":"sc-ichinose-honami-y3v3-p158-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka kobashi-yume kanzaki-ryuuji ichinose-honami","q":"ichinose honami watching the g11 battle  pre briefing class d watches the g11 battle on her tablet and sees class c flee southeast   that s not true   ayanokouji kun won t lose  no  i won t let him lose   if we absorb class c  we ll become the largest force   i need you to tell everyone in the class properly beforehand  ayanokouji kun will be making contact with class d  so when he does  make sure we absolutely do not attack first   i understand  ayanokouji kun  i know what you re thinking  calmly confident in ayanokoji despite his  uncharacteristic carelessness  orchestrates class d s reception of class c and pre empts any attack  reasons that absorbing class c makes them the largest force  which neither class a nor b can attack lightly  forcing them to fight each other  trusts him completely  attributes his blunders to a deeper plan and entrusts command to him  vip  relays her instructions to the class  sends word via kobashi  answers his doubt about class d s benefit","h":"<article class=\"card\" id=\"sc-ichinose-honami-y3v3-p158-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ichinose-honami.html#sc-ichinose-honami-y3v3-p158-1\">Watching the G11 battle; pre-briefing Class D<\/a><\/span><span class=\"meta\">Y3V3 · p.158–159<\/span><span class=\"by\">notes on <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/span><\/h3><p class=\"setup\">Watches the G11 battle on her tablet and sees Class C flee southeast.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/index.html#kobashi-yume\">Kobashi Yume<\/a> · <a href=\"../../../people/kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> &quot;That&#x27;s not true.&quot;<span class=\"pg\">p.159<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> &quot;Ayanokouji-kun won&#x27;t lose. No, I won&#x27;t let him lose.&quot;<span class=\"pg\">p.159<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> &quot;If we absorb Class C, we&#x27;ll become the largest force.&quot;<span class=\"pg\">p.159<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I need you to tell everyone in the class properly beforehand. Ayanokouji-kun will be making contact with Class D, so when he does, make sure we absolutely do not attack first.&quot;<span class=\"pg\">p.159<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;—I understand, Ayanokouji-kun. I know what you&#x27;re thinking.&quot;<span class=\"pg\">p.159<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Calmly confident in Ayanokōji despite his &quot;uncharacteristic carelessness&quot;; orchestrates Class D&#x27;s reception of Class C and pre-empts any attack.<span class=\"pg\">p.158–159<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> Reasons that absorbing Class C makes them the largest force, which neither Class A nor B can attack lightly, forcing them to fight each other.<span class=\"pg\">p.158<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Trusts him completely, attributes his blunders to a deeper plan and entrusts command to him.<span class=\"pg\">p.158–159<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kobashi Yume<\/b> VIP; relays her instructions to the class.<span class=\"pg\">p.158–159<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kanzaki Ryūji<\/b> Sends word via Kobashi; answers his doubt about Class D&#x27;s benefit.<span class=\"pg\">p.159<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y3v3-p151-1\">← Before: Ch.5 — depth read: Ichinose&#x27;s faith from afar<\/button><\/div><\/article>"},{"i":"sc-kobashi-yume-y3v3-p158-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ichinose-honami kanzaki-ryuuji kobashi-yume","q":"kobashi yume kobashi relays ichinose s instructions class d s vip  listening to the g11 battle and passing ichinose s words to the class   we re just going to keep our distance like we ve been doing  right   at this rate  class c might just end up losing   does that mean we re supposed to help class c  voices the safe  standard strategy and the worry that class c will lose  before ichinose corrects her  hurries off to relay the order not to attack first  receives and conveys her instructions  hurries off to get him with ichinose s message","h":"<article class=\"card\" id=\"sc-kobashi-yume-y3v3-p158-1\"><h3><span class=\"ttl\">Kobashi relays Ichinose&#x27;s instructions<\/span><span class=\"meta\">Y3V3 · p.158–159<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#kobashi-yume\">Kobashi Yume<\/a><\/span><\/h3><p class=\"setup\">Class D&#x27;s VIP, listening to the G11 battle and passing Ichinose&#x27;s words to the class.<\/p><p class=\"with\">with <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"../../../people/kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kobashi Yume<\/b> &quot;We&#x27;re just going to keep our distance like we&#x27;ve been doing, right?&quot;<span class=\"pg\">p.158<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kobashi Yume<\/b> &quot;At this rate, Class C might just end up losing.&quot;<span class=\"pg\">p.159<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kobashi Yume<\/b> &quot;...Does that mean we&#x27;re supposed to help Class C?&quot;<span class=\"pg\">p.159<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Voices the safe, standard strategy and the worry that Class C will lose, before Ichinose corrects her; hurries off to relay the order not to attack first.<span class=\"pg\">p.158–159<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Receives and conveys her instructions.<span class=\"pg\">p.158–159<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kanzaki Ryūji<\/b> Hurries off to get him with Ichinose&#x27;s message.<span class=\"pg\">p.159<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p160-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"kanzaki-ryuuji ichinose-honami shiraishi-asuka ayanokouji-atsuomi ayanokouji-kiyotaka","q":"ayanokoji kiyotaka the merged campsite and the talk with kanzaki the combined c d camp  class d treats the wary class c students as equals  lowering their guard   i m surprised  too  it s a strength that can t be seen from class rankings or test scores alone   to maintain an alliance  both sides must be equal  it would never work if the powerful party tried to dominate from above   if i m just stating my wishful thinking  i d want them to crush each other somewhere that doesn t involve us   i see  i appreciate that  but are you ok with that   such impressive loyalty   there s no  why  to it  we were hit with a surprise attack from ryuuen s class and lost half our classmates in an instant   you re overestimating me   can t you think of the alliance as insurance  just in case   you should try to better understand just how incredible it is to be trusted  frames the alliance as insurance that divides horikita s and ryuen s attention   it makes class c easier to operate  not a gift  humble about his own losses yet quietly pushing kanzaki to believe in class d s potential and trust  explains his motives  presses him to share ichinose s confidence and resolve  she entrusted command of class d to him  they discuss class d s trust building together  kanzaki s admiration of his father colors his high opinion of ayanokoji","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p160-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p160-1\">The merged campsite and the talk with Kanzaki<\/a><\/span><span class=\"meta\">Y3V3 · p.160–166<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">The combined C–D camp; Class D treats the wary Class C students as equals, lowering their guard.<\/p><p class=\"with\">with <a href=\"../../../people/kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a> · <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"../../../people/shiraishi-asuka.html\">Shiraishi Asuka<\/a> · <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;I&#x27;m surprised, too. It&#x27;s a strength that can&#x27;t be seen from class rankings or test scores alone.&quot;<span class=\"pg\">p.160<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;To maintain an alliance, both sides must be equal. It would never work if the powerful party tried to dominate from above.&quot;<span class=\"pg\">p.160<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;If I&#x27;m just stating my wishful thinking, I&#x27;d want them to crush each other somewhere that doesn&#x27;t involve us.&quot;<span class=\"pg\">p.161<\/span><\/li><\/ul><details class=\"more\"><summary>12 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I see. I appreciate that, but are you ok with that?&quot;<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Such impressive loyalty.&quot;<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;There&#x27;s no &#x27;why&#x27; to it. We were hit with a surprise attack from Ryuuen&#x27;s class and lost half our classmates in an instant.&quot;<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You&#x27;re overestimating me.&quot;<span class=\"pg\">p.165<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Can&#x27;t you think of the alliance as insurance, just in case?&quot;<span class=\"pg\">p.165<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You should try to better understand just how incredible it is to be trusted.&quot;<span class=\"pg\">p.166<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> Frames the alliance as insurance that divides Horikita&#x27;s and Ryūen&#x27;s attention — it makes Class C easier to operate, not a gift.<span class=\"pg\">p.165<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Humble about his own losses yet quietly pushing Kanzaki to believe in Class D&#x27;s potential and trust.<span class=\"pg\">p.163–166<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kanzaki Ryūji<\/b> Explains his motives; presses him to share Ichinose&#x27;s confidence and resolve.<span class=\"pg\">p.163–166<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> She entrusted command of Class D to him.<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiraishi Asuka<\/b> They discuss Class D&#x27;s trust-building together.<span class=\"pg\">p.160<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Atsuomi<\/b> Kanzaki&#x27;s admiration of his father colors his high opinion of Ayanokōji.<span class=\"pg\">p.165<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p154-1\">← Before: Going unarmed to negotiate<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p167-1\">→ After: Ch.6 — depth read: the solo plan<\/button><\/div><\/article>"},{"i":"sc-shiraishi-asuka-y3v3-p160-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka shiraishi-asuka","q":"shiraishi asuka impressed by class d s trust  the charm class d possesses is incredible  impressed by how class d treats the wary class c members as equals and actively mingles  lowering their guard  discusses the alliance s balance with him","h":"<article class=\"card\" id=\"sc-shiraishi-asuka-y3v3-p160-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shiraishi-asuka.html#sc-shiraishi-asuka-y3v3-p160-1\">Impressed by Class D&#x27;s trust<\/a><\/span><span class=\"meta\">Y3V3 · p.160<\/span><span class=\"by\">notes on <a href=\"../../../people/shiraishi-asuka.html\">Shiraishi Asuka<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shiraishi Asuka<\/b> &quot;The charm Class D possesses is incredible.&quot;<span class=\"pg\">p.160<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Impressed by how Class D treats the wary Class C members as equals and actively mingles, lowering their guard.<span class=\"pg\">p.160<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Discusses the alliance&#x27;s balance with him.<span class=\"pg\">p.160<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shiraishi-asuka-y3v3-p151-1\">← Before: Ch.5 — depth read: Class D&#x27;s trust impresses<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-shiraishi-asuka-y3v3-p197-1\">→ After: Ch.7 — depth read: Shiraishi reports the chaos<\/button><\/div><\/article>"},{"i":"sc-kanzaki-ryuuji-y3v3-p162-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka shibata-sou ayanokouji-atsuomi kanzaki-ryuuji","q":"kanzaki ryuji serving duty  questioning ayanokoji s motives interrupts shibata s greeting to speak with ayanokoji at the campfire   i forgot to tell you something important  regarding the chain of command from here on  ichinose has said to entrust everything to you  ayanokouji   my satisfaction is irrelevant  ichinose is the leader of class d   there s something that i just can t seem to accept   why did you propose something as unprofitable as an alliance with class d   you have the power to turn the tide of battle all by yourself   i can t shake the feeling that they re still out of our reach  but i suppose ichinose believes  believes that with you  we can aim for that  loyal  humble and still troubled   accepts ichinose s command transfer without complaint but needs to understand why ayanokoji helped  slowly won over  questions his motives  overestimates him based on two years of watching  and is urged to share ichinose s confidence  cuts off his conversation with ayanokoji  shibata flees  admires atsuomi  as his father did  which raises his opinion of ayanokoji","h":"<article class=\"card\" id=\"sc-kanzaki-ryuuji-y3v3-p162-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kanzaki-ryuuji.html#sc-kanzaki-ryuuji-y3v3-p162-1\">Serving duty; questioning Ayanokōji&#x27;s motives<\/a><\/span><span class=\"meta\">Y3V3 · p.162–166<\/span><span class=\"by\">notes on <a href=\"../../../people/kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a><\/span><\/h3><p class=\"setup\">Interrupts Shibata&#x27;s greeting to speak with Ayanokōji at the campfire.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/shibata-sou.html\">Shibata Sō<\/a> · <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kanzaki Ryūji<\/b> &quot;I forgot to tell you something important. Regarding the chain of command from here on, Ichinose has said to entrust everything to you, Ayanokouji.&quot;<span class=\"pg\">p.163<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kanzaki Ryūji<\/b> &quot;My satisfaction is irrelevant. Ichinose is the leader of Class D.&quot;<span class=\"pg\">p.163<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kanzaki Ryūji<\/b> &quot;...There&#x27;s something that I just can&#x27;t seem to accept.&quot;<span class=\"pg\">p.163<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Why did you propose something as unprofitable as an alliance with Class D?&quot;<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You have the power to turn the tide of battle all by yourself.&quot;<span class=\"pg\">p.165<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I can&#x27;t shake the feeling that they&#x27;re still out of our reach... But I suppose Ichinose believes; believes that with you, we can aim for that.&quot;<span class=\"pg\">p.165<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Loyal, humble and still troubled — accepts Ichinose&#x27;s command transfer without complaint but needs to understand why Ayanokōji helped; slowly won over.<span class=\"pg\">p.162–166<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Questions his motives, overestimates him based on two years of watching, and is urged to share Ichinose&#x27;s confidence.<span class=\"pg\">p.162–166<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shibata Sō<\/b> Cuts off his conversation with Ayanokōji; Shibata flees.<span class=\"pg\">p.162–163<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Atsuomi<\/b> Admires Atsuomi (as his father did), which raises his opinion of Ayanokōji.<span class=\"pg\">p.165<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kanzaki-ryuuji-y3v3-p155-1\">← Before: The armed reception; lowering the guns<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kanzaki-ryuuji-y3v3-p167-1\">→ After: Ch.6 — depth read: Kanzaki&#x27;s report and debate<\/button><\/div><\/article>"},{"i":"sc-shibata-sou-y3v3-p162-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka kanzaki-ryuuji shibata-sou","q":"shibata so the interrupted greeting approaches ayanokoji at the campfire as he cooks white rice   h hey  ayanokouji  sorry to bother you before you eat  but you got a sec   uh  how should i put it  we re allies now  right  so  i just wanted to say hi  or something   o oh  yeah  n no problem at all  see ya later  ayanokouji  nervous and eager to befriend ayanokoji now they are allies  flees in embarrassment when kanzaki interrupts before he can ask his question  tries to greet him  is cut off by kanzaki  is dismissed by him so he can speak to ayanokoji","h":"<article class=\"card\" id=\"sc-shibata-sou-y3v3-p162-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shibata-sou.html#sc-shibata-sou-y3v3-p162-1\">The interrupted greeting<\/a><\/span><span class=\"meta\">Y3V3 · p.162<\/span><span class=\"by\">notes on <a href=\"../../../people/shibata-sou.html\">Shibata Sō<\/a><\/span><\/h3><p class=\"setup\">Approaches Ayanokōji at the campfire as he cooks white rice.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shibata Sō<\/b> &quot;H-Hey, Ayanokouji. Sorry to bother you before you eat, but you got a sec?&quot;<span class=\"pg\">p.162<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shibata Sō<\/b> &quot;Uh... how should I put it? We&#x27;re allies now, right? So, I just wanted to say hi, or something...&quot;<span class=\"pg\">p.162<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shibata Sō<\/b> &quot;O-Oh, yeah, n-no problem at all. See ya later, Ayanokouji...!&quot;<span class=\"pg\">p.163<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Nervous and eager to befriend Ayanokōji now they are allies; flees in embarrassment when Kanzaki interrupts before he can ask his question.<span class=\"pg\">p.162–163<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Tries to greet him; is cut off by Kanzaki.<span class=\"pg\">p.162<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kanzaki Ryūji<\/b> Is dismissed by him so he can speak to Ayanokōji.<span class=\"pg\">p.163<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shibata-sou-y3v3-p151-1\">← Before: Ch.5 — depth read: Shibata&#x27;s interrupted greeting<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p167-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ryuuen-kakeru kanzaki-ryuuji takemoto ninomiya-yui ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 6   depth read  the solo plan  my bad  i had some business to take care of   the damage will only be greater if they lie to themselves and force it   there are broadly two methods for determining our plan  one is to envision the objective you wish to achieve and map out a path to it  the other is to gauge the enemy s aim and thwart their intentions   no  avoiding engagement is best for now  we ll stick to a defensive strategy   moving a little closer now would be the better option  h10 isn t a bad choice   class a is moving as planned  contact the commander now and tell them to disable my personal gps the moment the next gps update occurs   yeah  i m not coming back today  chooses a defensive strategy  letting the shrinking area force a general firefight   the development he s been waiting for  goes to retrieve g9 supplies then has his gps disabled  disappearing from the exam to execute a solo plan  i m not coming back today  reasons ryuen attacked class c specifically because ayanokoji is his arch rival  not class a  analyzes his motives and anticipates his final day move  explains his strategic reasoning to him  instructs him to disable his gps and handle the plan if he s  taken out  directs that she retire immediately due to fever","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p167-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p167-1\">Ch.6 — depth read: the solo plan<\/a><\/span><span class=\"meta\">Y3V3 · p.167–196<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"../../../people/kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a> · <a href=\"../../../people/ninomiya-yui.html\">Ninomiya Yui<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;My bad, I had some business to take care of.&quot;<span class=\"pg\">p.174<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;The damage will only be greater if they lie to themselves and force it.&quot;<span class=\"pg\">p.175<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;There are broadly two methods for determining our plan. One is to envision the objective you wish to achieve and map out a path to it. The other is to gauge the enemy&#x27;s aim and thwart their intentions.&quot;<span class=\"pg\">p.175<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;No, avoiding engagement is best for now. We&#x27;ll stick to a defensive strategy.&quot;<span class=\"pg\">p.177<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Moving a little closer now would be the better option. H10 isn&#x27;t a bad choice.&quot;<span class=\"pg\">p.181<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Class A is moving as planned. Contact the commander now and tell them to disable my personal GPS the moment the next GPS update occurs.&quot;<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Yeah, I&#x27;m not coming back today.&quot;<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Tactic<\/span> Chooses a defensive strategy, letting the shrinking area force a general firefight — the development he&#x27;s been waiting for.<span class=\"pg\">p.177<\/span><\/li><li><span class=\"mlabel\">Tactic<\/span> Goes to retrieve G9 supplies then has his GPS disabled, disappearing from the exam to execute a solo plan (&quot;I&#x27;m not coming back today&quot;).<span class=\"pg\">p.183–184<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> Reasons Ryūen attacked Class C specifically because Ayanokōji is his arch-rival, not Class A.<span class=\"pg\">p.175<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Analyzes his motives and anticipates his final-day move.<span class=\"pg\">p.175<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kanzaki Ryūji<\/b> Explains his strategic reasoning to him.<span class=\"pg\">p.174–181<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">takemoto<\/b> Instructs him to disable his GPS and handle the plan if he&#x27;s &quot;taken out.&quot;<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ninomiya Yui<\/b> Directs that she retire immediately due to fever.<span class=\"pg\">p.182<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p160-1\">← Before: The merged campsite and the talk with Kanzaki<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p174-1\">→ After: The alliance base: supply report and defensive strategy<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y3v3-p167-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka hashimoto-masayoshi","q":"hashimoto masayoshi ch 6   depth read  hashimoto on the shrinking area  but man  we re obviously runnin  low on supplies  we got nothin  but a bunch of starving folks over here  too   they re really testing us  but j5 and k10  that s just asking too much   we re inside the area and getting too close to the center is kinda sketchy   you re goin  too  ayanokouji  you can just save your strength for the final day  y know  worries about supplies and the shrinking area  and is concerned when ayanokoji decides to go on the supply run himself  discusses strategy and tries to talk him out of the supply run","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y3v3-p167-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hashimoto-masayoshi.html#sc-hashimoto-masayoshi-y3v3-p167-1\">Ch.6 — depth read: Hashimoto on the shrinking area<\/a><\/span><span class=\"meta\">Y3V3 · p.167–196<\/span><span class=\"by\">notes on <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;But man, we&#x27;re obviously runnin&#x27; low on supplies. We got nothin&#x27; but a bunch of starving folks over here, too.&quot;<span class=\"pg\">p.174<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;They&#x27;re really testing us... but J5 and K10? That&#x27;s just asking too much.&quot;<span class=\"pg\">p.178<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;We&#x27;re inside the area and getting too close to the center is kinda sketchy.&quot;<span class=\"pg\">p.180<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;You&#x27;re goin&#x27; too, Ayanokouji? You can just save your strength for the final day, y&#x27;know?&quot;<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Worries about supplies and the shrinking area, and is concerned when Ayanokōji decides to go on the supply run himself.<span class=\"pg\">p.174–183<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Discusses strategy and tries to talk him out of the supply run.<span class=\"pg\">p.174–183<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p154-1\">← Before: Going as Ayanokōji&#x27;s shield<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p174-1\">→ After: Worries about supplies<\/button><\/div><\/article>"},{"i":"sc-kanzaki-ryuuji-y3v3-p167-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka hashimoto-masayoshi moriyama kanzaki-ryuuji","q":"kanzaki ryuji ch 6   depth read  kanzaki s report and debate  i was just saying that we ve reached a difficult phase  we ve used most of our handheld provisions   also  sumida and minamikata have seemed somewhat unwell since this morning   that s right  i want to avoid the risk of pushing ourselves unnecessarily  losing stamina  or getting injured   to prevent them from narrowing down our vip  we ll assign several mobile guards from our class   however  waiting right on the edge of the designated area has its own risks  practical and cautious   reports the alliance s dwindling supplies and illness  and argues for positioning at h10 for flexibility  receives his strategic explanations and carries out supply positioning plans  debates positioning with him  sends him to relay ayanokoji s words to the unwell students","h":"<article class=\"card\" id=\"sc-kanzaki-ryuuji-y3v3-p167-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kanzaki-ryuuji.html#sc-kanzaki-ryuuji-y3v3-p167-1\">Ch.6 — depth read: Kanzaki&#x27;s report and debate<\/a><\/span><span class=\"meta\">Y3V3 · p.167–196<\/span><span class=\"by\">notes on <a href=\"../../../people/kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a> · <a href=\"../../../people/moriyama.html\">Moriyama<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kanzaki Ryūji<\/b> &quot;I was just saying that we&#x27;ve reached a difficult phase. We&#x27;ve used most of our handheld provisions.&quot;<span class=\"pg\">p.174<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kanzaki Ryūji<\/b> &quot;Also, Sumida and Minamikata have seemed somewhat unwell since this morning.&quot;<span class=\"pg\">p.174<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kanzaki Ryūji<\/b> &quot;That&#x27;s right. I want to avoid the risk of pushing ourselves unnecessarily, losing stamina, or getting injured.&quot;<span class=\"pg\">p.178<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;To prevent them from narrowing down our VIP, we&#x27;ll assign several mobile guards from our class.&quot;<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;However, waiting right on the edge of the designated area has its own risks.&quot;<span class=\"pg\">p.180<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Practical and cautious — reports the alliance&#x27;s dwindling supplies and illness, and argues for positioning at H10 for flexibility.<span class=\"pg\">p.174–181<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Receives his strategic explanations and carries out supply/positioning plans.<span class=\"pg\">p.174–181<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Debates positioning with him.<span class=\"pg\">p.174–180<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Moriyama<\/b> Sends him to relay Ayanokōji&#x27;s words to the unwell students.<span class=\"pg\">p.174<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kanzaki-ryuuji-y3v3-p162-1\">← Before: Serving duty; questioning Ayanokōji&#x27;s motives<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kanzaki-ryuuji-y3v3-p174-1\">→ After: Reporting supplies and illness; debating expansion<\/button><\/div><\/article>"},{"i":"sc-ninomiya-yui-y3v3-p167-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"amikura-mako ayanokouji-kiyotaka ninomiya-yui","q":"ninomiya yui ch 6   depth read  ninomiya s fever found lying in the shade of a tree  breathing heavily  having fallen ill with a fever   she hasn t been feeling well since this morning  i think she s started running a fever  too ill to pretend she s fine  coughing and in pain  she is ordered to retire and be picked up by the school  amikura stays anxiously by her side  he orders her immediate retirement","h":"<article class=\"card\" id=\"sc-ninomiya-yui-y3v3-p167-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ninomiya-yui.html#sc-ninomiya-yui-y3v3-p167-1\">Ch.6 — depth read: Ninomiya&#x27;s fever<\/a><\/span><span class=\"meta\">Y3V3 · p.167–196<\/span><span class=\"by\">notes on <a href=\"../../../people/ninomiya-yui.html\">Ninomiya Yui<\/a><\/span><\/h3><p class=\"setup\">Found lying in the shade of a tree, breathing heavily, having fallen ill with a fever.<\/p><p class=\"with\">with <a href=\"../../../people/amikura-mako.html\">Amikura Mako<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Amikura Mako<\/b> &quot;She hasn&#x27;t been feeling well since this morning... I think she&#x27;s started running a fever.&quot;<span class=\"pg\">p.182<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Too ill to pretend she&#x27;s fine; coughing and in pain, she is ordered to retire and be picked up by the school.<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amikura Mako<\/b> Amikura stays anxiously by her side.<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> He orders her immediate retirement.<span class=\"pg\">p.182<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ninomiya-yui-y3v3-p182-1\">→ After: Ninomiya falls ill with a fever<\/button><\/div><\/article>"},{"i":"sc-ryuuen-kakeru-y3v3-p167-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"shiina-hiyori ayanokouji-kiyotaka katsuragi-kouhei ibuki-mio ryuuen-kakeru","q":"ryuen kakeru ch 6   depth read  ryuen through shiina  lookin  pretty happy all by yourself  shiina   there ain t nothin  to it  i m gonna win this special exam and i m gonna do it with my own damn power   so in the end  it means we don t know shit about what s comin  huh   but still i ll force my way through with my own power  whatever it takes to take down ayanokouji   and that s even if i force some kinda cruel choice on you down the line  deliberates alone  feels forced onto the defensive by the alliance and refuses to react to ayanokoji s expectations   intent on winning his own way  speaks with her on the beach  tests her resolve with a malicious  cruel choice  question  vows to beat him  senses ayanokoji anticipated both attacking options  assesses the alliance and rejects allying with class a  discusses the situation with her","h":"<article class=\"card\" id=\"sc-ryuuen-kakeru-y3v3-p167-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ryuuen-kakeru.html#sc-ryuuen-kakeru-y3v3-p167-1\">Ch.6 — depth read: Ryūen through Shiina<\/a><\/span><span class=\"meta\">Y3V3 · p.167–196<\/span><span class=\"by\">notes on <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/shiina-hiyori.html\">Shiina Hiyori<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;Lookin&#x27; pretty happy all by yourself, Shiina.&quot;<span class=\"pg\">p.172<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;There ain&#x27;t nothin&#x27; to it. I&#x27;m gonna win this special exam and I&#x27;m gonna do it with my own damn power.&quot;<span class=\"pg\">p.172<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;So in the end, it means we don&#x27;t know shit about what&#x27;s comin&#x27;, huh.&quot;<span class=\"pg\">p.173<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;But still—I&#x27;ll force my way through with my own power. Whatever it takes to take down Ayanokouji.&quot;<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;And that&#x27;s even if I force some kinda cruel choice on you down the line?&quot;<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Deliberates alone, feels forced onto the defensive by the alliance and refuses to react to Ayanokōji&#x27;s expectations — intent on winning his own way.<span class=\"pg\">p.171–173<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiina Hiyori<\/b> Speaks with her on the beach; tests her resolve with a malicious &quot;cruel choice&quot; question.<span class=\"pg\">p.171–173<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Vows to beat him; senses Ayanokōji anticipated both attacking options.<span class=\"pg\">p.171–173<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Assesses the alliance and rejects allying with Class A.<span class=\"pg\">p.167–170<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ibuki Mio<\/b> Discusses the situation with her.<span class=\"pg\">p.167<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y3v3-p119-2\">← Before: Morning deliberation: whom to attack next<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y3v3-p167-2\">→ After: The C–D alliance sinks in; rejecting an alliance with Class A<\/button><\/div><\/article>"},{"i":"sc-ryuuen-kakeru-y3v3-p167-2","v":"y3v3","y":3,"o":35,"k":"spoken","w":"katsuragi-kouhei ibuki-mio ishizaki-daichi ryuuen-kakeru","q":"ryuen kakeru the c d alliance sinks in  rejecting an alliance with class a emerges from his tent after 9 p m  to katsuragi s report that class c and d have intermingled   so they teamed up  huh   it s the only way for the nearly annihilated class c to survive  i guess  heard they were making some weird contact with ichinose  too   man  i really wish he d just charged into class c and class d instead   nah  the timing was just too damn perfect   obviously class c s gonna compromise  no matter how you look at it  they re headed straight for last place on their own   and would we  who are similarly at a numerical disadvantage  concede and give first place to class a   things are finally gettin  interesting  suspects ayanokoji orchestrated the timing of koenji s clash with komiya s group as a by product of his own attack   the radio delay was too perfect  grudgingly impressed but boxed in   the lower class alliance of fifty has seized the initiative and stripped him of his gps shutdown tactic  debates the situation  both conclude the tables have turned  present at the late night briefing  fields his suggestions  ally with class a  and dismisses them","h":"<article class=\"card\" id=\"sc-ryuuen-kakeru-y3v3-p167-2\"><h3><span class=\"ttl\"><a href=\"../../../people/ryuuen-kakeru.html#sc-ryuuen-kakeru-y3v3-p167-2\">The C–D alliance sinks in; rejecting an alliance with Class A<\/a><\/span><span class=\"meta\">Y3V3 · p.167–170<\/span><span class=\"by\">notes on <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/span><\/h3><p class=\"setup\">Emerges from his tent after 9 p.m. to Katsuragi&#x27;s report that Class C and D have intermingled.<\/p><p class=\"with\">with <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a> · <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;So they teamed up, huh?&quot;<span class=\"pg\">p.167<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;It&#x27;s the only way for the nearly-annihilated Class C to survive, I guess. Heard they were making some weird contact with Ichinose, too.&quot;<span class=\"pg\">p.167<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;Man, I really wish he&#x27;d just charged into Class C and Class D instead.&quot;<span class=\"pg\">p.167<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Nah. The timing was just too damn perfect.&quot;<span class=\"pg\">p.168<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Obviously Class C&#x27;s gonna compromise. No matter how you look at it, they&#x27;re headed straight for last place on their own.&quot;<span class=\"pg\">p.169<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;And would we, who are similarly at a numerical disadvantage, concede and give first place to Class A?&quot;<span class=\"pg\">p.169<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Things are finally gettin&#x27; interesting.&quot;<span class=\"pg\">p.170<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> Suspects Ayanokōji orchestrated the timing of Kōenji&#x27;s clash with Komiya&#x27;s group as a by-product of his own attack — the radio delay was too perfect.<span class=\"pg\">p.168<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Grudgingly impressed but boxed in — the lower-class alliance of fifty has seized the initiative and stripped him of his GPS-shutdown tactic.<span class=\"pg\">p.167–170<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Debates the situation; both conclude the tables have turned.<span class=\"pg\">p.167–170<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ibuki Mio<\/b> Present at the late-night briefing.<span class=\"pg\">p.167–168<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> Fields his suggestions (ally with Class A) and dismisses them.<span class=\"pg\">p.167–169<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y3v3-p167-1\">← Before: Ch.6 — depth read: Ryūen through Shiina<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y3v3-p171-1\">→ After: The beach talk with Shiina; the cruel question<\/button><\/div><\/article>"},{"i":"sc-ryuuen-kakeru-y3v3-p171-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"shiina-hiyori ayanokouji-kiyotaka ryuuen-kakeru","q":"ryuen kakeru the beach talk with shiina  the cruel question  don t like this one bit   heh  he ain t that naive   what do i want to do  no  what do i want   lookin  pretty happy all by yourself  shiina   there ain t nothin  to it  i m gonna win this special exam and i m gonna do it with my own damn power   unfortunately  i m not a fan of stories with depressin  beginnings   so in the end  it means we don t know shit about what s comin  huh   but still i ll force my way through with my own power  whatever it takes to take down ayanokouji   and that s even if i force some kinda cruel choice on you down the line  deliberates alone  refuses to be dictated to by ayanokoji  and tests shiina with a malicious  cruel choice  question   he wants a certain victory  not merely a safe one  speaks with her on the beach  she pledges to follow him no matter what  vows to beat him with his own power  senses ayanokoji anticipated both attacking options","h":"<article class=\"card\" id=\"sc-ryuuen-kakeru-y3v3-p171-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ryuuen-kakeru.html#sc-ryuuen-kakeru-y3v3-p171-1\">The beach talk with Shiina; the cruel question<\/a><\/span><span class=\"meta\">Y3V3 · p.171–173<\/span><span class=\"by\">notes on <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/shiina-hiyori.html\">Shiina Hiyori<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;Don&#x27;t like this one bit.&quot;<span class=\"pg\">p.171<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;Heh, he ain&#x27;t that naive.&quot;<span class=\"pg\">p.171<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;What do I want to do... No, what do I want?&quot;<span class=\"pg\">p.171<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Lookin&#x27; pretty happy all by yourself, Shiina.&quot;<span class=\"pg\">p.172<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;There ain&#x27;t nothin&#x27; to it. I&#x27;m gonna win this special exam and I&#x27;m gonna do it with my own damn power.&quot;<span class=\"pg\">p.172<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Unfortunately, I&#x27;m not a fan of stories with depressin&#x27; beginnings.&quot;<span class=\"pg\">p.172<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;So in the end, it means we don&#x27;t know shit about what&#x27;s comin&#x27;, huh.&quot;<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;But still—I&#x27;ll force my way through with my own power. Whatever it takes to take down Ayanokouji.&quot;<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;And that&#x27;s even if I force some kinda cruel choice on you down the line?&quot;<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Deliberates alone, refuses to be dictated to by Ayanokōji, and tests Shiina with a malicious &quot;cruel choice&quot; question — he wants a certain victory, not merely a safe one.<span class=\"pg\">p.171–173<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiina Hiyori<\/b> Speaks with her on the beach; she pledges to follow him no matter what.<span class=\"pg\">p.171–173<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Vows to beat him with his own power; senses Ayanokōji anticipated both attacking options.<span class=\"pg\">p.171–173<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y3v3-p167-2\">← Before: The C–D alliance sinks in; rejecting an alliance with Class A<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y3v3-p172-1\">→ After: Depth review: beach conversation with Hiyori<\/button><\/div><\/article>"},{"i":"sc-shiina-hiyori-y3v3-p171-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ryuuen-kakeru shiina-hiyori","q":"shiina hiyori the beach conversation with ryuen walks alone smiling at the waves when ryuen approaches on the beach   oh my  good morning  ryuuen kun   since we re at the beach  i was taking a little walk   i heard that there is a high probability that class c and class d have joined forces  what do you intend to do   yes  we believe in your words  ryuuen kun and we will follow you  now and always   ryuuen kun  if the beginning of a novel you were reading was hopelessly pessimistic  what kind of ending would you imagine   that s true  the structure of a story is such that readers are most moved when it turns from darkness to light   that it s best to be mentally prepared for whatever might happen   however  it s a wide world out there  there are many masterpieces that are sad from beginning to end   if it would be for the sake of everyone  for the sake of the class b that is so important to me   in that case i won t hesitate  no matter who my opponent is  or what the outcome may be  calm and perceptive   reads ryuen s state of mind  uses a novel metaphor to urge preparation for any outcome  and pledges loyalty even under a  cruel choice  reassures and advises him  holds his sharp gaze without looking away","h":"<article class=\"card\" id=\"sc-shiina-hiyori-y3v3-p171-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shiina-hiyori.html#sc-shiina-hiyori-y3v3-p171-1\">The beach conversation with Ryūen<\/a><\/span><span class=\"meta\">Y3V3 · p.171–173<\/span><span class=\"by\">notes on <a href=\"../../../people/shiina-hiyori.html\">Shiina Hiyori<\/a><\/span><\/h3><p class=\"setup\">Walks alone smiling at the waves when Ryūen approaches on the beach.<\/p><p class=\"with\">with <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shiina Hiyori<\/b> “Oh my, good morning, Ryuuen-kun.”<span class=\"pg\">p.172<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiina Hiyori<\/b> “Since we’re at the beach, I was taking a little walk.”<span class=\"pg\">p.172<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiina Hiyori<\/b> “I heard that there is a high probability that Class C and Class D have joined forces. What do you intend to do?”<span class=\"pg\">p.172<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Yes. We believe in your words, Ryuuen-kun and we will follow you, now and always.”<span class=\"pg\">p.172<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ryuuen-kun, if the beginning of a novel you were reading was hopelessly pessimistic, what kind of ending would you imagine?”<span class=\"pg\">p.172<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s true. The structure of a story is such that readers are most moved when it turns from darkness to light.”<span class=\"pg\">p.172<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That it’s best to be mentally prepared for whatever might happen.”<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “However, it’s a wide world out there. There are many masterpieces that are sad from beginning to end.”<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If it would be for the sake of everyone... for the sake of the Class B that is so important to me...”<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In that case—I won’t hesitate. No matter who my opponent is, or what the outcome may be.”<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Calm and perceptive — reads Ryūen’s state of mind, uses a novel metaphor to urge preparation for any outcome, and pledges loyalty even under a “cruel choice.”<span class=\"pg\">p.172–173<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Reassures and advises him; holds his sharp gaze without looking away.<span class=\"pg\">p.171–173<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shiina-hiyori-y3v3-p12-1\">← Before: Prologue: the unspoken confession<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-shiina-hiyori-y3v3-p251-1\">→ After: Found in good spirits<\/button><\/div><\/article>"},{"i":"sc-ryuuen-kakeru-y3v3-p172-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"shiina-hiyori ryuuen-kakeru","q":"ryuen kakeru depth review  beach conversation with hiyori rolling up his map  approaches shiina on the beach and asks why she looks so pleased with herself   lookin  pretty happy all by yourself  shiina   there ain t nothin  to it   unfortunately  i m not a fan of stories with depressin  beginnings  declares he will win the exam  with my own damn power  forcefully masking his own indecisiveness  listens seriously to her novel ending metaphor about being prepared for any outcome  accepts her reaffirmation of class d s support","h":"<article class=\"card\" id=\"sc-ryuuen-kakeru-y3v3-p172-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ryuuen-kakeru.html#sc-ryuuen-kakeru-y3v3-p172-1\">Depth review: beach conversation with Hiyori<\/a><\/span><span class=\"meta\">Y3V3 · p.172–173<\/span><span class=\"by\">notes on <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/span><\/h3><p class=\"setup\">Rolling up his map, approaches Shiina on the beach and asks why she looks so pleased with herself.<\/p><p class=\"with\">with <a href=\"../../../people/shiina-hiyori.html\">Shiina Hiyori<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;Lookin&#x27; pretty happy all by yourself, Shiina.&quot;<span class=\"pg\">p.172<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;There ain&#x27;t nothin&#x27; to it.&quot;<span class=\"pg\">p.172<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;Unfortunately, I&#x27;m not a fan of stories with depressin&#x27; beginnings.&quot;<span class=\"pg\">p.172<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Declares he will win the exam &quot;with my own damn power,&quot; forcefully masking his own indecisiveness.<span class=\"pg\">p.172<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiina Hiyori<\/b> Listens seriously to her novel-ending metaphor about being prepared for any outcome; accepts her reaffirmation of Class D&#x27;s support.<span class=\"pg\">p.172–173<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y3v3-p171-1\">← Before: The beach talk with Shiina; the cruel question<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y3v3-p233-1\">→ After: Epilogue — depth read: the duel lost, defeat conceded<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p174-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"kanzaki-ryuuji hashimoto-masayoshi moriyama ayanokouji-kiyotaka","q":"ayanokoji kiyotaka the alliance base  supply report and defensive strategy returns to the k13 alliance base after  business  the previous night  hashimoto notices his dirty right hand   my bad  i had some business to take care of   it s nothing serious  don t worry about it   if one is the vip  it would be a bit of a hassle  but if they re guards  having them retire now may be an option   the damage will only be greater if they lie to themselves and force it   there s a troublesome presence in class a from the start  needless to say  it s koenji   he ll wait until the last possible moment without launching a hasty attack   no  avoiding engagement is best for now  we ll stick to a defensive strategy  predicts ryuen will not attack until the shrinking area forces a confrontation  chooses to wait for the general firefight they have been hoping for  calm and strategic   hides the late night infiltration  manages the ill students  and reasons precisely about ryuen s motives  receives supply and illness reports  debates ryuen s likely moves  concerns about dwindling supplies  sends him to relay his words to the unwell students","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p174-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p174-1\">The alliance base: supply report and defensive strategy<\/a><\/span><span class=\"meta\">Y3V3 · p.174–177<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Returns to the K13 alliance base after &quot;business&quot; the previous night; Hashimoto notices his dirty right hand.<\/p><p class=\"with\">with <a href=\"../../../people/kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a> · <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a> · <a href=\"../../../people/moriyama.html\">Moriyama<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;My bad, I had some business to take care of.&quot;<span class=\"pg\">p.174<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;It&#x27;s nothing serious, don&#x27;t worry about it.&quot;<span class=\"pg\">p.174<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;If one is the VIP, it would be a bit of a hassle, but if they&#x27;re guards, having them retire now may be an option.&quot;<span class=\"pg\">p.174<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;The damage will only be greater if they lie to themselves and force it.&quot;<span class=\"pg\">p.175<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;There&#x27;s a troublesome presence in Class A from the start. Needless to say, it&#x27;s Koenji.&quot;<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;He&#x27;ll wait until the last possible moment without launching a hasty attack.&quot;<span class=\"pg\">p.177<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;No, avoiding engagement is best for now. We&#x27;ll stick to a defensive strategy.&quot;<span class=\"pg\">p.177<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> Predicts Ryūen will not attack until the shrinking area forces a confrontation; chooses to wait for the general firefight they have been hoping for.<span class=\"pg\">p.175–177<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Calm and strategic — hides the late-night infiltration, manages the ill students, and reasons precisely about Ryūen&#x27;s motives.<span class=\"pg\">p.174–177<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kanzaki Ryūji<\/b> Receives supply and illness reports; debates Ryūen&#x27;s likely moves.<span class=\"pg\">p.174–177<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Concerns about dwindling supplies.<span class=\"pg\">p.174–175<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Moriyama<\/b> Sends him to relay his words to the unwell students.<span class=\"pg\">p.175<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p167-1\">← Before: Ch.6 — depth read: the solo plan<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p178-1\">→ After: Moving toward the center<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y3v3-p174-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"hashimoto-masayoshi","q":"hashimoto masayoshi worries about supplies  ain t it kinda dirty   but man  we re obviously runnin  low on supplies  we got nothin  but a bunch of starving folks over here  too  notices ayanokoji s dirty hand and worries openly about the alliance s hunger","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y3v3-p174-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hashimoto-masayoshi.html#sc-hashimoto-masayoshi-y3v3-p174-1\">Worries about supplies<\/a><\/span><span class=\"meta\">Y3V3 · p.174–175<\/span><span class=\"by\">notes on <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/span><\/h3><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Ain&#x27;t it kinda dirty?&quot;<span class=\"pg\">p.174<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;But man, we&#x27;re obviously runnin&#x27; low on supplies. We got nothin&#x27; but a bunch of starving folks over here, too.&quot;<span class=\"pg\">p.175<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Notices Ayanokōji&#x27;s dirty hand and worries openly about the alliance&#x27;s hunger.<span class=\"pg\">p.174–175<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p167-1\">← Before: Ch.6 — depth read: Hashimoto on the shrinking area<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p178-1\">→ After: The supply run and the shifting area<\/button><\/div><\/article>"},{"i":"sc-kanzaki-ryuuji-y3v3-p174-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka hashimoto-masayoshi kanzaki-ryuuji","q":"kanzaki ryuji reporting supplies and illness  debating expansion reports to ayanokoji at the alliance base   i was just saying that we ve reached a difficult phase  we ve used most of our handheld provisions   also  sumida and minamikata have seemed somewhat unwell since this morning   there s a troublesome presence in class a from the start  needless to say  it s koenji   then should we attack instead   that s right  i want to avoid the risk of pushing ourselves unnecessarily   however  waiting right on the edge of the designated area has its own risks   we can secure a better position if we move now  practical and cautious   reports the alliance s dwindling food and illness  reasons that koenji s unpredictability justified ryuen not attacking class a  and argues for the h10 position  receives his strategic instructions and carries them out  debates whether to move forward or wait","h":"<article class=\"card\" id=\"sc-kanzaki-ryuuji-y3v3-p174-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kanzaki-ryuuji.html#sc-kanzaki-ryuuji-y3v3-p174-1\">Reporting supplies and illness; debating expansion<\/a><\/span><span class=\"meta\">Y3V3 · p.174–178<\/span><span class=\"by\">notes on <a href=\"../../../people/kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a><\/span><\/h3><p class=\"setup\">Reports to Ayanokōji at the alliance base.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kanzaki Ryūji<\/b> &quot;I was just saying that we&#x27;ve reached a difficult phase. We&#x27;ve used most of our handheld provisions.&quot;<span class=\"pg\">p.174<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kanzaki Ryūji<\/b> &quot;Also, Sumida and Minamikata have seemed somewhat unwell since this morning.&quot;<span class=\"pg\">p.174<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kanzaki Ryūji<\/b> &quot;There&#x27;s a troublesome presence in Class A from the start. Needless to say, it&#x27;s Koenji.&quot;<span class=\"pg\">p.176<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Then should we attack instead?&quot;<span class=\"pg\">p.177<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;That&#x27;s right. I want to avoid the risk of pushing ourselves unnecessarily.&quot;<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;However, waiting right on the edge of the designated area has its own risks.&quot;<span class=\"pg\">p.180<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;We can secure a better position if we move now.&quot;<span class=\"pg\">p.180<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Practical and cautious — reports the alliance&#x27;s dwindling food and illness, reasons that Kōenji&#x27;s unpredictability justified Ryūen not attacking Class A, and argues for the H10 position.<span class=\"pg\">p.174–180<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Receives his strategic instructions and carries them out.<span class=\"pg\">p.174–180<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Debates whether to move forward or wait.<span class=\"pg\">p.180<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kanzaki-ryuuji-y3v3-p167-1\">← Before: Ch.6 — depth read: Kanzaki&#x27;s report and debate<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kanzaki-ryuuji-y3v3-p182-1\">→ After: Ninomiya&#x27;s fever<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p178-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"kanzaki-ryuuji ayanokouji-kiyotaka","q":"ayanokoji kiyotaka moving toward the center the 11 a m  event shrinks the area to a 9 9 grid  d4 l12   that s right  i want to avoid the risk of pushing ourselves unnecessarily  losing stamina  or getting injured   however  i want to send a few people ahead to secure the food at h10   it s simply a matter of the priority of fighting changing depending on what you prioritize   moving a little closer now would be the better option  h10 isn t a bad choice   form a retrieval squad and send a small group to j12  ignores treacherous supply routes  sends a light group for h10 food  and moves the alliance to h10 for flexibility as the area shifts southwest  agrees on the h10 move and the retrieval squads","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p178-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p178-1\">Moving toward the center<\/a><\/span><span class=\"meta\">Y3V3 · p.178–181<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">The 11 a.m. event shrinks the area to a 9×9 grid (D4–L12).<\/p><p class=\"with\">with <a href=\"../../../people/kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;That&#x27;s right. I want to avoid the risk of pushing ourselves unnecessarily, losing stamina, or getting injured.&quot;<span class=\"pg\">p.178<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;However, I want to send a few people ahead to secure the food at H10.&quot;<span class=\"pg\">p.178<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;It&#x27;s simply a matter of the priority of fighting changing depending on what you prioritize.&quot;<span class=\"pg\">p.179<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Moving a little closer now would be the better option. H10 isn&#x27;t a bad choice.&quot;<span class=\"pg\">p.181<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Form a retrieval squad and send a small group to J12.&quot;<span class=\"pg\">p.181<\/span><\/li><li><span class=\"mlabel\">Tactic<\/span> Ignores treacherous supply routes, sends a light group for H10 food, and moves the alliance to H10 for flexibility as the area shifts southwest.<span class=\"pg\">p.178–181<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kanzaki Ryūji<\/b> Agrees on the H10 move and the retrieval squads.<span class=\"pg\">p.178–181<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p174-1\">← Before: The alliance base: supply report and defensive strategy<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p182-1\">→ After: Ninomiya&#x27;s fever; the G9 run and the GPS shutdown<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y3v3-p178-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"hashimoto-masayoshi","q":"hashimoto masayoshi the supply run and the shifting area  they re really testing us  but j5 and k10  that s just asking too much   well then  guess i ll step up  i ll make a run for it and see if i can secure them   we re inside the area and getting too close to the center is kinda sketchy  y know   i get what you re saying  kanzaki  but are you suggesting we move forward one whole area  volunteers for the h10 supply run and weighs the risk of the shifting restricted area","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y3v3-p178-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hashimoto-masayoshi.html#sc-hashimoto-masayoshi-y3v3-p178-1\">The supply run and the shifting area<\/a><\/span><span class=\"meta\">Y3V3 · p.178–180<\/span><span class=\"by\">notes on <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/span><\/h3><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;They&#x27;re really testing us... but J5 and K10? That&#x27;s just asking too much.&quot;<span class=\"pg\">p.178<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Well then, guess I&#x27;ll step up. I&#x27;ll make a run for it and see if I can secure them.&quot;<span class=\"pg\">p.178<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;We&#x27;re inside the area and getting too close to the center is kinda sketchy, y&#x27;know?&quot;<span class=\"pg\">p.180<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I get what you&#x27;re saying, Kanzaki, but are you suggesting we move forward one whole area?&quot;<span class=\"pg\">p.180<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Volunteers for the H10 supply run and weighs the risk of the shifting restricted area.<span class=\"pg\">p.178–180<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p174-1\">← Before: Worries about supplies<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p183-1\">→ After: The shrinking area means less food<\/button><\/div><\/article>"},{"i":"sc-amikura-mako-y3v3-p182-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ninomiya-yui amikura-mako","q":"amikura mako caring for the ill ninomiya  she hasn t been feeling well since this morning  i think she s started running a fever  anxiously tends to ninomiya  placing a hand on her forehead and reporting her condition to ayanokoji and kanzaki  stays by her side as she falls ill","h":"<article class=\"card\" id=\"sc-amikura-mako-y3v3-p182-1\"><h3><span class=\"ttl\"><a href=\"../../../people/amikura-mako.html#sc-amikura-mako-y3v3-p182-1\">Caring for the ill Ninomiya<\/a><\/span><span class=\"meta\">Y3V3 · p.182<\/span><span class=\"by\">notes on <a href=\"../../../people/amikura-mako.html\">Amikura Mako<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ninomiya-yui.html\">Ninomiya Yui<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Amikura Mako<\/b> &quot;She hasn&#x27;t been feeling well since this morning... I think she&#x27;s started running a fever.&quot;<span class=\"pg\">p.182<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Anxiously tends to Ninomiya, placing a hand on her forehead and reporting her condition to Ayanokōji and Kanzaki.<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ninomiya Yui<\/b> Stays by her side as she falls ill.<span class=\"pg\">p.182<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p182-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ninomiya-yui takemoto-shigeru moriyama amikura-mako ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ninomiya s fever  the g9 run and the gps shutdown finds ninomiya ill with a fever in the shade of a tree  amikura is anxiously by her side   she should retire immediately and have the school come pick her up   a few students have been coughing since this morning  it s possible we might have a few more students retire between tonight and tomorrow   i ll go to g9  takemoto  and about six others  lend me a hand   class a is moving as planned  contact the commander now and tell them to disable my personal gps the moment the next gps update occurs   yeah  i m not coming back today  suspects a cold is spreading through the alliance  worsened by shared food and close proximity over three days  goes to retrieve g9 supplies then has his gps disabled   disappearing from the exam to execute a solo plan  with a contingency already shared with shimazaki via takemoto  orders her immediate retirement  instructs him to disable his gps and handle the  taken out  contingency  relays his words to the ill students  accompanies the g9 run  is with the ill ninomiya","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p182-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p182-1\">Ninomiya&#x27;s fever; the G9 run and the GPS shutdown<\/a><\/span><span class=\"meta\">Y3V3 · p.182–184<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Finds Ninomiya ill with a fever in the shade of a tree; Amikura is anxiously by her side.<\/p><p class=\"with\">with <a href=\"../../../people/ninomiya-yui.html\">Ninomiya Yui<\/a> · <a href=\"../../../people/takemoto-shigeru.html\">Takemoto Shigeru<\/a> · <a href=\"../../../people/moriyama.html\">Moriyama<\/a> · <a href=\"../../../people/amikura-mako.html\">Amikura Mako<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;She should retire immediately and have the school come pick her up.&quot;<span class=\"pg\">p.182<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;A few students have been coughing since this morning. It&#x27;s possible we might have a few more students retire between tonight and tomorrow.&quot;<span class=\"pg\">p.182<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;I&#x27;ll go to G9. Takemoto... and about six others, lend me a hand.&quot;<span class=\"pg\">p.183<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Class A is moving as planned. Contact the commander now and tell them to disable my personal GPS the moment the next GPS update occurs.&quot;<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Yeah, I&#x27;m not coming back today.&quot;<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> Suspects a cold is spreading through the alliance, worsened by shared food and close proximity over three days.<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Tactic<\/span> Goes to retrieve G9 supplies then has his GPS disabled — disappearing from the exam to execute a solo plan, with a contingency already shared with Shimazaki via Takemoto.<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ninomiya Yui<\/b> Orders her immediate retirement.<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Takemoto Shigeru<\/b> Instructs him to disable his GPS and handle the &quot;taken out&quot; contingency.<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Moriyama<\/b> Relays his words to the ill students; accompanies the G9 run.<span class=\"pg\">p.182–184<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amikura Mako<\/b> Is with the ill Ninomiya.<span class=\"pg\">p.182<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p178-1\">← Before: Moving toward the center<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p197-1\">→ After: Ch.7 — depth read: the mastermind&#x27;s final-day moves<\/button><\/div><\/article>"},{"i":"sc-kanzaki-ryuuji-y3v3-p182-1","v":"y3v3","y":3,"o":35,"k":"","w":"kanzaki-ryuuji","q":"kanzaki ryuji ninomiya s fever kanzaki nods when ayanokoji orders the ill ninomiya to retire  amikura stays anxiously by her side","h":"<article class=\"card\" id=\"sc-kanzaki-ryuuji-y3v3-p182-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kanzaki-ryuuji.html#sc-kanzaki-ryuuji-y3v3-p182-1\">Ninomiya&#x27;s fever<\/a><\/span><span class=\"meta\">Y3V3 · p.182<\/span><span class=\"by\">notes on <a href=\"../../../people/kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a><\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Kanzaki nods when Ayanokōji orders the ill Ninomiya to retire; Amikura stays anxiously by her side.<span class=\"pg\">p.182<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kanzaki-ryuuji-y3v3-p174-1\">← Before: Reporting supplies and illness; debating expansion<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kanzaki-ryuuji-y3v3-p233-1\">→ After: Epilogue — depth read: the guard who relays the map<\/button><\/div><\/article>"},{"i":"sc-ninomiya-yui-y3v3-p182-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"amikura-mako ayanokouji-kiyotaka ninomiya-yui","q":"ninomiya yui ninomiya falls ill with a fever found lying in the shade of a tree at h10  breathing heavily with a fever   she hasn t been feeling well since this morning  i think she s started running a fever  too ill to keep up the pretense of being fine  coughing and in visible pain  she is ordered to retire and be picked up by the school  amikura stays anxiously by her side  he orders her immediate retirement","h":"<article class=\"card\" id=\"sc-ninomiya-yui-y3v3-p182-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ninomiya-yui.html#sc-ninomiya-yui-y3v3-p182-1\">Ninomiya falls ill with a fever<\/a><\/span><span class=\"meta\">Y3V3 · p.182<\/span><span class=\"by\">notes on <a href=\"../../../people/ninomiya-yui.html\">Ninomiya Yui<\/a><\/span><\/h3><p class=\"setup\">Found lying in the shade of a tree at H10, breathing heavily with a fever.<\/p><p class=\"with\">with <a href=\"../../../people/amikura-mako.html\">Amikura Mako<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Amikura Mako<\/b> &quot;She hasn&#x27;t been feeling well since this morning... I think she&#x27;s started running a fever.&quot;<span class=\"pg\">p.182<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Too ill to keep up the pretense of being fine; coughing and in visible pain, she is ordered to retire and be picked up by the school.<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amikura Mako<\/b> Amikura stays anxiously by her side.<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> He orders her immediate retirement.<span class=\"pg\">p.182<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ninomiya-yui-y3v3-p167-1\">← Before: Ch.6 — depth read: Ninomiya&#x27;s fever<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y3v3-p183-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"hashimoto-masayoshi","q":"hashimoto masayoshi the shrinking area means less food  since the area s gettin  smaller  the number of supply drops is down to eight   looks like we re gonna be sleepin  on emptier stomachs tonight than yesterday  wryly notes the shrinking area means fewer supply drops and hungrier nights","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y3v3-p183-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hashimoto-masayoshi.html#sc-hashimoto-masayoshi-y3v3-p183-1\">The shrinking area means less food<\/a><\/span><span class=\"meta\">Y3V3 · p.183<\/span><span class=\"by\">notes on <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/span><\/h3><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Since the area&#x27;s gettin&#x27; smaller, the number of supply drops is down to eight.&quot;<span class=\"pg\">p.183<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Looks like we&#x27;re gonna be sleepin&#x27; on emptier stomachs tonight than yesterday.&quot;<span class=\"pg\">p.183<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Wryly notes the shrinking area means fewer supply drops and hungrier nights.<span class=\"pg\">p.183<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p178-1\">← Before: The supply run and the shifting area<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p197-1\">→ After: Ch.7 — depth read: Hashimoto&#x27;s duel with Hirata<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y3v3-p185-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"sudou-ken matsushita-chiaki horikita-suzune","q":"horikita suzune class a reaches g8  the unease arrives at g8 around 5 25 p m  after keeping the southern route open as an anti ambush precaution   i wonder what happened to the eight gps signals that went to retrieve supplies at g9   in any case  we need to focus on ourselves rather than the other classes right now   good work  everyone we can get some proper rest around here today   it can t be helped  this is the best position if we re to prepare for tomorrow  be careful as you work  vigilant about a possible gps shutdown attack and physically exhausted after three hungry days  keeps her class disciplined  agrees with his assessment that koenji wasn t fighting for class a  the commander confirms the g9 group s movements via vip wang","h":"<article class=\"card\" id=\"sc-horikita-suzune-y3v3-p185-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y3v3-p185-1\">Class A reaches G8; the unease<\/a><\/span><span class=\"meta\">Y3V3 · p.185–186<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">Arrives at G8 around 5:25 p.m. after keeping the southern route open as an anti-ambush precaution.<\/p><p class=\"with\">with <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a> · <a href=\"../../../people/matsushita-chiaki.html\">Matsushita Chiaki<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> &quot;I wonder what happened to the eight GPS signals that went to retrieve supplies at G9?&quot;<span class=\"pg\">p.185<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> &quot;In any case, we need to focus on ourselves rather than the other classes right now.&quot;<span class=\"pg\">p.185<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> &quot;Good work, everyone—we can get some proper rest around here today.&quot;<span class=\"pg\">p.186<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;It can&#x27;t be helped. This is the best position if we&#x27;re to prepare for tomorrow. Be careful as you work.&quot;<span class=\"pg\">p.186<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Vigilant about a possible GPS-shutdown attack and physically exhausted after three hungry days; keeps her class disciplined.<span class=\"pg\">p.185–186<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Agrees with his assessment that Kōenji wasn&#x27;t fighting for Class A.<span class=\"pg\">p.185<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Matsushita Chiaki<\/b> The commander confirms the G9 group&#x27;s movements via VIP Wang.<span class=\"pg\">p.185<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y3v3-p95-1\">← Before: Class A reacts: disbelief and &quot;invisible pressure&quot;<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y3v3-p186-1\">→ After: The private talk with Karuizawa<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y3v3-p186-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"karuizawa-kei ayanokouji-kiyotaka ichinose-honami sudou-ken horikita-suzune","q":"horikita suzune the private talk with karuizawa spots karuizawa after setting up her tent and pulls her aside for a private conversation   there s something i want to ask you  but it s difficult to talk about here   it s about class c and d  in the end  we ve come to the evening of the third day without the gps signals of either class decreasing significantly all day   what s bothering me is when the two classes decided to team up   right after he left the class  he and ichinose san became close  well   close  might be the wrong word  but i ve sensed that they ve been closing the distance between them   even though you re enemies now  do you like ayanokouji kun  horikita san   i i already told you  i ve never been in love with anyone  have i not   of course not  he s a dependable classmate    on sudo  she does  no  i m not that surprised  but  is that true   you mean  they re dating  sharp on the alliance s hidden origins and flustered when karuizawa turns the questions to her own feelings   her mind freezes where ayanokoji is concerned  confides in her as a friend  is caught off guard by the personal questions  pressed on whether she likes him  cannot answer clearly  learns from karuizawa that ichinose also likes ayanokoji and that their bond may be deeper than it seems  instantly rules out romantic feelings for him   which karuizawa uses to expose her hesitation over ayanokoji","h":"<article class=\"card\" id=\"sc-horikita-suzune-y3v3-p186-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y3v3-p186-1\">The private talk with Karuizawa<\/a><\/span><span class=\"meta\">Y3V3 · p.186–189<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">Spots Karuizawa after setting up her tent and pulls her aside for a private conversation.<\/p><p class=\"with\">with <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> &quot;There&#x27;s something I want to ask you... but it&#x27;s difficult to talk about here—&quot;<span class=\"pg\">p.187<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> &quot;It&#x27;s about Class C and D. In the end, we&#x27;ve come to the evening of the third day without the GPS signals of either class decreasing significantly all day.&quot;<span class=\"pg\">p.187<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> &quot;What&#x27;s bothering me is when the two classes decided to team up.&quot;<span class=\"pg\">p.188<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Right after he left the class, he and Ichinose-san became close... well, &#x27;close&#x27; might be the wrong word, but I&#x27;ve sensed that they&#x27;ve been closing the distance between them.&quot;<span class=\"pg\">p.188<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Even though you&#x27;re enemies now, do you like Ayanokouji-kun, Horikita-san?&quot;<span class=\"pg\">p.188<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I-I already told you, I&#x27;ve never been in love with anyone, have I not?&quot;<span class=\"pg\">p.188<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Of course not. He&#x27;s a dependable classmate.&quot; — on Sudō<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;...She does...? No, I&#x27;m not that surprised, but... is that true?&quot;<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You mean... they&#x27;re dating?&quot;<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Sharp on the alliance&#x27;s hidden origins and flustered when Karuizawa turns the questions to her own feelings — her mind freezes where Ayanokōji is concerned.<span class=\"pg\">p.187–189<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Karuizawa Kei<\/b> Confides in her as a friend; is caught off guard by the personal questions.<span class=\"pg\">p.186–189<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Pressed on whether she likes him; cannot answer clearly.<span class=\"pg\">p.188–189<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Learns from Karuizawa that Ichinose also likes Ayanokōji and that their bond may be deeper than it seems.<span class=\"pg\">p.188–189<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Instantly rules out romantic feelings for him — which Karuizawa uses to expose her hesitation over Ayanokōji.<span class=\"pg\">p.189<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y3v3-p185-1\">← Before: Class A reaches G8; the unease<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y3v3-p190-1\">→ After: Gunfire near the tents<\/button><\/div><\/article>"},{"i":"sc-karuizawa-kei-y3v3-p186-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"horikita-suzune ayanokouji-kiyotaka ichinose-honami karuizawa-kei","q":"karuizawa kei the private talk with horikita is approached by horikita after setting up camp  moves away to speak privately   hm  what s up  horikita san   something you want to talk to me about  it s something you don t want overheard  right   ask me anything  we re friends  aren t we   yeah  there s no mistake about that  it s easy for losing classes to team up   yeah  hirata kun and the others said the same thing   so you think the same   even though you re enemies now  do you like ayanokouji kun  horikita san   it s pretty important to me   see  you answered instantly  and it was a similar question   it s not just me and you who like ayanokouji kun  horikita san  ichinose san does too  warm and perceptive   confirms the alliance s obvious origins  then deftly turns the conversation to feelings  exposing horikita s hesitation by contrast with her instant answer about sudo  speaks privately as friends  presses her on her feelings for ayanokoji  admits she likes him and reveals ichinose does too  says their relationship is  close to  dating","h":"<article class=\"card\" id=\"sc-karuizawa-kei-y3v3-p186-1\"><h3><span class=\"ttl\"><a href=\"../../../people/karuizawa-kei.html#sc-karuizawa-kei-y3v3-p186-1\">The private talk with Horikita<\/a><\/span><span class=\"meta\">Y3V3 · p.186–189<\/span><span class=\"by\">notes on <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a><\/span><\/h3><p class=\"setup\">Is approached by Horikita after setting up camp; moves away to speak privately.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Karuizawa Kei<\/b> &quot;Hm? What&#x27;s up, Horikita-san?&quot;<span class=\"pg\">p.187<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Karuizawa Kei<\/b> &quot;Something you want to talk to me about? It&#x27;s something you don&#x27;t want overheard, right?&quot;<span class=\"pg\">p.187<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Karuizawa Kei<\/b> &quot;Ask me anything. We&#x27;re friends, aren&#x27;t we?&quot;<span class=\"pg\">p.187<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Yeah, there&#x27;s no mistake about that. It&#x27;s easy for losing classes to team up.&quot;<span class=\"pg\">p.187<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Yeah. Hirata-kun and the others said the same thing.&quot;<span class=\"pg\">p.188<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;So you think the same.&quot;<span class=\"pg\">p.188<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Even though you&#x27;re enemies now, do you like Ayanokouji-kun, Horikita-san?&quot;<span class=\"pg\">p.188<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;It&#x27;s pretty important to me.&quot;<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;See? You answered instantly. And it was a similar question.&quot;<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;It&#x27;s not just me and you who like Ayanokouji-kun, Horikita-san. Ichinose-san does too.&quot;<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Warm and perceptive — confirms the alliance&#x27;s obvious origins, then deftly turns the conversation to feelings, exposing Horikita&#x27;s hesitation by contrast with her instant answer about Sudō.<span class=\"pg\">p.187–189<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Speaks privately as friends; presses her on her feelings for Ayanokōji.<span class=\"pg\">p.186–189<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Admits she likes him and reveals Ichinose does too.<span class=\"pg\">p.188–189<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Says their relationship is &quot;close to&quot; dating.<span class=\"pg\">p.189<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-horikita-suzune-y3v3-p190-1","v":"y3v3","y":3,"o":35,"k":"","w":"horikita-suzune","q":"horikita suzune gunfire near the tents hears paintball fire near the camp just before 6 p m  and runs back with karuizawa  the narration  in horikita s viewpoint  registers the question of whether someone is shooting  then the certainty of it  and the decision to go back   the translation leaves the lines untagged  so no  says  row is claimed  finds ijuuin and mori hit with paint   an apparently impossible attack given the distance and timing","h":"<article class=\"card\" id=\"sc-horikita-suzune-y3v3-p190-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y3v3-p190-1\">Gunfire near the tents<\/a><\/span><span class=\"meta\">Y3V3 · p.190<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">Hears paintball fire near the camp just before 6 p.m. and runs back with Karuizawa.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> The narration, in Horikita&#x27;s viewpoint, registers the question of whether someone is shooting, then the certainty of it, and the decision to go back — the translation leaves the lines untagged, so no `[says]` row is claimed.<span class=\"pg\">p.190<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Finds Ijuuin and Mori hit with paint — an apparently impossible attack given the distance and timing.<span class=\"pg\">p.190<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y3v3-p186-1\">← Before: The private talk with Karuizawa<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y3v3-p197-1\">→ After: Ch.7 — depth read: Horikita on the final day<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p197-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"horikita-suzune shiraishi-asuka satou-maya ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 7   depth read  the mastermind s final day moves  the right call  headquarters is undoubtedly tracking every student s gps in real time  24 7   what am i planning  nothing  if there s a path  i ll walk it   we kept losing points in the beginning  i m glad i could make up for it  even just a little   there was something i came to understand from infiltrating class a  it was that class a was slightly lacking the tension it should ve had   appoint a commander  gather supplies  keep your distance  read the enemy s movements and avoid engagement   the objective wasn t to eliminate as many people as possible  but to find out who the vips were   if they could have predicted the attack beforehand  it could ve been a feint   now  all that s left is to take out the remaining class b students and this special exam will be over   adjustments  identified class a s three vips via the previous night s attack and passed the names to class b to catalyze an assault  aims to throw the battlefield into chaos so students panic and eliminate each other  then escape the vips  walks the path she leaves open  reads that she expects him to flee  has her report the battlefield state  leaves her with yamamura  identified her as a class a vip  her elimination narrows class a to one vip","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p197-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p197-1\">Ch.7 — depth read: the mastermind&#x27;s final-day moves<\/a><\/span><span class=\"meta\">Y3V3 · p.197–232<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/shiraishi-asuka.html\">Shiraishi Asuka<\/a> · <a href=\"../../../people/satou-maya.html\">Satō Maya<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;The right call. Headquarters is undoubtedly tracking every student&#x27;s GPS in real-time, 24/7.&quot;<span class=\"pg\">p.202<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;What am I planning? Nothing. If there&#x27;s a path, I&#x27;ll walk it.&quot;<span class=\"pg\">p.202<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;We kept losing points in the beginning. I&#x27;m glad I could make up for it, even just a little.&quot;<span class=\"pg\">p.204<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;There was something I came to understand from infiltrating Class A. It was that Class A was slightly lacking the tension it should&#x27;ve had.&quot;<span class=\"pg\">p.204<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Appoint a commander, gather supplies, keep your distance, read the enemy&#x27;s movements and avoid engagement.&quot;<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;The objective wasn&#x27;t to eliminate as many people as possible, but to find out who the VIPs were.&quot;<span class=\"pg\">p.231<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;If they could have predicted the attack beforehand, it could’ve been a feint.&quot;<span class=\"pg\">p.231<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Now, all that&#x27;s left is to take out the remaining Class B students and this special exam will be over.&quot;<span class=\"pg\">p.232<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Adjustments.&quot;<span class=\"pg\">p.232<\/span><\/li><li><span class=\"mlabel\">Tactic<\/span> Identified Class A&#x27;s three VIPs via the previous night&#x27;s attack and passed the names to Class B to catalyze an assault.<span class=\"pg\">p.231–232<\/span><\/li><li><span class=\"mlabel\">Tactic<\/span> Aims to throw the battlefield into chaos so students panic and eliminate each other, then escape the VIPs.<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Walks the path she leaves open; reads that she expects him to flee.<span class=\"pg\">p.201–203<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiraishi Asuka<\/b> Has her report the battlefield state; leaves her with Yamamura.<span class=\"pg\">p.230–232<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Satō Maya<\/b> Identified her as a Class A VIP; her elimination narrows Class A to one VIP.<span class=\"pg\">p.231<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p182-1\">← Before: Ninomiya&#x27;s fever; the G9 run and the GPS shutdown<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p204-1\">→ After: Shaking Class A; the &quot;adjustment&quot;<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y3v3-p197-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"hirata-yousuke ayanokouji-kiyotaka matoba-shinji hashimoto-masayoshi","q":"hashimoto masayoshi ch 7   depth read  hashimoto s duel with hirata is caught in the allied advance when class a splits its forces  faces hirata in a close range firefight   what s going on   take us out with a small group  are they serious   not bad  hirata  you re way more skilled than i thought  there s no hesitation or mercy in your aim   never seen you with such a desperate look on your face before  did getting abandoned by ayanokouji really piss you off that much   ayanokouji was sayin  he felt bad about what he did to you  hirata   that was some serious spirit  hirata  this match is my loss  duels hirata  uses taunts about ayanokoji to rattle him  but is eliminated by a slightly faster shot  praises hirata s spirit  duel opponent  is nearly shot again after being eliminated  uses his abandonment of hirata as psychological ammunition  matoba is shot beside him  he flees","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y3v3-p197-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hashimoto-masayoshi.html#sc-hashimoto-masayoshi-y3v3-p197-1\">Ch.7 — depth read: Hashimoto&#x27;s duel with Hirata<\/a><\/span><span class=\"meta\">Y3V3 · p.197–232<\/span><span class=\"by\">notes on <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/span><\/h3><p class=\"setup\">Is caught in the allied advance when Class A splits its forces; faces Hirata in a close-range firefight.<\/p><p class=\"with\">with <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/matoba-shinji.html\">Matoba Shinji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;What&#x27;s going on...?&quot;<span class=\"pg\">p.222<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Take us out with a small group? Are they serious?&quot;<span class=\"pg\">p.222<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Not bad, Hirata... You&#x27;re way more skilled than I thought. There&#x27;s no hesitation or mercy in your aim.&quot;<span class=\"pg\">p.222<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Never seen you with such a desperate look on your face before! Did getting abandoned by Ayanokouji really piss you off that much?!&quot;<span class=\"pg\">p.223<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Ayanokouji was sayin&#x27; he felt bad about what he did to you, Hirata.&quot;<span class=\"pg\">p.226<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;...That was some serious spirit, Hirata. This match is my loss.&quot;<span class=\"pg\">p.228<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Duels Hirata, uses taunts about Ayanokōji to rattle him, but is eliminated by a slightly faster shot; praises Hirata&#x27;s spirit.<span class=\"pg\">p.222–228<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Duel opponent; is nearly shot again after being eliminated.<span class=\"pg\">p.222–229<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Uses his abandonment of Hirata as psychological ammunition.<span class=\"pg\">p.223–226<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Matoba Shinji<\/b> Matoba is shot beside him; he flees.<span class=\"pg\">p.221<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p183-1\">← Before: The shrinking area means less food<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p221-1\">→ After: The duel with Hirata<\/button><\/div><\/article>"},{"i":"sc-hirata-yousuke-y3v3-p197-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"hashimoto-masayoshi ayanokouji-kiyotaka hirata-yousuke","q":"hirata yosuke ch 7   depth read  hirata s killing intent  not bad  hirata  you re way more skilled than i thought  there s no hesitation or mercy in your aim    hashimoto fights with  naked killing intent  unbecoming of a mere honor student  driven by resentment over ayanokoji s transfer  after defeating hashimoto he raises the gun on the already out opponent but stops before firing  duels him and wins  nearly fires a follow up shot but restrains himself  his anger at being  abandoned  by the transfer fuels his aggression  noted by hashimoto s taunt  hirata s internal state is shown only through hashimoto s observations  no hirata line is quoted in the duel","h":"<article class=\"card\" id=\"sc-hirata-yousuke-y3v3-p197-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hirata-yousuke.html#sc-hirata-yousuke-y3v3-p197-1\">Ch.7 — depth read: Hirata&#x27;s killing intent<\/a><\/span><span class=\"meta\">Y3V3 · p.197–232<\/span><span class=\"by\">notes on <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> &quot;Not bad, Hirata... You&#x27;re way more skilled than I thought. There&#x27;s no hesitation or mercy in your aim.&quot; — Hashimoto<span class=\"pg\">p.222<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Fights with &quot;naked killing intent, unbecoming of a mere honor student,&quot; driven by resentment over Ayanokōji&#x27;s transfer; after defeating Hashimoto he raises the gun on the already-out opponent but stops before firing.<span class=\"pg\">p.222–229<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Duels him and wins; nearly fires a follow-up shot but restrains himself.<span class=\"pg\">p.222–229<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> His anger at being &quot;abandoned&quot; by the transfer fuels his aggression (noted by Hashimoto&#x27;s taunt).<span class=\"pg\">p.223<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Hirata&#x27;s internal state is shown only through Hashimoto&#x27;s observations; no Hirata line is quoted in the duel.<span class=\"pg\">p.229<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y3v3-p198-1\">→ After: The final-day planning and the restraint rule<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y3v3-p197-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka sudou-ken hirata-yousuke hondou-ryoutaro horikita-suzune","q":"horikita suzune ch 7   depth read  horikita on the final day breaks down camp early  tense  the final day begins with four classes a stone s throw apart   fortunately  it was only the guards who were taken out   that s not a bad idea  in fact  that s probably the correct answer  i was thinking the same thing    on moving g8 e9  stop that  hondou kun  forcibly surrounding him here won t solve anything   we are to maintain a suitable distance and wait for 9 00 a m   don t  i m sure it s no use   if he had resolved to fight us at nine o clock sharp  we could defeat him  but i m sure he won t fight  bloodthirsty toward ayanokoji for the surprise attack yet restrained   keeps a legal path open  stops sudo chasing  and uses her gps protection point strategy defensively  deeply unsettled by his raid  predicts he ll flee and refuses to send sudo after him  consults with him  holds him back from chasing ayanokoji  plans the final positioning and tactic timing with him  stops him from illegally surrounding ayanokoji","h":"<article class=\"card\" id=\"sc-horikita-suzune-y3v3-p197-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y3v3-p197-1\">Ch.7 — depth read: Horikita on the final day<\/a><\/span><span class=\"meta\">Y3V3 · p.197–232<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">Breaks down camp early, tense; the final day begins with four classes a stone&#x27;s throw apart.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a> · <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/hondou-ryoutaro.html\">Hondō Ryōtaro<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> &quot;Fortunately, it was only the guards who were taken out.&quot;<span class=\"pg\">p.199<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> &quot;That&#x27;s not a bad idea... In fact, that&#x27;s probably the correct answer. I was thinking the same thing.&quot; — on moving G8→E9<span class=\"pg\">p.200<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> &quot;Stop that, Hondou-kun. Forcibly surrounding him here won&#x27;t solve anything.&quot;<span class=\"pg\">p.201<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;We are to maintain a suitable distance and wait for 9:00 a.m.&quot;<span class=\"pg\">p.201<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Don&#x27;t... I&#x27;m sure it&#x27;s no use.&quot;<span class=\"pg\">p.203<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;If he had resolved to fight us at nine o&#x27;clock sharp, we could defeat him. But I&#x27;m sure he won&#x27;t fight.&quot;<span class=\"pg\">p.203<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Bloodthirsty toward Ayanokōji for the surprise attack yet restrained — keeps a legal path open, stops Sudō chasing, and uses her GPS/Protection Point strategy defensively.<span class=\"pg\">p.198–203<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Deeply unsettled by his raid; predicts he&#x27;ll flee and refuses to send Sudō after him.<span class=\"pg\">p.198–203<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Consults with him; holds him back from chasing Ayanokōji.<span class=\"pg\">p.198–203<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Plans the final positioning and tactic timing with him.<span class=\"pg\">p.199–201<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hondō Ryōtaro<\/b> Stops him from illegally surrounding Ayanokōji.<span class=\"pg\">p.201<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y3v3-p190-1\">← Before: Gunfire near the tents<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y3v3-p197-2\">→ After: The final day: containing Ayanokōji legally<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y3v3-p197-2","v":"y3v3","y":3,"o":35,"k":"narration spoken","w":"ayanokouji-kiyotaka sudou-ken hirata-yousuke hondou-ryoutaro horikita-suzune","q":"horikita suzune the final day  containing ayanokoji legally breaks down camp early on the final day  the four classes a stone s throw apart  remaining  a  3 vips   27  b  3 vips   24  c  2 vips   12  d  3 vips   35   let s try to look on the bright side  fortunately  it was only the guards who were taken out   supplies are little more than a bonus at this point   for my part  i think we should bite the bullet and move from g8 to e9   stop that  hondou kun  forcibly surrounding him here won t solve anything   we are to maintain a suitable distance and wait for 9 00 a m   don t  i m sure it s no use   if he had resolved to fight us at nine o clock sharp  we could defeat him  but i m sure he won t fight  saves her gps shutdown tactic for defense  locks on to ayanokoji s gps  and leaves a meter wide path so surrounding him isn t ruled  restraint  clear headed and restrained under provocation   refuses to let the class break the rules  predicts ayanokoji will flee rather than fight  and stops sudo chasing  deeply unsettled by his raid  predicts he will try to escape and refuses to take the bait  holds him back from chasing ayanokoji  plans the final positioning and tactic timing with him  stops him from illegally surrounding ayanokoji","h":"<article class=\"card\" id=\"sc-horikita-suzune-y3v3-p197-2\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y3v3-p197-2\">The final day: containing Ayanokōji legally<\/a><\/span><span class=\"meta\">Y3V3 · p.197–203<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">Breaks down camp early on the final day, the four classes a stone&#x27;s throw apart.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a> · <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/hondou-ryoutaro.html\">Hondō Ryōtaro<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> &quot;Let&#x27;s try to look on the bright side. Fortunately, it was only the guards who were taken out.&quot;<span class=\"pg\">p.199<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> &quot;Supplies are little more than a bonus at this point.&quot;<span class=\"pg\">p.199<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> &quot;For my part, I think we should bite the bullet and move from G8 to E9.&quot;<span class=\"pg\">p.200<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> Remaining: A (3 VIPs + 27), B (3 VIPs + 24), C (2 VIPs + 12), D (3 VIPs + 35).<span class=\"pg\">p.197<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Stop that, Hondou-kun. Forcibly surrounding him here won&#x27;t solve anything.&quot;<span class=\"pg\">p.201<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;We are to maintain a suitable distance and wait for 9:00 a.m.&quot;<span class=\"pg\">p.201<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Don&#x27;t... I&#x27;m sure it&#x27;s no use.&quot;<span class=\"pg\">p.203<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;If he had resolved to fight us at nine o&#x27;clock sharp, we could defeat him. But I&#x27;m sure he won&#x27;t fight.&quot;<span class=\"pg\">p.203<\/span><\/li><li><span class=\"mlabel\">Tactic<\/span> Saves her GPS shutdown tactic for defense, locks on to Ayanokōji&#x27;s GPS, and leaves a meter-wide path so surrounding him isn&#x27;t ruled &quot;restraint.&quot;<span class=\"pg\">p.199–201<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Clear-headed and restrained under provocation — refuses to let the class break the rules, predicts Ayanokōji will flee rather than fight, and stops Sudō chasing.<span class=\"pg\">p.198–203<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Deeply unsettled by his raid; predicts he will try to escape and refuses to take the bait.<span class=\"pg\">p.198–203<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Holds him back from chasing Ayanokōji.<span class=\"pg\">p.198–203<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Plans the final positioning and tactic timing with him.<span class=\"pg\">p.198–201<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hondō Ryōtaro<\/b> Stops him from illegally surrounding Ayanokōji.<span class=\"pg\">p.201<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y3v3-p197-1\">← Before: Ch.7 — depth read: Horikita on the final day<\/button><\/div><\/article>"},{"i":"sc-satou-maya-y3v3-p197-1","v":"y3v3","y":3,"o":35,"k":"","w":"sudou-ken ayanokouji-kiyotaka satou-maya","q":"sato maya ch 7   depth read  sato  targeted vip is almost showered in paintballs as class b concentrates fire on her  having learned she s a class a vip  terrified  hides in the tent during ayanokoji s previous night raid   the moment that likely exposed the vips  identities  is saved by him and urges him to flee and protect the other vips  suspects her vip identity was exposed when he raided the camp","h":"<article class=\"card\" id=\"sc-satou-maya-y3v3-p197-1\"><h3><span class=\"ttl\"><a href=\"../../../people/satou-maya.html#sc-satou-maya-y3v3-p197-1\">Ch.7 — depth read: Satō, targeted VIP<\/a><\/span><span class=\"meta\">Y3V3 · p.197–232<\/span><span class=\"by\">notes on <a href=\"../../../people/satou-maya.html\">Satō Maya<\/a><\/span><\/h3><p class=\"setup\">Is almost showered in paintballs as Class B concentrates fire on her, having learned she&#x27;s a Class A VIP.<\/p><p class=\"with\">with <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Terrified, hides in the tent during Ayanokōji&#x27;s previous-night raid — the moment that likely exposed the VIPs&#x27; identities.<span class=\"pg\">p.217–219<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Is saved by him and urges him to flee and protect the other VIPs.<span class=\"pg\">p.217–220<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Suspects her VIP identity was exposed when he raided the camp.<span class=\"pg\">p.219<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-satou-maya-y3v3-p217-1\">→ After: Satō, the targeted VIP<\/button><\/div><\/article>"},{"i":"sc-shiraishi-asuka-y3v3-p197-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka shimazaki-ikkei shiraishi-asuka","q":"shiraishi asuka ch 7   depth read  shiraishi reports the chaos  the tactic s effect has worn off and it seems class a s current locations were all displayed at once   just as you said  ayanokouji kun  it s turned into quite a chaotic battle  hasn t it   i imagine class a is surprised right about now   so  they were skillfully outplayed by you alone  ayanokouji kun  calmly relays the battlefield state as recon commander  impressed by ayanokoji s manipulation of all three classes  reports to him and admiration for his outplaying of class a  prepares to use the individual gps shutdown on class d s vips","h":"<article class=\"card\" id=\"sc-shiraishi-asuka-y3v3-p197-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shiraishi-asuka.html#sc-shiraishi-asuka-y3v3-p197-1\">Ch.7 — depth read: Shiraishi reports the chaos<\/a><\/span><span class=\"meta\">Y3V3 · p.197–232<\/span><span class=\"by\">notes on <a href=\"../../../people/shiraishi-asuka.html\">Shiraishi Asuka<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/shimazaki-ikkei.html\">Shimazaki Ikkei<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shiraishi Asuka<\/b> &quot;The tactic&#x27;s effect has worn off and it seems Class A&#x27;s current locations were all displayed at once.&quot;<span class=\"pg\">p.230<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiraishi Asuka<\/b> &quot;Just as you said, Ayanokouji-kun, it&#x27;s turned into quite a chaotic battle, hasn&#x27;t it?&quot;<span class=\"pg\">p.230<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiraishi Asuka<\/b> &quot;I imagine Class A is surprised right about now.&quot;<span class=\"pg\">p.231<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;So, they were skillfully outplayed by you alone, Ayanokouji-kun.&quot;<span class=\"pg\">p.232<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Calmly relays the battlefield state as recon commander; impressed by Ayanokōji&#x27;s manipulation of all three classes.<span class=\"pg\">p.230–232<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Reports to him and admiration for his outplaying of Class A.<span class=\"pg\">p.230–232<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shimazaki Ikkei<\/b> Prepares to use the individual GPS shutdown on Class D&#x27;s VIPs.<span class=\"pg\">p.231<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shiraishi-asuka-y3v3-p160-1\">← Before: Impressed by Class D&#x27;s trust<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-shiraishi-asuka-y3v3-p230-1\">→ After: Reporting the chaotic battlefield<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y3v3-p197-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"satou-maya horikita-suzune ayanokouji-kiyotaka sudou-ken","q":"sudo ken ch 7   depth read  sudo protects sato  what are we gonna do  suzune  about him   yesterday seriously had me in a cold sweat   isn t it because you re here  sudou kun   if that s what it takes to win  maybe that s what i should do  but i m not gonna let  em take you out this easily  we just gotta fight  pulls sato out of a paintball barrage and leaps out to draw the enemy fire aimed at her  bloodthirsty toward ayanokoji but fiercely protective of sato  willing to sacrifice himself to save her  saves her from being eliminated  recognizes she s the vip class b is targeting  discusses ayanokoji  is held back from chasing him  deeply resentful of his surprise attack on class a","h":"<article class=\"card\" id=\"sc-sudou-ken-y3v3-p197-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sudou-ken.html#sc-sudou-ken-y3v3-p197-1\">Ch.7 — depth read: Sudō protects Satō<\/a><\/span><span class=\"meta\">Y3V3 · p.197–232<\/span><span class=\"by\">notes on <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/satou-maya.html\">Satō Maya<\/a> · <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> &quot;What are we gonna do, Suzune? About him.&quot;<span class=\"pg\">p.198<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> &quot;Yesterday seriously had me in a cold sweat.&quot;<span class=\"pg\">p.198<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Satō Maya<\/b> &quot;Isn&#x27;t it because you&#x27;re here, Sudou-kun?&quot;<span class=\"pg\">p.219<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;If that&#x27;s what it takes to win, maybe that&#x27;s what I should do. But I&#x27;m not gonna let &#x27;em take you out this easily... We just gotta fight!&quot;<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Pulls Satō out of a paintball barrage and leaps out to draw the enemy fire aimed at her.<span class=\"pg\">p.217–220<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Bloodthirsty toward Ayanokōji but fiercely protective of Satō; willing to sacrifice himself to save her.<span class=\"pg\">p.198–219<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Satō Maya<\/b> Saves her from being eliminated; recognizes she&#x27;s the VIP Class B is targeting.<span class=\"pg\">p.217–220<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Discusses Ayanokōji; is held back from chasing him.<span class=\"pg\">p.198–203<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Deeply resentful of his surprise attack on Class A.<span class=\"pg\">p.198<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y3v3-p95-1\">← Before: Sudō&#x27;s read and his vow<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y3v3-p198-1\">→ After: Protecting Satō on the final day<\/button><\/div><\/article>"},{"i":"sc-hirata-yousuke-y3v3-p198-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"hirata-yousuke","q":"hirata yosuke the final day planning and the restraint rule  everyone seems quite bloodthirsty  don t they   let s try to look on the bright side  fortunately  it was only the guards who were taken out   up until now  everything has gone more or less as expected  with the exception of the matter concerning ayanokouji kun  calm and strategic   helps plan the final positioning  notes ayanokoji is the one variable  and upholds the restraint rule","h":"<article class=\"card\" id=\"sc-hirata-yousuke-y3v3-p198-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hirata-yousuke.html#sc-hirata-yousuke-y3v3-p198-1\">The final-day planning and the restraint rule<\/a><\/span><span class=\"meta\">Y3V3 · p.198–201<\/span><span class=\"by\">notes on <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/span><\/h3><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> &quot;Everyone seems quite bloodthirsty, don&#x27;t they?&quot;<span class=\"pg\">p.198<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> &quot;Let&#x27;s try to look on the bright side. Fortunately, it was only the guards who were taken out.&quot;<span class=\"pg\">p.199<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> &quot;Up until now, everything has gone more or less as expected, with the exception of the matter concerning Ayanokouji-kun.&quot;<span class=\"pg\">p.200<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Calm and strategic — helps plan the final positioning, notes Ayanokōji is the one variable, and upholds the restraint rule.<span class=\"pg\">p.198–201<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y3v3-p197-1\">← Before: Ch.7 — depth read: Hirata&#x27;s killing intent<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y3v3-p221-1\">→ After: The duel with Hashimoto; the killing intent<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y3v3-p198-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"horikita-suzune ayanokouji-kiyotaka sudou-ken","q":"sudo ken protecting sato on the final day approaches horikita about ayanokoji s overnight solo raid on their camp   what are we gonna do  suzune  about him   yesterday seriously had me in a cold sweat   it seems several people managed to coordinate on the spot and form a defense to protect the three vips   i m goin  too   but i m confident i can keep up with him  he s got a lot of luggage  too  bloodthirsty toward ayanokoji for the raid yet protective of sato  held back from chasing ayanokoji by horikita  discusses ayanokoji  is stopped from dashing after him  deeply resentful of his surprise attack on class a","h":"<article class=\"card\" id=\"sc-sudou-ken-y3v3-p198-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sudou-ken.html#sc-sudou-ken-y3v3-p198-1\">Protecting Satō on the final day<\/a><\/span><span class=\"meta\">Y3V3 · p.198–203<\/span><span class=\"by\">notes on <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/span><\/h3><p class=\"setup\">Approaches Horikita about Ayanokōji&#x27;s overnight solo raid on their camp.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> &quot;What are we gonna do, Suzune? About him.&quot;<span class=\"pg\">p.198<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> &quot;Yesterday seriously had me in a cold sweat.&quot;<span class=\"pg\">p.198<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> &quot;It seems several people managed to coordinate on the spot and form a defense to protect the three VIPs.&quot;<span class=\"pg\">p.199<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;m goin&#x27; too—&quot;<span class=\"pg\">p.203<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;But I&#x27;m confident I can keep up with him. He&#x27;s got a lot of luggage, too.&quot;<span class=\"pg\">p.203<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Bloodthirsty toward Ayanokōji for the raid yet protective of Satō; held back from chasing Ayanokōji by Horikita.<span class=\"pg\">p.198–203<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Discusses Ayanokōji; is stopped from dashing after him.<span class=\"pg\">p.198–203<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Deeply resentful of his surprise attack on Class A.<span class=\"pg\">p.198<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y3v3-p197-1\">← Before: Ch.7 — depth read: Sudō protects Satō<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y3v3-p216-1\">→ After: Sudō&#x27;s ace-level last stand<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p204-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"hashimoto-masayoshi ayanokouji-kiyotaka","q":"ayanokoji kiyotaka shaking class a  the  adjustment  returns to h10 a little after 10 a m  having shaken off class a s guards overnight   yo  i got the report yesterday that you were out right at the very end and i   we kept losing points in the beginning  i m glad i could make up for it  even just a little   there was something i came to understand from infiltrating class a  it was that class a was slightly lacking the tension it should ve had  released after the rule violation elimination  calmly rejoins the alliance and notes class a s lack of tension  is greeted by him and takemoto at h10","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p204-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p204-1\">Shaking Class A; the &quot;adjustment&quot;<\/a><\/span><span class=\"meta\">Y3V3 · p.204–206<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Returns to H10 a little after 10 a.m., having shaken off Class A&#x27;s guards overnight.<\/p><p class=\"with\">with <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Yo! I got the report yesterday that you were out right at the very end and I—&quot;<span class=\"pg\">p.204<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;We kept losing points in the beginning. I&#x27;m glad I could make up for it, even just a little.&quot;<span class=\"pg\">p.204<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;There was something I came to understand from infiltrating Class A. It was that Class A was slightly lacking the tension it should&#x27;ve had.&quot;<span class=\"pg\">p.204<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Released after the rule-violation elimination, calmly rejoins the alliance and notes Class A&#x27;s lack of tension.<span class=\"pg\">p.204<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Is greeted by him and Takemoto at H10.<span class=\"pg\">p.204<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p197-1\">← Before: Ch.7 — depth read: the mastermind&#x27;s final-day moves<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p230-1\">→ After: Sowing chaos; how he found Class A&#x27;s VIPs<\/button><\/div><\/article>"},{"i":"sc-katsuragi-kouhei-y3v3-p210-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ryuuen-kakeru katsuragi-kouhei","q":"katsuragi kohei the final confrontation with class a takes a half step forward to quietly inform his classmates class a is only a few dozen meters away   class a is right in front of us  they re probably a few dozen meters away  everyone  stay sharp   they got behind us  fall back while returning fire  c and d are coming  hurry  calm and commanding   gives quiet  precise orders and switches to shouting hand signals become useless once class a gets behind them  coordinates with him as class b is caught between class a and the alliance","h":"<article class=\"card\" id=\"sc-katsuragi-kouhei-y3v3-p210-1\"><h3><span class=\"ttl\"><a href=\"../../../people/katsuragi-kouhei.html#sc-katsuragi-kouhei-y3v3-p210-1\">The final confrontation with Class A<\/a><\/span><span class=\"meta\">Y3V3 · p.210–212<\/span><span class=\"by\">notes on <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a><\/span><\/h3><p class=\"setup\">Takes a half step forward to quietly inform his classmates Class A is only a few dozen meters away.<\/p><p class=\"with\">with <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Katsuragi Kōhei<\/b> &quot;Class A is right in front of us. They&#x27;re probably a few dozen meters away. Everyone, stay sharp.&quot;<span class=\"pg\">p.210<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Katsuragi Kōhei<\/b> &quot;They got behind us?! Fall back while returning fire! C and D are coming, hurry!&quot;<span class=\"pg\">p.212<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Calm and commanding — gives quiet, precise orders and switches to shouting hand signals become useless once Class A gets behind them.<span class=\"pg\">p.210–212<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Coordinates with him as Class B is caught between Class A and the alliance.<span class=\"pg\">p.210–212<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-katsuragi-kouhei-y3v3-p87-1\">← Before: Katsuragi reports and debates the pursuit<\/button><\/div><\/article>"},{"i":"sc-ibuki-mio-y3v3-p212-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ishizaki-daichi horikita-suzune ibuki-mio","q":"ibuki mio ibuki s grudge against horikita breaks into a fierce smile on learning class a is behind them   because i ve finally met the opponent i m supposed to take down   i ve just been itching for a fight  because i wanted so  so badly to see that look of frustration on that horikita girl s face   all my pent up grudges  i m gonna pay them back right here  right now   you re my support   as long as i can take down horikita  that s all that matters  ferocious and single minded   cares nothing for the exam s result  only for beating horikita  and drags ishizaki in as her shield to charge the enemy  forces him to be her shield  they charge together  obsessed with seeing the look of frustration on horikita s face","h":"<article class=\"card\" id=\"sc-ibuki-mio-y3v3-p212-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ibuki-mio.html#sc-ibuki-mio-y3v3-p212-1\">Ibuki&#x27;s grudge against Horikita<\/a><\/span><span class=\"meta\">Y3V3 · p.212–215<\/span><span class=\"by\">notes on <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/span><\/h3><p class=\"setup\">Breaks into a fierce smile on learning Class A is behind them.<\/p><p class=\"with\">with <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a> · <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ibuki Mio<\/b> &quot;Because I&#x27;ve finally met the opponent I&#x27;m supposed to take down.&quot;<span class=\"pg\">p.212<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ibuki Mio<\/b> &quot;I&#x27;ve just been itching for a fight... because I wanted so, so badly to see that look of frustration on that Horikita girl&#x27;s face!&quot;<span class=\"pg\">p.213<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ibuki Mio<\/b> &quot;All my pent-up grudges, I&#x27;m gonna pay them back right here, right now!&quot;<span class=\"pg\">p.215<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;You&#x27;re my support.&quot;<span class=\"pg\">p.215<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;As long as I can take down Horikita, that&#x27;s all that matters!&quot;<span class=\"pg\">p.215<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Ferocious and single-minded — cares nothing for the exam&#x27;s result, only for beating Horikita, and drags Ishizaki in as her shield to charge the enemy.<span class=\"pg\">p.212–215<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> Forces him to be her shield; they charge together.<span class=\"pg\">p.215<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Obsessed with seeing the look of frustration on Horikita&#x27;s face.<span class=\"pg\">p.213–215<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ibuki-mio-y3v3-p131-1\">← Before: Depth review: the wild card eliminated<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ibuki-mio-y3v3-p233-1\">→ After: Epilogue — depth read: the wild card falls<\/button><\/div><\/article>"},{"i":"sc-ishizaki-daichi-y3v3-p212-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ibuki-mio ryuuen-kakeru ishizaki-daichi","q":"ishizaki daichi ishizaki dragged into ibuki s charge hides behind a tree with ibuki as class a attacks from behind   w what s with that creepy laugh  you re givin  me the creeps  ibuki   ooh  pretty ambitious for you  thinkin  class a is the biggest enemy  huh   huh  give me a break  i ve gotta protect ryuuen san   no way in hell   if i go now  it s like i m asking them to shoot me   it s not all that matters   agh  fine  i guess i ve got no choice  follow me  ibuki  reluctant and practical   resists ibuki s reckless plan and wants to protect ryuen  but is dragged into charging as her shield  is bullied into being her shield and charges with her  feels obligated to protect him","h":"<article class=\"card\" id=\"sc-ishizaki-daichi-y3v3-p212-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ishizaki-daichi.html#sc-ishizaki-daichi-y3v3-p212-1\">Ishizaki dragged into Ibuki&#x27;s charge<\/a><\/span><span class=\"meta\">Y3V3 · p.212–215<\/span><span class=\"by\">notes on <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a><\/span><\/h3><p class=\"setup\">Hides behind a tree with Ibuki as Class A attacks from behind.<\/p><p class=\"with\">with <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a> · <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ishizaki Daichi<\/b> &quot;W-what&#x27;s with that creepy laugh? You&#x27;re givin&#x27; me the creeps, Ibuki!&quot;<span class=\"pg\">p.212<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ishizaki Daichi<\/b> &quot;Ooh... pretty ambitious for you. Thinkin&#x27; Class A is the biggest enemy, huh?&quot;<span class=\"pg\">p.215<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ishizaki Daichi<\/b> &quot;Huh? Give me a break. I&#x27;ve gotta protect Ryuuen-san.&quot;<span class=\"pg\">p.215<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;No way in hell!&quot;<span class=\"pg\">p.215<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;If I go now, it&#x27;s like I&#x27;m asking them to shoot me!&quot;<span class=\"pg\">p.215<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;It&#x27;s not all that matters!&quot;<span class=\"pg\">p.215<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Agh, fine! I guess I&#x27;ve got no choice! Follow me, Ibuki!&quot;<span class=\"pg\">p.215<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Reluctant and practical — resists Ibuki&#x27;s reckless plan and wants to protect Ryūen, but is dragged into charging as her shield.<span class=\"pg\">p.212–215<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ibuki Mio<\/b> Is bullied into being her shield and charges with her.<span class=\"pg\">p.212–215<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Feels obligated to protect him.<span class=\"pg\">p.215<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-sudou-ken-y3v3-p216-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"yukimura-teruhiko satou-maya sudou-ken","q":"sudo ken sudo s ace level last stand  i m out of ammo  let me reload   oh  for real  that s lucky  just two more   that s suzune for ya   they re closing in  you stay hidden   i won t let you get away   tch  i m leaving this place to you guys  takes out five opponents in an  ace level performance  protected and supplied by vip yukimura  then breaks past the flank to chase two class b students and defend sato  in his element   blessed with great physical ability and polished skill  he fights without holding back and delights in the class s successes  the vip hands him a loaded magazine   support that does not violate the rules  leaves orders to protect her before chasing class b","h":"<article class=\"card\" id=\"sc-sudou-ken-y3v3-p216-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sudou-ken.html#sc-sudou-ken-y3v3-p216-1\">Sudō&#x27;s ace-level last stand<\/a><\/span><span class=\"meta\">Y3V3 · p.216<\/span><span class=\"by\">notes on <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/yukimura-teruhiko.html\">Yukimura Teruhiko<\/a> · <a href=\"../../../people/satou-maya.html\">Satō Maya<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> &quot;I&#x27;m out of ammo! Let me reload!&quot;<span class=\"pg\">p.216<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> &quot;Oh, for real? That&#x27;s lucky...! Just two more!&quot;<span class=\"pg\">p.216<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> &quot;That&#x27;s Suzune for ya—&quot;<span class=\"pg\">p.216<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;They&#x27;re closing in! You stay hidden!&quot;<span class=\"pg\">p.216<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I won&#x27;t let you get away!&quot;<span class=\"pg\">p.216<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Tch! I&#x27;m leaving this place to you guys!&quot;<span class=\"pg\">p.216<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Takes out five opponents in an &quot;ace-level performance,&quot; protected and supplied by VIP Yukimura, then breaks past the flank to chase two Class B students and defend Satō.<span class=\"pg\">p.215–216<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> In his element — blessed with great physical ability and polished skill, he fights without holding back and delights in the class&#x27;s successes.<span class=\"pg\">p.216<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yukimura Teruhiko<\/b> The VIP hands him a loaded magazine — support that does not violate the rules.<span class=\"pg\">p.216<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Satō Maya<\/b> Leaves orders to protect her before chasing Class B.<span class=\"pg\">p.216<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y3v3-p198-1\">← Before: Protecting Satō on the final day<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y3v3-p217-1\">→ After: Saving Satō from the barrage<\/button><\/div><\/article>"},{"i":"sc-satou-maya-y3v3-p217-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"sudou-ken satou-maya","q":"sato maya sato  the targeted vip is almost showered in paintballs as class b concentrates fire on her  having learned she is a class a vip   isn t it because you re here  sudou kun   h how  really   maybe they figured out the vip s identity somehow  and what s worse  maybe everyone s   i  i don t think i can get away  at least you should run  sudou kun and protect the other vips  terrified and hiding in the tent during ayanokoji s raid   the likely moment her vip identity was exposed   she urges sudo to flee and protect the other vips  is saved by him and urges him to run","h":"<article class=\"card\" id=\"sc-satou-maya-y3v3-p217-1\"><h3><span class=\"ttl\"><a href=\"../../../people/satou-maya.html#sc-satou-maya-y3v3-p217-1\">Satō, the targeted VIP<\/a><\/span><span class=\"meta\">Y3V3 · p.217–219<\/span><span class=\"by\">notes on <a href=\"../../../people/satou-maya.html\">Satō Maya<\/a><\/span><\/h3><p class=\"setup\">Is almost showered in paintballs as Class B concentrates fire on her, having learned she is a Class A VIP.<\/p><p class=\"with\">with <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Satō Maya<\/b> &quot;Isn&#x27;t it because you&#x27;re here, Sudou-kun?&quot;<span class=\"pg\">p.219<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Satō Maya<\/b> &quot;H-How...? Really?&quot;<span class=\"pg\">p.219<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Satō Maya<\/b> &quot;Maybe they figured out the VIP&#x27;s identity somehow... and what&#x27;s worse, maybe everyone&#x27;s—&quot;<span class=\"pg\">p.219<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I... I don&#x27;t think I can get away. At least you should run, Sudou-kun and protect the other VIPs—&quot;<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Terrified and hiding in the tent during Ayanokōji&#x27;s raid — the likely moment her VIP identity was exposed — she urges Sudō to flee and protect the other VIPs.<span class=\"pg\">p.217–219<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Is saved by him and urges him to run.<span class=\"pg\">p.217–220<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-satou-maya-y3v3-p197-1\">← Before: Ch.7 — depth read: Satō, targeted VIP<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y3v3-p217-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"satou-maya sudou-ken","q":"sudo ken saving sato from the barrage pulls sato out of a paintball shower and leaps in front of the enemy to draw fire aimed at her  sacrificing himself to protect the vip   are you okay   they re comin  at us with everything they ve got  are they plannin  on using up all their ammo here   isn t it because you re here  sudou kun   nah  it s been like this since before i jumped in  in other words  doesn t that mean class b knew you were the vip before we even started fightin   if that s what it takes to win  maybe that s what i should do  but i m not gonna let  em take you out this easily  we just gotta fight  fiercely protective of sato   willing to sacrifice himself   and sharp enough to realize class b already knew she was the vip  saves her repeatedly  recognizes she is the vip class b is targeting  sato was hiding in the tent during ayanokoji s raid   the likely moment her vip identity was exposed","h":"<article class=\"card\" id=\"sc-sudou-ken-y3v3-p217-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sudou-ken.html#sc-sudou-ken-y3v3-p217-1\">Saving Satō from the barrage<\/a><\/span><span class=\"meta\">Y3V3 · p.217–220<\/span><span class=\"by\">notes on <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/satou-maya.html\">Satō Maya<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> &quot;Are you okay?!&quot;<span class=\"pg\">p.217<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> &quot;They&#x27;re comin&#x27; at us with everything they&#x27;ve got. Are they plannin&#x27; on using up all their ammo here?!&quot;<span class=\"pg\">p.217<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Satō Maya<\/b> &quot;Isn&#x27;t it because you&#x27;re here, Sudou-kun?&quot;<span class=\"pg\">p.219<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Feat<\/span> Pulls Satō out of a paintball shower and leaps in front of the enemy to draw fire aimed at her, sacrificing himself to protect the VIP.<span class=\"pg\">p.217–220<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Nah, it&#x27;s been like this since before I jumped in. In other words, doesn&#x27;t that mean Class B knew you were the VIP before we even started fightin&#x27;?&quot;<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;If that&#x27;s what it takes to win, maybe that&#x27;s what I should do. But I&#x27;m not gonna let &#x27;em take you out this easily... We just gotta fight!&quot;<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Fiercely protective of Satō — willing to sacrifice himself — and sharp enough to realize Class B already knew she was the VIP.<span class=\"pg\">p.217–220<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Satō Maya<\/b> Saves her repeatedly; recognizes she is the VIP Class B is targeting.<span class=\"pg\">p.217–220<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Satō was hiding in the tent during Ayanokōji&#x27;s raid — the likely moment her VIP identity was exposed.<span class=\"pg\">p.219<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y3v3-p216-1\">← Before: Sudō&#x27;s ace-level last stand<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y3v3-p221-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"hirata-yousuke matoba-shinji hashimoto-masayoshi","q":"hashimoto masayoshi the duel with hirata is caught in the allied advance when matoba is shot beside him and he realizes class a split its forces   it s class a  hirata s here  hashimoto   take us out with a small group  are they serious   what s going on   not bad  hirata  you re way more skilled than i thought  there s no hesitation or mercy in your aim   never seen you with such a desperate look on your face before  did getting abandoned by ayanokouji really piss you off that much   how  bout it  i could ask ayanokouji to negotiate pulling you into our class   ayanokouji was sayin  he felt bad about what he did to you  hirata   so this is what they call a desperate situation   that was some serious spirit  hirata  this match is my loss   guess i pushed the honor student a little too far  duels hirata  uses taunts about ayanokoji to rattle him  but loses to a slightly faster shot  nearly gets shot again after being eliminated  quick and psychological   reads the divided enemy  fights with feints and mind games  and praises his opponent s spirit in defeat  shaken by hirata s revealed killing intent  duel opponent  is nearly shot again after being eliminated  is beside him when matoba is shot","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y3v3-p221-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hashimoto-masayoshi.html#sc-hashimoto-masayoshi-y3v3-p221-1\">The duel with Hirata<\/a><\/span><span class=\"meta\">Y3V3 · p.221–229<\/span><span class=\"by\">notes on <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/span><\/h3><p class=\"setup\">Is caught in the allied advance when Matoba is shot beside him and he realizes Class A split its forces.<\/p><p class=\"with\">with <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/matoba-shinji.html\">Matoba Shinji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;It&#x27;s Class A! Hirata&#x27;s here, Hashimoto!&quot;<span class=\"pg\">p.221<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Take us out with a small group? Are they serious?&quot;<span class=\"pg\">p.221<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;...What&#x27;s going on...?&quot;<span class=\"pg\">p.222<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Not bad, Hirata... You&#x27;re way more skilled than I thought. There&#x27;s no hesitation or mercy in your aim.&quot;<span class=\"pg\">p.222<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Never seen you with such a desperate look on your face before! Did getting abandoned by Ayanokouji really piss you off that much?!&quot;<span class=\"pg\">p.223<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;How &#x27;bout it? I could ask Ayanokouji to negotiate pulling you into our class.&quot;<span class=\"pg\">p.223<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Ayanokouji was sayin&#x27; he felt bad about what he did to you, Hirata.&quot;<span class=\"pg\">p.226<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;So this is what they call a desperate situation...!&quot;<span class=\"pg\">p.227<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;...That was some serious spirit, Hirata. This match is my loss.&quot;<span class=\"pg\">p.228<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Guess I pushed the honor student a little too far—&quot;<span class=\"pg\">p.229<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Duels Hirata, uses taunts about Ayanokōji to rattle him, but loses to a slightly faster shot; nearly gets shot again after being eliminated.<span class=\"pg\">p.222–228<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Quick and psychological — reads the divided enemy, fights with feints and mind games, and praises his opponent&#x27;s spirit in defeat; shaken by Hirata&#x27;s revealed killing intent.<span class=\"pg\">p.221–229<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Duel opponent; is nearly shot again after being eliminated.<span class=\"pg\">p.221–229<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Matoba Shinji<\/b> Is beside him when Matoba is shot.<span class=\"pg\">p.221<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p197-1\">← Before: Ch.7 — depth read: Hashimoto&#x27;s duel with Hirata<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p222-1\">→ After: Depth review: the duel lost<\/button><\/div><\/article>"},{"i":"sc-hirata-yousuke-y3v3-p221-1","v":"y3v3","y":3,"o":35,"k":"","w":"hashimoto-masayoshi ayanokouji-kiyotaka hirata-yousuke","q":"hirata yosuke the duel with hashimoto  the killing intent is among the class a students who circle around behind class b to engage the alliance  duels hashimoto at close range and wins with a slightly faster shot  his  naked killing intent  unbecoming of a mere honor student  shocks hashimoto  after the duel is decided  he raises the gun on the already out hashimoto and presses the muzzle to his forehead  then stops before firing and walks away   the translation gives him no line in the duel  his state is shown only through hashimoto s observations  driven by resentment over ayanokoji s transfer   his aggression and near follow up shot reveal a violent edge concealed beneath the honor student facade  duels and defeats him  nearly fires a follow up shot but restrains himself  hashimoto s taunt claims ayanokoji s abandonment fueled his aggression","h":"<article class=\"card\" id=\"sc-hirata-yousuke-y3v3-p221-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hirata-yousuke.html#sc-hirata-yousuke-y3v3-p221-1\">The duel with Hashimoto; the killing intent<\/a><\/span><span class=\"meta\">Y3V3 · p.221–229<\/span><span class=\"by\">notes on <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/span><\/h3><p class=\"setup\">Is among the Class A students who circle around behind Class B to engage the alliance.<\/p><p class=\"with\">with <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Feat<\/span> Duels Hashimoto at close range and wins with a slightly faster shot; his &quot;naked killing intent, unbecoming of a mere honor student,&quot; shocks Hashimoto.<span class=\"pg\">p.224–228<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> After the duel is decided, he raises the gun on the already-out Hashimoto and presses the muzzle to his forehead, then stops before firing and walks away — the translation gives him no line in the duel; his state is shown only through Hashimoto&#x27;s observations.<span class=\"pg\">p.228–229<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Driven by resentment over Ayanokōji&#x27;s transfer — his aggression and near-follow-up shot reveal a violent edge concealed beneath the honor-student façade.<span class=\"pg\">p.222–229<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Duels and defeats him; nearly fires a follow-up shot but restrains himself.<span class=\"pg\">p.221–229<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Hashimoto&#x27;s taunt claims Ayanokōji&#x27;s abandonment fueled his aggression.<span class=\"pg\">p.223<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y3v3-p198-1\">← Before: The final-day planning and the restraint rule<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y3v3-p222-1\">→ After: Depth review: the honor student&#x27;s restraint<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y3v3-p222-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"hirata-yousuke ayanokouji-kiyotaka hashimoto-masayoshi","q":"hashimoto masayoshi depth review  the duel lost faces hirata in the forest after class a s guard units are split up  outnumbered and without his vip nearby   not bad  hirata  you re way more skilled than i thought   never seen you with such a desperate look on your face before   that was some serious spirit  hirata   guess i pushed the honor student a little too far  fights a disciplined close range duel  uses psychological taunts about ayanokoji abandoning hirata  and is eliminated by a slightly faster shot to the chest  frank and observant  admits respect for an opponent mid fight  quick to read the killing intent in hirata s aim  loses narrowly to hirata  is left shaken when hirata raises the gun again after the match is decided  duel opponent  praises his spirit  then fears for his life when the trigger is squeezed partway  tries to rattle hirata by invoking ayanokoji s abandonment","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y3v3-p222-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hashimoto-masayoshi.html#sc-hashimoto-masayoshi-y3v3-p222-1\">Depth review: the duel lost<\/a><\/span><span class=\"meta\">Y3V3 · p.222–229<\/span><span class=\"by\">notes on <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/span><\/h3><p class=\"setup\">Faces Hirata in the forest after Class A&#x27;s guard units are split up; outnumbered and without his VIP nearby.<\/p><p class=\"with\">with <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Not bad, Hirata... You&#x27;re way more skilled than I thought.&quot;<span class=\"pg\">p.222<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Never seen you with such a desperate look on your face before!&quot;<span class=\"pg\">p.223<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;That was some serious spirit, Hirata.&quot;<span class=\"pg\">p.228<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Guess I pushed the honor student a little too far—&quot;<span class=\"pg\">p.229<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Fights a disciplined close-range duel, uses psychological taunts about Ayanokōji abandoning Hirata, and is eliminated by a slightly faster shot to the chest.<span class=\"pg\">p.222–228<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Frank and observant, admits respect for an opponent mid-fight; quick to read the killing intent in Hirata&#x27;s aim.<span class=\"pg\">p.222<\/span><\/li><li><span class=\"mlabel\">Limit<\/span> Loses narrowly to Hirata; is left shaken when Hirata raises the gun again after the match is decided.<span class=\"pg\">p.228<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Duel opponent; praises his spirit, then fears for his life when the trigger is squeezed partway.<span class=\"pg\">p.222–229<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Tries to rattle Hirata by invoking Ayanokōji&#x27;s abandonment.<span class=\"pg\">p.223<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p221-1\">← Before: The duel with Hirata<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p233-1\">→ After: Epilogue — depth read: praise, then a bad feeling<\/button><\/div><\/article>"},{"i":"sc-hirata-yousuke-y3v3-p222-1","v":"y3v3","y":3,"o":35,"k":"","w":"hashimoto-masayoshi ayanokouji-kiyotaka hirata-yousuke","q":"hirata yosuke depth review  the honor student s restraint engages hashimoto in a close range paintball duel in the forest after class a s gps is jammed  eliminates hashimoto with a slightly faster shot to the chest  fights with  naked killing intent  unbecoming of a mere honor student  driven by resentment over ayanokoji s transfer  after the match is decided  raises the muzzle to hashimoto s forehead and places a finger on the trigger   then stops and walks away without firing  duel opponent  nearly fires a follow up shot at the already eliminated hashimoto  resents being  abandoned  by his transfer   the emotional core of his aggression in this volume  hirata s internal state is shown only through hashimoto s observations  the narration never enters his head  so no direct quote is attributed to him in this duel","h":"<article class=\"card\" id=\"sc-hirata-yousuke-y3v3-p222-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hirata-yousuke.html#sc-hirata-yousuke-y3v3-p222-1\">Depth review: the honor student&#x27;s restraint<\/a><\/span><span class=\"meta\">Y3V3 · p.222–230<\/span><span class=\"by\">notes on <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/span><\/h3><p class=\"setup\">Engages Hashimoto in a close-range paintball duel in the forest after Class A&#x27;s GPS is jammed.<\/p><p class=\"with\">with <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Feat<\/span> Eliminates Hashimoto with a slightly faster shot to the chest.<span class=\"pg\">p.228<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Fights with &quot;naked killing intent, unbecoming of a mere honor student,&quot; driven by resentment over Ayanokōji&#x27;s transfer.<span class=\"pg\">p.222<\/span><\/li><li><span class=\"mlabel\">Position<\/span> After the match is decided, raises the muzzle to Hashimoto&#x27;s forehead and places a finger on the trigger — then stops and walks away without firing.<span class=\"pg\">p.229<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Duel opponent; nearly fires a follow-up shot at the already-eliminated Hashimoto.<span class=\"pg\">p.222–229<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Resents being &quot;abandoned&quot; by his transfer — the emotional core of his aggression in this volume.<span class=\"pg\">p.223<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Hirata&#x27;s internal state is shown only through Hashimoto&#x27;s observations; the narration never enters his head, so no direct quote is attributed to him in this duel.<span class=\"pg\">p.222–229<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y3v3-p221-1\">← Before: The duel with Hashimoto; the killing intent<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p230-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"shiraishi-asuka ichinose-honami ayanokouji-kiyotaka","q":"ayanokoji kiyotaka sowing chaos  how he found class a s vips  appoint a commander  gather supplies  keep your distance  read the enemy s movements and avoid engagement   they can carry things out reasonably well up to this point  but once the firefight actually starts  anyone would lose their ability to think calmly   the objective wasn t to eliminate as many people as possible  but to find out who the vips were   if they could have predicted the attack beforehand  it could ve been a feint   i think class a s movements weren t bad  considering they knew they were a target   adjustments  sows chaos so students panic and eliminate each other  identified class a s three vips  wang  sato  yukimura  by attacking at night and watching who the guards protected  then fed the names to class b  uses the individual gps shutdown on the class d vips  not his own class  to hide them   no rule against targeting any class  has her report the battlefield state  leaves her with yamamura before heading to f11  walked home with her earlier","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p230-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p230-1\">Sowing chaos; how he found Class A&#x27;s VIPs<\/a><\/span><span class=\"meta\">Y3V3 · p.230–232<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/shiraishi-asuka.html\">Shiraishi Asuka<\/a> · <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Appoint a commander, gather supplies, keep your distance, read the enemy&#x27;s movements and avoid engagement.&quot;<span class=\"pg\">p.230<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;They can carry things out reasonably well up to this point, but once the firefight actually starts, anyone would lose their ability to think calmly.&quot;<span class=\"pg\">p.230<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;The objective wasn&#x27;t to eliminate as many people as possible, but to find out who the VIPs were.&quot;<span class=\"pg\">p.231<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;If they could have predicted the attack beforehand, it could&#x27;ve been a feint.&quot;<span class=\"pg\">p.231<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I think Class A&#x27;s movements weren&#x27;t bad, considering they knew they were a target.&quot;<span class=\"pg\">p.232<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Adjustments.&quot;<span class=\"pg\">p.232<\/span><\/li><li><span class=\"mlabel\">Tactic<\/span> Sows chaos so students panic and eliminate each other; identified Class A&#x27;s three VIPs (Wang, Satō, Yukimura) by attacking at night and watching who the guards protected, then fed the names to Class B.<span class=\"pg\">p.230–232<\/span><\/li><li><span class=\"mlabel\">Tactic<\/span> Uses the individual GPS shutdown on the Class D VIPs (not his own class) to hide them — no rule against targeting any class.<span class=\"pg\">p.231<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiraishi Asuka<\/b> Has her report the battlefield state; leaves her with Yamamura before heading to F11.<span class=\"pg\">p.230–232<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Walked home with her earlier.<span class=\"pg\">p.220<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p204-1\">← Before: Shaking Class A; the &quot;adjustment&quot;<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p233-1\">→ After: Epilogue — depth read: the bluff and the true goal<\/button><\/div><\/article>"},{"i":"sc-shiraishi-asuka-y3v3-p230-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka shimazaki-ikkei shiraishi-asuka","q":"shiraishi asuka reporting the chaotic battlefield  the tactic s effect has worn off and it seems class a s current locations were all displayed at once   just as you said  ayanokouji kun  it s turned into quite a chaotic battle  hasn t it   just now  another one from class a  yukimura kun the second vip was eliminated   i imagine class a is surprised right about now  wondering why their three vips were found out and are being so persistently targeted   so  they were skillfully outplayed by you alone  ayanokouji kun   excuse me  there s a message from shimazaki kun  calmly relays the battlefield state as recon commander  impressed by ayanokoji s manipulation of all three classes  reports to him  left with yamamura as he heads to f11  prepares the individual gps shutdown on the class d vips per his orders","h":"<article class=\"card\" id=\"sc-shiraishi-asuka-y3v3-p230-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shiraishi-asuka.html#sc-shiraishi-asuka-y3v3-p230-1\">Reporting the chaotic battlefield<\/a><\/span><span class=\"meta\">Y3V3 · p.230–232<\/span><span class=\"by\">notes on <a href=\"../../../people/shiraishi-asuka.html\">Shiraishi Asuka<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/shimazaki-ikkei.html\">Shimazaki Ikkei<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shiraishi Asuka<\/b> &quot;The tactic&#x27;s effect has worn off and it seems Class A&#x27;s current locations were all displayed at once.&quot;<span class=\"pg\">p.230<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiraishi Asuka<\/b> &quot;Just as you said, Ayanokouji-kun, it&#x27;s turned into quite a chaotic battle, hasn&#x27;t it?&quot;<span class=\"pg\">p.230<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiraishi Asuka<\/b> &quot;Just now, another one from Class A, Yukimura-kun—the second VIP—was eliminated.&quot;<span class=\"pg\">p.231<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I imagine Class A is surprised right about now. Wondering why their three VIPs were found out and are being so persistently targeted.&quot;<span class=\"pg\">p.231<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;So, they were skillfully outplayed by you alone, Ayanokouji-kun.&quot;<span class=\"pg\">p.232<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;...Excuse me, there&#x27;s a message from Shimazaki-kun.&quot;<span class=\"pg\">p.232<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Calmly relays the battlefield state as recon commander, impressed by Ayanokōji&#x27;s manipulation of all three classes.<span class=\"pg\">p.230–232<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Reports to him; left with Yamamura as he heads to F11.<span class=\"pg\">p.230–232<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shimazaki Ikkei<\/b> Prepares the individual GPS shutdown on the Class D VIPs per his orders.<span class=\"pg\">p.231<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shiraishi-asuka-y3v3-p197-1\">← Before: Ch.7 — depth read: Shiraishi reports the chaos<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-shiraishi-asuka-y3v3-p233-1\">→ After: Epilogue — depth read: reporting the final state<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p233-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ryuuen-kakeru ibuki-mio shiina-hiyori beppu-ryouta ayanokouji-kiyotaka","q":"ayanokoji kiyotaka epilogue   depth read  the bluff and the true goal stands over the battlefield as the three minute mark seals class a s elimination  kanzaki  the two class d vips  shiraishi and yamamura gather before him   were the remaining guards taken out   tell me the details   then there are three left  i just took down yoshimoto there a moment ago   it s not robbery or anything  it s just a transfer   i have 22 rounds left  that should be enough   i surrender   impossible  there s no way i can dodge them all   i already told you it s impossible  the muzzle velocity of these paint guns is about 90 m s   it s a matter of perspective   there s nothing in the rules against it   i ll make it official here  i  class d and ichinose have joined forces   that s right  unfortunately for you  winning a shootout wasn t my first priority   it was a matter of sooner or later  burns his ammunition against ibuki and ryuen  eliminates ibuki with a paintball to the thigh  then   out of ammo and apparently surrendered   throws a deliberately damaged paintball that bursts on ryuen s abdomen  eliminating both  led ryuen onto the coverless beach and bluffed that yamamura was behind him  exploiting ryuen s need for a certain victory  the damaged paintball was prepared over three days of repeated trials  reveals the exam s true goal  he allowed class b s surprise attack so that cornered class c would have no choice but to request an alliance with class d  class c places second behind class d  the alliance is now open  and a new exam built on trust and betrayal is announced  fights him on the beach  ryuen concedes and vows no mercy from here on  outmaneuvers her in the forest and eliminates her with a paintball to the thigh  looks for her on the disembarkation beach and finds her talking with kaneda  in good spirits  takes the class d vip with him to the center of e11 to bait the confrontation","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p233-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p233-1\">Epilogue — depth read: the bluff and the true goal<\/a><\/span><span class=\"meta\">Y3V3 · p.233–252<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Stands over the battlefield as the three-minute mark seals Class A&#x27;s elimination; Kanzaki, the two Class D VIPs, Shiraishi and Yamamura gather before him.<\/p><p class=\"with\">with <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a> · <a href=\"../../../people/shiina-hiyori.html\">Shiina Hiyori<\/a> · <a href=\"../../../people/beppu-ryouta.html\">Beppu Ryōta<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Were the remaining guards taken out?&quot;<span class=\"pg\">p.233<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Tell me the details.&quot;<span class=\"pg\">p.233<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Then there are three left. I just took down Yoshimoto there a moment ago.&quot;<span class=\"pg\">p.233<\/span><\/li><\/ul><details class=\"more\"><summary>18 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;It&#x27;s not robbery or anything. It&#x27;s just a transfer.&quot;<span class=\"pg\">p.234<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I have 22 rounds left. That should be enough.&quot;<span class=\"pg\">p.234<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I surrender.&quot;<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Impossible. There&#x27;s no way I can dodge them all.&quot;<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I already told you it&#x27;s impossible. The muzzle velocity of these paint guns is about 90 m/s.&quot;<span class=\"pg\">p.244<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;It&#x27;s a matter of perspective.&quot;<span class=\"pg\">p.245<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;There&#x27;s nothing in the rules against it.&quot;<span class=\"pg\">p.248<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;ll make it official here. I, Class D and Ichinose have joined forces.&quot;<span class=\"pg\">p.249<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;That&#x27;s right. Unfortunately for you, winning a shootout wasn&#x27;t my first priority.&quot;<span class=\"pg\">p.249<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;It was a matter of sooner or later.&quot;<span class=\"pg\">p.250<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Burns his ammunition against Ibuki and Ryūen, eliminates Ibuki with a paintball to the thigh, then — out of ammo and apparently surrendered — throws a deliberately damaged paintball that bursts on Ryūen&#x27;s abdomen, eliminating both.<span class=\"pg\">p.240–248<\/span><\/li><li><span class=\"mlabel\">Tactic<\/span> Led Ryūen onto the coverless beach and bluffed that Yamamura was behind him, exploiting Ryūen&#x27;s need for a certain victory; the damaged paintball was prepared over three days of repeated trials.<span class=\"pg\">p.245–249<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> Reveals the exam&#x27;s true goal: he allowed Class B&#x27;s surprise attack so that cornered Class C would have no choice but to request an alliance with Class D.<span class=\"pg\">p.249–250<\/span><\/li><li><span class=\"mlabel\">Position<\/span> Class C places second behind Class D; the alliance is now open, and a new exam built on trust and betrayal is announced.<span class=\"pg\">p.251–252<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Fights him on the beach; Ryūen concedes and vows no mercy from here on.<span class=\"pg\">p.236–250<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ibuki Mio<\/b> Outmaneuvers her in the forest and eliminates her with a paintball to the thigh.<span class=\"pg\">p.236–240<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiina Hiyori<\/b> Looks for her on the disembarkation beach and finds her talking with Kaneda, in good spirits.<span class=\"pg\">p.251<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Beppu Ryōta<\/b> Takes the Class D VIP with him to the center of E11 to bait the confrontation.<span class=\"pg\">p.235–236<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p230-1\">← Before: Sowing chaos; how he found Class A&#x27;s VIPs<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p233-2\">→ After: Class A eliminated; handing over ammo<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p233-2","v":"y3v3","y":3,"o":35,"k":"spoken","w":"kanzaki-ryuuji beppu-ryouta ayanokouji-kiyotaka","q":"ayanokoji kiyotaka class a eliminated  handing over ammo at 3 p m  class a is eliminated  yamamura  shiraishi  kanzaki and the two class d vips gather before him   were the remaining guards taken out   tell me the details   then there are three left  i just took down yoshimoto there a moment ago   i cleaned up the area within my line of sight to a certain extent  but it seems the two troublesome ones are still left   i figured  there s no merit whatsoever in making ibuki the vip   then take this   it s not robbery or anything  it s just a transfer   i have 22 rounds left  that should be enough   ryuuen won t be satisfied with the exam ending like this   sorry  but beppu  could you come with me for a bit  class a last is set  no expulsion risk  but third place and above are undecided   one surviving guard could decide it  gives his two spare magazines to kanzaki so the guards can protect the vips  keeping only 22 rounds   an intentionally small amount to enjoy the uncertain fight  transfers spare ammo to him  takes the class d vip with him toward e11 to bait a confrontation","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p233-2\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p233-2\">Class A eliminated; handing over ammo<\/a><\/span><span class=\"meta\">Y3V3 · p.233–235<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">At 3 p.m. Class A is eliminated; Yamamura, Shiraishi, Kanzaki and the two Class D VIPs gather before him.<\/p><p class=\"with\">with <a href=\"../../../people/kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a> · <a href=\"../../../people/beppu-ryouta.html\">Beppu Ryōta<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Were the remaining guards taken out?&quot;<span class=\"pg\">p.233<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Tell me the details.&quot;<span class=\"pg\">p.233<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Then there are three left. I just took down Yoshimoto there a moment ago.&quot;<span class=\"pg\">p.233<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I cleaned up the area within my line of sight to a certain extent. But it seems the two troublesome ones are still left.&quot;<span class=\"pg\">p.233<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I figured. There&#x27;s no merit whatsoever in making Ibuki the VIP.&quot;<span class=\"pg\">p.234<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Then take this.&quot;<span class=\"pg\">p.234<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;It&#x27;s not robbery or anything. It&#x27;s just a transfer.&quot;<span class=\"pg\">p.234<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I have 22 rounds left. That should be enough.&quot;<span class=\"pg\">p.234<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Ryuuen won&#x27;t be satisfied with the exam ending like this.&quot;<span class=\"pg\">p.234<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Sorry, but Beppu, could you come with me for a bit?&quot;<span class=\"pg\">p.235<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> Class A last is set (no expulsion risk), but third place and above are undecided — one surviving guard could decide it.<span class=\"pg\">p.234<\/span><\/li><li><span class=\"mlabel\">Tactic<\/span> Gives his two spare magazines to Kanzaki so the guards can protect the VIPs, keeping only 22 rounds — an intentionally small amount to enjoy the uncertain fight.<span class=\"pg\">p.234<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kanzaki Ryūji<\/b> Transfers spare ammo to him.<span class=\"pg\">p.234<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Beppu Ryōta<\/b> Takes the Class D VIP with him toward E11 to bait a confrontation.<span class=\"pg\">p.235<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p233-1\">← Before: Epilogue — depth read: the bluff and the true goal<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p236-1\">→ After: Eliminating Ibuki; out of ammo<\/button><\/div><\/article>"},{"i":"sc-beppu-ryouta-y3v3-p233-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka beppu-ryouta","q":"beppu ryota epilogue   depth read  the vip who walks into the trap is asked by ayanokoji to accompany him to the center of e11 to check the enemy s position and bait the confrontation   what are you going to do   i hope you re right  to be honest  i m at my absolute limit   what s with her  is she a tsundere or something  well  i m outta here  then  exhausted after nearly four days on the island but game   tracks the enemy positions for ayanokoji  then withdraws lightly when ibuki s shout reveals their approach  acts as his spotter and is sent away before the confrontation","h":"<article class=\"card\" id=\"sc-beppu-ryouta-y3v3-p233-1\"><h3><span class=\"ttl\"><a href=\"../../../people/beppu-ryouta.html#sc-beppu-ryouta-y3v3-p233-1\">Epilogue — depth read: the VIP who walks into the trap<\/a><\/span><span class=\"meta\">Y3V3 · p.233–252<\/span><span class=\"by\">notes on <a href=\"../../../people/beppu-ryouta.html\">Beppu Ryōta<\/a><\/span><\/h3><p class=\"setup\">Is asked by Ayanokōji to accompany him to the center of E11 to check the enemy&#x27;s position and bait the confrontation.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Beppu Ryōta<\/b> &quot;What are you going to do...?&quot;<span class=\"pg\">p.235<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Beppu Ryōta<\/b> &quot;I hope you&#x27;re right... To be honest, I&#x27;m at my absolute limit...&quot;<span class=\"pg\">p.236<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Beppu Ryōta<\/b> &quot;What&#x27;s with her, is she a tsundere or something...? Well, I&#x27;m outta here, then?&quot;<span class=\"pg\">p.236<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Exhausted after nearly four days on the island but game — tracks the enemy positions for Ayanokōji, then withdraws lightly when Ibuki&#x27;s shout reveals their approach.<span class=\"pg\">p.235–236<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Acts as his spotter and is sent away before the confrontation.<span class=\"pg\">p.235–236<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-beppu-ryouta-y3v3-p235-1\">→ After: Beppu as the spotter<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y3v3-p233-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka yoshida-kenta hashimoto-masayoshi","q":"hashimoto masayoshi epilogue   depth read  praise  then a bad feeling  man  don t you get a really bad feeling about this  comes to praise ayanokoji for the second place finish  then   with yoshida   senses the strange  solemn atmosphere of the results announcement before the new exam is revealed  congratulates him on the result and shares his unease  celebrates second place with him at the disembarkation","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y3v3-p233-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hashimoto-masayoshi.html#sc-hashimoto-masayoshi-y3v3-p233-1\">Epilogue — depth read: praise, then a bad feeling<\/a><\/span><span class=\"meta\">Y3V3 · p.233–252<\/span><span class=\"by\">notes on <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/yoshida-kenta.html\">Yoshida Kenta<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Man, don&#x27;t you get a really bad feeling about this?&quot;<span class=\"pg\">p.252<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Comes to praise Ayanokōji for the second-place finish, then — with Yoshida — senses the strange, solemn atmosphere of the results announcement before the new exam is revealed.<span class=\"pg\">p.251–252<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Congratulates him on the result and shares his unease.<span class=\"pg\">p.251<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yoshida Kenta<\/b> Celebrates second place with him at the disembarkation.<span class=\"pg\">p.251<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v3-p222-1\">← Before: Depth review: the duel lost<\/button><\/div><\/article>"},{"i":"sc-ibuki-mio-y3v3-p233-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka ryuuen-kakeru ibuki-mio","q":"ibuki mio epilogue   depth read  the wild card falls emerges from the trees beside ryuen to confront ayanokoji in the final shrinking area   die  ayanokouji   where are you even aiming  you think you re gonna hit me with a shot that pathetic  you re a lousy shot   agh  dammit  so this is how it ends  this is so fucking annoying  i told you i didn t want to do this  suppresses ayanokoji with a submachine gun spray and runs between the trees with animal like speed  but is eliminated by a paintball to the right thigh when she misreads his aim  ferocious and impatient   relishes the frontal fight  taunts her opponent  and rages at being eliminated in a game she never wanted to play  is outmaneuvered and eliminated by him  ryuen reveals she had wanted to gamble everything on a shot at a class d vip rather than the 2 v 1","h":"<article class=\"card\" id=\"sc-ibuki-mio-y3v3-p233-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ibuki-mio.html#sc-ibuki-mio-y3v3-p233-1\">Epilogue — depth read: the wild card falls<\/a><\/span><span class=\"meta\">Y3V3 · p.233–252<\/span><span class=\"by\">notes on <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/span><\/h3><p class=\"setup\">Emerges from the trees beside Ryūen to confront Ayanokōji in the final shrinking area.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ibuki Mio<\/b> &quot;Die, Ayanokouji!&quot;<span class=\"pg\">p.238<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ibuki Mio<\/b> &quot;Where are you even aiming? You think you&#x27;re gonna hit me with a shot that pathetic? You&#x27;re a lousy shot.&quot;<span class=\"pg\">p.239<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ibuki Mio<\/b> &quot;Agh, dammit! So this is how it ends!? This is so fucking annoying!! I told you I didn&#x27;t want to do this!&quot;<span class=\"pg\">p.240<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Feat<\/span> Suppresses Ayanokōji with a submachine-gun spray and runs between the trees with animal-like speed, but is eliminated by a paintball to the right thigh when she misreads his aim.<span class=\"pg\">p.238–240<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Ferocious and impatient — relishes the frontal fight, taunts her opponent, and rages at being eliminated in a game she never wanted to play.<span class=\"pg\">p.236–240<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is outmaneuvered and eliminated by him.<span class=\"pg\">p.236–240<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Ryūen reveals she had wanted to gamble everything on a shot at a Class D VIP rather than the 2-v-1.<span class=\"pg\">p.241<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ibuki-mio-y3v3-p212-1\">← Before: Ibuki&#x27;s grudge against Horikita<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ibuki-mio-y3v3-p236-1\">→ After: Ibuki&#x27;s last stand and elimination<\/button><\/div><\/article>"},{"i":"sc-kanzaki-ryuuji-y3v3-p233-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka ichinose-honami kanzaki-ryuuji","q":"kanzaki ryuji epilogue   depth read  the guard who relays the map spreads out a map for the breathless yamamura and reports the surviving class b members and their location   the ones left in class b are ryuuen and ibuki  as well as yamashita and yoshimoto  their location is d11   i appreciate it  but doesn t this break the rules   but what about you  do you have enough ammo   then i can t accept this  you should be able to use it more effectively than me  practical and rule conscious   takes charge of the map and intel  and hesitates to accept ayanokoji s spare magazines until he is assured his leader has enough  receives two spare magazines from him to protect the class d vips  protects her class s vips  beppu and himeno  in the final stage","h":"<article class=\"card\" id=\"sc-kanzaki-ryuuji-y3v3-p233-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kanzaki-ryuuji.html#sc-kanzaki-ryuuji-y3v3-p233-1\">Epilogue — depth read: the guard who relays the map<\/a><\/span><span class=\"meta\">Y3V3 · p.233–252<\/span><span class=\"by\">notes on <a href=\"../../../people/kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a><\/span><\/h3><p class=\"setup\">Spreads out a map for the breathless Yamamura and reports the surviving Class B members and their location.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kanzaki Ryūji<\/b> &quot;The ones left in Class B are Ryuuen and Ibuki, as well as Yamashita and Yoshimoto. Their location is D11—&quot;<span class=\"pg\">p.233<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kanzaki Ryūji<\/b> &quot;I appreciate it, but doesn&#x27;t this break the rules—?&quot;<span class=\"pg\">p.234<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kanzaki Ryūji<\/b> &quot;But what about you? Do you have enough ammo?&quot;<span class=\"pg\">p.234<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Then I can&#x27;t accept this. You should be able to use it more effectively than me.&quot;<span class=\"pg\">p.234<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Practical and rule-conscious — takes charge of the map and intel, and hesitates to accept Ayanokōji&#x27;s spare magazines until he is assured his leader has enough.<span class=\"pg\">p.233–234<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Receives two spare magazines from him to protect the Class D VIPs.<span class=\"pg\">p.234<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Protects her class&#x27;s VIPs, Beppu and Himeno, in the final stage.<span class=\"pg\">p.233<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kanzaki-ryuuji-y3v3-p182-1\">← Before: Ninomiya&#x27;s fever<\/button><\/div><\/article>"},{"i":"sc-ryuuen-kakeru-y3v3-p233-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka ibuki-mio ryuuen-kakeru","q":"ryuen kakeru epilogue   depth read  the duel lost  defeat conceded emerges from the trees with ibuki and yamashita to confront ayanokoji in the shrinking center of e11   sounds like you were pretty successful  how many people did you take out   i don t like it  but it s thanks to the information you sent  a convergence of interests  i suppose   yeah  but i d like to hand you a loss just as much  time s running out  let s settle this here and now and decide our ranks   so even you can t dodge every bullet here  can you   gotta take every precaution when i m up against you  ayanokouji  right   even in a 2 v 1  there s no guarantee we d win a shootout against you   nah  if it were just about winning  i d have thought that was the better move  too   i just wanna know  is this really you surrendering   no matter who you are  there s no way you can dodge every single bullet i fire  right   you  threw it   in the end  that idiot ibuki was the most right  huh   i ve seen your process of using any environment to win  in that case  from here on out  i m not gonna show you any mercy in the truest sense  cornered ayanokoji on the beach with an overwhelming ammunition advantage but lost when the damaged paintball burst on his abdomen  accepts the defeat with a declaration of future  merciless rivalry  driven by obsession with a certain victory   refuses the safe all or nothing shot at a vip and insists on beating ayanokoji directly  even at the risk of his own defeat  fights him on the beach  concedes defeat  and vows no mercy from here on  says her preference was to gamble on an all or nothing shot at a vip rather than challenge ayanokoji","h":"<article class=\"card\" id=\"sc-ryuuen-kakeru-y3v3-p233-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ryuuen-kakeru.html#sc-ryuuen-kakeru-y3v3-p233-1\">Epilogue — depth read: the duel lost, defeat conceded<\/a><\/span><span class=\"meta\">Y3V3 · p.233–252<\/span><span class=\"by\">notes on <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/span><\/h3><p class=\"setup\">Emerges from the trees with Ibuki and Yamashita to confront Ayanokōji in the shrinking center of E11.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;Sounds like you were pretty successful. How many people did you take out?&quot;<span class=\"pg\">p.237<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;I don&#x27;t like it, but it&#x27;s thanks to the information you sent. A convergence of interests, I suppose?&quot;<span class=\"pg\">p.237<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;Yeah. But I&#x27;d like to hand you a loss just as much. Time&#x27;s running out. Let&#x27;s settle this here and now and decide our ranks.&quot;<span class=\"pg\">p.237<\/span><\/li><\/ul><details class=\"more\"><summary>13 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;So even you can&#x27;t dodge every bullet here, can you?&quot;<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Gotta take every precaution when I&#x27;m up against you, Ayanokouji, right?&quot;<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Even in a 2-v-1, there&#x27;s no guarantee we&#x27;d win a shootout against you.&quot;<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Nah. If it were just about winning, I&#x27;d have thought that was the better move, too.&quot;<span class=\"pg\">p.242<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I just wanna know, is this really you surrendering?&quot;<span class=\"pg\">p.242<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;No matter who you are, there&#x27;s no way you can dodge every single bullet I fire, right?&quot;<span class=\"pg\">p.244<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You... threw it...!?&quot;<span class=\"pg\">p.248<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;In the end, that idiot Ibuki was the most right, huh.&quot;<span class=\"pg\">p.250<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;ve seen your process of using any environment to win. In that case, from here on out, I&#x27;m not gonna show you any mercy in the truest sense.&quot;<span class=\"pg\">p.250<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Cornered Ayanokōji on the beach with an overwhelming ammunition advantage but lost when the damaged paintball burst on his abdomen; accepts the defeat with a declaration of future, merciless rivalry.<span class=\"pg\">p.237–248<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Driven by obsession with a certain victory — refuses the safe all-or-nothing shot at a VIP and insists on beating Ayanokōji directly, even at the risk of his own defeat.<span class=\"pg\">p.241–242<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Fights him on the beach, concedes defeat, and vows no mercy from here on.<span class=\"pg\">p.236–250<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ibuki Mio<\/b> Says her preference was to gamble on an all-or-nothing shot at a VIP rather than challenge Ayanokōji.<span class=\"pg\">p.241<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y3v3-p172-1\">← Before: Depth review: beach conversation with Hiyori<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y3v3-p237-1\">→ After: The beach duel and concession<\/button><\/div><\/article>"},{"i":"sc-shiraishi-asuka-y3v3-p233-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka ichinose-honami shiraishi-asuka","q":"shiraishi asuka epilogue   depth read  reporting the final state arrives breathless with yamamura  kanzaki and the two class d vips to report the situation after ayanokoji s solo action   yes  we were attacked by two class b students while we were running away  according to ichinose san  it seems those two had their personal gps signals turned off  so they completely caught us by surprise  recovers from the surprise attack and reports calmly despite being out of breath  confirms the surviving class b members and their location  reports to him  acknowledges his buying them time with his solo action  relays her information about class b s gps jamming attackers","h":"<article class=\"card\" id=\"sc-shiraishi-asuka-y3v3-p233-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shiraishi-asuka.html#sc-shiraishi-asuka-y3v3-p233-1\">Epilogue — depth read: reporting the final state<\/a><\/span><span class=\"meta\">Y3V3 · p.233–252<\/span><span class=\"by\">notes on <a href=\"../../../people/shiraishi-asuka.html\">Shiraishi Asuka<\/a><\/span><\/h3><p class=\"setup\">Arrives breathless with Yamamura, Kanzaki and the two Class D VIPs to report the situation after Ayanokōji&#x27;s solo action.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shiraishi Asuka<\/b> &quot;Yes. We were attacked by two Class B students while we were running away... According to Ichinose-san, it seems those two had their personal GPS signals turned off, so they completely caught us by surprise.&quot;<span class=\"pg\">p.233<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Recovers from the surprise attack and reports calmly despite being out of breath; confirms the surviving Class B members and their location.<span class=\"pg\">p.233<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Reports to him; acknowledges his buying them time with his solo action.<span class=\"pg\">p.233<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Relays her information about Class B&#x27;s GPS-jamming attackers.<span class=\"pg\">p.233<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shiraishi-asuka-y3v3-p230-1\">← Before: Reporting the chaotic battlefield<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y3v3-p233-1","v":"y3v3","y":3,"o":35,"k":"","w":"ayanokouji-kiyotaka ryuuen-kakeru yamamura-miki","q":"yamamura miki epilogue   depth read  the unseen final guard arrives out of breath with shiraishi  kanzaki and the two class d vips after ayanokoji s solo action  too exhausted to speak  survives to the final stage as class c s last guard and is named by ayanokoji as the ideal person to sneak up silently   light  nimble and skilled at erasing her presence   which makes the bluff against ryuen credible  is named as the guard who might be positioned behind ryuen  though she was never actually there  is used as a phantom threat to force him to turn around in the final standoff","h":"<article class=\"card\" id=\"sc-yamamura-miki-y3v3-p233-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yamamura-miki.html#sc-yamamura-miki-y3v3-p233-1\">Epilogue — depth read: the unseen final guard<\/a><\/span><span class=\"meta\">Y3V3 · p.233–252<\/span><span class=\"by\">notes on <a href=\"../../../people/yamamura-miki.html\">Yamamura Miki<\/a><\/span><\/h3><p class=\"setup\">Arrives out of breath with Shiraishi, Kanzaki and the two Class D VIPs after Ayanokōji&#x27;s solo action; too exhausted to speak.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Survives to the final stage as Class C&#x27;s last guard and is named by Ayanokōji as the ideal person to sneak up silently — light, nimble and skilled at erasing her presence — which makes the bluff against Ryūen credible.<span class=\"pg\">p.233, 246<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is named as the guard who might be positioned behind Ryūen, though she was never actually there.<span class=\"pg\">p.246<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Is used as a phantom threat to force him to turn around in the final standoff.<span class=\"pg\">p.246<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y3v3-p94-1\">← Before: Yamamura&#x27;s fear of being separated<\/button><\/div><\/article>"},{"i":"sc-beppu-ryouta-y3v3-p235-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka beppu-ryouta","q":"beppu ryota beppu as the spotter walks with ayanokoji to the center of e11  checking the enemy s position   what are you going to do   they re coming  all three of them  they re really close now  right in front of us   i hope you re right  to be honest  i m at my absolute limit   what s with her  is she a tsundere or something  well  i m outta here  then  exhausted after nearly four days but game   tracks the enemy for ayanokoji and withdraws lightly when ibuki s shout reveals their approach  acts as his spotter and is sent away before the confrontation","h":"<article class=\"card\" id=\"sc-beppu-ryouta-y3v3-p235-1\"><h3><span class=\"ttl\"><a href=\"../../../people/beppu-ryouta.html#sc-beppu-ryouta-y3v3-p235-1\">Beppu as the spotter<\/a><\/span><span class=\"meta\">Y3V3 · p.235–236<\/span><span class=\"by\">notes on <a href=\"../../../people/beppu-ryouta.html\">Beppu Ryōta<\/a><\/span><\/h3><p class=\"setup\">Walks with Ayanokōji to the center of E11, checking the enemy&#x27;s position.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Beppu Ryōta<\/b> &quot;What are you going to do...?&quot;<span class=\"pg\">p.235<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Beppu Ryōta<\/b> &quot;...They&#x27;re coming. All three of them, they&#x27;re really close now, right in front of us...!&quot;<span class=\"pg\">p.236<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Beppu Ryōta<\/b> &quot;I hope you&#x27;re right... To be honest, I&#x27;m at my absolute limit...&quot;<span class=\"pg\">p.236<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;What&#x27;s with her, is she a tsundere or something...? Well, I&#x27;m outta here, then?&quot;<span class=\"pg\">p.236<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Exhausted after nearly four days but game — tracks the enemy for Ayanokōji and withdraws lightly when Ibuki&#x27;s shout reveals their approach.<span class=\"pg\">p.235–236<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Acts as his spotter and is sent away before the confrontation.<span class=\"pg\">p.235–236<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-beppu-ryouta-y3v3-p233-1\">← Before: Epilogue — depth read: the VIP who walks into the trap<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p236-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ibuki-mio beppu-ryouta ayanokouji-kiyotaka","q":"ayanokoji kiyotaka eliminating ibuki  out of ammo walks into the center of e11 with beppu  ryuen and ibuki emerge from the trees  yamashita behind them   that s unlikely  yamashita isn t very athletic and she s probably nearing her limit   she s fast  as expected   sounds like you were pretty successful  how many people did you take out   it would be a problem for the other three classes if class a didn t lose  right   die  ayanokouji  reads ibuki s predictable movement and  with the muzzle alone aimed at her new position  hits her right thigh   then finds his rifle empty  calculation under pressure   with  20 rounds he processes distance  cover angles  ibuki s habits and ryuen s line of fire  refusing to waste shots  outmaneuvers and eliminates her with a thigh shot  has him check the enemy s position  then sends him away  i m outta here","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p236-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p236-1\">Eliminating Ibuki; out of ammo<\/a><\/span><span class=\"meta\">Y3V3 · p.236–240<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Walks into the center of E11 with Beppu; Ryūen and Ibuki emerge from the trees, Yamashita behind them.<\/p><p class=\"with\">with <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a> · <a href=\"../../../people/beppu-ryouta.html\">Beppu Ryōta<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;That&#x27;s unlikely. Yamashita isn&#x27;t very athletic and she&#x27;s probably nearing her limit.&quot;<span class=\"pg\">p.236<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;She&#x27;s fast, as expected.&quot;<span class=\"pg\">p.236<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Sounds like you were pretty successful. How many people did you take out?&quot;<span class=\"pg\">p.237<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;It would be a problem for the other three classes if Class A didn&#x27;t lose. Right?&quot;<span class=\"pg\">p.237<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Die, Ayanokouji!&quot;<span class=\"pg\">p.238<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Reads Ibuki&#x27;s predictable movement and, with the muzzle alone aimed at her new position, hits her right thigh — then finds his rifle empty.<span class=\"pg\">p.240<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Calculation under pressure — with ~20 rounds he processes distance, cover angles, Ibuki&#x27;s habits and Ryūen&#x27;s line of fire, refusing to waste shots.<span class=\"pg\">p.237–240<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ibuki Mio<\/b> Outmaneuvers and eliminates her with a thigh shot.<span class=\"pg\">p.238–240<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Beppu Ryōta<\/b> Has him check the enemy&#x27;s position, then sends him away (&quot;I&#x27;m outta here&quot;).<span class=\"pg\">p.236<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p233-2\">← Before: Class A eliminated; handing over ammo<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p241-1\">→ After: The beach surrender and the damaged paintball<\/button><\/div><\/article>"},{"i":"sc-ibuki-mio-y3v3-p236-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka ibuki-mio","q":"ibuki mio ibuki s last stand and elimination  die  ayanokouji   where are you even aiming  you think you re gonna hit me with a shot that pathetic  you re a lousy shot   agh  dammit  so this is how it ends  this is so fucking annoying  i told you i didn t want to do this  suppresses ayanokoji with a submachine gun spray and moves between the trees with animal speed  but is eliminated by a paintball to the thigh when she misreads his aim  ferocious and impatient   relishes the frontal fight  taunts her opponent  and rages at being eliminated  is outmaneuvered and eliminated by him","h":"<article class=\"card\" id=\"sc-ibuki-mio-y3v3-p236-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ibuki-mio.html#sc-ibuki-mio-y3v3-p236-1\">Ibuki&#x27;s last stand and elimination<\/a><\/span><span class=\"meta\">Y3V3 · p.236–240<\/span><span class=\"by\">notes on <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ibuki Mio<\/b> &quot;Die, Ayanokouji!&quot;<span class=\"pg\">p.238<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ibuki Mio<\/b> &quot;Where are you even aiming? You think you&#x27;re gonna hit me with a shot that pathetic? You&#x27;re a lousy shot.&quot;<span class=\"pg\">p.239<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ibuki Mio<\/b> &quot;Agh, dammit! So this is how it ends!? This is so fucking annoying!! I told you I didn&#x27;t want to do this!&quot;<span class=\"pg\">p.240<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Feat<\/span> Suppresses Ayanokōji with a submachine-gun spray and moves between the trees with animal speed, but is eliminated by a paintball to the thigh when she misreads his aim.<span class=\"pg\">p.238–240<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Ferocious and impatient — relishes the frontal fight, taunts her opponent, and rages at being eliminated.<span class=\"pg\">p.236–240<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is outmaneuvered and eliminated by him.<span class=\"pg\">p.238–240<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ibuki-mio-y3v3-p233-1\">← Before: Epilogue — depth read: the wild card falls<\/button><\/div><\/article>"},{"i":"sc-ryuuen-kakeru-y3v3-p237-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka ibuki-mio ryuuen-kakeru","q":"ryuen kakeru the beach duel and concession confronts ayanokoji in the shrinking area with ibuki and yamashita   hah  we ve been playing this exam seriously  all trial and error  but in the end  it s just a flashy shootout with no brains involved that wears everyone down   i don t like it  but it s thanks to the information you sent  a convergence of interests  i suppose   yeah  but i d like to hand you a loss just as much  time s running out  let s settle this here and now and decide our ranks   so even you can t dodge every bullet here  can you   gotta take every precaution when i m up against you  ayanokouji  right   nah  if it were just about winning  i d have thought that was the better move  too   i just wanna know  is this really you surrendering   even if it means risking my own defeat   you  threw it   in the end  that idiot ibuki was the most right  huh   i ve seen your process of using any environment to win  in that case  from here on out  i m not gonna show you any mercy in the truest sense  cornered ayanokoji on the beach with overwhelming ammunition but lost to the thrown damaged paintball  accepts defeat with a declaration of future merciless rivalry  obsessed with a certain victory   refuses the safe vip shot  insists on beating ayanokoji directly  and demands to see how he can escape even at the risk of his own defeat  fights him on the beach  concedes and vows no mercy from here on  says she favored an all or nothing shot at a vip over the 2 v 1","h":"<article class=\"card\" id=\"sc-ryuuen-kakeru-y3v3-p237-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ryuuen-kakeru.html#sc-ryuuen-kakeru-y3v3-p237-1\">The beach duel and concession<\/a><\/span><span class=\"meta\">Y3V3 · p.237–248<\/span><span class=\"by\">notes on <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/span><\/h3><p class=\"setup\">Confronts Ayanokōji in the shrinking area with Ibuki and Yamashita.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;Hah, we&#x27;ve been playing this exam seriously, all trial and error, but in the end, it&#x27;s just a flashy shootout with no brains involved that wears everyone down.&quot;<span class=\"pg\">p.237<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;I don&#x27;t like it, but it&#x27;s thanks to the information you sent. A convergence of interests, I suppose?&quot;<span class=\"pg\">p.237<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;Yeah. But I&#x27;d like to hand you a loss just as much. Time&#x27;s running out. Let&#x27;s settle this here and now and decide our ranks.&quot;<span class=\"pg\">p.237<\/span><\/li><\/ul><details class=\"more\"><summary>12 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;So even you can&#x27;t dodge every bullet here, can you?&quot;<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Gotta take every precaution when I&#x27;m up against you, Ayanokouji, right?&quot;<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Nah. If it were just about winning, I&#x27;d have thought that was the better move, too.&quot;<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I just wanna know, is this really you surrendering?&quot;<span class=\"pg\">p.242<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Even if it means risking my own defeat.&quot;<span class=\"pg\">p.242<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You... threw it...!?&quot;<span class=\"pg\">p.248<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;In the end, that idiot Ibuki was the most right, huh.&quot;<span class=\"pg\">p.250<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;ve seen your process of using any environment to win. In that case, from here on out, I&#x27;m not gonna show you any mercy in the truest sense.&quot;<span class=\"pg\">p.250<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Cornered Ayanokōji on the beach with overwhelming ammunition but lost to the thrown damaged paintball; accepts defeat with a declaration of future merciless rivalry.<span class=\"pg\">p.237–248<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Obsessed with a certain victory — refuses the safe VIP shot, insists on beating Ayanokōji directly, and demands to see how he can escape even at the risk of his own defeat.<span class=\"pg\">p.241–242<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Fights him on the beach; concedes and vows no mercy from here on.<span class=\"pg\">p.236–250<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ibuki Mio<\/b> Says she favored an all-or-nothing shot at a VIP over the 2-v-1.<span class=\"pg\">p.241<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ryuuen-kakeru-y3v3-p233-1\">← Before: Epilogue — depth read: the duel lost, defeat conceded<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v3-p241-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ryuuen-kakeru ayanokouji-kiyotaka","q":"ayanokoji kiyotaka the beach surrender and the damaged paintball throws down the empty weapon on the coverless beach and surrenders to ryuen at gunpoint   i surrender   impossible  there s no way i can dodge them all   correct  while we re standing here like this  yamashita might be getting targeted by one of our guards   i already told you it s impossible  the muzzle velocity of these paint guns is about 90 m s   it s a matter of perspective   she s skilled at erasing her presence  she s lightweight and nimble   there s nothing in the rules against it  throws a deliberately damaged paintball that bursts on ryuen s abdomen  eliminating both   prepared over three days of trial and error on how much damage makes it rupture on impact  lures ryuen onto the coverless beach  bluffs that yamamura is behind him to force a glance  then strikes with the concealed paintball   winning the psychological duel by making ryuen need  all the answers  coldly theatrical   surrenders in appearance while manipulating every variable   fine with losing here  because the true goal is already achieved  duels him on the beach  ryuen concedes defeat","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v3-p241-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v3-p241-1\">The beach surrender and the damaged paintball<\/a><\/span><span class=\"meta\">Y3V3 · p.241–248<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Throws down the empty weapon on the coverless beach and surrenders to Ryūen at gunpoint.<\/p><p class=\"with\">with <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;I surrender.&quot;<span class=\"pg\">p.241<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Impossible. There&#x27;s no way I can dodge them all.&quot;<span class=\"pg\">p.241<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Correct. While we&#x27;re standing here like this, Yamashita might be getting targeted by one of our guards.&quot;<span class=\"pg\">p.242<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I already told you it&#x27;s impossible. The muzzle velocity of these paint guns is about 90 m/s.&quot;<span class=\"pg\">p.244<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;It&#x27;s a matter of perspective.&quot;<span class=\"pg\">p.245<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;She&#x27;s skilled at erasing her presence, she&#x27;s lightweight and nimble.&quot;<span class=\"pg\">p.246<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;There&#x27;s nothing in the rules against it.&quot;<span class=\"pg\">p.248<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Throws a deliberately damaged paintball that bursts on Ryūen&#x27;s abdomen, eliminating both — prepared over three days of trial and error on how much damage makes it rupture on impact.<span class=\"pg\">p.248<\/span><\/li><li><span class=\"mlabel\">Tactic<\/span> Lures Ryūen onto the coverless beach, bluffs that Yamamura is behind him to force a glance, then strikes with the concealed paintball — winning the psychological duel by making Ryūen need &quot;all the answers.&quot;<span class=\"pg\">p.245–248<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Coldly theatrical — surrenders in appearance while manipulating every variable, &quot;fine with losing here&quot; because the true goal is already achieved.<span class=\"pg\">p.241–248<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Duels him on the beach; Ryūen concedes defeat.<span class=\"pg\">p.236–250<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v3-p236-1\">← Before: Eliminating Ibuki; out of ammo<\/button><\/div><\/article>"},{"i":"sc-shiina-hiyori-y3v3-p251-1","v":"y3v3","y":3,"o":35,"k":"","w":"ayanokouji-kiyotaka kaneda-satoru shiina-hiyori","q":"shiina hiyori found in good spirits is not seen once during the island exam  on the disembarkation beach ayanokoji spots her in the distance talking with kaneda  appears uninjured and in good spirits  continuing the reconciliation begun in the library   a quiet sign of the friends she has made  is searched for by him after the exam  he wonders whether to go over but is swept up by yoshida and hashimoto  is seen talking with him on the beach","h":"<article class=\"card\" id=\"sc-shiina-hiyori-y3v3-p251-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shiina-hiyori.html#sc-shiina-hiyori-y3v3-p251-1\">Found in good spirits<\/a><\/span><span class=\"meta\">Y3V3 · p.251<\/span><span class=\"by\">notes on <a href=\"../../../people/shiina-hiyori.html\">Shiina Hiyori<\/a><\/span><\/h3><p class=\"setup\">Is not seen once during the island exam; on the disembarkation beach Ayanokōji spots her in the distance talking with Kaneda.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/kaneda-satoru.html\">Kaneda Satoru<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Appears uninjured and in good spirits, continuing the reconciliation begun in the library — a quiet sign of the friends she has made.<span class=\"pg\">p.251<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is searched for by him after the exam; he wonders whether to go over but is swept up by Yoshida and Hashimoto.<span class=\"pg\">p.251<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kaneda Satoru<\/b> Is seen talking with him on the beach.<span class=\"pg\">p.251<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shiina-hiyori-y3v3-p171-1\">← Before: The beach conversation with Ryūen<\/button><\/div><\/article>"}];
